window.DATA_A2_G=[{"id":"G1","q":"____ señores son amigos de mi padre.","o":["Ese","Esas","Eso","Esos"],"a":3,"k":"지시형용사 성·수","t":"저 신사분들은 우리 아버지의 친구들이다.","e":"지시형용사(이/그/저 + 명사)는 뒤에 오는 명사의 성(남성·여성)과 수(단수·복수)에 맞춰야 합니다. 'señores(신사분들)'는 남성 복수이므로 남성 복수형 esos를 씁니다. 예: esos libros(그 책들), esas casas(그 집들).","x":["Ese: 남성 단수형이라 복수 명사 señores와 맞지 않습니다 ✗","Esas: 여성 복수형이라 남성 명사 señores와 맞지 않습니다 ✗","Eso: 중성 대명사(그것)로 명사 앞에 올 수 없습니다 ✗","Esos: 남성 복수형으로 señores와 성·수가 일치합니다 → 정답 ✓"]},{"id":"G2","q":"Dicen que esta serie es buenísima, por eso quiero ____.","o":["verlo","verle","verla","verlas"],"a":2,"k":"직접목적격 대명사","t":"이 드라마가 정말 재미있다고들 해서, 나는 그것을 보고 싶다.","e":"'serie(드라마, 시리즈)'는 여성 단수 명사이므로 '그것을'은 직접목적격 대명사(~을/를에 해당) la로 받습니다. 동사원형 뒤에는 대명사를 붙여 한 단어로 씁니다: ver + la → verla. 예: Quiero comprarla.(그것을 사고 싶어.)","x":["verlo: lo는 남성 단수를 받으므로 여성 명사 serie와 맞지 않습니다 ✗","verle: le는 간접목적격(~에게)이라 '그것을 보다'에 맞지 않습니다 ✗","verla: 여성 단수 직접목적격 la로 serie를 받습니다 → 정답 ✓","verlas: las는 여성 복수라 단수인 serie와 맞지 않습니다 ✗"]},{"id":"G3","q":"Me fascinan ____ novelas de Isabel Allende.","o":["ø","una","las","los"],"a":2,"k":"정관사 용법","t":"나는 이사벨 아옌데의 소설들에 매료된다.","e":"fascinar(매료시키다)는 gustar처럼 쓰이는 동사로, 주어인 명사에는 보통 정관사를 붙입니다. 또 'de Isabel Allende'로 특정 작가의 소설들을 가리키므로 정관사가 필요합니다. novelas는 여성 복수이므로 las가 맞습니다.","x":["ø: gustar류 동사의 주어 명사에는 관사가 필요해서 비우면 어색합니다 ✗","una: 단수 부정관사라 복수 novelas와 맞지 않습니다 ✗","las: 여성 복수 정관사로 novelas와 일치합니다 → 정답 ✓","los: 남성 복수 정관사라 여성 명사 novelas와 맞지 않습니다 ✗"]},{"id":"G4","q":"Soy ____ ganador de este concurso.","o":["el primer","primero","primer","el primero"],"a":0,"k":"서수 primero 어미탈락","t":"나는 이 대회의 첫 번째 우승자이다.","e":"서수 primero(첫 번째)는 남성 단수 명사 앞에서 -o가 떨어져 primer가 됩니다(어미탈락). 또 '이 대회의 첫 우승자'처럼 특정한 대상을 말하므로 정관사 el이 필요합니다. 그래서 'el primer ganador'가 됩니다. 예: el primer día(첫날).","x":["el primer: 정관사 + 어미탈락형 primer로 ganador 앞에 알맞습니다 → 정답 ✓","primero: 남성 단수 명사 앞에서는 primer로 줄여야 하고 관사도 없습니다 ✗","primer: 형태는 맞지만 특정 대상을 가리키는 정관사 el이 빠졌습니다 ✗","el primero: 명사 앞에서는 primer로 줄여야 하므로 틀립니다 ✗"]},{"id":"G5","q":"____ apartamento es más grande que el mío.","o":["El vuestro","Vuestro","La vuestra","Vuestros"],"a":1,"k":"소유형용사 vuestro","t":"너희 아파트는 내 것보다 더 크다.","e":"명사 앞에 오는 소유형용사(너희의)는 관사 없이 vuestro/vuestra/vuestros/vuestras를 씁니다. apartamento는 남성 단수이므로 vuestro가 맞습니다. 'el vuestro'는 명사 없이 '너희 것'이라는 소유대명사로 쓸 때의 형태입니다. vosotros 형태는 주로 스페인에서 쓰고, 중남미에서는 'su apartamento(de ustedes)'라고 합니다.","x":["El vuestro: 소유대명사(너희 것) 형태라 명사 앞에 쓰지 않습니다 ✗","Vuestro: 남성 단수 소유형용사로 apartamento 앞에 알맞습니다 → 정답 ✓","La vuestra: 여성형 소유대명사라 성도 용법도 맞지 않습니다 ✗","Vuestros: 복수형이라 단수 apartamento와 맞지 않습니다 ✗"]},{"id":"G6","q":"He quedado con Martín en la plaza ____ 6 de la tarde.","o":["al","a las","en las","a los"],"a":1,"k":"시각 표현 a las","t":"나는 마르틴과 오후 6시에 광장에서 만나기로 했다.","e":"'몇 시에'라고 시각을 말할 때는 'a + 정관사 + 숫자'를 씁니다. 1시는 'a la una', 2시 이상은 'a las dos, a las seis'처럼 여성 복수 las를 씁니다(horas가 생략된 것). 그래서 'a las 6'이 정답입니다.","x":["al: a + el의 축약형으로 시각 표현에 쓰지 않습니다 ✗","a las: 2시 이상의 시각 '~시에' 표현 → 정답 ✓","en las: 시각 앞에는 en이 아니라 a를 씁니다 ✗","a los: 시각은 여성(horas)이므로 los가 아닌 las를 씁니다 ✗"]},{"id":"G7","q":"Miguel ____ cuando llegó su esposa a casa.","o":["estaba durmiendo","estuvo durmiendo","ha dormido","duerme"],"a":0,"k":"과거진행형","t":"미겔은 아내가 집에 도착했을 때 자고 있었다.","e":"과거의 어떤 순간(아내가 도착했을 때)에 '진행 중이던 동작'은 불완료과거 진행형(estaba + 현재분사)으로 나타냅니다. llegó(도착했다)는 그 진행 중에 끼어든 사건이라 단순과거로 씁니다. 예: Estaba leyendo cuando sonó el teléfono.(전화가 울렸을 때 책을 읽고 있었다.)","x":["estaba durmiendo: 과거 특정 순간에 진행 중이던 동작 → 정답 ✓","estuvo durmiendo: 일정 기간 동안 끝난 행동을 나타내어 '~했을 때 자고 있었다'의 배경 묘사에 맞지 않습니다 ✗","ha dormido: 현재완료라 과거 이야기 속 배경으로 쓸 수 없습니다 ✗","duerme: 현재형이라 과거 시제 llegó와 맞지 않습니다 ✗"]},{"id":"G8","q":"Llevo dos noches ____ dormir, estoy cansadísima.","o":["por","a","sin","en"],"a":2,"k":"전치사 sin + 동사원형","t":"나는 이틀 밤째 잠을 못 자고 있어서 너무 피곤하다.","e":"'llevar + 기간 + sin + 동사원형'은 '~동안 ~하지 않고 있다'는 뜻입니다. sin(~없이)은 뒤에 동사원형을 바로 받아 '~하지 않고'의 의미를 만듭니다. 예: Llevo un año sin fumar.(1년째 담배를 안 피우고 있어.)","x":["por: '~때문에/~을 위해' 뜻으로 '자지 않고'의 의미가 나오지 않습니다 ✗","a: '~하러/~에' 뜻이라 문맥에 맞지 않습니다 ✗","sin: '~하지 않고'를 뜻해 '이틀 밤째 못 자고'를 표현합니다 → 정답 ✓","en: '~에서/~에' 뜻이라 이 구조에 쓰지 않습니다 ✗"]},{"id":"G9","q":"Está triste ____ su novia lo ha dejado.","o":["como","por","aunque","porque"],"a":3,"k":"이유 접속사 porque","t":"그는 여자친구가 그를 떠났기 때문에 슬프다.","e":"porque(왜냐하면, ~때문에)는 앞 문장의 이유를 뒤에 연결할 때 씁니다. '슬프다' + '여자친구가 떠났기 때문에'의 이유 관계이므로 porque가 맞습니다. como도 이유를 나타내지만 문장 맨 앞에 올 때만 씁니다(Como su novia lo ha dejado, está triste).","x":["como: 이유의 como는 문장 맨 앞에 와야 하므로 이 위치에선 틀립니다 ✗","por: 전치사라 뒤에 명사·동사원형이 오며, 활용된 동사 문장을 바로 받지 못합니다 ✗","aunque: '비록 ~이지만'이라는 양보 뜻이라 의미가 맞지 않습니다 ✗","porque: 뒤 문장이 슬픈 이유임을 나타냅니다 → 정답 ✓"]},{"id":"G10","q":"¿De quién es ____?","o":["estas","esto","estos","esta"],"a":1,"k":"중성 지시대명사 esto","t":"이건 누구 거야?","e":"무엇인지 모르거나 명사를 밝히지 않은 대상을 가리킬 때는 중성 지시대명사 esto(이것)를 씁니다. 동사도 단수 es이므로 단수형이어야 합니다. estas/estos/esta는 성·수가 있는 형태로, 무엇을 가리키는지 명확할 때 씁니다.","x":["estas: 여성 복수라 단수 동사 es와 맞지 않습니다 ✗","esto: 정체를 밝히지 않은 '이것'을 가리키는 중성 대명사 → 정답 ✓","estos: 남성 복수라 단수 동사 es와 맞지 않습니다 ✗","esta: 여성 단수 명사를 가리킬 때 쓰며, 명사가 정해지지 않은 이 문장에서는 esto가 자연스럽습니다 ✗"]},{"id":"G11","q":"Almudena quiere que ____ con ella a la inauguración de la tienda de su esposo.","o":["vaya","voy a ir","voy","iría"],"a":0,"k":"querer que+접속법","t":"알무데나는 내가 남편 가게 개업식에 자기와 함께 가기를 원한다.","e":"'querer que(~가 ~하기를 원하다)'처럼 바람을 나타내는 동사 뒤 que절의 주어가 다르면, que절 동사는 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태)으로 씁니다. ir의 접속법 현재 1인칭은 vaya입니다. 예: Quiero que vengas.(네가 오기를 원해.)","x":["vaya: ir의 접속법 현재로 querer que 뒤에 알맞습니다 → 정답 ✓","voy a ir: 직설법 미래 표현이라 바람을 나타내는 que절에 쓸 수 없습니다 ✗","voy: 직설법 현재라 querer que 뒤에 쓸 수 없습니다 ✗","iría: 가정미래(조건법)라 이 문장 구조와 맞지 않습니다 ✗"]},{"id":"G12","q":"En este espacio caben ____ personas.","o":["trescientos","tres cientas","trescienta","trescientas"],"a":3,"k":"숫자 백 단위 성 일치","t":"이 공간에는 300명이 들어갈 수 있다.","e":"200~900의 백 단위 숫자는 뒤 명사의 성에 맞춰 형태가 바뀝니다. personas(사람들)는 여성 복수이므로 trescientas를 씁니다. 그리고 한 단어로 붙여 씁니다. 예: trescientos libros(책 300권), trescientas casas(집 300채).","x":["trescientos: 남성형이라 여성 명사 personas와 맞지 않습니다 ✗","tres cientas: 백 단위 숫자는 띄어 쓰지 않고 한 단어로 씁니다 ✗","trescienta: 복수 -s가 빠진 잘못된 형태입니다 ✗","trescientas: 여성 복수형으로 personas와 일치합니다 → 정답 ✓"]},{"id":"G13","q":"¿Te importaría ____ este café a la abuela?","o":["le llevar","llevarle","llevarla","llevar le"],"a":1,"k":"간접목적격 대명사 위치","t":"이 커피를 할머니께 가져다줄 수 있겠니?","e":"'a la abuela(할머니에게)'는 간접목적어(~에게)이므로 간접목적격 대명사 le를 씁니다. 동사원형과 함께 쓸 때는 대명사를 동사원형 끝에 붙여 한 단어로 씁니다: llevar + le → llevarle. '¿Te importaría + 동사원형?'은 '~해 줄 수 있겠니?'라는 공손한 부탁 표현입니다.","x":["le llevar: 대명사는 동사원형 앞에 따로 둘 수 없습니다 ✗","llevarle: 간접목적격 le를 동사원형 뒤에 붙인 올바른 형태 → 정답 ✓","llevarla: la는 직접목적격(그녀를)이라 '할머니에게'를 받을 수 없습니다 ✗","llevar le: 대명사는 동사원형에 붙여 써야 하며 띄어 쓰지 않습니다 ✗"]},{"id":"G14","q":"____, ¿sabe si hay un supermercado por aquí cerca?","o":["Perdone","Perdones","Perdona","Perdonas"],"a":0,"k":"usted 명령형","t":"실례합니다, 이 근처에 슈퍼마켓이 있는지 아세요?","e":"뒤의 '¿sabe?(아세요?)'가 usted(당신, 존칭)에 대한 동사이므로 앞의 '실례합니다'도 usted 명령형을 씁니다. perdonar의 usted 명령형은 접속법 형태인 perdone입니다. 친한 사이(tú)라면 perdona를 씁니다.","x":["Perdone: usted에 대한 명령형으로 존칭 sabe와 어울립니다 → 정답 ✓","Perdones: tú의 부정명령(no perdones)에만 쓰는 형태입니다 ✗","Perdona: tú 명령형이라 존칭 sabe와 맞지 않습니다 ✗","Perdonas: 직설법 현재(너는 용서한다)라 명령의 뜻이 아닙니다 ✗"]},{"id":"G15","q":"Dicen que los frutos rojos ____ buenos para la memoria.","o":["están","son","sean","estén"],"a":1,"k":"ser vs estar","t":"붉은 베리류 과일은 기억력에 좋다고들 한다.","e":"'ser bueno para ~'는 '~에 좋다(유익하다)'라는 본래의 성질을 나타내므로 ser를 씁니다. estar bueno는 '맛있다(음식 상태)'라는 다른 뜻입니다. 또 'Dicen que(~라고들 한다)'는 사실 전달이라 직설법을 씁니다.","x":["están: estar bueno는 '맛있다'는 상태 의미라 '건강에 좋다'에 맞지 않습니다 ✗","son: 본래의 성질 '~에 좋다'를 나타냅니다 → 정답 ✓","sean: 접속법이라 사실을 전달하는 dicen que 뒤에 맞지 않습니다 ✗","estén: estar의 접속법이라 의미와 법 모두 맞지 않습니다 ✗"]},{"id":"G16","q":"Necesito ____ un momento para hacer una llamada.","o":["de salir","salir","que salgo","salgo"],"a":1,"k":"necesitar+원형","t":"전화 한 통 하러 잠깐 나가야 해.","e":"necesitar(필요하다)는 주어가 같을 때 뒤에 동사원형을 바로 붙입니다: necesitar + salir. 전치사 de는 필요 없습니다. 예: Necesito descansar.(쉬어야 해.)","x":["de salir: necesitar 뒤에는 전치사 de를 넣지 않습니다 ✗","salir: necesitar + 동사원형 → 정답 ✓","que salgo: 주어가 같으므로 que절을 쓰지 않습니다 ✗","salgo: 활용형 동사를 연달아 쓸 수 없습니다 ✗"]},{"id":"G17","q":"Estos juguetes no son adecuados ____ los niños menores de cinco años.","o":["de","por","para","a"],"a":2,"k":"전치사 para","t":"이 장난감들은 5세 미만 어린이에게 적합하지 않다.","e":"'adecuado para ~'는 '~에게 적합한'이라는 뜻으로, 대상·용도를 나타내는 para를 씁니다. 예: Este libro es adecuado para principiantes.(이 책은 초보자에게 적합하다.)","x":["de: '~의'라는 소유·출처 뜻이라 맞지 않습니다 ✗","por: 원인·경로를 나타내 '~에게 적합한'의 의미가 아닙니다 ✗","para: 대상·용도 '~에게/~을 위해' → 정답 ✓","a: adecuado와 함께 대상을 나타내는 표현으로 쓰지 않습니다 ✗"]},{"id":"G18","q":"Le pregunté ____ mi alumno qué le había parecido la lección, pero no contestó.","o":["ø","el","a","al"],"a":2,"k":"간접목적어 a + 사람","t":"나는 내 학생에게 수업이 어땠는지 물었지만, 그는 대답하지 않았다.","e":"preguntar(묻다)의 '~에게'에 해당하는 사람은 'a + 사람'으로 씁니다. 앞의 le가 이 사람을 미리 가리키고(중복 표현), 'a mi alumno'가 구체적으로 누구인지 밝혀 줍니다. mi가 있으므로 정관사 el은 들어가지 않습니다.","x":["ø: 간접목적어인 사람 앞에는 a가 필요합니다 ✗","el: 소유형용사 mi와 정관사를 함께 쓸 수 없고 전치사도 빠집니다 ✗","a: '~에게'를 나타내는 전치사 → 정답 ✓","al: a + el인데 mi 앞에 정관사를 쓸 수 없습니다 ✗"]},{"id":"G19","q":"____ hablar con nuestros amigos sobre nuestra infancia.","o":["Nos gusta","Nos gustamos","Gustamos","Nos gustan"],"a":0,"k":"gustar + 동사원형","t":"우리는 친구들과 어린 시절에 대해 이야기하는 것을 좋아한다.","e":"gustar 구문에서 좋아하는 대상이 동사원형(hablar)이면 동사는 항상 3인칭 단수 gusta를 씁니다. 좋아하는 사람 '우리'는 간접목적격 nos로 나타냅니다. 예: Me gusta bailar.(나는 춤추는 걸 좋아해.)","x":["Nos gusta: nos(우리에게) + 동사원형 주어에 맞는 단수 gusta → 정답 ✓","Nos gustamos: '우리가 서로 마음에 든다'는 뜻이 되어 맞지 않습니다 ✗","Gustamos: 간접목적격이 없고 '우리가 (남에게) 호감을 준다'는 뜻이 됩니다 ✗","Nos gustan: 복수형은 복수 명사가 주어일 때만 씁니다 ✗"]},{"id":"G20","q":"Cada vez que escuchaba esa canción, ____ a llorar.","o":["se ponía","se puso","se ha puesto","se pone"],"a":0,"k":"불완료과거 반복 습관","t":"그 노래를 들을 때마다 그녀는 울기 시작하곤 했다.","e":"'Cada vez que(~할 때마다)'와 escuchaba(불완료과거)는 과거에 반복된 습관을 나타냅니다. 그래서 주절도 불완료과거 se ponía를 씁니다. 'ponerse a + 동사원형'은 '~하기 시작하다'라는 뜻입니다.","x":["se ponía: 과거의 반복 행동을 나타내는 불완료과거 → 정답 ✓","se puso: 한 번 일어난 사건이라 '~할 때마다'와 맞지 않습니다 ✗","se ha puesto: 현재완료라 과거 습관 묘사에 맞지 않습니다 ✗","se pone: 현재형이라 과거형 escuchaba와 시제가 맞지 않습니다 ✗"]},{"id":"G21","q":"¿Dónde aprendiste ____ coser?","o":["de","a","en","ø"],"a":1,"k":"aprender a+원형","t":"너는 어디서 바느질하는 걸 배웠니?","e":"aprender(배우다) 뒤에 동사원형이 오면 전치사 a를 넣어 'aprender a + 동사원형'으로 씁니다. 예: Aprendí a nadar de niño.(나는 어릴 때 수영을 배웠다.)","x":["de: aprender와 함께 동사원형을 이끄는 전치사가 아닙니다 ✗","a: aprender a + 동사원형 → 정답 ✓","en: 장소를 나타내는 전치사라 이 구조에 쓰지 않습니다 ✗","ø: 동사원형 앞에 a가 반드시 필요합니다 ✗"]},{"id":"G22","q":"Callaos, la maestra ____.","o":["hablando","es hablando","habla","está hablando"],"a":3,"k":"현재진행형","t":"조용히 해, 선생님이 말씀하고 계셔.","e":"'지금 이 순간 진행 중인 동작'은 'estar + 현재분사'로 나타냅니다. 'Callaos(너희 조용히 해)'라고 지금 말하는 상황이므로 está hablando가 가장 알맞습니다. Callaos는 vosotros 명령형으로 주로 스페인에서 쓰며, 중남미에서는 Cállense를 씁니다.","x":["hablando: 현재분사만으로는 동사 역할을 못 합니다 ✗","es hablando: 진행형은 ser가 아니라 estar로 만듭니다 ✗","habla: 현재형도 가능하지만 '지금 말하고 있다'는 진행 의미는 진행형이 정확합니다 ✗","está hablando: 지금 진행 중인 동작 → 정답 ✓"]},{"id":"G23","q":"Voy a ir al supermercado ____ volver a mi casa.","o":["antes","de antes","desde antes","antes de"],"a":3,"k":"antes de + 동사원형","t":"집에 돌아가기 전에 슈퍼마켓에 갈 거야.","e":"'~하기 전에'는 'antes de + 동사원형'으로 씁니다. antes 혼자는 '전에, 먼저'라는 부사라 뒤에 동사를 바로 받지 못합니다. 예: Lávate las manos antes de comer.(먹기 전에 손을 씻어.)","x":["antes: 부사라 뒤에 동사원형을 이으려면 de가 필요합니다 ✗","de antes: 어순이 틀린 표현입니다 ✗","desde antes: '그 전부터'라는 뜻으로 맞지 않습니다 ✗","antes de: '~하기 전에' → 정답 ✓"]},{"id":"G24","q":"Mis niños beben agua en vasos ____ plástico.","o":["de","con","a","en"],"a":0,"k":"재료 전치사 de","t":"우리 아이들은 플라스틱 컵으로 물을 마신다.","e":"물건의 재료를 나타낼 때는 'de + 재료'를 씁니다: vaso de plástico(플라스틱 컵), mesa de madera(나무 탁자). 관사 없이 바로 재료 이름이 옵니다.","x":["de: 재료 '~로 만든' → 정답 ✓","con: '~와 함께/~을 가지고'라 재료 표현에 쓰지 않습니다 ✗","a: 재료를 나타내지 않습니다 ✗","en: '~안에'라는 장소 뜻이 됩니다 ✗"]},{"id":"G25","q":"Es normal que no encuentres tus gafas, siempre ____ dejas en cualquier parte.","o":["les","los","las","la"],"a":2,"k":"직접목적격 대명사","t":"네가 안경을 못 찾는 것도 당연해, 너는 늘 그걸 아무 데나 두잖아.","e":"'gafas(안경)'는 스페인어에서 항상 여성 복수 명사입니다. '그것을 두다'의 직접목적어이므로 여성 복수 직접목적격 las를 씁니다. 참고로 중남미에서는 안경을 lentes(남성 복수)라고 하는 곳이 많아 그때는 los가 됩니다.","x":["les: 간접목적격(그들에게)이라 '그것을'에 맞지 않습니다 ✗","los: 남성 복수라 여성 명사 gafas와 맞지 않습니다 ✗","las: 여성 복수 직접목적격으로 gafas를 받습니다 → 정답 ✓","la: 단수라 복수 명사 gafas와 맞지 않습니다 ✗"]},{"id":"G26","q":"Voy a ____ al bebé en su cuna.","o":["acostarme","acuesto","acostaré","acostar"],"a":3,"k":"ir a + 동사원형","t":"아기를 요람에 재우러 갈게.","e":"'ir a + 동사원형'은 '~할 것이다/~하러 가다'라는 가까운 미래 표현입니다. 여기서 재우는 대상은 아기(al bebé)이므로, 재귀형 acostarme(내가 눕다)가 아니라 타동사 acostar(눕히다, 재우다)를 씁니다.","x":["acostarme: '내가 자러 눕다'는 재귀 의미라 아기를 재우는 뜻이 안 됩니다 ✗","acuesto: 활용형이라 voy a 뒤에 올 수 없습니다 ✗","acostaré: 미래 활용형이라 voy a 뒤에 올 수 없습니다 ✗","acostar: voy a + 동사원형, '(아기를) 재우다' → 정답 ✓"]},{"id":"G27","q":"Te recomiendo ____ hables con mi abogado sobre ese asunto.","o":["que","porque","de que","a que"],"a":0,"k":"recomendar que","t":"그 문제에 대해서는 내 변호사와 이야기해 보길 권해.","e":"'recomendar que(~하기를 권하다)'는 뒤에 que절을 바로 이끌며, que절 동사는 접속법(hables)을 씁니다. 전치사 de나 a는 넣지 않습니다. 예: Te recomiendo que descanses.(쉬기를 권해.)","x":["que: recomendar 뒤에서 접속법 절을 이끕니다 → 정답 ✓","porque: '왜냐하면'이라 권유의 내용을 이끌지 못합니다 ✗","de que: recomendar 뒤에 de를 넣는 것은 틀린 표현(데케이스모)입니다 ✗","a que: recomendar는 전치사 a를 요구하지 않습니다 ✗"]},{"id":"G28","q":"¿____ qué año murió Picasso?","o":["De","En","A","Por"],"a":1,"k":"연도 앞 전치사 en","t":"피카소는 몇 년도에 죽었니?","e":"연도·월·계절 앞에는 전치사 en을 씁니다: en 1973, en mayo, en verano. 의문문에서도 '¿En qué año...?(몇 년도에?)'가 됩니다.","x":["De: '~의/~부터'라 연도를 묻는 표현이 아닙니다 ✗","En: 연도 앞 '~에' → 정답 ✓","A: 시각(a las 3)에 쓰며 연도에는 쓰지 않습니다 ✗","Por: '~때문에/~무렵'이라 이 의문문에 맞지 않습니다 ✗"]},{"id":"G29","q":"Quiero pasar por la casa de Lucía ____ ir a clase.","o":["antes","después","mientras","antes de"],"a":3,"k":"antes de + 동사원형","t":"수업에 가기 전에 루시아의 집에 들르고 싶다.","e":"뒤에 동사원형(ir)이 이어지므로 '~하기 전에'를 뜻하는 'antes de + 동사원형'을 씁니다. 'pasar por + 장소'는 '~에 들르다'라는 표현입니다.","x":["antes: de 없이 동사원형을 바로 받을 수 없습니다 ✗","después: '~후에'라도 동사원형 앞에는 de가 필요하고 의미도 다릅니다 ✗","mientras: '~하는 동안'이라 뒤에 활용된 동사가 와야 합니다 ✗","antes de: '~하기 전에' → 정답 ✓"]},{"id":"G30","q":"Tenemos ____ preparar muchas cosas antes de viajar.","o":["de","a","que","ø"],"a":2,"k":"tener que+원형","t":"우리는 여행 전에 준비할 게 많다.","e":"'tener que + 동사원형'은 '~해야 한다'는 의무 표현입니다. 'Tenemos que preparar'는 '우리는 준비해야 한다'는 뜻입니다. 예: Tengo que estudiar.(공부해야 해.)","x":["de: 'tener de'는 현대 스페인어에서 의무 표현으로 쓰지 않습니다 ✗","a: tener와 동사원형 사이에 a를 쓰지 않습니다 ✗","que: tener que + 동사원형(~해야 한다) → 정답 ✓","ø: tener 뒤에 동사원형을 바로 붙일 수 없습니다 ✗"]},{"id":"G31","q":"____ una tarta, ¿nos ayudas?","o":["Estuvimos haciendo","Hicimos","Estamos haciendo","Hacemos"],"a":2,"k":"현재진행형","t":"우리 지금 케이크 만들고 있어, 도와줄래?","e":"'¿nos ayudas?(도와줄래?)'라고 지금 부탁하므로, 지금 진행 중인 동작을 나타내는 'estar + 현재분사'가 알맞습니다. hacer의 현재분사는 haciendo입니다.","x":["Estuvimos haciendo: 과거에 끝난 행동이라 지금 도와달라는 말과 맞지 않습니다 ✗","Hicimos: 단순과거(만들었다)라 현재 진행 상황이 아닙니다 ✗","Estamos haciendo: 지금 진행 중인 동작 → 정답 ✓","Hacemos: 현재형은 습관·일반적 사실에 가까워 '지금 하는 중'을 강조하지 못합니다 ✗"]},{"id":"G32","q":"En ese armario no ____ nada.","o":["está","son","hay","es"],"a":2,"k":"hay (존재 표현)","t":"그 옷장 안에는 아무것도 없다.","e":"'~이 있다/없다'처럼 사물의 존재 유무를 말할 때는 hay(haber의 무인칭형)를 씁니다. nada(아무것도), algo(무언가), 부정관사·숫자가 붙은 명사와 함께 씁니다. estar는 이미 알려진 특정한 것의 위치를 말할 때 씁니다(El libro está en el armario).","x":["está: 특정한 것의 위치에 쓰며 nada와 함께 존재를 말할 수 없습니다 ✗","son: ser는 존재 유무를 나타내지 않습니다 ✗","hay: 존재 유무 '~이 있다/없다' → 정답 ✓","es: ser는 존재를 나타내지 않습니다 ✗"]},{"id":"G33","q":"Tengo ____ dinero, no puedo ir al teatro esta noche.","o":["un poco","poco","demasiado","bastante"],"a":1,"k":"poco vs un poco","t":"나는 돈이 거의 없어서 오늘 밤 극장에 갈 수 없다.","e":"poco(거의 없는, 적은)는 부족함을 강조하는 부정적인 뜻이라 '극장에 갈 수 없다'는 결과와 어울립니다. 'un poco de'는 '약간 있는'이라는 긍정적 뉘앙스이고, 명사 앞에는 de가 필요합니다.","x":["un poco: '약간'이라는 긍정 뉘앙스이며 명사 앞에는 un poco de가 되어야 합니다 ✗","poco: '거의 없는'으로 돈이 부족함을 나타냅니다 → 정답 ✓","demasiado: '너무 많은'이라 극장에 못 간다는 문맥과 반대입니다 ✗","bastante: '충분한/꽤 많은'이라 문맥과 반대입니다 ✗"]},{"id":"G34","q":"Mario se enamoró de Yolanda ____ la vio.","o":["al","cuanto","como","en cuanto"],"a":3,"k":"en cuanto","t":"마리오는 요란다를 보자마자 사랑에 빠졌다.","e":"en cuanto는 '~하자마자'라는 뜻의 시간 접속사로 뒤에 활용된 동사(la vio)를 받습니다. 예: En cuanto llegues, llámame.(도착하자마자 전화해.) al도 '~할 때'를 뜻하지만 뒤에 동사원형이 와야 합니다(al verla).","x":["al: 'al + 동사원형'으로만 써서 활용형 vio 앞에 올 수 없습니다 ✗","cuanto: en 없이 혼자 쓰면 '~하자마자'의 뜻이 되지 않습니다 ✗","como: '~처럼/~해서'라 시간 관계를 나타내지 않습니다 ✗","en cuanto: '~하자마자' → 정답 ✓"]},{"id":"G35","q":"Todavía no sé ____ podré ir a la cena de Navidad de mi empresa.","o":["sí","si","que","qué"],"a":1,"k":"si (~인지 아닌지)","t":"회사 크리스마스 저녁 모임에 갈 수 있을지 아직 모르겠다.","e":"'saber si ~'처럼 간접의문문으로 '~인지 아닌지'를 말할 때는 악센트 없는 si를 씁니다. 악센트가 있는 sí는 '네'라는 뜻이고, qué는 '무엇'을 묻는 의문사입니다.","x":["sí: 악센트가 있으면 '네/그렇다'는 뜻이라 맞지 않습니다 ✗","si: '~인지 아닌지' 간접의문 → 정답 ✓","que: '~라는 것'이라 모르는 상황(여부)을 표현하지 못합니다 ✗","qué: '무엇을'이라 '갈 수 있을지 여부'에 맞지 않습니다 ✗"]},{"id":"G36","q":"En ese departamento viven más ____ cuatro personas.","o":["a","como","que","de"],"a":3,"k":"más de + 숫자","t":"그 아파트에는 네 명이 넘게 산다.","e":"비교급에서 숫자·수량 앞에서는 que 대신 de를 써서 'más de + 숫자(~이상, ~넘게)'라고 합니다. 예: Tengo más de veinte años.(나는 스무 살이 넘었다.) 참고로 departamento(아파트)는 중남미에서 자주 쓰는 단어입니다.","x":["a: 비교급에 쓰지 않는 전치사입니다 ✗","como: 동등 비교(tan ... como)에 쓰며 más와 함께 쓰지 않습니다 ✗","que: 일반 비교에는 쓰지만 숫자 앞에서는 de로 바뀝니다 ✗","de: 숫자 앞 'más de' → 정답 ✓"]},{"id":"G37","q":"―¿Tienes los apuntes de la clase de historia? ―Sí, ____ tengo aquí.","o":["los","les","las","lo"],"a":0,"k":"직접목적격 대명사","t":"―역사 수업 필기 있어? ―응, 여기 있어.","e":"'apuntes(필기, 노트)'는 남성 복수 명사입니다. '그것을 가지고 있다'의 직접목적어이므로 남성 복수 직접목적격 los를 씁니다.","x":["los: 남성 복수 직접목적격으로 apuntes를 받습니다 → 정답 ✓","les: 간접목적격(그들에게)이라 맞지 않습니다 ✗","las: 여성 복수라 남성 명사 apuntes와 맞지 않습니다 ✗","lo: 단수라 복수 apuntes와 맞지 않습니다 ✗"]},{"id":"G38","q":"Mi amiga Ana nunca ____.","o":["maquilla se","maquillarse","se maquilla","maquillar"],"a":2,"k":"재귀동사 위치","t":"내 친구 아나는 절대 화장을 하지 않는다.","e":"maquillarse(자기 얼굴에 화장하다)는 재귀동사입니다. 활용된 동사와 쓸 때는 재귀대명사 se를 동사 앞에 따로 둡니다: se maquilla. 부정어 nunca는 그 앞에 옵니다.","x":["maquilla se: 활용된 동사 뒤에 대명사를 띄어 쓸 수 없습니다 ✗","maquillarse: 동사원형이라 주어 Ana의 동사가 될 수 없습니다 ✗","se maquilla: 재귀대명사 + 3인칭 단수 활용형 → 정답 ✓","maquillar: 동사원형이고 재귀대명사도 없습니다 ✗"]},{"id":"G39","q":"No hay nadie ____ calle porque hace mal tiempo.","o":["a la","en el","en la","al"],"a":2,"k":"장소 전치사 en","t":"날씨가 나빠서 거리에 아무도 없다.","e":"'~에(장소 안에) 있다'는 전치사 en을 씁니다. calle(거리)는 여성 명사이므로 en la calle입니다. a는 '~로'라는 방향을 나타낼 때 씁니다(Voy a la calle).","x":["a la: '~로'라는 방향이라 '거리에 있다'에 맞지 않습니다 ✗","en el: calle는 여성 명사라 el이 맞지 않습니다 ✗","en la: 장소 en + 여성 정관사 → 정답 ✓","al: 방향의 a + 남성 el이라 성도 의미도 맞지 않습니다 ✗"]},{"id":"G40","q":"Estamos ahorrando para ____ a un sitio mejor.","o":["nos mudar","mudar nos","mudarnos","mudarse"],"a":2,"k":"재귀동사 동사원형","t":"우리는 더 좋은 곳으로 이사 가려고 돈을 모으고 있다.","e":"mudarse(이사하다)는 재귀동사입니다. para 뒤 동사원형에 재귀대명사를 붙일 때는 주어(nosotros)에 맞춰 nos를 끝에 붙입니다: mudarnos. 예: Vamos a levantarnos.(우리 일어나자.)","x":["nos mudar: 동사원형 앞에 대명사를 따로 둘 수 없습니다 ✗","mudar nos: 띄어 쓰지 않고 붙여 써야 합니다 ✗","mudarnos: 주어 nosotros에 맞는 재귀대명사를 붙인 형태 → 정답 ✓","mudarse: se는 3인칭이라 주어 '우리'와 맞지 않습니다 ✗"]},{"id":"G41","q":"Si ____, podemos cenar comida tailandesa esta noche.","o":["querréis","queríais","queréis","queráis"],"a":2,"k":"조건절 si + 직설법 현재","t":"너희가 원하면, 오늘 저녁에 태국 음식을 먹을 수 있어.","e":"실현 가능한 조건 'si(만약 ~라면)'에는 직설법 현재를 씁니다. 이때 si 뒤에 미래형이나 접속법 현재는 쓰지 않습니다. 주어가 vosotros이므로 queréis입니다. 중남미라면 'Si quieren'이라고 합니다.","x":["querréis: si 조건절에는 미래형을 쓰지 않습니다 ✗","queríais: 불완료과거라 현재의 제안 문맥에 맞지 않습니다 ✗","queréis: 실현 가능한 조건의 직설법 현재 → 정답 ✓","queráis: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G42","q":"Mis padres están ____ en este momento.","o":["ocupada","ocupadas","ocupado","ocupados"],"a":3,"k":"형용사 성·수 일치","t":"우리 부모님은 지금 바쁘시다.","e":"형용사는 주어의 성·수에 맞춰야 합니다. padres(부모님)는 아버지와 어머니를 함께 가리키는 남성 복수이므로 ocupados를 씁니다. 남녀가 섞이면 남성 복수를 씁니다.","x":["ocupada: 여성 단수라 복수 주어와 맞지 않습니다 ✗","ocupadas: 여성 복수라 남성 복수 padres와 맞지 않습니다 ✗","ocupado: 단수라 복수 주어와 맞지 않습니다 ✗","ocupados: 남성 복수로 padres와 일치합니다 → 정답 ✓"]},{"id":"G43","q":"Mi abuelo murió cuando mi padre ____ muy joven.","o":["ha sido","fue","estuvo siendo","era"],"a":3,"k":"불완료과거 (배경 묘사)","t":"우리 할아버지는 우리 아버지가 아주 어렸을 때 돌아가셨다.","e":"과거 사건(murió)의 배경이 되는 상태나 나이 묘사는 불완료과거로 씁니다. '아버지가 어렸다'는 그 당시의 상태이므로 era가 맞습니다. 예: Cuando era niño, vivía en Busan.(어렸을 때 부산에 살았다.)","x":["ha sido: 현재완료라 과거 배경 묘사에 맞지 않습니다 ✗","fue: 완결된 사건을 말할 때 써서 '어렸을 때'라는 상태 묘사에 어색합니다 ✗","estuvo siendo: ser는 진행형으로 거의 쓰지 않는 부자연스러운 형태입니다 ✗","era: 과거의 상태(나이) 배경 묘사 → 정답 ✓"]},{"id":"G44","q":"Llegué a casa de Miguel al mediodía, pero ya no ____ allí, se había ido un poco antes.","o":["ha estado","estuvo","estaría","estaba"],"a":3,"k":"불완료과거 (상태)","t":"나는 정오에 미겔의 집에 도착했지만, 그는 이미 거기 없었다. 조금 전에 떠나 버렸던 것이다.","e":"내가 도착한 순간(llegué)의 상황, 즉 '그가 거기 없었다'는 상태는 불완료과거 estaba로 씁니다. 'se había ido(이미 떠났었다)'는 그보다 더 이전의 일이라 과거완료로 씁니다.","x":["ha estado: 현재완료라 과거 이야기와 맞지 않습니다 ✗","estuvo: 일정 기간 완결된 행동을 나타내 '그 순간의 상태' 묘사에 맞지 않습니다 ✗","estaría: 가정·추측(~였을 것이다) 뜻이라 맞지 않습니다 ✗","estaba: 과거 그 순간의 상태 → 정답 ✓"]},{"id":"G45","q":"Este ejercicio es ____ facilísimo.","o":["mucho","ø","muy","mucha"],"a":1,"k":"절대최상급 -ísimo","t":"이 연습 문제는 엄청나게 쉽다.","e":"'-ísimo/-ísima'는 '아주, 엄청나게'라는 뜻이 이미 들어 있는 절대최상급입니다(fácil → facilísimo). 그래서 앞에 muy나 mucho를 다시 붙이지 않습니다. 예: La comida está riquísima.(음식이 정말 맛있어.)","x":["mucho: 형용사 앞에 mucho를 쓰지 않으며 -ísimo와 중복됩니다 ✗","ø: -ísimo 자체에 강조가 있어 아무것도 넣지 않습니다 → 정답 ✓","muy: muy와 -ísimo는 같은 뜻이 겹쳐 함께 쓰지 않습니다 ✗","mucha: 여성형이며 형용사 앞 강조로 쓰지 않습니다 ✗"]},{"id":"G46","q":"¿Qué sueles hacer en el cole ____ hora del recreo?","o":["a","al","el","a la"],"a":3,"k":"a la hora de","t":"너는 학교에서 쉬는 시간에 보통 뭐 하니?","e":"'a la hora de ~'는 '~하는 시간에'라는 뜻입니다. hora(시간)가 여성 명사이므로 a la를 씁니다. cole는 colegio(학교)의 구어 줄임말이고, 'soler + 동사원형'은 '보통 ~하다'는 뜻입니다.","x":["a: 정관사 없이 'a hora del recreo'라고 하지 않습니다 ✗","al: a + el인데 hora는 여성 명사라 맞지 않습니다 ✗","el: 전치사 a가 빠졌고 성도 맞지 않습니다 ✗","a la: 'a la hora de(~ 시간에)' → 정답 ✓"]},{"id":"G47","q":"¿____ está tu mamá?","o":["Cómo","Qué","Quién","Cuál"],"a":0,"k":"의문사 cómo","t":"너희 엄마는 어떻게 지내셔?","e":"estar와 함께 사람의 안부·상태를 물을 때는 '¿Cómo está...?(어떻게 지내요?)'를 씁니다. mamá(엄마)는 중남미에서 특히 많이 쓰는 표현입니다.","x":["Cómo: 상태·안부 '어떻게' → 정답 ✓","Qué: '무엇'이라 안부를 묻는 데 쓰지 않습니다 ✗","Quién: '누구'라 뒤에 tu mamá가 있어 맞지 않습니다 ✗","Cuál: '어느 것'이라 안부 질문에 맞지 않습니다 ✗"]},{"id":"G48","q":"Los perros están ladrando ____ hay un extraño en la puerta principal.","o":["aunque","por eso","para que","porque"],"a":3,"k":"이유 접속사 porque","t":"정문에 낯선 사람이 있어서 개들이 짖고 있다.","e":"개들이 짖는 '이유'가 뒤에 나오므로 porque(~때문에)를 씁니다. por eso(그래서)는 앞 내용이 원인이고 뒤가 결과일 때 씁니다(Hay un extraño, por eso ladran).","x":["aunque: '비록 ~이지만'이라 이유 관계가 아닙니다 ✗","por eso: '그래서'라 원인과 결과 순서가 반대가 됩니다 ✗","para que: '~하도록'이라는 목적이며 뒤에 접속법이 와야 합니다 ✗","porque: 짖는 이유를 연결합니다 → 정답 ✓"]},{"id":"G49","q":"Nuestro vuelo sale ____ las 11 en punto.","o":["por","de","en","a"],"a":3,"k":"시각 표현 a las","t":"우리 비행기는 정각 11시에 출발한다.","e":"'몇 시에'는 'a + las + 숫자'로 나타냅니다. 'en punto'는 '정각'이라는 뜻입니다. 예: La clase empieza a las nueve en punto.(수업은 9시 정각에 시작한다.)","x":["por: 'por la mañana(오전에)'처럼 시간대에 쓰며 정확한 시각엔 쓰지 않습니다 ✗","de: 'las 11 de la noche'처럼 쓰지만 '~시에'를 나타내지 못합니다 ✗","en: 시각 앞에는 en을 쓰지 않습니다 ✗","a: 시각 앞 '~에' → 정답 ✓"]},{"id":"G50","q":"Voy a llamar ____ profesor de mi hija, quiero preguntarle algo.","o":["el","al","a la","a"],"a":1,"k":"인칭 a + 정관사 축약","t":"딸의 선생님께 전화할 거야, 여쭤볼 게 있어서.","e":"사람을 직접목적어로 받을 때는 앞에 전치사 a를 씁니다(인칭 a). 'a + el profesor'는 축약해서 al profesor가 됩니다. profesor는 남성 명사라 a la는 맞지 않습니다.","x":["el: 사람 목적어 앞에 필요한 a가 빠졌습니다 ✗","al: 인칭 a + el의 축약형 → 정답 ✓","a la: 여성 정관사라 남성 profesor와 맞지 않습니다 ✗","a: 정관사가 빠져 'a profesor'는 어색합니다 ✗"]},{"id":"G51","q":"Mi nombre es Alfonso, soy de Barcelona y ____ 26 años.","o":["soy","estoy","tengo","es"],"a":2,"k":"나이 표현 tener","t":"내 이름은 알폰소이고, 바르셀로나 출신이며 26살이다.","e":"스페인어로 나이는 'tener + 숫자 + años'로 말합니다(직역하면 '~해를 가지고 있다'). ser나 estar를 쓰지 않는다는 점에 주의하세요. 예: ¿Cuántos años tienes?(몇 살이니?)","x":["soy: ser로는 나이를 말하지 않습니다 ✗","estoy: estar로는 나이를 말하지 않습니다 ✗","tengo: tener + 숫자 + años = 나이 → 정답 ✓","es: 3인칭이고 나이 표현에도 쓰지 않습니다 ✗"]},{"id":"G52","q":"En verano siempre ____ camisetas de manga corta.","o":["pongo","me pongo","estoy poniendo","ponerme"],"a":1,"k":"재귀동사 ponerse","t":"여름에는 나는 항상 반팔 티셔츠를 입는다.","e":"ponerse는 '(옷을 자기 몸에) 입다'라는 재귀동사입니다. 재귀대명사 없이 poner만 쓰면 '(물건을) 놓다'라는 뜻이 됩니다. 'siempre(항상)'는 습관이므로 현재형 me pongo가 알맞습니다.","x":["pongo: 재귀대명사가 없어 '놓다'라는 뜻이 됩니다 ✗","me pongo: 습관적으로 '(내가) 입는다' → 정답 ✓","estoy poniendo: 진행형이라 '항상'이라는 습관과 맞지 않고 재귀대명사도 없습니다 ✗","ponerme: 동사원형이라 문장의 동사가 될 수 없습니다 ✗"]},{"id":"G53","q":"Adiós, abuela, que ____.","o":["te mejoras","te mejores","que mejoras","mejorarte"],"a":1,"k":"기원문 que + 접속법","t":"안녕히 계세요, 할머니. 얼른 나으세요.","e":"'Que + 접속법'은 '~하기를 바라요'라는 기원(바람) 표현입니다. mejorarse(병이 낫다)의 tú 접속법 현재는 te mejores입니다. 예: ¡Que te vaya bien!(잘 지내!), ¡Que aproveche!(맛있게 드세요!)","x":["te mejoras: 직설법이라 바람을 나타내지 못합니다 ✗","te mejores: 기원의 que + 접속법 현재 → 정답 ✓","que mejoras: que가 중복되고 직설법이며 재귀대명사도 없습니다 ✗","mejorarte: 동사원형이라 que 뒤에 올 수 없습니다 ✗"]},{"id":"G54","q":"A mis sobrinos ____ encanta esta serie de dibujos animados.","o":["los","se","le","les"],"a":3,"k":"encantar 구문","t":"내 조카들은 이 만화 시리즈를 무척 좋아한다.","e":"encantar(무척 좋아하다)는 gustar와 같은 구조로, 좋아하는 사람을 간접목적격 대명사로 씁니다. 'A mis sobrinos(내 조카들에게)'는 3인칭 복수이므로 les를 씁니다.","x":["los: 직접목적격이라 encantar 구문에 쓰지 않습니다 ✗","se: 재귀·무인칭 대명사라 이 구조와 맞지 않습니다 ✗","le: 3인칭 단수라 복수 sobrinos와 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격 → 정답 ✓"]},{"id":"G55","q":"En este pueblo no hay tantos servicios ____ en el mío.","o":["de","a","que","como"],"a":3,"k":"동등비교 tanto como","t":"이 마을에는 우리 마을만큼 시설이 많지 않다.","e":"동등 비교(~만큼)는 'tanto/tanta/tantos/tantas + 명사 + como'로 씁니다. 앞에 tantos가 나왔으므로 뒤에는 반드시 como가 짝을 이룹니다. 예: No tengo tantos libros como tú.(나는 너만큼 책이 많지 않아.)","x":["de: 동등 비교에 쓰지 않습니다 ✗","a: 비교 표현에 쓰지 않습니다 ✗","que: más/menos 비교에 쓰며 tanto와 짝이 아닙니다 ✗","como: tanto ... como(~만큼) → 정답 ✓"]},{"id":"G56","q":"No me pasa nada, ____ gracias por preguntar.","o":["porque","en cambio","pero","sino"],"a":2,"k":"접속사 pero","t":"나 아무 일 없어, 그래도 물어봐 줘서 고마워.","e":"pero(하지만, 그래도)는 앞 내용과 대조되는 말을 이어 줍니다. '아무 일 없다' + '그래도 물어봐 줘서 고맙다'는 흐름에 자연스럽습니다. sino는 'no A sino B(A가 아니라 B)'처럼 앞을 부정하고 바로잡을 때 씁니다.","x":["porque: '왜냐하면'이라 감사 인사와 이유 관계가 아닙니다 ✗","en cambio: '반면에'라는 강한 대조로 여기에 어색합니다 ✗","pero: '그래도'로 자연스럽게 이어 줍니다 → 정답 ✓","sino: 앞의 명사·내용을 바로잡을 때만 써서 맞지 않습니다 ✗"]},{"id":"G57","q":"La casa está patas arriba. ¿Qué ____ todo el día?","o":["hacíais","habéis estado haciendo","estabais haciendo","habíais hecho"],"a":1,"k":"현재완료 진행형","t":"집이 엉망진창이네. 너희 하루 종일 뭐 하고 있었니?","e":"'todo el día(하루 종일)' 지금까지 계속된 행동을 물을 때는 현재완료 진행형 'haber + estado + 현재분사'를 씁니다. 지금 눈앞의 결과(집이 엉망)와 연결된 최근 일이라 현재완료가 알맞습니다. 'patas arriba'는 '엉망진창인'이라는 관용 표현입니다.","x":["hacíais: 과거 습관·배경이라 지금의 결과와 연결되지 않습니다 ✗","habéis estado haciendo: 지금까지 계속된 행동 → 정답 ✓","estabais haciendo: 과거 특정 순간의 진행이라 지금과 연결되지 않습니다 ✗","habíais hecho: 과거완료라 과거의 더 이전 일을 말할 때 씁니다 ✗"]},{"id":"G58","q":"Alberto ____ Irene son novios desde hace cinco años.","o":["o","e","y","con"],"a":1,"k":"y → e 변화","t":"알베르토와 이레네는 5년 전부터 연인 사이다.","e":"접속사 y(그리고)는 다음 단어가 i- 또는 hi- 소리로 시작하면 발음이 겹치지 않도록 e로 바뀝니다. Irene은 i로 시작하므로 'Alberto e Irene'이 됩니다. 예: padre e hijo(아버지와 아들).","x":["o: '또는'이라 둘 다 연인이라는 뜻이 안 됩니다 ✗","e: i 소리 앞에서 y가 바뀐 형태 → 정답 ✓","y: 뒤 단어가 i로 시작해서 e로 바꿔야 합니다 ✗","con: '~와 함께'라 동사 son(복수)과 맞지 않습니다 ✗"]},{"id":"G59","q":"Abel no puede ponerse al teléfono ahora, ____.","o":["se ducha","está duchando","está duchándose","ducha"],"a":2,"k":"재귀동사 진행형","t":"아벨은 지금 전화를 받을 수 없어, 샤워하는 중이야.","e":"ducharse(샤워하다)는 재귀동사이므로 진행형에서도 재귀대명사가 필요합니다. 현재분사 뒤에 붙이면 duchándose가 되고, 강세 유지를 위해 악센트(á)를 찍습니다. 'se está duchando'라고 써도 같은 뜻입니다.","x":["se ducha: 현재형이라 '지금 하는 중'의 진행 의미가 약합니다 ✗","está duchando: 재귀대명사 se가 빠져 '(누군가를) 씻기는 중'이 됩니다 ✗","está duchándose: 재귀동사의 현재진행형 → 정답 ✓","ducha: 재귀대명사가 없고 진행 의미도 없습니다 ✗"]},{"id":"G60","q":"Cuando mi hermana ____ un bebé, le daba miedo todo.","o":["estuvo siendo","ha sido","fue","era"],"a":3,"k":"불완료과거 (배경 묘사)","t":"우리 언니(누나)는 아기였을 때 모든 걸 무서워했다.","e":"과거의 시기(아기였을 때)를 묘사할 때는 불완료과거를 씁니다. 주절의 daba(불완료과거)도 그 시절의 반복된 상태를 나타냅니다. 'Cuando + 불완료과거'는 '~였을 때(그 시절)'라는 배경 표현입니다.","x":["estuvo siendo: ser는 진행형으로 거의 쓰지 않습니다 ✗","ha sido: 현재완료라 과거 시절 묘사에 맞지 않습니다 ✗","fue: 완결된 사건을 나타내 '아기였던 시절'의 묘사에 어색합니다 ✗","era: 과거 시절의 상태 묘사 → 정답 ✓"]},{"id":"G61","q":"¿Podría traerme ____ tenedor? Este está sucio.","o":["otro","un otro","a otro","uno otro"],"a":0,"k":"otro 용법","t":"포크 하나 더 가져다주실 수 있나요? 이건 더러워요.","e":"otro(다른, 또 하나의)는 앞에 부정관사 un을 붙이지 않습니다. 'un otro tenedor'는 영어 'another'를 직역한 흔한 실수입니다. 그냥 'otro tenedor'라고 합니다. 예: ¿Quieres otro café?(커피 한 잔 더 할래?)","x":["otro: 관사 없이 '또 하나의' → 정답 ✓","un otro: otro 앞에는 부정관사를 쓰지 않습니다 ✗","a otro: 사물인 tenedor 앞에 인칭 a를 쓰지 않습니다 ✗","uno otro: 문법적으로 틀린 표현입니다 ✗"]},{"id":"G62","q":"Tengo una cita con el abogado ____ once y media de la mañana.","o":["las","a","al","a las"],"a":3,"k":"시각 표현 a las","t":"나는 오전 11시 반에 변호사와 약속이 있다.","e":"'~시에'는 'a las + 숫자'로 말하고, 30분은 'y media'를 붙입니다. 'a las once y media de la mañana'는 '오전 11시 반에'라는 뜻입니다.","x":["las: '~에'를 나타내는 전치사 a가 빠졌습니다 ✗","a: 시각 앞에 정관사 las가 필요합니다 ✗","al: 시각은 여성(horas)이라 a + el을 쓰지 않습니다 ✗","a las: 2시 이상의 시각 '~시에' → 정답 ✓"]},{"id":"G63","q":"He estado estudiando ____ mañana y, pese a todo, no me acuerdo de nada.","o":["todo el","toda la","toda","todos"],"a":1,"k":"todo + 정관사 + 명사","t":"아침 내내 공부했는데도, 아무것도 기억이 안 난다.","e":"'todo/toda + 정관사 + 명사'는 '~ 내내, ~ 전체'라는 뜻입니다. mañana(아침, 오전)는 여성 명사이므로 'toda la mañana'가 됩니다. 예: todo el día(하루 종일), toda la noche(밤새도록).","x":["todo el: mañana는 여성 명사라 남성형이 맞지 않습니다 ✗","toda la: 여성 단수 todo + 정관사, '아침 내내' → 정답 ✓","toda: 정관사 la가 빠지면 '~내내'의 뜻이 되지 않습니다 ✗","todos: 남성 복수라 단수 여성 명사와 맞지 않습니다 ✗"]},{"id":"G64","q":"¿De quién ____ estas zapatillas?","o":["es","son","está","están"],"a":1,"k":"소유 표현 ser de","t":"이 운동화는 누구 거예요?","e":"'~의 것이다(소유)'는 'ser de + 사람'으로 나타냅니다. 주어 'estas zapatillas(이 운동화들)'가 복수이므로 동사도 복수 son이 됩니다. 예: ¿De quién es este libro?(이 책 누구 거야?)","x":["es: 단수라 복수 주어 zapatillas와 맞지 않습니다 ✗","son: 소유의 ser + 복수 주어에 일치 → 정답 ✓","está: 소유는 estar로 나타내지 않습니다 ✗","están: 소유는 estar로 나타내지 않습니다 ✗"]},{"id":"G65","q":"Hoy ____ domingo, por eso no tenemos que ir a la escuela.","o":["está","está el","es el","es"],"a":3,"k":"요일 표현 ser","t":"오늘은 일요일이라서 우리는 학교에 가지 않아도 된다.","e":"'오늘은 ~요일이다'는 'Hoy es + 요일'로 말하고 관사를 붙이지 않습니다. 요일 앞에 정관사를 쓰면 '~요일에'라는 뜻이 됩니다(El domingo voy al cine: 일요일에 영화관에 간다). 'Estamos a domingo'라고도 할 수 있지만 está는 쓰지 않습니다.","x":["está: 요일을 말할 때 3인칭 단수 está는 쓰지 않습니다 ✗","está el: 요일 표현에 맞지 않는 형태입니다 ✗","es el: '오늘은 ~요일이다'에는 정관사를 쓰지 않습니다 ✗","es: Hoy es + 요일 → 정답 ✓"]},{"id":"G66","q":"Vengo en un momentito, voy ____ tirar la basura.","o":["ø","a","por","de"],"a":1,"k":"ir a + 동사원형","t":"금방 올게, 쓰레기 버리러 가.","e":"'ir a + 동사원형'은 '~하러 가다'라는 뜻입니다. voy 뒤에 동사원형 tirar가 오려면 전치사 a가 필요합니다. 'tirar la basura'는 '쓰레기를 버리다'입니다. momentito는 momento에 축소사 -ito를 붙인 정겨운 표현입니다.","x":["ø: ir 뒤에 동사원형을 바로 붙일 수 없습니다 ✗","a: ir a + 동사원형(~하러 가다) → 정답 ✓","por: 'ir por'는 '~를 가지러 가다'로 명사가 와야 합니다 ✗","de: ir와 동사원형을 이어 주지 못합니다 ✗"]},{"id":"G67","q":"El aceite de oliva es ____ sano que otros aceites.","o":["igual","más","tan","tanto"],"a":1,"k":"비교급 más que","t":"올리브유는 다른 기름들보다 더 건강하다.","e":"우등 비교(~보다 더 ~한)는 'más + 형용사 + que'로 씁니다. 뒤에 que가 나왔으므로 más가 짝입니다. 동등 비교 tan은 como와 짝을 이룹니다(tan sano como).","x":["igual: 'igual de sano que'처럼 써야 하므로 형태가 맞지 않습니다 ✗","más: más ... que(~보다 더) → 정답 ✓","tan: tan은 como와 짝을 이루므로 que와 쓸 수 없습니다 ✗","tanto: 형용사 앞에서는 tan을 쓰며 que와도 맞지 않습니다 ✗"]},{"id":"G68","q":"―¿Les llevaste las bebidas a esos clientes? ―Sí, ____ llevé hace rato.","o":["les las","se las","se los","le las"],"a":1,"k":"le → se 변환","t":"―그 손님들에게 음료 가져다드렸어? ―응, 한참 전에 가져다드렸어.","e":"간접목적격(les: 그들에게)과 직접목적격(las: 그것들을)이 함께 오면, le/les는 se로 바뀝니다. bebidas(음료)는 여성 복수이므로 las를 써서 'se las llevé'가 됩니다. 순서는 항상 '간접 + 직접'입니다.","x":["les las: les와 las를 함께 쓸 때는 les를 se로 바꿔야 합니다 ✗","se las: les → se, 여성 복수 bebidas → las → 정답 ✓","se los: bebidas는 여성이라 los가 맞지 않습니다 ✗","le las: le도 직접목적격 앞에서는 se로 바뀌어야 합니다 ✗"]},{"id":"G69","q":"No sabía que Íñigo se había independizado. ¿Vosotros ____ sabíais?","o":["lo","ø","los","le"],"a":0,"k":"중성 대명사 lo","t":"이니고가 독립한 줄 몰랐어. 너희는 알고 있었니?","e":"앞 문장의 내용 전체(이니고가 독립했다는 사실)를 받을 때는 중성 직접목적격 lo를 씁니다. 'saber(알다)' 다음에 '그 사실을'을 lo로 나타냅니다. 예: ―¿Sabes que se casa? ―Sí, lo sé.(―그가 결혼하는 거 알아? ―응, 알아.)","x":["lo: 앞 문장 내용을 받는 중성 대명사 → 정답 ✓","ø: 스페인어에서는 '그것을'을 lo로 넣어 주는 것이 자연스럽습니다 ✗","los: 복수형이라 하나의 사실을 받을 수 없습니다 ✗","le: 간접목적격이라 '그 사실을'을 받지 못합니다 ✗"]},{"id":"G70","q":"¿____ usted le gusta el marisco?","o":["A","De","ø","Para"],"a":0,"k":"gustar의 a+사람","t":"해산물 좋아하세요?","e":"gustar 구문에서 좋아하는 사람을 강조하거나 분명히 할 때 'a + 사람'을 앞에 둡니다. le는 '그/그녀/당신에게'로 뜻이 여러 가지이므로 'A usted'를 넣어 '당신'임을 분명히 합니다.","x":["A: gustar 구문의 'a + 사람' → 정답 ✓","De: gustar의 경험자를 나타내지 못합니다 ✗","ø: 'Usted le gusta'는 usted가 주어처럼 보여 틀린 문장이 됩니다 ✗","Para: '~을 위해'라 gustar 구문에 쓰지 않습니다 ✗"]},{"id":"G71","q":"Anoche ____ varios accidentes en esa carretera.","o":["hubo","habrá","hubieron","hay"],"a":0,"k":"hubo (haber 과거)","t":"어젯밤 그 도로에서 사고가 여러 건 있었다.","e":"존재를 나타내는 haber(hay)는 뒤의 명사가 복수여도 항상 단수형을 씁니다. 'Anoche(어젯밤)'처럼 끝난 과거 사건이므로 단순과거 hubo가 알맞습니다. 'hubieron'은 원어민도 가끔 쓰지만 표준 문법에서는 틀린 형태입니다.","x":["hubo: 존재 haber의 단순과거, 항상 단수 → 정답 ✓","habrá: 미래형이라 anoche와 맞지 않습니다 ✗","hubieron: 존재의 haber는 복수로 쓰지 않아 표준어에서 틀립니다 ✗","hay: 현재형이라 anoche와 맞지 않습니다 ✗"]},{"id":"G72","q":"Necesito ____ un favor.","o":["te pedir","que te pido","pedirte","te pido"],"a":2,"k":"동사원형 + 대명사","t":"너한테 부탁 하나 해야 해.","e":"necesitar 뒤에는 동사원형이 오고, 목적격 대명사 te(너에게)는 동사원형 끝에 붙여 한 단어로 씁니다: pedir + te → pedirte. 'pedir un favor'는 '부탁하다'라는 표현입니다.","x":["te pedir: 동사원형 앞에 대명사를 따로 둘 수 없습니다 ✗","que te pido: 주어가 같으므로 que절을 쓰지 않습니다 ✗","pedirte: 동사원형에 te를 붙인 올바른 형태 → 정답 ✓","te pido: 활용된 동사가 연달아 올 수 없습니다 ✗"]},{"id":"G73","q":"¿Dónde está el banco ____ cercano?","o":["mucho","muy","el más","más"],"a":3,"k":"최상급","t":"가장 가까운 은행이 어디예요?","e":"최상급(가장 ~한)은 '정관사 + 명사 + más + 형용사'로 씁니다. 이미 'el banco'에 정관사가 있으므로 뒤에는 más만 넣습니다: el banco más cercano. 예: la chica más alta(가장 키 큰 소녀).","x":["mucho: 형용사 앞에 mucho를 쓰지 않습니다 ✗","muy: '매우 가까운'이라 '가장 가까운'의 최상급이 되지 않습니다 ✗","el más: 정관사가 이미 banco 앞에 있어 중복됩니다 ✗","más: 정관사 + 명사 + más + 형용사 → 정답 ✓"]},{"id":"G74","q":"Podemos hacer otra cosa ____ no te apetece este plan.","o":["para que","si","como","así que"],"a":1,"k":"조건 접속사 si","t":"이 계획이 마음에 안 들면 다른 걸 할 수 있어.","e":"si(만약 ~라면)는 조건을 나타냅니다. '이 계획이 내키지 않으면' 다른 것을 할 수 있다는 조건 관계이므로 si가 알맞습니다. apetecer(~하고 싶다, 내키다)는 gustar처럼 쓰이는 동사로 스페인에서 많이 씁니다.","x":["para que: '~하도록'이라는 목적이며 접속법이 필요합니다 ✗","si: '만약 ~라면'의 조건 → 정답 ✓","como: 조건의 como는 접속법과 함께 써야 하고 의미도 어색합니다 ✗","así que: '그러니까'라는 결과 표현이라 맞지 않습니다 ✗"]},{"id":"G75","q":"Nunca olvides que te queremos ____.","o":["mucho","tan","muchísima","muy"],"a":0,"k":"mucho vs muy","t":"우리가 너를 많이 사랑한다는 걸 절대 잊지 마.","e":"동사(queremos)를 꾸밀 때는 부사 mucho(많이)를 씁니다. muy는 형용사·부사 앞에서만 씁니다(muy bonito). 'querer a alguien'은 '누군가를 사랑하다'라는 뜻입니다.","x":["mucho: 동사를 꾸미는 부사 '많이' → 정답 ✓","tan: '그렇게'라는 뜻으로 비교 대상 없이 혼자 쓰면 어색합니다 ✗","muchísima: 여성형 형용사라 동사를 꾸밀 수 없습니다 ✗","muy: 동사 뒤에 혼자 쓸 수 없습니다 ✗"]},{"id":"G76","q":"No tengo diccionario, ____ ha llevado Cristina.","o":["se","se lo","la","lo"],"a":1,"k":"se lo (가져가다)","t":"나 사전이 없어, 크리스티나가 가져가 버렸거든.","e":"llevarse는 '가져가 버리다'라는 뜻의 재귀형입니다. se(재귀) + lo(그것을 = 사전)를 함께 써서 'se lo ha llevado(그것을 가져가 버렸다)'가 됩니다. diccionario는 남성 단수라 lo입니다.","x":["se: '그것을'에 해당하는 lo가 빠져 무엇을 가져갔는지 나타나지 않습니다 ✗","se lo: 재귀 se + 직접목적격 lo(사전) → 정답 ✓","la: 여성형이라 남성 명사 diccionario와 맞지 않습니다 ✗","lo: 문법적으로 가능하지만 '가져가 버렸다'는 llevarse의 se가 빠져 덜 자연스럽습니다 ✗"]},{"id":"G77","q":"No se siente bien ____ ha comido demasiado.","o":["porque","y que","que","aunque"],"a":0,"k":"이유 접속사 porque","t":"그는 너무 많이 먹어서 몸이 좋지 않다.","e":"porque(~때문에)는 앞 문장의 이유를 설명합니다. '몸이 안 좋다'의 이유가 '너무 많이 먹었다'이므로 porque가 맞습니다. 'sentirse bien'은 '몸·기분이 좋다'라는 뜻입니다.","x":["porque: 이유를 연결하는 접속사 → 정답 ✓","y que: 이런 연결 표현은 쓰지 않습니다 ✗","que: 구어에서 이유로 쓰기도 하지만 표준적인 선택은 porque입니다 ✗","aunque: '비록 ~이지만'이라 의미가 반대로 됩니다 ✗"]},{"id":"G78","q":"¿____ está el gato?","o":["Cuándo","Dónde","Cuánto","Qué"],"a":1,"k":"의문사 dónde","t":"고양이 어디 있어?","e":"estar로 위치를 물을 때는 '¿Dónde está...?(어디에 있어?)'를 씁니다. 예: ¿Dónde está el baño?(화장실이 어디예요?)","x":["Cuándo: '언제'라 위치를 묻지 못합니다 ✗","Dónde: 위치 '어디' → 정답 ✓","Cuánto: '얼마나'라 맞지 않습니다 ✗","Qué: '무엇'이라 위치 질문에 맞지 않습니다 ✗"]},{"id":"G79","q":"____ no me gusta nadar en la piscina comunitaria, pero a mis vecinos sí.","o":["A mí","Mí","Mi","Yo"],"a":0,"k":"강조형 a mí","t":"나는 공동 수영장에서 수영하는 걸 좋아하지 않지만, 우리 이웃들은 좋아한다.","e":"gustar 구문에서 사람을 강조하거나 대조할 때 'a + 전치격 대명사'를 씁니다. '나'는 'a mí'(악센트 있음)입니다. 뒤의 'a mis vecinos sí'와 대조를 이루어 꼭 필요합니다.","x":["A mí: gustar 구문의 강조형 '나에게는' → 정답 ✓","Mí: 전치사 a가 빠졌습니다 ✗","Mi: 악센트 없는 mi는 소유형용사 '나의'입니다 ✗","Yo: 주격이라 gustar 구문에 쓰지 않습니다 ✗"]},{"id":"G80","q":"Mi ex y yo ____ separamos porque teníamos demasiados problemas de pareja.","o":["nosotros","ø","nos los","nos"],"a":3,"k":"재귀동사 separarse","t":"전 애인과 나는 연애 문제가 너무 많아서 헤어졌다.","e":"separarse(헤어지다)는 재귀동사입니다. 주어 'Mi ex y yo(전 애인과 나)'는 '우리(nosotros)'이므로 재귀대명사 nos를 씁니다: nos separamos.","x":["nosotros: 주격 대명사라 재귀대명사 자리에 쓸 수 없습니다 ✗","ø: 재귀대명사가 빠지면 '(무언가를) 분리했다'는 뜻이 됩니다 ✗","nos los: 불필요한 직접목적격 los가 들어갔습니다 ✗","nos: 주어 '우리'에 맞는 재귀대명사 → 정답 ✓"]},{"id":"G81","q":"Ayer estuvimos ____ 40 grados. ¡Qué calor!","o":["desde","en","a","por"],"a":2,"k":"온도 표현 estar a","t":"어제는 40도였어. 정말 덥다!","e":"기온을 말할 때는 'estar a + 온도'를 씁니다. 'Estamos a 40 grados'는 '(지금) 40도이다'라는 뜻입니다. 같은 구조로 날짜도 'Estamos a 5 de mayo(5월 5일이다)'라고 합니다.","x":["desde: '~부터'라 기온 표현에 맞지 않습니다 ✗","en: 기온 앞에는 en을 쓰지 않습니다 ✗","a: estar a + 온도 → 정답 ✓","por: '~ 무렵'이라 정확한 기온 표현이 아닙니다 ✗"]},{"id":"G82","q":"¿Qué hacen ellos aquí? ¿Quién ____ ha invitado?","o":["lo","las","le","los"],"a":3,"k":"직접목적격 대명사","t":"그들이 여기서 뭐 하는 거야? 누가 그들을 초대했어?","e":"invitar(초대하다)의 대상 '그들을'은 직접목적어입니다. ellos(그들)는 남성 복수이므로 직접목적격 los를 씁니다. 스페인 일부 지역에서는 남자 사람에게 le/les를 쓰는 레이스모(leísmo)도 있지만, 표준은 los입니다.","x":["lo: 단수라 복수 ellos와 맞지 않습니다 ✗","las: 여성 복수라 ellos와 맞지 않습니다 ✗","le: 간접목적격 단수라 맞지 않습니다 ✗","los: 남성 복수 직접목적격 → 정답 ✓"]},{"id":"G83","q":"Nos vemos ____ parque en una hora. ¡Hasta luego!","o":["a","en el","al","en"],"a":1,"k":"장소 전치사 en","t":"한 시간 후에 공원에서 보자. 이따 봐!","e":"'~에서 만나다/보다'처럼 장소 안에서 일어나는 일은 en을 씁니다. parque(공원)는 남성 명사라 'en el parque'입니다. al은 방향(~로)을 나타냅니다(Vamos al parque).","x":["a: 방향을 나타내며 관사도 빠졌습니다 ✗","en el: 장소 en + 남성 정관사 → 정답 ✓","al: '공원으로'라는 방향이라 '공원에서 보자'에 맞지 않습니다 ✗","en: 정관사 el이 빠졌습니다 ✗"]},{"id":"G84","q":"Raquel ____ al tenis cuando era pequeña.","o":["jugaría","jugó","estaba jugando","jugaba"],"a":3,"k":"불완료과거 (과거 습관)","t":"라켈은 어렸을 때 테니스를 치곤 했다.","e":"'cuando era pequeña(어렸을 때)'처럼 과거의 한 시절에 반복적으로 하던 일은 불완료과거로 나타냅니다. jugar의 불완료과거 3인칭 단수는 jugaba입니다. 운동 경기 앞에는 'jugar al + 운동'을 씁니다.","x":["jugaría: 가정미래(~할 것이다)라 과거 습관이 아닙니다 ✗","jugó: 한 번의 완결된 행동이라 '어렸을 때 하곤 했다'에 맞지 않습니다 ✗","estaba jugando: 특정 순간의 진행이라 시절의 습관과 맞지 않습니다 ✗","jugaba: 과거 시절의 습관 → 정답 ✓"]},{"id":"G85","q":"____, Carla, ¿puedes ayudarme a hacer esta actividad?","o":["Perdone","Perdona","Perdonas","Perdones"],"a":1,"k":"tú 명령형","t":"미안, 카를라, 이 활동 하는 거 도와줄 수 있어?","e":"이름(Carla)을 부르고 '¿puedes?(할 수 있어?)'라고 tú로 말하므로 tú 긍정명령형 perdona를 씁니다. tú 긍정명령은 대부분 직설법 현재 3인칭 단수와 형태가 같습니다(habla, come, perdona).","x":["Perdone: usted 명령형이라 tú로 말하는 puedes와 맞지 않습니다 ✗","Perdona: tú 긍정명령형 → 정답 ✓","Perdonas: 직설법 현재라 명령이 아닙니다 ✗","Perdones: tú 부정명령(no perdones)에만 씁니다 ✗"]},{"id":"G86","q":"____ clima de esta región es simplemente maravilloso.","o":["El","La","Al","Lo"],"a":0,"k":"-ma 남성 명사","t":"이 지역의 기후는 그야말로 훌륭하다.","e":"clima(기후)는 -a로 끝나지만 남성 명사입니다. 그리스어에서 온 -ma 단어 중에 이런 경우가 많습니다: el problema(문제), el tema(주제), el idioma(언어). 그래서 정관사 el을 씁니다.","x":["El: clima는 남성 명사 → 정답 ✓","La: -a로 끝나도 clima는 남성이라 틀립니다 ✗","Al: a + el이라 주어 앞에 쓸 수 없습니다 ✗","Lo: 중성 관사로 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G87","q":"No me importa que ____ con tus amigos, al contrario.","o":["estás viniendo","vendrás","vienes","vengas"],"a":3,"k":"감정 동사 + 접속법","t":"네가 친구들과 오는 건 상관없어, 오히려 좋아.","e":"'No me importa que(~해도 상관없다)'처럼 감정·평가를 나타내는 표현 뒤 que절에는 접속법을 씁니다. venir의 tú 접속법 현재는 vengas입니다. 'al contrario'는 '오히려, 반대로'라는 뜻입니다.","x":["estás viniendo: 직설법 진행형이라 감정 표현 뒤에 쓸 수 없습니다 ✗","vendrás: 직설법 미래라 맞지 않습니다 ✗","vienes: 직설법 현재라 importar que 뒤에 쓸 수 없습니다 ✗","vengas: 감정 표현 뒤 접속법 현재 → 정답 ✓"]},{"id":"G88","q":"¿Por qué ____ ropa de invierno con el calor que hace?","o":["la pones","tú pones","te pones","pones"],"a":2,"k":"재귀동사 ponerse","t":"이렇게 더운데 왜 겨울옷을 입니?","e":"'(옷을) 입다'는 재귀동사 ponerse를 씁니다. 주어가 tú이므로 'te pones'가 됩니다. 재귀대명사 없이 pones만 쓰면 '놓다'라는 뜻이 됩니다. 'con el calor que hace'는 '이렇게 더운데'라는 표현입니다.","x":["la pones: 직접목적격 la가 들어가 '그것을 놓다'가 되어 ropa와 중복됩니다 ✗","tú pones: 재귀대명사가 없어 '입다'의 뜻이 안 됩니다 ✗","te pones: tú의 재귀형 '(네가) 입다' → 정답 ✓","pones: 재귀대명사가 없어 '놓다'라는 뜻입니다 ✗"]},{"id":"G89","q":"No ____ las comidas muy picantes.","o":["me gustar","me gusto","gusto","me gustan"],"a":3,"k":"gustar + 복수 명사","t":"나는 아주 매운 음식을 좋아하지 않는다.","e":"gustar는 '좋아하는 대상'이 문법상 주어입니다. 'las comidas muy picantes(아주 매운 음식들)'가 복수이므로 동사도 복수 gustan을 씁니다. 좋아하는 사람 '나'는 me로 나타냅니다.","x":["me gustar: 동사원형이라 문장의 동사가 될 수 없습니다 ✗","me gusto: '나는 (나 자신이) 마음에 든다'는 뜻이 됩니다 ✗","gusto: 간접목적격이 없고 '내가 남에게 호감을 준다'는 뜻이 됩니다 ✗","me gustan: 복수 주어에 맞춘 gustan → 정답 ✓"]},{"id":"G90","q":"Nosotros vamos a preparar la comida y vosotros ____ ir a comprar el postre.","o":["pueden","podéis","puedes","podáis"],"a":1,"k":"vosotros 동사 활용","t":"우리는 음식을 준비할 테니 너희는 디저트를 사러 가면 돼.","e":"주어가 vosotros(너희)이므로 poder의 vosotros 직설법 현재 형태 podéis를 씁니다. 중남미에서는 vosotros 대신 ustedes를 써서 'ustedes pueden'이라고 합니다. 이 문장은 vosotros를 쓰는 스페인식입니다.","x":["pueden: ustedes/ellos 형태라 vosotros와 맞지 않습니다 ✗","podéis: vosotros 직설법 현재 → 정답 ✓","puedes: tú 형태라 맞지 않습니다 ✗","podáis: 접속법이라 단순 진술에 맞지 않습니다 ✗"]},{"id":"G91","q":"Mi piso de estudiante ____ oscuro y frío.","o":["era","había sido","estaba siendo","fue"],"a":0,"k":"불완료과거 (묘사)","t":"내 학생 시절 아파트는 어둡고 추웠다.","e":"과거의 장소·사물의 모습을 묘사할 때는 불완료과거를 씁니다. '어둡고 추웠다'는 그 시절 집의 특징이므로 era가 알맞습니다. piso는 스페인에서 '아파트'를 뜻하는 말입니다.","x":["era: 과거의 모습·특징 묘사 → 정답 ✓","había sido: 과거완료라 다른 과거보다 더 이전 일을 말할 때 씁니다 ✗","estaba siendo: ser 진행형은 묘사에 쓰지 않습니다 ✗","fue: 완결된 사건을 말할 때 써서 배경 묘사에 어색합니다 ✗"]},{"id":"G92","q":"No tengo ganas ____ comer, merendé hace un rato.","o":["por","a","de","para"],"a":2,"k":"tener ganas de","t":"아까 간식을 먹어서 먹고 싶은 생각이 없다.","e":"'tener ganas de + 동사원형'은 '~하고 싶다'라는 뜻의 관용 표현입니다. 전치사는 항상 de입니다. merendar는 '오후 간식을 먹다'라는 뜻입니다. 예: Tengo ganas de verte.(너 보고 싶어.)","x":["por: tener ganas와 함께 쓰지 않습니다 ✗","a: tener ganas와 함께 쓰지 않습니다 ✗","de: tener ganas de + 동사원형 → 정답 ✓","para: tener ganas와 함께 쓰지 않습니다 ✗"]},{"id":"G93","q":"Creo que ____ llover, mira aquellas nubes negras acercándose.","o":["acaba de","ha dejado de","ha vuelto a","va a"],"a":3,"k":"ir a + 동사원형","t":"비가 올 것 같아, 저기 다가오는 먹구름 좀 봐.","e":"'ir a + 동사원형'은 지금 보이는 증거에 근거해 곧 일어날 일을 말할 때 씁니다. 먹구름이 다가오는 것을 보고 '곧 비가 올 것이다'라고 예측하므로 va a llover가 맞습니다.","x":["acaba de: '방금 ~했다'라 앞으로의 예측이 아닙니다 ✗","ha dejado de: '~하는 것을 멈췄다'라 문맥과 맞지 않습니다 ✗","ha vuelto a: '다시 ~했다'라 예측이 아닙니다 ✗","va a: 곧 일어날 일을 예측하는 ir a → 정답 ✓"]},{"id":"G94","q":"Me molesta que la gente me ____ preguntas personales.","o":["hizo","haría","haga","hace"],"a":2,"k":"감정 동사 + 접속법","t":"사람들이 나에게 개인적인 질문을 하는 게 싫다.","e":"'Me molesta que(~하는 게 싫다/거슬린다)'처럼 감정을 나타내는 표현 뒤 que절에는 접속법을 씁니다. hacer의 3인칭 단수 접속법 현재는 haga입니다. la gente(사람들)는 문법상 단수 취급입니다.","x":["hizo: 직설법 과거라 감정 표현 뒤에 쓸 수 없습니다 ✗","haría: 가정미래라 맞지 않습니다 ✗","haga: 감정 표현 뒤 접속법 현재 → 정답 ✓","hace: 직설법 현재라 molestar que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G95","q":"Necesitamos ____ horno nuevo.","o":["ø","el","uno","un"],"a":3,"k":"부정관사 un","t":"우리는 새 오븐이 필요하다.","e":"처음 언급하는 셀 수 있는 명사 하나는 부정관사(하나의)를 씁니다. horno(오븐)는 남성 단수이므로 un입니다. uno는 명사 없이 '하나'라고 대명사로 쓸 때의 형태입니다(Necesito uno).","x":["ø: 셀 수 있는 단수 명사 앞에는 보통 관사가 필요합니다 ✗","el: 특정한 오븐이 아니라 '새 오븐 하나'이므로 부적절합니다 ✗","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","un: 남성 단수 부정관사 → 정답 ✓"]},{"id":"G96","q":"Llevo ____ tiempo esperando mi turno.","o":["muchos","muy","mucho","mucha"],"a":2,"k":"mucho 형용사 일치","t":"나는 차례를 오래 기다리고 있다.","e":"mucho가 명사를 꾸밀 때는 명사의 성·수에 맞춥니다. tiempo(시간)는 남성 단수이므로 mucho tiempo입니다. 'llevar + 기간 + 현재분사'는 '~ 동안 ~하고 있다'라는 뜻입니다.","x":["muchos: 복수라 단수 tiempo와 맞지 않습니다 ✗","muy: 명사 앞에 쓸 수 없습니다 ✗","mucho: 남성 단수 형용사로 tiempo와 일치 → 정답 ✓","mucha: 여성형이라 남성 tiempo와 맞지 않습니다 ✗"]},{"id":"G97","q":"Antes de ayer ____ mi cumpleaños.","o":["fueron","estuvieron","estuvo","fue"],"a":3,"k":"ser 단순과거 (행사)","t":"그저께는 내 생일이었다.","e":"생일·파티처럼 '일어나는 행사·사건'은 ser로 나타냅니다. 'Antes de ayer(그저께)'라는 끝난 시점이므로 단순과거 fue를 씁니다. 주어 mi cumpleaños는 단수입니다.","x":["fueron: 복수라 단수 cumpleaños와 맞지 않습니다 ✗","estuvieron: estar는 행사 날짜를 나타내지 않고 수도 맞지 않습니다 ✗","estuvo: 행사·날을 말할 때는 estar가 아니라 ser를 씁니다 ✗","fue: ser의 단순과거 3인칭 단수 → 정답 ✓"]},{"id":"G98","q":"____ mucho aprender idiomas.","o":["Me interesan","Me intereso","Me interesa","Yo intereso"],"a":2,"k":"interesar+원형","t":"나는 언어를 배우는 것에 관심이 많다.","e":"interesar(~에게 관심을 끌다)는 gustar처럼 쓰입니다. 관심의 대상이 동사원형(aprender)이면 동사는 3인칭 단수 interesa가 됩니다. 관심을 갖는 사람 '나'는 me로 나타냅니다.","x":["Me interesan: 복수형은 복수 명사가 주어일 때 씁니다 ✗","Me intereso: 재귀형으로 'interesarse por(~에 관심을 갖다)' 구조라 이 문장에 맞지 않습니다 ✗","Me interesa: 동사원형 주어에 맞는 단수형 → 정답 ✓","Yo intereso: '내가 (남의) 관심을 끈다'는 뜻이 됩니다 ✗"]},{"id":"G99","q":"____ voy a leer la introducción del libro.","o":["Primera","Primer","Primero","Lo primero"],"a":2,"k":"부사 primero","t":"먼저 나는 책의 서문을 읽을 것이다.","e":"'먼저, 우선'이라는 부사로 쓸 때는 형태가 바뀌지 않는 primero를 씁니다. primer는 남성 명사 앞에서만 쓰고, primera는 여성 명사를 꾸밉니다. 'Lo primero'는 '첫 번째 일'이라는 명사구라 'Lo primero que voy a hacer es...'처럼 써야 합니다.","x":["Primera: 여성 형용사라 부사 '먼저'로 쓸 수 없습니다 ✗","Primer: 남성 명사 앞에서만 쓰는 형태입니다 ✗","Primero: 부사 '먼저, 우선' → 정답 ✓","Lo primero: '첫 번째 일'이라는 명사구라 이 문장 구조와 맞지 않습니다 ✗"]},{"id":"G100","q":"Anteayer ____ una reunión de trabajo.","o":["tenía","estuve teniendo","he tenido","tuve"],"a":3,"k":"단순과거","t":"그저께 나는 업무 회의가 있었다.","e":"'Anteayer(그저께)'처럼 끝난 과거의 특정 시점에 한 번 일어난 일은 단순과거(부정과거)로 씁니다. tener의 1인칭 단순과거는 tuve입니다.","x":["tenía: 불완료과거라 배경·습관을 나타내 한 번의 사건에 어색합니다 ✗","estuve teniendo: 이런 진행형은 회의를 '가졌다'는 표현에 쓰지 않습니다 ✗","he tenido: 현재완료는 anteayer 같은 끝난 시점과 잘 쓰지 않습니다 ✗","tuve: 끝난 과거 시점의 단순과거 → 정답 ✓"]},{"id":"G101","q":"Si ves a Joaquín, ____ que necesito hablar con él lo antes posible.","o":["di le","di a él","dile","dilo"],"a":2,"k":"tú 명령형 + 대명사","t":"호아킨을 보면, 내가 가능한 한 빨리 그와 이야기해야 한다고 전해 줘.","e":"decir의 tú 긍정명령은 불규칙형 di입니다. '그에게'는 간접목적격 le이고, 긍정명령에서는 대명사를 동사 끝에 붙여 한 단어로 씁니다: di + le → dile. 'lo antes posible'은 '가능한 한 빨리'입니다.","x":["di le: 대명사는 명령형에 붙여 써야 합니다 ✗","di a él: 간접목적격 대명사 le를 써야 자연스럽습니다 ✗","dile: 명령형 di + 간접목적격 le → 정답 ✓","dilo: lo는 '그것을'이라 '그에게 말해'의 뜻이 되지 않습니다 ✗"]},{"id":"G102","q":"Antoñito, ____, me duele la cabeza.","o":["debes","deja de gritar","tienes que gritar","sigue gritando"],"a":1,"k":"dejar de + 동사원형","t":"안토니토, 소리 좀 그만 질러, 머리 아파.","e":"'dejar de + 동사원형'은 '~하는 것을 그만두다'라는 뜻입니다. 머리가 아프다고 했으니 '그만 소리 질러'가 자연스럽습니다. 반대로 'seguir + 현재분사'는 '계속 ~하다'입니다. Antoñito는 Antonio에 축소사를 붙인 애칭입니다.","x":["debes: 뒤에 동사가 없어 문장이 완성되지 않습니다 ✗","deja de gritar: '소리 그만 질러' → 정답 ✓","tienes que gritar: '소리 질러야 해'라 문맥과 반대입니다 ✗","sigue gritando: '계속 소리 질러'라 문맥과 반대입니다 ✗"]},{"id":"G103","q":"¿Qué quieres que te ____ para cenar?","o":["preparo","voy a preparar","preparar","prepare"],"a":3,"k":"querer que+접속법","t":"저녁으로 내가 뭘 만들어 주면 좋겠어?","e":"querer que 뒤에 주어가 바뀌면(너 → 나) que절에는 접속법을 씁니다. preparar의 1인칭 단수 접속법 현재는 prepare입니다. 예: ¿Quieres que te ayude?(내가 도와줄까?)","x":["preparo: 직설법이라 querer que 뒤에 쓸 수 없습니다 ✗","voy a preparar: 직설법 미래 표현이라 맞지 않습니다 ✗","preparar: 주어가 다르므로 동사원형을 쓸 수 없습니다 ✗","prepare: 접속법 현재 1인칭 → 정답 ✓"]},{"id":"G104","q":"¿Os gustó ____ espectáculo que vimos el otro día?","o":["un","lo","el","ø"],"a":2,"k":"정관사 el","t":"너희 지난번에 우리가 본 공연 마음에 들었니?","e":"'que vimos el otro día(지난번에 우리가 본)'라는 설명으로 특정한 공연을 가리키므로 정관사가 필요합니다. espectáculo는 남성 명사라 el입니다. gustó가 단수이므로 주어도 단수입니다.","x":["un: 듣는 사람도 아는 특정한 공연이므로 부정관사는 어색합니다 ✗","lo: 중성 관사로 명사 앞에 쓰지 않습니다 ✗","el: 특정한 공연을 가리키는 남성 정관사 → 정답 ✓","ø: gustar의 주어 명사에는 관사가 필요합니다 ✗"]},{"id":"G105","q":"¿Qué ____ el sábado pasado?","o":["habéis hecho","haríais","hacíais","hicisteis"],"a":3,"k":"단순과거","t":"너희 지난 토요일에 뭐 했니?","e":"'el sábado pasado(지난 토요일)'처럼 끝난 과거 시점의 일은 단순과거로 묻습니다. hacer의 vosotros 단순과거는 hicisteis입니다. 중남미에서는 '¿Qué hicieron (ustedes)?'라고 합니다.","x":["habéis hecho: 현재완료는 '지난 토요일'처럼 끝난 시점과 잘 쓰지 않습니다 ✗","haríais: 가정미래(~할 텐데)라 맞지 않습니다 ✗","hacíais: 불완료과거라 습관을 묻는 느낌이 됩니다 ✗","hicisteis: 끝난 과거 시점의 단순과거 → 정답 ✓"]},{"id":"G106","q":"Están buscando ____ Ignacio, nadie sabe dónde se ha metido.","o":["a","por","ø","de"],"a":0,"k":"인칭 a","t":"사람들이 이그나시오를 찾고 있는데, 아무도 그가 어디 숨었는지 모른다.","e":"특정한 사람이 직접목적어(~을/를)일 때는 앞에 전치사 a를 붙입니다(인칭 a). 'buscar a Ignacio'는 '이그나시오를 찾다'입니다. 사물을 찾을 때는 a를 쓰지 않습니다(Busco mis llaves). 'meterse'는 여기서 '(어딘가에) 들어가 숨다'라는 뜻입니다.","x":["a: 사람 목적어 앞의 인칭 a → 정답 ✓","por: 'buscar por'는 이런 뜻으로 쓰지 않습니다 ✗","ø: 특정한 사람 목적어 앞에는 a가 필요합니다 ✗","de: buscar와 함께 쓰지 않습니다 ✗"]},{"id":"G107","q":"Todos estos regalos son para ____.","o":["ti","tu","te","tú"],"a":0,"k":"전치격 대명사 ti","t":"이 선물들은 모두 너를 위한 거야.","e":"전치사(para, de, sin 등) 뒤에서는 '너'를 ti로 씁니다(악센트 없음). '나'는 mí가 됩니다. 단, con과 함께면 contigo, conmigo로 바뀝니다.","x":["ti: 전치사 뒤 '너' → 정답 ✓","tu: 소유형용사 '너의'라 뒤에 명사가 필요합니다 ✗","te: 목적격 대명사라 전치사 뒤에 쓰지 않습니다 ✗","tú: 주격 '너는'이라 전치사 뒤에 쓰지 않습니다 ✗"]},{"id":"G108","q":"Esos dos alumnos se están peleando. ¿____ ves?","o":["Le","La","Las","Los"],"a":3,"k":"직접목적격 대명사","t":"저 두 학생이 싸우고 있어. 그들 보이니?","e":"ver(보다)의 대상 '그들을'은 직접목적어입니다. 'esos dos alumnos'는 남성 복수이므로 los를 씁니다.","x":["Le: 간접목적격 단수라 맞지 않습니다 ✗","La: 여성 단수라 맞지 않습니다 ✗","Las: 여성 복수라 남성 alumnos와 맞지 않습니다 ✗","Los: 남성 복수 직접목적격 → 정답 ✓"]},{"id":"G109","q":"Estas camisas ____ de seda.","o":["son","están","está","es"],"a":0,"k":"재료 ser de","t":"이 셔츠들은 실크로 만들어졌다.","e":"물건의 재료를 말할 때는 'ser de + 재료'를 씁니다. 재료는 그 물건의 본질적인 특징이므로 estar가 아니라 ser를 씁니다. 주어 'estas camisas'가 복수이므로 son입니다.","x":["son: 재료의 ser de + 복수 주어 → 정답 ✓","están: 재료는 estar로 나타내지 않습니다 ✗","está: estar이고 단수라 맞지 않습니다 ✗","es: 단수라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G110","q":"¿Cómo piensas ____ aprobar todos los exámenes sin estudiar?","o":["ø","de","por","a"],"a":0,"k":"pensar + 동사원형","t":"공부도 안 하고 어떻게 모든 시험에 통과할 생각이니?","e":"pensar 뒤에 동사원형이 바로 오면 '~할 생각이다, ~할 작정이다'라는 뜻입니다. 전치사를 넣지 않습니다. 'pensar en'은 '~에 대해 생각하다'라는 다른 뜻입니다. 예: Pienso viajar este verano.(올여름에 여행할 생각이야.)","x":["ø: pensar + 동사원형(~할 생각이다) → 정답 ✓","de: 'pensar de'는 '~에 대해 어떻게 생각하다'로 의미가 다릅니다 ✗","por: pensar와 동사원형 사이에 쓰지 않습니다 ✗","a: pensar와 동사원형 사이에 쓰지 않습니다 ✗"]},{"id":"G111","q":"Este es ____ mejor concurso de la tele que he visto en toda mi vida.","o":["un","ø","lo","el"],"a":3,"k":"최상급 el mejor","t":"이건 내가 평생 본 TV 경연 프로그램 중 최고다.","e":"mejor(더 좋은)에 정관사를 붙이면 최상급 '가장 좋은, 최고의'가 됩니다. concurso는 남성 명사라 'el mejor concurso'입니다. 'que he visto en toda mi vida(내가 평생 본 것 중)'가 최상급과 잘 어울립니다.","x":["un: 부정관사로는 '최고의'라는 최상급이 되지 않습니다 ✗","ø: 정관사가 없으면 최상급 의미가 되지 않습니다 ✗","lo: 중성 관사라 명사 concurso 앞에 쓸 수 없습니다 ✗","el: el + mejor = 최상급 → 정답 ✓"]},{"id":"G112","q":"¿Es verdad que ____ vais a casar en la iglesia del pueblo?","o":["ustedes","os","vosotros","se"],"a":1,"k":"재귀동사 casarse","t":"너희가 마을 성당에서 결혼한다는 게 사실이야?","e":"casarse(결혼하다)는 재귀동사입니다. 동사 vais가 vosotros형이므로 재귀대명사도 vosotros에 맞는 os를 씁니다: os vais a casar. 중남미에서는 '¿se van a casar?'라고 합니다.","x":["ustedes: 주격 대명사라 재귀대명사 자리에 쓸 수 없습니다 ✗","os: vosotros의 재귀대명사 → 정답 ✓","vosotros: 주격이라 재귀대명사가 될 수 없습니다 ✗","se: ustedes/ellos용이라 동사 vais와 맞지 않습니다 ✗"]},{"id":"G113","q":"―¿Cómo vas a tu trabajo? ―Normalmente voy ____.","o":["ando","andando","andar","andado"],"a":1,"k":"현재분사 (방법)","t":"―회사에 어떻게 가? ―보통 걸어서 가.","e":"'ir andando'는 '걸어서 가다'라는 뜻으로, 현재분사(andando)가 이동 방법을 나타냅니다. 'ir a pie'와 같은 의미입니다. 중남미에서는 'ir caminando'를 더 많이 씁니다.","x":["ando: 활용형이라 voy 뒤에 바로 올 수 없습니다 ✗","andando: 방법을 나타내는 현재분사 '걸어서' → 정답 ✓","andar: 동사원형은 ir 뒤에 바로 올 수 없습니다 ✗","andado: 과거분사라 방법을 나타내지 못합니다 ✗"]},{"id":"G114","q":"____ en verano, es normal que haga calor.","o":["Son","Somos","Estamos","Estemos"],"a":2,"k":"estar en + 계절","t":"여름이니까 더운 게 당연하지.","e":"'지금은 ~(계절·달)이다'는 'estar en + 계절'로 말합니다. 'Estamos en verano'는 '(우리는) 여름 안에 있다' 즉 '지금은 여름이다'라는 뜻입니다. 예: Estamos en enero.(지금은 1월이다.)","x":["Son: 계절에는 ser + en을 쓰지 않습니다 ✗","Somos: 'somos en verano'라는 표현은 쓰지 않습니다 ✗","Estamos: estar en + 계절 → 정답 ✓","Estemos: 접속법이라 사실 진술에 맞지 않습니다 ✗"]},{"id":"G115","q":"Los niños ____ de su casa sin llevarse los bocadillos.","o":["se fueran","fueron","fueran","se fueron"],"a":3,"k":"irse 단순과거","t":"아이들은 샌드위치를 챙기지 않고 집에서 나갔다.","e":"irse는 '(어떤 곳을) 떠나다, 나가다'라는 뜻입니다. 'de su casa(집에서)'를 떠난 것이므로 se fueron을 씁니다. 한 번 일어난 과거 사건이라 직설법 단순과거입니다. bocadillo는 스페인에서 '바게트 샌드위치'를 말합니다.","x":["se fueran: 접속법 과거라 단순 진술에 쓸 수 없습니다 ✗","fueron: se가 없으면 '갔다'로, 'de su casa(집에서)'와 어울리지 않습니다 ✗","fueran: 접속법이고 se도 없습니다 ✗","se fueron: irse의 단순과거 '떠났다' → 정답 ✓"]},{"id":"G116","q":"¿Cuál es ____ color que más te gusta para vestir?","o":["la","lo","ø","el"],"a":3,"k":"정관사 el","t":"옷 입을 때 네가 가장 좋아하는 색은 뭐야?","e":"color(색)는 남성 명사입니다. 'que más te gusta(네가 가장 좋아하는)'로 특정한 하나를 가리키므로 정관사 el이 필요합니다.","x":["la: color는 남성 명사라 맞지 않습니다 ✗","lo: 중성 관사로 명사 앞에 쓰지 않습니다 ✗","ø: 특정한 대상이므로 관사가 필요합니다 ✗","el: 남성 단수 정관사 → 정답 ✓"]},{"id":"G117","q":"Todos ____ veranos voy a Mallorca.","o":["ø","a los","los","en los"],"a":2,"k":"todos los + 명사","t":"매년 여름 나는 마요르카에 간다.","e":"'todos los/todas las + 복수 명사'는 '매 ~마다'라는 뜻입니다: todos los días(매일), todas las semanas(매주). 앞에 전치사를 넣지 않습니다. veranos는 남성 복수라 los입니다.","x":["ø: todos와 명사 사이에 정관사가 필요합니다 ✗","a los: 전치사 a가 불필요합니다 ✗","los: todos los + 복수 명사(매 ~) → 정답 ✓","en los: 전치사 en이 불필요합니다 ✗"]},{"id":"G118","q":"¿Nunca ____ en la capital de tu país?","o":["estabas","has estado","eras","has sido"],"a":1,"k":"현재완료 (경험)","t":"너는 너희 나라 수도에 한 번도 가 본 적이 없니?","e":"'~해 본 적이 있다/없다'라는 경험은 현재완료로 나타냅니다. 어떤 장소에 '가 보다, 있어 보다'는 estar를 써서 'haber estado en'이라고 합니다. 예: ¿Has estado en Corea?(한국에 가 봤니?)","x":["estabas: 불완료과거라 경험을 묻는 데 쓰지 않습니다 ✗","has estado: 경험의 현재완료 '가 본 적 있다' → 정답 ✓","eras: ser의 불완료과거라 장소 경험과 무관합니다 ✗","has sido: ser의 현재완료라 장소에 '있어 본' 경험을 나타내지 못합니다 ✗"]},{"id":"G119","q":"¡Qué ____ está esta sopa!","o":["bueno","buen","buena","buenos"],"a":2,"k":"감탄문 형용사 일치","t":"이 수프 정말 맛있다!","e":"'¡Qué + 형용사 + está...!'는 '정말 ~하다!'라는 감탄문입니다. 형용사는 주어 sopa(수프, 여성 단수)에 맞춰 buena를 씁니다. 여기서 'estar bueno/a'는 '(음식이) 맛있다'라는 뜻입니다.","x":["bueno: 남성형이라 여성 명사 sopa와 맞지 않습니다 ✗","buen: 남성 명사 앞에서만 쓰는 줄임형입니다 ✗","buena: 여성 단수로 sopa와 일치 → 정답 ✓","buenos: 남성 복수라 맞지 않습니다 ✗"]},{"id":"G120","q":"Mándame un mensaje cuando ____ a punto de salir de tu casa.","o":["estarás","estuvieras","estés","estabas"],"a":2,"k":"cuando + 접속법","t":"집에서 나가려고 할 때 메시지 보내 줘.","e":"cuando 뒤에 앞으로 일어날 일(미래)이 오면 접속법 현재를 씁니다. 미래형은 쓰지 않습니다. 'estar a punto de + 동사원형'은 '막 ~하려는 참이다'라는 뜻입니다. 예: Cuando llegues, llámame.(도착하면 전화해.)","x":["estarás: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","estuvieras: 접속법 과거라 현재의 부탁 문맥에 맞지 않습니다 ✗","estés: 미래 일을 나타내는 cuando + 접속법 현재 → 정답 ✓","estabas: 직설법 과거라 앞으로의 일에 맞지 않습니다 ✗"]},{"id":"G121","q":"Cada vez que salgo de mi trabajo, ____ por teléfono a mi novia.","o":["llamo","llamé","estoy llamando","llamaba"],"a":0,"k":"현재형 (습관)","t":"회사에서 퇴근할 때마다 나는 여자친구에게 전화한다.","e":"'Cada vez que(~할 때마다)' + 현재형 salgo는 현재의 습관을 나타냅니다. 그래서 주절도 직설법 현재 llamo를 씁니다. 'llamar por teléfono a alguien'은 '누구에게 전화하다'입니다.","x":["llamo: 현재 습관을 나타내는 직설법 현재 → 정답 ✓","llamé: 단순과거라 현재형 salgo와 시제가 맞지 않습니다 ✗","estoy llamando: 지금 진행 중인 동작이라 반복 습관에 맞지 않습니다 ✗","llamaba: 불완료과거라 현재 습관이 아닙니다 ✗"]},{"id":"G122","q":"Me gustó tanto la peli que vi el otro día que ____ vería otra vez.","o":["lo","la","ø","le"],"a":1,"k":"직접목적격 대명사","t":"지난번에 본 영화가 너무 좋아서 다시 보고 싶을 정도다.","e":"peli는 película(영화)의 줄임말로 여성 명사입니다. '그것을 다시 볼 것이다'의 직접목적어이므로 여성 단수 la를 씁니다. 'tanto ... que'는 '너무 ~해서 ~하다'라는 표현입니다.","x":["lo: 남성형이라 여성 명사 peli와 맞지 않습니다 ✗","la: 여성 단수 직접목적격으로 peli를 받습니다 → 정답 ✓","ø: 목적어를 받는 대명사가 필요합니다 ✗","le: 간접목적격이라 '그것을'에 맞지 않습니다 ✗"]},{"id":"G123","q":"Cádiz ____ una ciudad del sur de España.","o":["está","es","son","hay"],"a":1,"k":"ser (정의·소개)","t":"카디스는 스페인 남부의 도시이다.","e":"'A는 B이다'처럼 무엇인지 정의하거나 소개할 때는 ser를 씁니다. 'Cádiz es una ciudad'는 카디스가 어떤 곳인지 설명합니다. 위치만 말할 때는 estar를 씁니다(Cádiz está en el sur de España).","x":["está: 위치를 말할 때 쓰며 '~인 도시이다'라는 정의에는 쓰지 않습니다 ✗","es: 정의·소개의 ser → 정답 ✓","son: 복수라 단수 주어 Cádiz와 맞지 않습니다 ✗","hay: 존재 표현이라 주어가 있는 정의 문장에 맞지 않습니다 ✗"]},{"id":"G124","q":"Todos ustedes ____ rellenar el formulario al completo.","o":["hay","tienen que","hay que","tienen"],"a":1,"k":"tener que/hay que","t":"여러분 모두 양식을 빠짐없이 작성하셔야 합니다.","e":"주어(todos ustedes)가 있는 의무는 'tener que + 동사원형'을 씁니다. ustedes는 3인칭 복수 동사를 쓰므로 tienen que가 됩니다. 'hay que'는 주어 없이 '(일반적으로) ~해야 한다'고 할 때 씁니다.","x":["hay: que가 없고 주어와도 맞지 않습니다 ✗","tienen que: ustedes + 의무 표현 → 정답 ✓","hay que: 무인칭 표현이라 주어 ustedes와 함께 쓸 수 없습니다 ✗","tienen: que가 빠져 동사원형을 이을 수 없습니다 ✗"]},{"id":"G125","q":"¿____ estudiaste en la universidad?","o":["Que","Cuál","Quién","Qué"],"a":3,"k":"의문사 qué","t":"너는 대학에서 무엇을 공부했니?","e":"'무엇을'이라고 물을 때는 악센트가 있는 의문사 qué를 씁니다. 악센트 없는 que는 '~라는 것'이라는 접속사나 관계대명사입니다. 예: ¿Qué haces?(뭐 해?)","x":["Que: 악센트가 없으면 의문사가 아닙니다 ✗","Cuál: '어느 것'이라 동사 앞에서 전공 일반을 묻는 데 어색합니다 ✗","Quién: '누가'라 의미가 맞지 않습니다 ✗","Qué: 의문사 '무엇을' → 정답 ✓"]},{"id":"G126","q":"En 2010 hice ____ viaje por Sudamérica.","o":["uno","una","un","ø"],"a":2,"k":"부정관사 un","t":"2010년에 나는 남미 여행을 했다.","e":"처음 말하는 '하나의 여행'이므로 부정관사를 씁니다. viaje는 남성 명사이므로 un입니다. 'hacer un viaje'는 '여행을 하다'라는 표현입니다.","x":["uno: 명사 앞에서는 un으로 줄여 씁니다 ✗","una: 여성형이라 남성 viaje와 맞지 않습니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","ø: 셀 수 있는 단수 명사 viaje 앞에 관사가 필요합니다 ✗"]},{"id":"G127","q":"Llevás horas gritando como loco, ____ insoportable.","o":["sos","son","sois","sé"],"a":0,"k":"보세오 (vos)","t":"너 몇 시간째 미친 사람처럼 소리 지르고 있어, 정말 못 참겠다.","e":"Llevás는 아르헨티나·우루과이 등에서 쓰는 vos(너) 형태의 동사입니다(보세오). vos에 대한 ser의 현재형은 sos입니다. 스페인식 tú라면 'Llevas ... eres insoportable'이 됩니다.","x":["sos: vos의 ser 현재형으로 Llevás와 맞습니다 → 정답 ✓","son: ustedes/ellos 형태라 맞지 않습니다 ✗","sois: vosotros 형태라 맞지 않습니다 ✗","sé: ser의 tú 명령형(또는 saber의 yo형)이라 맞지 않습니다 ✗"]},{"id":"G128","q":"Confía en ____, yo nunca te voy a traicionar.","o":["mi","me","mí","to"],"a":2,"k":"전치격 대명사 mí","t":"나를 믿어, 나는 절대 너를 배신하지 않을 거야.","e":"'confiar en(~을 믿다)'처럼 전치사 뒤에서 '나'는 악센트가 있는 mí를 씁니다. 악센트 없는 mi는 '나의'라는 소유형용사입니다.","x":["mi: 악센트가 없으면 소유형용사 '나의'입니다 ✗","me: 목적격 대명사라 전치사 en 뒤에 쓰지 않습니다 ✗","mí: 전치사 뒤 '나' → 정답 ✓","to: 스페인어에 없는 형태입니다 ✗"]},{"id":"G129","q":"Los domingos suelo ____ más tiempo para descansar.","o":["teniendo","a tener","de tener","tener"],"a":3,"k":"soler + 동사원형","t":"일요일마다 나는 보통 쉴 시간이 더 많다.","e":"'soler + 동사원형'은 '보통 ~하다, ~하곤 하다'라는 습관 표현입니다. soler 뒤에는 전치사 없이 동사원형이 바로 옵니다. 예: Suelo levantarme a las siete.(나는 보통 7시에 일어난다.)","x":["teniendo: 현재분사는 soler 뒤에 올 수 없습니다 ✗","a tener: soler 뒤에 전치사 a를 넣지 않습니다 ✗","de tener: soler 뒤에 전치사 de를 넣지 않습니다 ✗","tener: soler + 동사원형 → 정답 ✓"]},{"id":"G130","q":"Somos ____ Madrid, pero vivimos en Sevilla.","o":["en","desde","de","a"],"a":2,"k":"출신 ser de","t":"우리는 마드리드 출신이지만, 세비야에 산다.","e":"출신지를 말할 때는 'ser de + 장소'를 씁니다. 'Somos de Madrid'는 '우리는 마드리드 출신이다'입니다. 예: ¿De dónde eres?(어디 출신이야?)","x":["en: '~에'라 출신을 나타내지 못합니다 ✗","desde: '~부터'라는 출발점이며 출신 표현이 아닙니다 ✗","de: 출신 ser de → 정답 ✓","a: 방향 '~로'라 맞지 않습니다 ✗"]},{"id":"G131","q":"¿Puedes enviarme el archivo ____ correo electrónico?","o":["por","en","con","para"],"a":0,"k":"수단 전치사 por","t":"나한테 그 파일을 이메일로 보내 줄 수 있어?","e":"전달·통신 수단(~으로, ~을 통해)은 por를 씁니다: por correo electrónico(이메일로), por teléfono(전화로), por correo(우편으로).","x":["por: 통신 수단 '~으로' → 정답 ✓","en: 수단 표현에 맞지 않습니다 ✗","con: '~을 가지고'라 이메일 전송 수단에는 쓰지 않습니다 ✗","para: 목적·대상이라 수단을 나타내지 않습니다 ✗"]},{"id":"G132","q":"Dígame, ¿qué ____ hacer por usted?","o":["pueda","puedo","podido","poder"],"a":1,"k":"poder 현재형","t":"말씀하세요, 제가 무엇을 도와드릴까요?","e":"'¿Qué puedo hacer por usted?(제가 당신을 위해 무엇을 할 수 있을까요?)'는 직원이 손님에게 자주 하는 공손한 표현입니다. 일반 의문문이므로 직설법 현재 1인칭 puedo를 씁니다. Dígame는 decir의 usted 명령형입니다.","x":["pueda: 접속법이라 일반 의문문에 쓰지 않습니다 ✗","puedo: 직설법 현재 1인칭 → 정답 ✓","podido: 과거분사라 혼자 동사가 될 수 없습니다 ✗","poder: 동사원형이라 주어에 맞게 활용해야 합니다 ✗"]},{"id":"G133","q":"Este no es el tren que va a Madrid, es ____.","o":["eso","esos","esa","ese"],"a":3,"k":"지시대명사 ese","t":"이건 마드리드행 기차가 아니야, 저거야.","e":"앞에 나온 명사 tren(기차, 남성 단수)을 다시 가리키는 지시대명사이므로 ese를 씁니다. 중성 eso는 정체를 모르는 대상이나 내용 전체를 가리킬 때 씁니다.","x":["eso: 중성이라 이미 정해진 명사 tren을 가리키기에 맞지 않습니다 ✗","esos: 복수라 단수 tren과 맞지 않습니다 ✗","esa: 여성형이라 남성 tren과 맞지 않습니다 ✗","ese: 남성 단수 지시대명사 → 정답 ✓"]},{"id":"G134","q":"Cuando ____ del trabajo, mi padre siempre se sienta a ver su programa preferido.","o":["vuelve","vuelva","volvía","volvió"],"a":0,"k":"cuando+현재(습관)","t":"회사에서 돌아오면 우리 아버지는 항상 좋아하는 프로그램을 보려고 앉으신다.","e":"cuando 뒤가 현재의 습관(늘 반복되는 일)이면 직설법 현재를 씁니다. 주절의 'siempre se sienta(항상 앉는다)'도 현재 습관이므로 vuelve가 맞습니다. 미래의 일이라면 접속법(cuando vuelva)을 씁니다.","x":["vuelve: 현재 습관을 나타내는 직설법 현재 → 정답 ✓","vuelva: 접속법은 미래의 일일 때 써서 습관 문장에 맞지 않습니다 ✗","volvía: 불완료과거라 현재형 se sienta와 시제가 맞지 않습니다 ✗","volvió: 단순과거라 현재 습관과 맞지 않습니다 ✗"]},{"id":"G135","q":"¡____ rápido que vamos a llegar tarde!","o":["Vístete","Tú vistes","Viste","Vistes"],"a":0,"k":"재귀동사 tú 명령형","t":"빨리 옷 입어, 우리 늦겠어!","e":"vestirse(옷을 입다)는 재귀동사입니다. tú 긍정명령은 viste이고, 재귀대명사 te를 끝에 붙이면 vístete가 됩니다. 강세 위치를 지키기 위해 악센트(í)를 찍습니다.","x":["Vístete: 재귀동사 vestirse의 tú 명령형 → 정답 ✓","Tú vistes: 직설법 현재이고 재귀대명사도 없습니다 ✗","Viste: 재귀대명사 te가 빠져 '(누구에게) 옷을 입혀라'가 됩니다 ✗","Vistes: 직설법 현재(너는 입힌다)라 명령이 아닙니다 ✗"]},{"id":"G136","q":"Estoy en contra de ____ sistema.","o":["estas","este","esto","esta"],"a":1,"k":"지시형용사 este","t":"나는 이 시스템에 반대한다.","e":"sistema(시스템)는 -a로 끝나지만 그리스어에서 온 남성 명사입니다(el sistema, el problema, el tema). 그래서 남성 단수 지시형용사 este를 씁니다. 'estar en contra de'는 '~에 반대하다'입니다.","x":["estas: 여성 복수라 맞지 않습니다 ✗","este: sistema는 남성 단수 → 정답 ✓","esto: 중성 대명사로 명사 앞에 쓸 수 없습니다 ✗","esta: -a로 끝나도 sistema는 남성이라 틀립니다 ✗"]},{"id":"G137","q":"Nunca leo libros ____ historia porque me aburren.","o":["de","en","a","por"],"a":0,"k":"주제·종류 de","t":"나는 역사책을 절대 읽지 않는다, 지루하거든.","e":"명사의 종류·주제를 나타낼 때는 'de + 명사'를 씁니다: libro de historia(역사책), clase de español(스페인어 수업), película de terror(공포 영화).","x":["de: 종류·주제 '~의, ~에 관한' → 정답 ✓","en: 책의 종류를 나타내지 못합니다 ✗","a: 종류 표현에 쓰지 않습니다 ✗","por: 종류 표현에 쓰지 않습니다 ✗"]},{"id":"G138","q":"¿____ vas a cocinar esta noche?","o":["A qué","De quién","Qué","Quién"],"a":2,"k":"의문사 qué","t":"오늘 저녁에 뭐 요리할 거야?","e":"cocinar(요리하다)의 목적어 '무엇을'을 묻는 의문사 qué를 씁니다. 동사 vas가 tú형이므로 주어는 '너'이고, 그래서 quién(누가)은 맞지 않습니다.","x":["A qué: '무엇에/몇 시에'라 요리할 음식을 묻지 못합니다 ✗","De quién: '누구의'라 맞지 않습니다 ✗","Qué: '무엇을' → 정답 ✓","Quién: 동사 vas(너)와 맞지 않고 '누가'라 의미도 맞지 않습니다 ✗"]},{"id":"G139","q":"____ dirección no es correcta.","o":["Estos","Esto","Este","Esta"],"a":3,"k":"지시형용사 esta","t":"이 주소는 맞지 않다.","e":"dirección(주소)은 -ción으로 끝나는 여성 명사입니다. -ción, -sión으로 끝나는 명사는 거의 다 여성입니다. 그래서 여성 단수 지시형용사 esta를 씁니다.","x":["Estos: 남성 복수라 맞지 않습니다 ✗","Esto: 중성 대명사로 명사 앞에 쓸 수 없습니다 ✗","Este: 남성형이라 여성 dirección과 맞지 않습니다 ✗","Esta: 여성 단수로 dirección과 일치 → 정답 ✓"]},{"id":"G140","q":"No tomo ____ leche, tengo alergia a los lácteos.","o":["una","la","ø","el"],"a":2,"k":"무관사 (물질명사)","t":"나는 유제품 알레르기가 있어서 우유를 마시지 않는다.","e":"우유 같은 셀 수 없는 물질명사를 '일반적으로' 먹거나 마신다고 할 때, 특히 tomar·beber 같은 동사 뒤 목적어에는 관사를 쓰지 않습니다. 예: No como carne.(나는 고기를 안 먹어.)","x":["una: 셀 수 없는 물질명사에 부정관사를 쓰지 않습니다 ✗","la: 특정한 우유를 가리키는 뜻이 되어 맞지 않습니다 ✗","ø: 물질명사 일반을 말할 때 관사 없음 → 정답 ✓","el: leche는 여성 명사이고 관사도 필요 없습니다 ✗"]},{"id":"G141","q":"No tenemos ____ clientes como vosotros.","o":["tantos","tanto","tan","tanta"],"a":0,"k":"tanto 형용사 일치","t":"우리에게는 너희 같은 손님이 그렇게 많지 않다.","e":"tanto가 명사 앞에서 '그렇게 많은'이라는 형용사로 쓰일 때는 명사의 성·수에 맞춥니다. clientes(손님들)는 남성 복수이므로 tantos입니다. 'tantos ... como'는 '~만큼 많은'이라는 비교 표현이기도 합니다.","x":["tantos: 남성 복수로 clientes와 일치 → 정답 ✓","tanto: 단수라 복수 clientes와 맞지 않습니다 ✗","tan: 형용사·부사 앞에만 쓰며 명사 앞에 쓸 수 없습니다 ✗","tanta: 여성 단수라 맞지 않습니다 ✗"]},{"id":"G142","q":"____ llegué al instituto, me di cuenta de que ese día no había clases.","o":["Como","Cuanto","Cuando","Donde"],"a":2,"k":"시간 접속사 cuando","t":"고등학교에 도착했을 때, 나는 그날 수업이 없다는 걸 알았다.","e":"cuando(~할 때)는 시간 관계를 나타내는 접속사입니다. '학교에 도착했을 때 깨달았다'는 시간 순서이므로 cuando가 맞습니다. 'darse cuenta de'는 '~을 깨닫다'입니다. instituto는 스페인에서 '중·고등학교'를 말합니다.","x":["Como: '~해서'라는 이유나 '~처럼'이라 시간 관계가 아닙니다 ✗","Cuanto: '~할수록/~만큼'이라 맞지 않습니다 ✗","Cuando: '~했을 때' → 정답 ✓","Donde: '~하는 곳에'라 장소를 나타냅니다 ✗"]},{"id":"G143","q":"¿Te ____ bien que vayamos a pie hasta la estación?","o":["parece","pareces","parezca","lo parece"],"a":0,"k":"parecer 구문","t":"역까지 걸어가는 거 괜찮아?","e":"'parecer bien a alguien'은 '~에게 좋게 보이다, 괜찮다'는 뜻으로 gustar처럼 쓰입니다. 주어는 'que vayamos a pie(우리가 걸어가는 것)'라는 절이므로 동사는 3인칭 단수 parece입니다. '¿Te parece bien...?'은 상대의 동의를 묻는 표현입니다.","x":["parece: que절 주어에 맞는 3인칭 단수 → 정답 ✓","pareces: '네가 ~처럼 보인다'는 뜻이 되어 맞지 않습니다 ✗","parezca: 접속법이라 일반 의문문에 쓰지 않습니다 ✗","lo parece: 불필요한 lo가 들어가 틀립니다 ✗"]},{"id":"G144","q":"¿____ te han dicho para que estés tan decepcionado?","o":["Quién","Cuál","Qué","Cómo"],"a":2,"k":"의문사 qué","t":"사람들이 너한테 뭐라고 했길래 그렇게 실망했니?","e":"decir(말하다)의 목적어 '무엇을'을 묻는 의문사 qué를 씁니다. han dicho의 주어는 '사람들(그들)'이고, 묻는 것은 '말한 내용'입니다. 'para que + 접속법'은 여기서 '~할 정도로'라는 의미입니다.","x":["Quién: '누가'인데 동사 han이 복수라 맞지 않습니다 ✗","Cuál: '어느 것'이라 말한 내용을 묻는 데 쓰지 않습니다 ✗","Qué: '무엇을' 말했는지 → 정답 ✓","Cómo: '어떻게'라 말한 내용을 묻지 못합니다 ✗"]},{"id":"G145","q":"Lo siento, no ____ terminar el informe ayer.","o":["pude","podré","puedo","podría"],"a":0,"k":"단순과거","t":"죄송해요, 어제 보고서를 끝낼 수 없었어요.","e":"'ayer(어제)'라는 끝난 과거 시점에 '할 수 없었다'는 결과이므로 단순과거 pude를 씁니다. poder의 단순과거는 불규칙형(pude, pudiste, pudo...)입니다.","x":["pude: 끝난 과거 시점의 단순과거 → 정답 ✓","podré: 미래형이라 ayer와 맞지 않습니다 ✗","puedo: 현재형이라 ayer와 맞지 않습니다 ✗","podría: 가정미래라 실제 과거 사건에 맞지 않습니다 ✗"]},{"id":"G146","q":"―¿Te ha gustado la película? ―No mucho, ¿y ____?","o":["ti","a tú","tú","a ti"],"a":3,"k":"gustar 구문 a ti","t":"―영화 마음에 들었어? ―별로. 너는?","e":"gustar 구문으로 '너는(어때)?'라고 되물을 때는 'a ti'를 씁니다. 앞 질문이 '¿Te ha gustado?'였으므로 같은 구조로 '¿Y a ti?'가 됩니다. 일반 동사 문장이었다면 '¿Y tú?'라고 했을 것입니다.","x":["ti: 전치사 a가 빠졌습니다 ✗","a tú: 전치사 뒤에는 tú가 아니라 ti를 씁니다 ✗","tú: gustar 구문에는 주격을 쓰지 않습니다 ✗","a ti: gustar 구문의 '너에게는' → 정답 ✓"]},{"id":"G147","q":"¿Dónde ____ el verano pasado?","o":["fuisteis","habéis ido","estuvisteis yendo","ibais"],"a":0,"k":"단순과거","t":"너희 지난여름에 어디 갔었어?","e":"'el verano pasado(지난여름)'처럼 끝난 과거 시점의 일은 단순과거를 씁니다. ir의 vosotros 단순과거는 fuisteis입니다(ser와 형태가 같음). 중남미에서는 '¿Dónde fueron?'이라고 합니다.","x":["fuisteis: 끝난 과거 시점의 단순과거 → 정답 ✓","habéis ido: 현재완료는 '지난여름'처럼 끝난 시점과 잘 쓰지 않습니다 ✗","estuvisteis yendo: 이런 진행형은 여행지를 묻는 데 쓰지 않습니다 ✗","ibais: 불완료과거라 습관을 묻는 뜻이 됩니다 ✗"]},{"id":"G148","q":"¿____ algo más, señora?","o":["Deseáis","Deseas","Desea","Desee"],"a":2,"k":"usted 동사 활용","t":"더 필요하신 거 있으세요, 손님?","e":"señora(부인, 손님)에게 정중하게 말할 때는 usted를 쓰고, 동사는 3인칭 단수로 활용합니다. desear의 3인칭 단수 직설법 현재는 desea입니다. 가게 점원이 자주 쓰는 표현입니다.","x":["Deseáis: vosotros형이라 한 사람(señora)에게 쓸 수 없습니다 ✗","Deseas: tú형이라 존칭 대상인 señora에게 어색합니다 ✗","Desea: usted에 맞는 3인칭 단수 → 정답 ✓","Desee: 접속법이라 일반 의문문에 쓰지 않습니다 ✗"]},{"id":"G149","q":"____ mucha gente que habla dos lenguas.","o":["Son","Hay","Está","Es"],"a":1,"k":"hay (존재 표현)","t":"두 언어를 하는 사람들이 많다.","e":"'~이 있다(존재)'는 hay를 씁니다. 'mucha gente(많은 사람들)'처럼 수량 표현이 붙은 명사의 존재를 말할 때 hay가 알맞습니다. gente는 문법상 단수 명사입니다.","x":["Son: ser는 존재를 나타내지 않습니다 ✗","Hay: 존재 '~이 있다' → 정답 ✓","Está: estar는 특정한 것의 위치를 말해 mucha gente와 쓰지 않습니다 ✗","Es: ser는 존재를 나타내지 않습니다 ✗"]},{"id":"G150","q":"¿Dónde están mis pantalones ____?","o":["negros","negro","negras","negra"],"a":0,"k":"형용사 성·수 일치","t":"내 검은 바지 어디 있어?","e":"pantalones(바지)는 스페인어에서 보통 복수형으로 쓰는 남성 명사입니다. 형용사는 명사의 성·수에 맞추므로 남성 복수 negros를 씁니다.","x":["negros: 남성 복수로 pantalones와 일치 → 정답 ✓","negro: 단수라 복수 pantalones와 맞지 않습니다 ✗","negras: 여성 복수라 남성 명사와 맞지 않습니다 ✗","negra: 여성 단수라 맞지 않습니다 ✗"]},{"id":"G151","q":"Para mí, ____ sábado es el mejor día de la semana.","o":["ø","lo","un","el"],"a":3,"k":"요일 앞 정관사","t":"나에게는 토요일이 일주일 중 가장 좋은 날이다.","e":"스페인어에서 요일 이름을 문장의 주어로 쓸 때는 정관사 el을 붙입니다. sábado(토요일)는 남성 명사이므로 'el sábado'가 됩니다. 예: El lunes es difícil. (월요일은 힘들다.)","x":["ø: 주어 자리의 요일에는 관사가 필요하므로 빈칸을 비우면 ✗","lo: 중성 관사로 형용사 앞에 쓰며 명사 앞에는 쓰지 않습니다 ✗","un: 부정관사(어떤 하나의)로 '어떤 토요일'이 되어 일반적인 의미와 맞지 않습니다 ✗","el: 남성 단수 정관사, 요일 앞에 쓰는 관사 → 정답 ✓"]},{"id":"G152","q":"No interrumpas a tu mamá, ¿no ves que ____ por teléfono?","o":["habla","hablaría","ha hablado","está hablando"],"a":3,"k":"현재진행형","t":"엄마 방해하지 마, 엄마가 통화 중인 거 안 보이니?","e":"'지금 이 순간 ~하고 있다'는 진행 중인 동작은 estar + 현재분사(-ando/-iendo)로 나타냅니다. 엄마가 바로 지금 전화로 이야기하는 중이므로 'está hablando'가 가장 자연스럽습니다.","x":["habla: 단순 현재로 습관이나 일반적 사실에 더 어울려 '지금 진행 중'을 강조하지 못합니다 ✗","hablaría: 조건법(~할 텐데)이라 현재 상황과 맞지 않습니다 ✗","ha hablado: 현재완료(~했다)로 이미 끝난 일을 뜻해 ✗","está hablando: estar + 현재분사, 지금 통화하는 중 → 정답 ✓"]},{"id":"G153","q":"No olvides ____ debes dormir lo suficiente para tener una buena salud.","o":["que","a que","de que","ø"],"a":0,"k":"olvidar que","t":"건강을 위해 충분히 자야 한다는 것을 잊지 마.","e":"olvidar(잊다)는 타동사라서 '~라는 것을 잊다'는 바로 'olvidar que + 문장'으로 씁니다. de를 넣는 것은 olvidarse de(재귀형)일 때만 가능하며, 여기서는 olvides(재귀 아님)이므로 que만 씁니다. 불필요하게 de que를 쓰는 실수를 '데께이스모(dequeísmo)'라고 합니다.","x":["que: olvidar + que + 문장, 올바른 연결 → 정답 ✓","a que: olvidar은 전치사 a를 요구하지 않습니다 ✗","de que: 재귀형 olvidarse de일 때만 가능하고 여기선 틀린 표현입니다 ✗","ø: 동사와 절을 이어 줄 que가 반드시 필요합니다 ✗"]},{"id":"G154","q":"Tengo flores de ____ colores.","o":["todos los","todas las","todas","todos"],"a":0,"k":"todo의 성·수 일치","t":"나는 온갖 색깔의 꽃을 가지고 있다.","e":"todo(모든)는 뒤 명사의 성·수에 맞추고, 보통 정관사를 함께 써서 'todo + 관사 + 명사' 형태가 됩니다. color(색)는 남성 명사이므로 복수는 'todos los colores'입니다. 'flores'가 여성이라고 todas를 고르지 않도록 주의하세요.","x":["todos los: 남성 복수 colores에 맞는 형태 → 정답 ✓","todas las: 여성 복수형인데 color는 남성 명사라 ✗","todas: 성이 맞지 않고 관사도 빠져 ✗","todos: 성은 맞지만 정관사 los가 빠져 어색합니다 ✗"]},{"id":"G155","q":"En ese autobús ____ caben más pasajeros. Vamos a esperar el siguiente.","o":["todavía","ya","ya no","aún"],"a":2,"k":"ya no","t":"저 버스에는 더 이상 승객이 탈 자리가 없다. 다음 버스를 기다리자.","e":"'ya no'는 '이제는 더 이상 ~않다'라는 뜻으로, 전에는 가능했지만 지금은 아닌 상태를 나타냅니다. 버스가 꽉 차서 더 이상 사람이 들어갈 수 없으므로 ya no가 맞습니다. 예: Ya no vivo aquí. (나는 더 이상 여기 살지 않는다.)","x":["todavía: '아직'이라는 뜻이라 '아직 더 들어간다'가 되어 뒷문장과 모순입니다 ✗","ya: '이미/벌써'로 부정어가 없어 '더 이상 안 된다'는 뜻이 안 됩니다 ✗","ya no: '더 이상 ~않다' → 정답 ✓","aún: todavía와 같은 '아직'이라는 뜻이라 ✗"]},{"id":"G156","q":"Manuel tiene ____ auto muy antiguo.","o":["lo","un","ø","el"],"a":1,"k":"부정관사 un","t":"마누엘은 아주 오래된 차를 한 대 가지고 있다.","e":"처음 언급하는 '어떤 하나의' 물건에는 부정관사(un, una)를 씁니다. auto(자동차)는 남성 명사이므로 'un auto'입니다. auto는 중남미에서 주로 쓰는 말이고, 스페인에서는 coche라고 많이 합니다.","x":["lo: 중성 관사/대명사로 명사 앞에 쓰지 않습니다 ✗","un: 남성 단수 부정관사, 처음 소개하는 차 → 정답 ✓","ø: tener + 셀 수 있는 단수 명사 + 형용사에서는 관사가 필요합니다 ✗","el: 정관사(그)로 이미 알려진 특정한 차일 때 써서 ✗"]},{"id":"G157","q":"Me encanta su forma ____ escribir, sin duda es mi autor favorito.","o":["a","con","de","en"],"a":2,"k":"명사 + de + 동사원형","t":"나는 그의 글 쓰는 방식이 정말 좋아. 그는 단연 내가 가장 좋아하는 작가야.","e":"'~하는 방식'은 'forma de + 동사원형' 또는 'manera de + 동사원형'으로 표현합니다. 명사 뒤에서 그 명사를 설명하는 동사원형은 전치사 de로 연결합니다. 예: su manera de hablar (그의 말하는 방식)","x":["a: forma 뒤에 a를 쓰지 않습니다 ✗","con: '~와 함께'라는 뜻이라 의미가 맞지 않습니다 ✗","de: forma de + 동사원형 '~하는 방식' → 정답 ✓","en: '~안에서'라는 뜻으로 이 구조에 맞지 않습니다 ✗"]},{"id":"G158","q":"¿____ han arreglado el ascensor?","o":["Ahora no","Todavía no","Hasta ahora","Ya no"],"a":1,"k":"todavía no","t":"아직 엘리베이터를 안 고쳤어요?","e":"'todavía no'는 '아직 ~하지 않았다'라는 뜻으로 현재완료(han arreglado)와 자주 함께 씁니다. 고쳐질 것을 기대하지만 아직 안 됐는지를 묻는 상황이므로 todavía no가 맞습니다.","x":["Ahora no: '지금은 아니다'라는 뜻으로 완료 시제와 어울리지 않습니다 ✗","Todavía no: '아직 ~않았다' → 정답 ✓","Hasta ahora: '지금까지'로 부정 의미가 없어 문맥과 맞지 않습니다 ✗","Ya no: '더 이상 ~않다'로 고치는 동작과 어울리지 않습니다 ✗"]},{"id":"G159","q":"No tenemos ____ manzanas para hacer la tarta.","o":["suficientes","suficiente","unas","muchos"],"a":0,"k":"suficiente 수 일치","t":"타르트를 만들 만큼 사과가 충분하지 않다.","e":"suficiente(충분한)는 명사 앞에서 수에 맞춰 변합니다. manzanas(사과들)가 복수이므로 suficientes가 됩니다. 성은 변하지 않아서 남성·여성 모두 suficiente/suficientes를 씁니다.","x":["suficientes: 복수 명사 manzanas에 맞는 형태 → 정답 ✓","suficiente: 단수형이라 복수 명사와 맞지 않습니다 ✗","unas: '몇 개의'라는 뜻으로 '사과가 몇 개 없다'가 되어 어색합니다 ✗","muchos: 남성형이라 여성 명사 manzanas와 성이 맞지 않습니다 ✗"]},{"id":"G160","q":"En la cocina ____ algunos platos sucios, voy a lavarlos.","o":["son","hay","están","es"],"a":1,"k":"hay (존재)","t":"부엌에 더러운 접시가 몇 개 있어서, 내가 씻을게.","e":"'~이 있다'라는 존재를 처음 알릴 때는 haber의 특수형 hay를 씁니다. 특히 algunos, unos, 숫자 등 불특정한 명사 앞에서는 estar가 아니라 hay를 씁니다. 반면 정관사가 붙은 특정한 것의 위치는 estar로 말합니다(Los platos están en la cocina).","x":["son: ser는 성질·정체를 말할 때 쓰며 존재를 나타내지 않습니다 ✗","hay: 불특정한 것의 존재 '~이 있다' → 정답 ✓","están: 특정한 것의 위치에 쓰며 algunos 같은 불특정 명사와는 쓰지 않습니다 ✗","es: ser의 단수형으로 의미도 수도 맞지 않습니다 ✗"]},{"id":"G161","q":"Hoy ____ particularmente contento, ¿a qué se debe?","o":["estás","estés","eres","seas"],"a":0,"k":"estar + 감정","t":"너 오늘 유난히 기분이 좋구나, 무슨 일이야?","e":"contento(기쁜, 만족한)처럼 일시적인 기분·상태는 estar로 표현합니다. 'Hoy(오늘)'라는 말이 지금의 상태임을 보여 주고, 사실을 말하는 문장이므로 직설법 estás를 씁니다.","x":["estás: estar 직설법, 오늘의 일시적 기분 → 정답 ✓","estés: 접속법(바람·의심 등에 쓰는 형태)이라 평서문에 쓸 수 없습니다 ✗","eres: ser는 성격 같은 본질적 특징에 쓰고 contento와는 쓰지 않습니다 ✗","seas: ser의 접속법으로 동사도 형태도 맞지 않습니다 ✗"]},{"id":"G162","q":"____ tranquilamente cuando llamaron a la puerta.","o":["Estaban cenando","Han cenado","Cenarían","Estuvieron cenando"],"a":0,"k":"과거진행형","t":"그들이 조용히 저녁을 먹고 있을 때 누군가 문을 두드렸다.","e":"과거의 어떤 순간에 진행 중이던 배경 동작은 불완료과거 진행형(estaba + 현재분사)으로, 그 중간에 끼어든 사건은 단순과거(llamaron)로 씁니다. '저녁을 먹던 중에 → 초인종이 울렸다'는 구조이므로 Estaban cenando가 맞습니다.","x":["Estaban cenando: 과거에 진행 중이던 배경 동작 → 정답 ✓","Han cenado: 현재완료라 과거 이야기의 배경으로 쓸 수 없습니다 ✗","Cenarían: 조건법(~할 텐데)이라 의미가 맞지 않습니다 ✗","Estuvieron cenando: 끝난 기간 전체를 말할 때 써서 끼어든 사건의 배경으로는 어색합니다 ✗"]},{"id":"G163","q":"No conozco a la mujer ____ la que está charlando mi madre.","o":["de","a","con","para"],"a":2,"k":"전치사 + 관계대명사","t":"나는 우리 엄마와 이야기하고 있는 그 여자를 모른다.","e":"관계절 안의 동사가 전치사를 요구하면 그 전치사를 관계대명사(la que) 앞에 씁니다. charlar con alguien(누구와 수다 떨다)이므로 'con la que'가 됩니다. 원래 문장: Mi madre está charlando con la mujer.","x":["de: charlar de는 '~에 대해 이야기하다'라서 사람에게는 맞지 않습니다 ✗","a: charlar은 a를 쓰지 않습니다 ✗","con: charlar con(~와 이야기하다) → 정답 ✓","para: '~을 위해'라는 뜻이라 의미가 맞지 않습니다 ✗"]},{"id":"G164","q":"¿Todavía te duele ____ espalda?","o":["tuya","tu","ø","la"],"a":3,"k":"신체 부위 + 정관사","t":"아직도 허리가 아프니?","e":"스페인어에서는 신체 부위 앞에 소유사(tu) 대신 정관사(el, la)를 씁니다. 누구의 신체인지는 간접목적격 대명사 te(너에게)가 이미 보여 주기 때문입니다. espalda(등, 허리)는 여성 명사이므로 la espalda입니다.","x":["tuya: 소유대명사로 명사 앞에 올 수 없습니다 ✗","tu: 문법상 이해는 되지만 te가 있으므로 신체 부위에는 정관사를 씁니다 ✗","ø: 주어인 명사 앞에는 관사가 필요합니다 ✗","la: 신체 부위 앞 정관사 → 정답 ✓"]},{"id":"G165","q":"Sed un poquito pacientes, vamos a llegar ____ diez minutos.","o":["en","a","de","desde"],"a":0,"k":"en + 시간","t":"조금만 참아 줘, 우리 10분 후에 도착할 거야.","e":"'en + 시간'은 '~ 후에(~ 안에)'라는 뜻으로 지금부터 걸리는 시간을 말합니다. 스페인에서는 'dentro de diez minutos'도 많이 쓰고, 중남미에서는 en이 특히 흔합니다. 참고로 Sed는 vosotros에게 하는 ser의 명령형으로 스페인식 표현입니다.","x":["en: en + 시간 '~ 후에' → 정답 ✓","a: a diez minutos는 '10분 거리에'라는 뜻이라 ✗","de: 시간 길이 앞에 de를 쓰지 않습니다 ✗","desde: '~부터'라는 뜻이라 의미가 맞지 않습니다 ✗"]},{"id":"G166","q":"____ mi punto de vista, hay que ser valiente para tener un negocio propio.","o":["De","Desde","Por","En"],"a":1,"k":"desde mi punto de vista","t":"내 관점에서는, 자기 사업을 하려면 용기가 있어야 한다.","e":"'내 관점에서 보면'은 관용적으로 'desde mi punto de vista'라고 합니다. desde(~에서부터)가 '어떤 위치에서 바라보다'라는 느낌을 줍니다. 비슷한 표현: en mi opinión(내 생각에는)","x":["De: punto de vista 앞에 쓰지 않는 표현입니다 ✗","Desde: desde mi punto de vista '내 관점에서' → 정답 ✓","Por: '~때문에/~을 통해'라 이 표현과 맞지 않습니다 ✗","En: en mi opinión과 혼동한 것으로 표준 표현이 아닙니다 ✗"]},{"id":"G167","q":"Cuando salimos del despacho de Mariana, sus empleados ya ____.","o":["se habían ido","se han ido","se van","se vayan"],"a":0,"k":"과거완료","t":"우리가 마리아나의 사무실에서 나왔을 때, 그녀의 직원들은 이미 가 버린 뒤였다.","e":"과거의 어떤 시점(salimos)보다 더 먼저 끝난 일은 과거완료(había + 과거분사)로 씁니다. 우리가 나오기 전에 직원들이 이미 떠났으므로 'se habían ido'가 맞습니다. ya(이미)와 자주 함께 씁니다.","x":["se habían ido: 과거보다 더 이전에 끝난 일 → 정답 ✓","se han ido: 현재완료라 과거 이야기와 시제가 맞지 않습니다 ✗","se van: 현재형이라 시제가 맞지 않습니다 ✗","se vayan: 접속법 현재로 이 문장에 쓸 이유가 없습니다 ✗"]},{"id":"G168","q":"Cuando vayamos en el autocar, pararemos ____ tres horas para estirar las piernas.","o":["en cada","de cada","para cada","cada"],"a":3,"k":"cada + 시간","t":"관광버스를 타고 갈 때, 다리를 펴기 위해 세 시간마다 멈출 거야.","e":"'~마다'는 전치사 없이 'cada + 숫자 + 명사'로 씁니다. 'cada tres horas'는 '세 시간마다'라는 뜻입니다. 예: cada dos días (이틀마다). autocar는 스페인에서 장거리 버스를 가리킵니다.","x":["en cada: 앞에 en을 붙이지 않습니다 ✗","de cada: '각각의 ~ 중에서'라는 뜻이 되어 ✗","para cada: '각각을 위해'라는 뜻이라 ✗","cada: cada + 시간 '~마다' → 정답 ✓"]},{"id":"G169","q":"Querría un helado de dos bolas, ____ de vainilla y otra de chocolate.","o":["una","uno","la una","un"],"a":0,"k":"una ... otra","t":"아이스크림 두 스쿱짜리 주세요, 하나는 바닐라, 다른 하나는 초콜릿으로요.","e":"bola(스쿱, 공)는 여성 명사이므로 '하나는 ~, 다른 하나는 ~'을 'una ... otra ...'로 표현합니다. 대명사로 쓰인 una가 bola를 대신합니다. 남성 명사라면 'uno ... otro'가 됩니다.","x":["una: 여성 명사 bola를 대신하는 '하나' → 정답 ✓","uno: 남성형이라 여성 명사 bola와 맞지 않습니다 ✗","la una: 이 구조에서는 관사 없이 una ... otra로 씁니다 ✗","un: 명사 없이 단독으로 쓸 수 없는 형태입니다 ✗"]},{"id":"G170","q":"____ viernes salgo de clase antes que el resto de días.","o":["ø","Al","Los","Las"],"a":2,"k":"요일 복수 (매주)","t":"금요일마다 나는 다른 요일보다 수업이 일찍 끝난다.","e":"'매주 ~요일마다'는 정관사 복수를 붙여 'los + 요일'로 표현합니다. 요일은 모두 남성 명사이므로 'los viernes'입니다. viernes는 단수와 복수 형태가 같아서 관사로 구별합니다.","x":["ø: 요일 앞 관사가 빠지면 '매주 금요일'이라는 뜻이 되지 않습니다 ✗","Al: '~할 때'처럼 쓰이며 요일 반복 표현이 아닙니다 ✗","Los: 남성 복수 정관사, '금요일마다' → 정답 ✓","Las: 여성형인데 요일은 남성 명사라 ✗"]},{"id":"G171","q":"Estos zapatos ____ pequeños.","o":["me quedan","me quedo","queda","me queda"],"a":0,"k":"quedar (옷이 맞다)","t":"이 신발은 나에게 작다.","e":"quedar은 '(옷이) ~하게 맞다'라는 뜻으로 gustar처럼 씁니다. 옷·신발이 주어이고, 입는 사람은 간접목적격 대명사(me, te, le...)로 나타냅니다. 주어 zapatos가 복수이므로 'me quedan'입니다.","x":["me quedan: 복수 주어 zapatos + 나에게 → 정답 ✓","me quedo: '나는 머무른다'라는 뜻이 되어 ✗","queda: 단수형이고 '나에게'를 뜻하는 me도 없습니다 ✗","me queda: 단수형이라 복수 주어 zapatos와 맞지 않습니다 ✗"]},{"id":"G172","q":"¿____ mucho tiempo que estudias japonés?","o":["Hace","Desde hace","Desde","Desde que"],"a":0,"k":"hace + 시간 + que","t":"일본어 공부한 지 오래됐니?","e":"'~한 지 (시간)이 되었다'는 'Hace + 시간 + que + 현재형'으로 표현합니다. 질문형은 '¿Hace mucho tiempo que...?'가 됩니다. 비교: Estudio japonés desde hace dos años. (2년 전부터 일본어를 공부한다.)","x":["Hace: hace + 시간 + que 구조 → 정답 ✓","Desde hace: 문장 앞에서 que와 함께 쓰는 구조가 아닙니다 ✗","Desde: 뒤에 시점이 와야 하며 que 구조와 맞지 않습니다 ✗","Desde que: '~한 이후로'라는 접속사라 문장이 성립하지 않습니다 ✗"]},{"id":"G173","q":"Este jugador ha marcado ____ goles que ningún otro este año.","o":["tan","muchos","tantos","más"],"a":3,"k":"우등비교 más que","t":"이 선수는 올해 다른 어떤 선수보다 더 많은 골을 넣었다.","e":"'~보다 더 많은'은 'más + 명사 + que'로 씁니다. 'que ningún otro'는 '다른 어떤 것보다도'라는 강조 표현입니다. 동등비교 tantos는 que가 아니라 como와 함께 쓰이므로 맞지 않습니다.","x":["tan: 형용사·부사 앞에 쓰며 명사 앞에 쓰지 않습니다 ✗","muchos: 비교 표현이 아니라 que와 이어지지 않습니다 ✗","tantos: 동등비교로 como와 짝을 이루므로 que와 쓸 수 없습니다 ✗","más: más + 명사 + que '~보다 더 많은' → 정답 ✓"]},{"id":"G174","q":"¡Qué casa ____ bonita!","o":["tanto","tantos","tan","tanta"],"a":2,"k":"감탄문 qué ... tan","t":"정말 예쁜 집이다!","e":"'¡Qué + 명사 + tan/más + 형용사!'는 '정말 ~한 (명사)구나!'라는 감탄문입니다. 형용사 bonita 앞에는 변하지 않는 부사 tan을 씁니다. 예: ¡Qué día tan bonito! (정말 멋진 날이다!)","x":["tanto: 동사 뒤나 비교에 쓰는 형태로 형용사 앞에 쓰지 않습니다 ✗","tantos: 명사 앞 '그렇게 많은'이라는 형태라 ✗","tan: 형용사 앞의 '그렇게/정말' → 정답 ✓","tanta: 여성 단수 명사 앞에 쓰는 형태라 형용사 앞에는 ✗"]},{"id":"G175","q":"Felisa y Adrián ____ enamorados.","o":["estén","están","son","sean"],"a":1,"k":"estar enamorado","t":"펠리사와 아드리안은 사랑에 빠져 있다.","e":"enamorado(사랑에 빠진)는 감정 상태를 나타내므로 estar와 씁니다. 주어가 두 사람(3인칭 복수)이고 사실을 말하는 평서문이므로 직설법 están이 맞습니다.","x":["estén: 접속법이라 평서문에 쓸 수 없습니다 ✗","están: estar 3인칭 복수, 감정 상태 → 정답 ✓","son: ser는 enamorado와 함께 쓰지 않습니다 ✗","sean: ser의 접속법이라 동사도 형태도 맞지 않습니다 ✗"]},{"id":"G176","q":"Si quieres más pan, llama ____ camarero.","o":["al","a","por el","del"],"a":0,"k":"a + el = al","t":"빵이 더 필요하면 웨이터를 불러.","e":"llamar a alguien(누구를 부르다)처럼 사람이 직접목적어일 때는 전치사 a를 씁니다. a 뒤에 정관사 el이 오면 축약해서 al이 됩니다. 그래서 'llama al camarero'입니다.","x":["al: a + el, 사람 목적어 앞의 a → 정답 ✓","a: 관사 el이 빠져 a camarero는 어색합니다 ✗","por el: '웨이터를 통해/위해'라는 뜻이 되어 ✗","del: de + el로 '웨이터의'라는 뜻이 되어 ✗"]},{"id":"G177","q":"Hoy ____ especialmente guapo. Te queda muy bien ese jersey.","o":["estás","seas","estés","eres"],"a":0,"k":"estar + 외모(일시적)","t":"너 오늘 특히 멋있다. 그 스웨터가 정말 잘 어울려.","e":"guapo(잘생긴, 멋진)를 ser와 쓰면 원래 외모를, estar와 쓰면 '오늘따라 멋있어 보인다'는 일시적 모습을 뜻합니다. Hoy(오늘)와 스웨터 이야기가 나오므로 estás가 맞습니다. jersey는 스페인에서 '스웨터'를 뜻합니다.","x":["estás: estar, 오늘 잠깐 보이는 모습 → 정답 ✓","seas: 접속법이라 평서문에 쓸 수 없습니다 ✗","estés: 접속법이라 평서문에 쓸 수 없습니다 ✗","eres: 본래 외모를 뜻해 hoy와 어울리지 않습니다 ✗"]},{"id":"G178","q":"____ la verdad, ¿qué pasó aquel día?","o":["Dijiste","Dices","Dice","Di"],"a":3,"k":"불규칙 명령형 di","t":"사실대로 말해, 그날 무슨 일이 있었어?","e":"decir(말하다)의 tú 긍정 명령형은 불규칙형 di입니다. '사실을 말해!'라고 상대에게 명령·요청하는 문장이므로 'Di la verdad'가 됩니다. 비슷한 불규칙 명령형: haz(해), pon(놓아), ven(와).","x":["Dijiste: 단순과거 '너는 말했다'라서 명령이 아닙니다 ✗","Dices: 현재형 '너는 말한다'라서 명령이 아닙니다 ✗","Dice: 3인칭 현재형이라 ✗","Di: decir의 tú 명령형 '말해' → 정답 ✓"]},{"id":"G179","q":"¿____ suelen almorzar ustedes?","o":["Dónde","Donde","Adonde","Adónde"],"a":0,"k":"의문사 dónde","t":"여러분은 보통 어디에서 점심을 드세요?","e":"장소 '어디에서'를 묻는 의문사는 악센트가 있는 dónde입니다. almorzar(점심 먹다)는 이동 동사가 아니므로 '어디로'를 뜻하는 adónde는 맞지 않습니다. 의문사는 항상 악센트를 찍습니다.","x":["Dónde: 의문사 '어디에서' → 정답 ✓","Donde: 악센트가 없으면 관계부사라 의문문에 쓸 수 없습니다 ✗","Adonde: 악센트 없는 관계부사이고 방향을 뜻해 ✗","Adónde: '어디로'라는 방향 의문사로 이동 동사와 씁니다 ✗"]},{"id":"G180","q":"¿Qué hizo Luis Miguel después de ____?","o":["se gradúa","se graduar","graduarse","graduar se"],"a":2,"k":"전치사 + 재귀동사 원형","t":"루이스 미겔은 졸업한 후에 무엇을 했니?","e":"전치사(después de) 뒤에는 동사원형을 씁니다. graduarse(졸업하다)는 재귀동사이므로 재귀대명사 se를 원형 끝에 붙여 'graduarse'라고 씁니다.","x":["se gradúa: 활용형이라 전치사 바로 뒤에 올 수 없습니다 ✗","se graduar: 원형 앞에 se를 떼어 쓰지 않습니다 ✗","graduarse: 전치사 뒤 재귀동사 원형 → 정답 ✓","graduar se: 띄어 쓰지 않고 붙여 씁니다 ✗"]},{"id":"G181","q":"No tengo ganas de comer ni ____, así que vamos a esperar.","o":["a ella no","a ella sí","ella tampoco","ella también"],"a":2,"k":"부정 동의 tampoco","t":"나는 먹고 싶지 않고 그녀도 마찬가지야, 그러니 기다리자.","e":"부정문에 '~도 역시 아니다'라고 동의할 때는 tampoco를 씁니다. 'No tengo ganas de comer'가 부정이고 ella가 주어이므로 'ni ella tampoco(그녀도 역시 아니다)'가 됩니다. 긍정문에 동의할 때는 también을 씁니다.","x":["a ella no: '그녀에게는'이라는 간접목적어 형태라 tener ganas 구문과 맞지 않습니다 ✗","a ella sí: 형태도 맞지 않고 '그녀는 그렇다'는 반대 의미가 됩니다 ✗","ella tampoco: 부정에 대한 동의 '그녀도 아니다' → 정답 ✓","ella también: 긍정문에 동의할 때 써서 부정 문장과 맞지 않습니다 ✗"]},{"id":"G182","q":"Alberto se casó con ____ mujer hace cinco años.","o":["suya","la suya","su","tu"],"a":2,"k":"소유형용사 su","t":"알베르토는 5년 전에 그의 아내와 결혼했다.","e":"명사 앞에 오는 3인칭 소유형용사는 su(그의/그녀의/당신의)입니다. 주어 Alberto가 3인칭이고 mujer가 단수이므로 'su mujer'가 됩니다. 스페인에서는 mujer가 '아내'라는 뜻으로도 자주 쓰입니다.","x":["suya: 명사 뒤나 단독으로 쓰는 형태라 명사 앞에 올 수 없습니다 ✗","la suya: 소유대명사(그의 것)로 명사 앞에 올 수 없습니다 ✗","su: 명사 앞 3인칭 소유형용사 → 정답 ✓","tu: '너의'라서 주어 Alberto와 맞지 않습니다 ✗"]},{"id":"G183","q":"Soy ____ médico, trabajo en este centro de salud.","o":["algún","uno","ø","un"],"a":2,"k":"직업 앞 무관사","t":"나는 의사입니다. 이 보건소에서 일해요.","e":"ser 뒤에 직업·국적·종교 등을 말할 때는 보통 관사를 쓰지 않습니다. 'Soy médico(나는 의사다)'처럼 씁니다. 단, 형용사가 붙으면 관사를 씁니다: Soy un médico muy famoso.","x":["algún: '어떤'이라는 뜻으로 '어떤 의사'가 되어 어색합니다 ✗","uno: 명사 앞에서는 un으로 줄여 쓰며, 그래도 관사가 필요 없습니다 ✗","ø: ser + 직업은 관사 없이 → 정답 ✓","un: 형용사 없이 직업만 말할 때는 관사를 쓰지 않습니다 ✗"]},{"id":"G184","q":"No ____ lo que ha explicado el profe de física.","o":["entender","entiendo","entendo","entendido"],"a":1,"k":"어간모음 변화 e→ie","t":"물리 선생님이 설명한 것을 이해하지 못하겠어.","e":"entender(이해하다)는 현재형에서 강세가 오는 어간의 e가 ie로 바뀝니다: entiendo, entiendes, entiende... 주어가 '나(yo)'이므로 entiendo가 맞습니다. profe는 profesor의 구어체 줄임말입니다.","x":["entender: 동사원형이라 주어 '나'와 활용되지 않았습니다 ✗","entiendo: e→ie 변화한 1인칭 현재형 → 정답 ✓","entendo: 어간 변화를 하지 않은 잘못된 형태입니다 ✗","entendido: 과거분사라 단독으로 쓸 수 없습니다 ✗"]},{"id":"G185","q":"Quiero que ____ feliz.","o":["eres","serás","vas a ser","seas"],"a":3,"k":"querer que + 접속법","t":"나는 네가 행복하길 바라.","e":"querer que(~하기를 원하다)처럼 바람을 나타내는 표현 뒤, 주어가 바뀌면(나 → 너) que 뒤 동사는 접속법(바람·의심·감정을 나타내는 동사 형태)을 씁니다. ser의 tú 접속법 현재는 seas입니다.","x":["eres: 직설법이라 바람 표현 뒤에 쓸 수 없습니다 ✗","serás: 미래형 직설법이라 ✗","vas a ser: 근접미래(직설법)라 ✗","seas: ser 접속법 현재 → 정답 ✓"]},{"id":"G186","q":"Están cansados porque han trabajado ____.","o":["muchos","muy","mucha","mucho"],"a":3,"k":"부사 mucho","t":"그들은 많이 일해서 피곤하다.","e":"동사(han trabajado)를 꾸며 '많이'라는 뜻을 나타낼 때는 부사 mucho를 씁니다. 부사는 성·수에 따라 변하지 않으므로 주어가 복수여도 mucho입니다. muy는 형용사·부사 앞에서만 씁니다(muy cansados).","x":["muchos: 형용사 복수형으로 명사 앞에 쓰는 형태라 ✗","muy: 형용사·부사 앞에만 쓰고 동사 뒤에 단독으로 쓰지 않습니다 ✗","mucha: 여성 단수 형용사형이라 ✗","mucho: 동사를 꾸미는 부사 '많이' → 정답 ✓"]},{"id":"G187","q":"Suspendió la prueba escrita ____ no había practicado nada.","o":["por eso","como","por","porque"],"a":3,"k":"원인 porque","t":"그는 연습을 전혀 하지 않았기 때문에 필기시험에 떨어졌다.","e":"porque(왜냐하면, ~때문에)는 결과를 먼저 말하고 뒤에서 이유를 설명할 때 씁니다. 같은 이유를 나타내는 como는 반드시 문장 맨 앞에 와야 하므로 중간에는 porque가 맞습니다. suspender는 스페인에서 '(시험에) 떨어지다'라는 뜻입니다.","x":["por eso: '그래서'라는 결과 표현이라 원인·결과가 뒤바뀝니다 ✗","como: 이유의 como는 문장 맨 앞에 와야 해서 ✗","por: 전치사라 뒤에 활용된 동사 문장이 올 수 없습니다 ✗","porque: 뒤에 이유를 설명하는 접속사 → 정답 ✓"]},{"id":"G188","q":"Este vaso es muy frágil, es ____ cristal.","o":["al","de","a","del"],"a":1,"k":"재료 de","t":"이 컵은 아주 깨지기 쉬워, 유리로 만들어진 거야.","e":"물건의 재료를 말할 때는 'ser de + 재료(관사 없이)'를 씁니다. 'es de cristal'은 '유리로 되어 있다'라는 뜻입니다. 예: La mesa es de madera. (탁자는 나무로 되어 있다.)","x":["al: a + el로 재료를 나타내지 않습니다 ✗","de: ser de + 재료 → 정답 ✓","a: 재료를 나타내는 전치사가 아닙니다 ✗","del: 재료 앞에는 관사를 붙이지 않습니다 ✗"]},{"id":"G189","q":"____ aquí desde 1998 hasta 2002.","o":["Trabajarían","Trabajaban","Han trabajado","Trabajaron"],"a":3,"k":"단순과거 (기간)","t":"그들은 1998년부터 2002년까지 여기서 일했다.","e":"시작과 끝이 분명한 과거의 기간(desde ... hasta ...)은 단순과거(pretérito indefinido)로 씁니다. 이미 끝난 하나의 덩어리로 보기 때문입니다. 예: Viví en Chile de 2010 a 2015. (2010~2015년 칠레에 살았다.)","x":["Trabajarían: 조건법(~할 텐데)이라 ✗","Trabajaban: 불완료과거는 배경·습관에 쓰여 끝이 정해진 기간과 어울리지 않습니다 ✗","Han trabajado: 현재완료는 현재와 연결된 시간에 써서 2002년까지라는 과거 기간과 맞지 않습니다 ✗","Trabajaron: 끝난 과거 기간의 단순과거 → 정답 ✓"]},{"id":"G190","q":"París ____ en Francia.","o":["estaba","era","está","es"],"a":2,"k":"estar (위치)","t":"파리는 프랑스에 있다.","e":"사물·장소의 위치를 말할 때는 estar를 씁니다. 도시가 어디에 있는지는 변하지 않는 사실이라도 위치이므로 estar를 씁니다. 단, 행사가 열리는 장소는 ser를 씁니다(La fiesta es en mi casa).","x":["estaba: 불완료과거라 지금도 사실인 내용에는 어색합니다 ✗","era: ser는 위치를 말할 때 쓰지 않습니다 ✗","está: 위치를 나타내는 estar 현재형 → 정답 ✓","es: ser는 위치 표현에 쓰지 않습니다 ✗"]},{"id":"G191","q":"Cuando ____ joven tenía poco dinero, pero era muy feliz.","o":["fui","era","he sido","estaba siendo"],"a":1,"k":"불완료과거 (나이·묘사)","t":"젊었을 때 나는 돈이 별로 없었지만, 아주 행복했다.","e":"과거의 나이, 시기, 상태를 묘사할 때는 불완료과거(pretérito imperfecto)를 씁니다. 'Cuando era joven(젊었을 때)'은 아주 자주 쓰는 표현입니다. 뒤의 tenía, era도 모두 불완료과거입니다.","x":["fui: 단순과거로 끝난 사건에 쓰며 시기 묘사에는 어색합니다 ✗","era: ser 불완료과거, 과거 시기 묘사 → 정답 ✓","he sido: 현재완료라 과거 시기 묘사와 맞지 않습니다 ✗","estaba siendo: 진행형으로 이런 상태 묘사에 쓰지 않습니다 ✗"]},{"id":"G192","q":"Perdona, ahora ____, no puedo ayudarte.","o":["trabajando","trabajo","he trabajado","estoy trabajando"],"a":3,"k":"현재진행형","t":"미안, 지금 일하는 중이라 도와줄 수가 없어.","e":"ahora(지금)와 함께 바로 이 순간 하고 있는 일을 말할 때는 estar + 현재분사를 씁니다. 'estoy trabajando'는 '일하는 중이다'라는 뜻입니다. 단순 현재 trabajo도 가능은 하지만 '지금 하는 중'이라는 의미가 약합니다.","x":["trabajando: 현재분사만 있고 estar가 빠져 ✗","trabajo: 습관적인 '일한다'에 더 가까워 지금 진행 중이라는 의미가 약합니다 ✗","he trabajado: 현재완료 '일했다'라서 ✗","estoy trabajando: 지금 진행 중인 동작 → 정답 ✓"]},{"id":"G193","q":"De pequeños, ____ al campo cada domingo.","o":["íbamos","habíamos ido","fuimos","hemos ido"],"a":0,"k":"불완료과거 (습관)","t":"어렸을 때 우리는 일요일마다 시골에 가곤 했다.","e":"과거에 반복된 습관 '~하곤 했다'는 불완료과거로 표현합니다. 'De pequeños(어렸을 때)'와 'cada domingo(일요일마다)'가 습관을 알려 줍니다. ir의 불완료과거는 불규칙형으로 iba, ibas, iba, íbamos...입니다.","x":["íbamos: ir 불완료과거, 과거의 습관 → 정답 ✓","habíamos ido: 과거완료라 습관을 나타내지 않습니다 ✗","fuimos: 단순과거로 한 번의 사건에 써서 cada domingo와 맞지 않습니다 ✗","hemos ido: 현재완료라 어린 시절 습관과 맞지 않습니다 ✗"]},{"id":"G194","q":"Estos son ____ hijos, Carlos y Ana María.","o":["nuestros","nosotros","nos","nuestro"],"a":0,"k":"소유형용사 nuestro","t":"이 아이들이 우리 아이들, 카를로스와 아나 마리아예요.","e":"nuestro(우리의)는 뒤의 명사에 성·수를 맞춥니다. hijos(아들딸들)는 남성 복수이므로 nuestros입니다. 남자아이와 여자아이가 섞인 경우에도 hijos라는 남성 복수형을 씁니다.","x":["nuestros: 남성 복수 hijos에 맞는 형태 → 정답 ✓","nosotros: 주격 인칭대명사 '우리는'이라 명사 앞에 쓸 수 없습니다 ✗","nos: 목적격 대명사라 ✗","nuestro: 단수형이라 hijos와 수가 맞지 않습니다 ✗"]},{"id":"G195","q":"____ jueves tengo clase de flamenco.","o":["Los","A los","Las","En las"],"a":0,"k":"요일 복수 (매주)","t":"목요일마다 나는 플라멩코 수업이 있다.","e":"'매주 ~요일에'는 전치사 없이 'los + 요일'로 씁니다. 요일은 남성 명사이므로 'Los jueves'입니다. 한국어로 '~에'가 붙어도 스페인어에서는 en이나 a를 쓰지 않습니다.","x":["Los: 남성 복수 정관사, '목요일마다' → 정답 ✓","A los: 요일 앞에 a를 붙이지 않습니다 ✗","Las: 요일은 남성 명사라 여성형은 ✗","En las: 전치사도 성도 맞지 않습니다 ✗"]},{"id":"G196","q":"¿____ es tu santo? El mío es el 1 de enero.","o":["Cómo","Qué","Quién","Cuándo"],"a":3,"k":"의문사 cuándo","t":"너의 영명축일은 언제야? 내 것은 1월 1일이야.","e":"santo는 자기 이름과 같은 성인(聖人)의 축일로, 스페인어권에서는 생일처럼 축하하기도 합니다. 대답이 날짜(1월 1일)이므로 '언제'를 묻는 cuándo가 맞습니다.","x":["Cómo: '어떻게'라서 날짜를 묻지 않습니다 ✗","Qué: '무엇'이라 ¿Qué es tu santo?는 '축일이 무엇이냐'가 되어 ✗","Quién: '누구'라서 ✗","Cuándo: '언제', 날짜를 묻는 의문사 → 정답 ✓"]},{"id":"G197","q":"Me gustaría tener un horario más flexible, ____ es imposible por ahora.","o":["pero","además","ni","o"],"a":0,"k":"대조 pero","t":"나는 좀 더 유연한 근무 시간을 갖고 싶지만, 지금으로서는 불가능하다.","e":"앞의 바람(유연한 시간을 원함)과 뒤의 현실(불가능함)이 서로 반대되므로 '하지만'을 뜻하는 pero를 씁니다. pero는 두 문장을 대조적으로 이어 주는 가장 기본적인 접속사입니다.","x":["pero: '하지만', 대조 → 정답 ✓","además: '게다가'라서 반대 내용을 잇지 못합니다 ✗","ni: '~도 아니다'라서 앞 문장이 부정일 때 씁니다 ✗","o: '또는'이라 선택을 나타내 ✗"]},{"id":"G198","q":"____ equipaje está en el auto.","o":["Nosotros","Nuestra","Nuestro","Nos"],"a":2,"k":"소유형용사 nuestro","t":"우리 짐은 차 안에 있다.","e":"equipaje(짐)는 남성 단수 명사이므로 '우리의'는 nuestro를 씁니다. -aje로 끝나는 명사는 대부분 남성입니다(el viaje, el mensaje). auto는 중남미에서 '차'를 뜻합니다.","x":["Nosotros: 주격 대명사 '우리는'이라 명사 앞에 쓸 수 없습니다 ✗","Nuestra: 여성형인데 equipaje는 남성 명사라 ✗","Nuestro: 남성 단수 소유형용사 → 정답 ✓","Nos: 목적격 대명사라 ✗"]},{"id":"G199","q":"Raúl nació el 23 ____ septiembre.","o":["en","a","por","de"],"a":3,"k":"날짜 표현 de","t":"라울은 9월 23일에 태어났다.","e":"날짜는 'el + 일 + de + 월'로 씁니다. 그래서 '9월 23일'은 'el 23 de septiembre'입니다. 연도까지 말할 때도 de를 씁니다: el 23 de septiembre de 1990.","x":["en: 날짜 사이에 en을 쓰지 않습니다(en septiembre는 '9월에') ✗","a: 날짜 표현에 쓰지 않습니다 ✗","por: 날짜 표현에 쓰지 않습니다 ✗","de: 일 + de + 월 → 정답 ✓"]},{"id":"G200","q":"No hay ____ problema, si tiene el recibo, puede descambiar el producto.","o":["algún","ø","el","un"],"a":1,"k":"부정문 무관사","t":"문제없어요. 영수증이 있으면 상품을 교환하실 수 있어요.","e":"'No hay problema(문제없다)'는 관사 없이 쓰는 고정 표현입니다. 부정문에서 hay 뒤의 불특정 명사는 관사를 생략하는 경우가 많습니다. 강조하고 싶으면 'No hay ningún problema'라고 합니다. descambiar는 스페인 구어로 '(산 물건을) 교환·환불하다'입니다.","x":["algún: 부정문에서는 ningún을 써야 해서 ✗","ø: No hay problema, 관사 없는 고정 표현 → 정답 ✓","el: hay는 정관사와 함께 쓰지 않습니다 ✗","un: 부정문 고정 표현에서는 관사를 넣지 않습니다 ✗"]},{"id":"G201","q":"____ hacía mucho frío, encendí la estufa.","o":["Así que","Como","Porque","Aunque"],"a":1,"k":"이유 como (문두)","t":"날씨가 아주 추웠기 때문에, 나는 난로를 켰다.","e":"이유를 먼저 말하고 결과를 뒤에 말할 때는 문장 맨 앞에 como(~이니까, ~이라서)를 씁니다. porque는 보통 문장 중간에서 결과 뒤에 이유를 붙일 때 씁니다. 예: Como llovía, me quedé en casa. (비가 와서 집에 있었다.)","x":["Así que: '그래서'로 문장 맨 앞에 와서 이유를 이끌 수 없습니다 ✗","Como: 문두에서 이유를 나타내는 접속사 → 정답 ✓","Porque: 이유를 나타내지만 보통 문장 맨 앞에는 쓰지 않습니다 ✗","Aunque: '비록 ~이지만'이라서 의미가 반대가 됩니다 ✗"]},{"id":"G202","q":"¿A qué ____ tu hermano mayor?","o":["se dedica","dedica","lo dedica","le dedica"],"a":0,"k":"dedicarse a","t":"네 형은 무슨 일을 하니?","e":"'¿A qué se dedica?'는 '직업이 무엇인가요?'라는 뜻의 자주 쓰는 표현입니다. dedicarse a(~에 종사하다)는 재귀동사이므로 se가 필요하고, 주어가 tu hermano(3인칭)라서 'se dedica'가 됩니다.","x":["se dedica: 재귀동사 dedicarse 3인칭 → 정답 ✓","dedica: 재귀대명사 se가 빠져 '~을 바치다'라는 다른 뜻이 됩니다 ✗","lo dedica: '그것을 바친다'라는 뜻이 되어 ✗","le dedica: '그에게 바친다'라는 뜻이 되어 ✗"]},{"id":"G203","q":"Patricia sabe que su exnovio se ha casado, ____ dije yo.","o":["le","se lo","se la","le lo"],"a":1,"k":"간접+직접 목적격 se lo","t":"파트리시아는 전 남자친구가 결혼한 걸 알아, 내가 그녀에게 말해 줬거든.","e":"간접목적격(le: 그녀에게)과 직접목적격(lo: 그것을)이 함께 오면 le가 se로 바뀌어 'se lo'가 됩니다. 여기서 lo는 '전 남자친구가 결혼했다는 사실' 전체를 가리키는 중성 대명사입니다.","x":["le: '그녀에게'만 있고 '그것을'이 빠져 ✗","se lo: le → se + lo(그 사실을) → 정답 ✓","se la: la는 여성 명사를 받는데 가리키는 것은 사실(중성)이라 ✗","le lo: le와 lo가 함께 오면 반드시 se lo로 바뀝니다 ✗"]},{"id":"G204","q":"Maribel ha llamado ____ confirmar su asistencia al evento.","o":["a","sobre","para","de"],"a":2,"k":"목적 para","t":"마리벨이 행사 참석을 확인하려고 전화했어.","e":"'~하기 위해'라는 목적은 'para + 동사원형'으로 나타냅니다. 전화한 목적이 참석 확인이므로 'para confirmar'가 맞습니다.","x":["a: 이동 동사 뒤 목적에는 쓸 수 있지만 llamar 뒤 목적 표현으로는 para가 자연스럽습니다 ✗","sobre: '~에 관해'라서 동사원형과 목적을 나타내지 않습니다 ✗","para: para + 동사원형 '~하기 위해' → 정답 ✓","de: 목적을 나타내지 않습니다 ✗"]},{"id":"G205","q":"____ compañeras de clase son simpatiquísimas.","o":["Mías","Mis","De mis","Mi"],"a":1,"k":"소유형용사 mis","t":"내 반 친구들은 엄청 친절하다.","e":"명사 앞에 오는 '나의'는 mi이고, 명사가 복수면 mis가 됩니다. compañeras(여자 친구들)가 복수이므로 mis입니다. mi/mis는 남성·여성 구분이 없습니다. simpatiquísimas는 simpáticas의 최상급(-ísimo) 형태입니다.","x":["Mías: 명사 뒤에 오는 형태라 명사 앞에 쓸 수 없습니다 ✗","Mis: 명사 앞 1인칭 소유형용사 복수 → 정답 ✓","De mis: 앞에 de가 붙으면 주어가 성립하지 않습니다 ✗","Mi: 단수형이라 복수 명사와 맞지 않습니다 ✗"]},{"id":"G206","q":"____ pantalones me quedan largos.","o":["Estas","Esta","Este","Estos"],"a":3,"k":"지시형용사 estos","t":"이 바지는 나에게 길다.","e":"지시형용사 este(이)는 명사의 성·수에 맞춥니다. pantalones(바지)는 남성 복수 명사이므로 estos가 맞습니다. 스페인어에서 바지는 보통 복수형으로 씁니다.","x":["Estas: 여성 복수형이라 ✗","Esta: 여성 단수형이라 ✗","Este: 남성 단수형이라 복수 명사와 맞지 않습니다 ✗","Estos: 남성 복수 지시형용사 → 정답 ✓"]},{"id":"G207","q":"Admiro a las personas ____.","o":["positivos","positiva","positivo","positivas"],"a":3,"k":"형용사 성·수 일치","t":"나는 긍정적인 사람들을 존경한다.","e":"형용사는 꾸미는 명사의 성·수에 맞춥니다. personas(사람들)는 여성 복수 명사이므로 positivas가 됩니다. persona는 남자를 가리켜도 문법적으로 항상 여성 명사입니다.","x":["positivos: 남성 복수형이라 ✗","positiva: 단수형이라 ✗","positivo: 남성 단수형이라 ✗","positivas: 여성 복수 personas에 맞는 형태 → 정답 ✓"]},{"id":"G208","q":"Asunción y Mariana ____ enfermas.","o":["están","estamos","está","estáis"],"a":0,"k":"estar + 상태","t":"아순시온과 마리아나는 아프다.","e":"enfermo(아픈)는 일시적 건강 상태이므로 estar를 씁니다. 주어가 두 사람(그녀들, 3인칭 복수)이므로 están입니다. enfermas가 여성 복수인 것도 주어와 맞춘 것입니다.","x":["están: estar 3인칭 복수 → 정답 ✓","estamos: '우리는'이라서 주어와 맞지 않습니다 ✗","está: 3인칭 단수라 ✗","estáis: '너희는'이라서 ✗"]},{"id":"G209","q":"Si te apetece, ven ____ al centro comercial.","o":["conmigo","con mí","contigo","con yo"],"a":0,"k":"conmigo","t":"괜찮으면 나랑 같이 쇼핑몰에 가자.","e":"전치사 con 뒤에 '나'가 올 때는 특별한 형태 conmigo(나와 함께)를 씁니다. 'con mí'나 'con yo'라고 하지 않습니다. 마찬가지로 '너와 함께'는 contigo입니다.","x":["conmigo: con + 나 = '나와 함께' → 정답 ✓","con mí: 잘못된 형태로, 반드시 conmigo로 씁니다 ✗","contigo: '너와 함께'라서 명령문의 상대(너)와 겹쳐 어색합니다 ✗","con yo: 전치사 뒤에 주격 yo를 쓰지 않습니다 ✗"]},{"id":"G210","q":"Ana ____ ducha en cuanto termina su entrenamiento.","o":["la","se","le","lo"],"a":1,"k":"재귀동사 ducharse","t":"아나는 운동이 끝나자마자 샤워를 한다.","e":"ducharse(샤워하다)는 '자기 자신을 씻긴다'는 재귀동사로, 주어에 맞는 재귀대명사가 필요합니다. 주어 Ana는 3인칭이므로 'se ducha'입니다. en cuanto는 '~하자마자'라는 뜻입니다.","x":["la: 직접목적격 '그녀를'이라 다른 사람을 씻긴다는 뜻이 되어 ✗","se: 3인칭 재귀대명사 → 정답 ✓","le: 간접목적격 '그녀에게'라서 ✗","lo: 직접목적격 '그를/그것을'이라 ✗"]},{"id":"G211","q":"La sopa ____ con cuchara.","o":["tomarse","toma","se toma","tomas"],"a":2,"k":"무인칭 se","t":"수프는 숟가락으로 먹는다.","e":"'se + 3인칭 동사'는 특정한 주어 없이 '(일반적으로) ~한다'는 뜻을 나타냅니다. 수프를 먹는 일반적인 방법을 말하므로 'se toma'가 맞습니다. 예: Aquí se habla español. (여기서는 스페인어를 쓴다.)","x":["tomarse: 동사원형이라 문장의 동사가 될 수 없습니다 ✗","toma: '수프가 먹는다'라는 이상한 뜻이 되어 ✗","se toma: 무인칭·수동의 se '먹는다' → 정답 ✓","tomas: '너는 먹는다'라서 일반적 규칙을 말하지 못합니다 ✗"]},{"id":"G212","q":"____ pintalabios me lo regaló mi mejor amiga.","o":["Estos","Esta","Estas","Este"],"a":3,"k":"지시형용사 este","t":"이 립스틱은 내 가장 친한 친구가 선물해 줬다.","e":"pintalabios(립스틱)는 남성 단수 명사입니다. -s로 끝나지만 복수가 아니고, 단·복수 형태가 같은 합성어입니다(pintar + labios). 그래서 'este pintalabios'이며, 뒤의 lo(그것을)도 남성 단수임을 보여 줍니다.","x":["Estos: 남성 복수형이고 뒤의 lo가 단수라 ✗","Esta: 여성 단수형이라 ✗","Estas: 여성 복수형이라 ✗","Este: 남성 단수 지시형용사 → 정답 ✓"]},{"id":"G213","q":"¿Qué os ____ pasa? ¿Por qué tenéis esa cara?","o":["ø","la","lo","le"],"a":0,"k":"pasar 구문 (os)","t":"너희 무슨 일 있어? 왜 그런 표정이야?","e":"'¿Qué te/os pasa?'는 '무슨 일 있어?'라는 표현으로, 일을 겪는 사람을 간접목적격 대명사로 나타냅니다. 이미 os(너희에게)가 있으므로 다른 대명사를 넣을 필요가 없습니다. vosotros(너희)는 스페인에서 쓰고, 중남미에서는 '¿Qué les pasa?'라고 합니다.","x":["ø: os가 이미 있어 빈칸을 비움 → 정답 ✓","la: 대명사가 중복되어 문법적으로 틀립니다 ✗","lo: 대명사가 중복되어 틀립니다 ✗","le: os와 le를 함께 쓸 수 없습니다 ✗"]},{"id":"G214","q":"____ te gusta nada de lo que ves en esta tienda, vamos a otra.","o":["Sino","Sí no","No si","Si no"],"a":3,"k":"si no vs sino","t":"이 가게에서 보는 것 중에 마음에 드는 게 하나도 없으면, 다른 가게로 가자.","e":"'si no'는 '만약 ~하지 않으면'이라는 조건(si) + 부정(no)입니다. 한 단어 sino는 '~이 아니라 ~이다'라는 대조 접속사로 전혀 다른 뜻입니다. 여기서는 조건문이므로 'Si no'가 맞습니다.","x":["Sino: '~이 아니라'라는 대조 접속사라 ✗","Sí no: sí(예)에 악센트가 붙은 잘못된 형태입니다 ✗","No si: 어순이 틀렸습니다 ✗","Si no: '만약 ~하지 않으면' → 정답 ✓"]},{"id":"G215","q":"Sin respeto no hay ____ amor.","o":["ø","el","la","del"],"a":0,"k":"부정문 무관사","t":"존중이 없으면 사랑도 없다.","e":"'no hay + 명사'에서 셀 수 없거나 추상적인 명사는 관사 없이 씁니다. amor(사랑)는 추상명사이고 hay는 정관사와 함께 쓰지 않으므로 빈칸을 비웁니다. 앞의 'Sin respeto'도 관사가 없습니다.","x":["ø: hay + 추상명사, 관사 없음 → 정답 ✓","el: hay는 정관사와 함께 쓰지 않습니다 ✗","la: 정관사이고 amor는 남성 명사라 ✗","del: de + el로 의미가 맞지 않습니다 ✗"]},{"id":"G216","q":"El banco está ____ el estanco y la ferretería.","o":["detrás","desde","entre","cerca"],"a":2,"k":"위치 entre","t":"은행은 담배 가게와 철물점 사이에 있다.","e":"'A와 B 사이에'는 'entre A y B'로 씁니다. 두 장소(estanco와 ferretería)가 y로 연결되어 있으므로 entre가 맞습니다. estanco는 스페인에서 담배·우표 등을 파는 가게입니다.","x":["detrás: '뒤에'는 detrás de로 써야 하고 두 장소를 잇지 못합니다 ✗","desde: '~부터'라 의미가 맞지 않습니다 ✗","entre: entre A y B 'A와 B 사이에' → 정답 ✓","cerca: '가까이'는 cerca de로 써야 하며 y 구조와 맞지 않습니다 ✗"]},{"id":"G217","q":"En este momento los actores ____ en el teatro.","o":["ensayan","están ensayando","está ensayando","han ensayado"],"a":1,"k":"현재진행형","t":"지금 이 순간 배우들은 극장에서 리허설을 하고 있다.","e":"'En este momento(지금 이 순간)'는 진행 중인 동작을 나타내므로 estar + 현재분사를 씁니다. 주어 los actores가 3인칭 복수이므로 'están ensayando'입니다.","x":["ensayan: 단순 현재로 '지금 진행 중'을 잘 드러내지 못합니다 ✗","están ensayando: 3인칭 복수 현재진행형 → 정답 ✓","está ensayando: 단수형이라 복수 주어와 맞지 않습니다 ✗","han ensayado: 현재완료 '리허설했다'라서 ✗"]},{"id":"G218","q":"Siempre ____ antes de salir de casa.","o":["me peino","me estoy peinando","peino","estoy peinando"],"a":0,"k":"재귀동사 + 습관","t":"나는 항상 집을 나서기 전에 머리를 빗는다.","e":"peinarse(자기 머리를 빗다)는 재귀동사이므로 me를 함께 씁니다. siempre(항상)는 습관을 나타내므로 진행형이 아닌 단순 현재 'me peino'가 맞습니다.","x":["me peino: 재귀동사 현재형, 습관 → 정답 ✓","me estoy peinando: 진행형은 지금 하는 중일 때 써서 siempre와 어울리지 않습니다 ✗","peino: 재귀대명사가 없으면 '다른 사람을 빗긴다'가 되어 ✗","estoy peinando: 진행형이고 재귀대명사도 빠졌습니다 ✗"]},{"id":"G219","q":"Duermo al menos 7 horas ____ los días.","o":["toda","todas","todo","todos"],"a":3,"k":"todos los días","t":"나는 매일 적어도 7시간은 잔다.","e":"'매일'은 'todos los días'라고 합니다. día(날)는 -a로 끝나지만 남성 명사이므로 todos를 씁니다. 비교: todo el día는 '하루 종일'이라는 뜻입니다.","x":["toda: 여성 단수형이라 ✗","todas: 여성 복수형인데 día는 남성 명사라 ✗","todo: 단수형이라 복수 los días와 맞지 않습니다 ✗","todos: 남성 복수 'todos los días(매일)' → 정답 ✓"]},{"id":"G220","q":"¿Con cuánta frecuencia te cortas ____ pelo?","o":["el","ø","tu","al"],"a":0,"k":"신체 부위 + 정관사","t":"너는 얼마나 자주 머리를 자르니?","e":"cortarse el pelo(머리를 자르다)처럼 재귀동사와 신체 부위를 함께 쓸 때는 소유사 대신 정관사를 씁니다. te가 '너 자신의'라는 의미를 이미 보여 주기 때문입니다. pelo는 남성 명사라 el pelo입니다.","x":["el: 신체 부위 앞 정관사 → 정답 ✓","ø: 목적어 명사 앞에 관사가 필요합니다 ✗","tu: te가 있으므로 소유사를 쓰지 않습니다 ✗","al: a + el로 목적어 앞에 쓸 수 없습니다 ✗"]},{"id":"G221","q":"Llegamos tarde al cine ____ culpa de Inma, necesita mucho tiempo para prepararse.","o":["por","a","de","para"],"a":0,"k":"por culpa de","t":"우리는 인마 때문에 영화관에 늦었어, 그녀는 준비하는 데 시간이 많이 걸려.","e":"'por culpa de + 사람/사물'은 '~의 탓에, ~ 때문에'라는 관용 표현입니다. 부정적인 원인을 말할 때 씁니다. 긍정적인 원인에는 'gracias a(~ 덕분에)'를 씁니다.","x":["por: por culpa de '~ 탓에' → 정답 ✓","a: a culpa de라는 표현은 없습니다 ✗","de: de culpa de라는 표현은 없습니다 ✗","para: '~을 위해'라서 원인을 나타내지 않습니다 ✗"]},{"id":"G222","q":"Has trabajado ____, ahora deberías descansar.","o":["muchas","mucha","muchos","mucho"],"a":3,"k":"부사 mucho","t":"너는 일을 많이 했으니까, 이제 좀 쉬어야 해.","e":"동사(has trabajado)를 꾸미는 '많이'는 부사 mucho입니다. 부사는 성·수 변화가 없습니다. muchas, mucha, muchos는 명사 앞에서 '많은'을 뜻하는 형용사형입니다.","x":["muchas: 여성 복수 형용사형이라 꾸밀 명사가 없습니다 ✗","mucha: 여성 단수 형용사형이라 ✗","muchos: 남성 복수 형용사형이라 ✗","mucho: 동사를 꾸미는 부사 '많이' → 정답 ✓"]},{"id":"G223","q":"Los chicos quieren ir ____ a ver el partido.","o":["con ti","contigo","con tú","con te"],"a":1,"k":"contigo","t":"남자애들은 너랑 같이 경기를 보러 가고 싶어 해.","e":"전치사 con 뒤에 '너'가 올 때는 특별한 형태 contigo(너와 함께)를 씁니다. 'con ti', 'con tú'라고 하지 않습니다. 같은 방식으로 '나와 함께'는 conmigo입니다.","x":["con ti: 잘못된 형태로 반드시 contigo로 씁니다 ✗","contigo: con + 너 '너와 함께' → 정답 ✓","con tú: 전치사 뒤에 주격 tú를 쓰지 않습니다 ✗","con te: te는 목적격 대명사라 전치사 뒤에 쓸 수 없습니다 ✗"]},{"id":"G224","q":"Vivo lejos ____ la universidad, por eso no puedo ir a pie.","o":["hasta","a","de","ø"],"a":2,"k":"lejos de","t":"나는 대학교에서 멀리 살아서 걸어갈 수 없다.","e":"'~에서 멀리'는 'lejos de + 장소'로 씁니다. 반대 표현 '~에서 가까이'는 'cerca de'입니다. 예: Vivo cerca del metro. (나는 지하철역 가까이 산다.)","x":["hasta: '~까지'라서 lejos와 짝을 이루지 않습니다 ✗","a: lejos a라는 표현은 쓰지 않습니다 ✗","de: lejos de '~에서 멀리' → 정답 ✓","ø: lejos 뒤에 장소를 이으려면 de가 필요합니다 ✗"]},{"id":"G225","q":"Cuando era más joven, me resultaba más difícil ____ encontrar trabajo.","o":["ø","a","por","de"],"a":0,"k":"resultar + 형용사 + 원형","t":"더 젊었을 때는 일자리를 구하는 것이 더 어려웠다.","e":"'me resulta difícil + 동사원형'은 '~하는 것이 나에게 어렵다'는 뜻으로, 동사원형(encontrar)이 문장의 진짜 주어입니다. 주어 역할을 하는 동사원형 앞에는 전치사를 붙이지 않습니다. 예: Es fácil aprender español. (스페인어를 배우는 것은 쉽다.)","x":["ø: 주어인 동사원형 앞에는 전치사 없음 → 정답 ✓","a: difícil 뒤 주어 원형에 a를 붙이지 않습니다 ✗","por: 의미와 구조가 맞지 않습니다 ✗","de: 이 구조에서는 de를 쓰지 않습니다 ✗"]},{"id":"G226","q":"¿A qué hora sueles ____ los domingos?","o":["te levantar","levantarte","levantar","levantar te"],"a":1,"k":"soler + 재귀동사 원형","t":"너는 일요일에 보통 몇 시에 일어나니?","e":"soler(보통 ~하다) 뒤에는 동사원형이 옵니다. levantarse(일어나다)는 재귀동사이므로, 주어 '너'에 맞춰 원형 끝에 te를 붙여 'levantarte'가 됩니다. 'te sueles levantar'처럼 앞에 놓는 것도 가능합니다.","x":["te levantar: 대명사를 원형 바로 앞에 떼어 쓸 수 없습니다 ✗","levantarte: 원형 + 재귀대명사 te → 정답 ✓","levantar: 재귀대명사가 없으면 '무언가를 들다'라는 뜻이 됩니다 ✗","levantar te: 띄어 쓰지 않고 붙여 씁니다 ✗"]},{"id":"G227","q":"____ famosa periodista dio la noticia en directo.","o":["Una","Un","Uno","Unas"],"a":0,"k":"부정관사 una","t":"한 유명한 여기자가 생방송으로 그 소식을 전했다.","e":"periodista(기자)는 남녀 형태가 같은 명사로, 관사로 성별을 구별합니다. famosa가 여성형이므로 여성 기자이고, 단수이므로 una를 씁니다.","x":["Una: 여성 단수 부정관사 → 정답 ✓","Un: 남성형인데 famosa가 여성이라 ✗","Uno: 명사 앞에서는 un으로 줄여 써서 ✗","Unas: 복수형이라 단수 동사 dio와 맞지 않습니다 ✗"]},{"id":"G228","q":"¿Desde ____ aprendes portugués?","o":["qué","cuánto","cuándo","cómo"],"a":2,"k":"desde cuándo","t":"너는 언제부터 포르투갈어를 배우니?","e":"'언제부터'는 '¿Desde cuándo?'로 묻습니다. 스페인어는 현재도 계속되는 일에 현재형(aprendes)을 씁니다. 대답 예: Desde 2020. / Desde hace dos años.","x":["qué: desde qué 뒤에는 명사가 필요합니다(desde qué año) ✗","cuánto: '얼마나 오래'는 ¿Cuánto tiempo hace que...?로 묻습니다 ✗","cuándo: desde cuándo '언제부터' → 정답 ✓","cómo: '어떻게'라 의미가 맞지 않습니다 ✗"]},{"id":"G229","q":"Es importantísimo que ____ una alimentación sana.","o":["tienes","teniendo","tengas","tendrías"],"a":2,"k":"es importante que + 접속법","t":"건강한 식습관을 갖는 것은 매우 중요하다.","e":"'Es importante que...'처럼 가치 판단·필요를 나타내는 표현 뒤에는 접속법(바람·판단 등을 나타내는 동사 형태)을 씁니다. tener의 tú 접속법 현재는 tengas입니다. importantísimo는 importante의 최상급(아주 중요한)입니다.","x":["tienes: 직설법이라 es importante que 뒤에 쓸 수 없습니다 ✗","teniendo: 현재분사라 que 뒤 동사가 될 수 없습니다 ✗","tengas: tener 접속법 현재 → 정답 ✓","tendrías: 조건법이라 ✗"]},{"id":"G230","q":"¿____ ha dicho esa barbaridad sobre ti?","o":["Quiénes","Cuáles","Quienes","Quién"],"a":3,"k":"의문사 quién","t":"누가 너에 대해 그런 터무니없는 말을 했어?","e":"'누가'를 묻는 의문사는 quién입니다. 동사 ha dicho가 단수이므로 단수형 quién을 씁니다. 의문사는 항상 악센트를 찍습니다.","x":["Quiénes: 복수형이라 단수 동사 ha dicho와 맞지 않습니다 ✗","Cuáles: '어떤 것들'이라 사람을 묻지 않고 수도 맞지 않습니다 ✗","Quienes: 악센트가 없어 관계대명사이므로 의문문에 쓸 수 없습니다 ✗","Quién: 단수 '누가' → 정답 ✓"]},{"id":"G231","q":"Anteayer vi a Jimena con su madre. ____ al mercado central.","o":["Irán","Han ido","Iban","Estuvieron yendo"],"a":2,"k":"불완료과거 (배경)","t":"그저께 나는 히메나가 엄마와 함께 있는 걸 봤다. 그들은 중앙시장에 가는 중이었다.","e":"과거에 본 장면에서 '~하던 중이었다'는 배경 동작은 불완료과거로 씁니다. 내가 봤을 때(vi) 그들은 시장으로 가고 있었으므로 'Iban'이 맞습니다.","x":["Irán: 미래형이라 과거 장면과 맞지 않습니다 ✗","Han ido: 현재완료라 anteayer(그저께)와 맞지 않습니다 ✗","Iban: ir 불완료과거, 과거 장면의 배경 → 정답 ✓","Estuvieron yendo: 끝난 기간을 뜻해 배경 묘사로는 어색합니다 ✗"]},{"id":"G232","q":"¿Alguien ha visto ____ Fernando?","o":["a","ø","de","por"],"a":0,"k":"사람 목적어 a","t":"누구 페르난도 본 사람 있어?","e":"직접목적어가 특정한 사람일 때는 동사 뒤에 전치사 a를 붙입니다. 이것을 '인칭의 a'라고 합니다. 'ver a Fernando'처럼 쓰며, 사물이면 a를 쓰지 않습니다(ver la película).","x":["a: 사람 목적어 앞 인칭의 a → 정답 ✓","ø: 사람 목적어 앞에는 a가 필요합니다 ✗","de: '페르난도의'라는 뜻이 되어 ✗","por: '페르난도를 통해/때문에'라는 뜻이 되어 ✗"]},{"id":"G233","q":"Claro que me gusta salir de marcha, ____ no tengo tiempo en este periodo.","o":["pero","así que","como","ya que"],"a":0,"k":"대조 pero","t":"물론 나는 놀러 나가는 걸 좋아하지만, 요즘은 시간이 없어.","e":"앞 문장(좋아한다)과 뒤 문장(시간이 없다)이 대조되므로 pero(하지만)를 씁니다. salir de marcha는 스페인 구어로 '밤에 놀러 나가다'라는 뜻입니다.","x":["pero: '하지만', 대조 → 정답 ✓","así que: '그래서'라 결과를 나타내 의미가 맞지 않습니다 ✗","como: 이유의 como는 문장 맨 앞에 쓰며 의미도 맞지 않습니다 ✗","ya que: '~이니까'라 이유를 나타내 ✗"]},{"id":"G234","q":"El instituto en el que estudio está muy lejos ____ aquí.","o":["a","hacia","hasta","de"],"a":3,"k":"lejos de","t":"내가 다니는 고등학교는 여기서 아주 멀다.","e":"'~에서 멀리'는 'lejos de'로 씁니다. 'lejos de aquí'는 '여기서 멀리'라는 자주 쓰는 표현입니다. instituto는 스페인에서 중·고등학교를 뜻합니다.","x":["a: lejos a는 쓰지 않습니다 ✗","hacia: '~쪽으로'라서 ✗","hasta: '~까지'라서 ✗","de: lejos de '~에서 멀리' → 정답 ✓"]},{"id":"G235","q":"Lo más importante para mí es ____ salud.","o":["la","las","ø","el"],"a":0,"k":"추상명사 + 정관사","t":"나에게 가장 중요한 것은 건강이다.","e":"일반적인 의미의 추상명사가 주어나 보어로 쓰일 때는 정관사를 붙입니다. salud(건강)는 -d로 끝나는 여성 명사이므로 'la salud'입니다. 예: La paciencia es importante. (인내는 중요하다.)","x":["la: 여성 단수 정관사 → 정답 ✓","las: 복수형이라 ✗","ø: 일반적 의미의 추상명사에는 정관사가 필요합니다 ✗","el: 남성형인데 salud는 여성 명사라 ✗"]},{"id":"G236","q":"____ mi marido prepara el almuerzo, yo recojo a los niños del colegio.","o":["Durante","Entonces","Cuándo","Mientras"],"a":3,"k":"동시 mientras","t":"남편이 점심을 준비하는 동안, 나는 학교에서 아이들을 데려온다.","e":"mientras(~하는 동안)는 두 동작이 동시에 일어날 때 접속사로 써서 뒤에 문장을 이끕니다. durante도 '~동안'이지만 전치사라서 명사만 올 수 있습니다(durante la comida).","x":["Durante: 전치사라 뒤에 문장이 올 수 없습니다 ✗","Entonces: '그때/그래서'라 두 문장을 동시로 연결하지 못합니다 ✗","Cuándo: 악센트가 있는 의문사라 평서문에 쓸 수 없습니다 ✗","Mientras: '~하는 동안' 접속사 → 정답 ✓"]},{"id":"G237","q":"¿Podemos ir ____ parque esta tarde?","o":["al","en el","el","a la"],"a":0,"k":"ir a + el = al","t":"오늘 오후에 공원에 갈 수 있어?","e":"이동 동사 ir 뒤에서 목적지는 a로 나타냅니다. parque(공원)는 남성 명사라 a + el이 되고, 이를 줄여 al이라고 씁니다. 그래서 'ir al parque'입니다.","x":["al: a + el, 목적지 표현 → 정답 ✓","en el: en은 장소 안을 뜻해 이동의 목적지에는 쓰지 않습니다 ✗","el: 전치사 a가 빠졌습니다 ✗","a la: 여성형인데 parque는 남성 명사라 ✗"]},{"id":"G238","q":"El hijo de Luisa tiene doce años, ____ tiene diez.","o":["el mío","mi","el mi","mío"],"a":0,"k":"소유대명사 el mío","t":"루이사의 아들은 열두 살이고, 내 아들은 열 살이다.","e":"앞에 나온 명사(hijo)를 반복하지 않고 '내 것'이라고 할 때는 소유대명사 'el mío'를 씁니다. hijo가 남성 단수이므로 el mío입니다. mi는 명사 앞에서만 쓸 수 있습니다.","x":["el mío: 소유대명사 '내 것(내 아들)' → 정답 ✓","mi: 뒤에 명사가 있어야 하므로 단독으로 못 씁니다 ✗","el mi: 관사와 mi를 함께 쓰지 않습니다 ✗","mío: 주어로 쓰려면 정관사 el이 필요합니다 ✗"]},{"id":"G239","q":"Os invitaré a comer ____ cobre mi sueldo.","o":["después de","en cuanto","nada más","al"],"a":1,"k":"en cuanto + 접속법","t":"월급 받자마자 너희에게 밥 살게.","e":"'en cuanto'는 '~하자마자'라는 시간 접속사입니다. 미래의 일을 말할 때는 그 뒤에 접속법을 쓰므로 'en cuanto cobre'가 됩니다. después de, nada más, al은 모두 뒤에 동사원형이 와야 합니다.","x":["después de: 뒤에 동사원형이 와야 해서 cobre(활용형)와 맞지 않습니다 ✗","en cuanto: '~하자마자' + 접속법 → 정답 ✓","nada más: '~하자마자'이지만 동사원형과 써야 합니다(nada más cobrar) ✗","al: al + 동사원형으로 써야 해서 ✗"]},{"id":"G240","q":"¿Cuándo ____ a su marido?","o":["ha estado conociendo","estaba conociendo","conoció","conocía"],"a":2,"k":"단순과거 (conocer)","t":"그녀는 남편을 언제 만났나요?","e":"conocer는 단순과거로 쓰면 '처음 알게 되다, 처음 만나다'라는 뜻이 됩니다. 남편을 처음 만난 특정한 순간을 묻는 질문이므로 단순과거 'conoció'가 맞습니다.","x":["ha estado conociendo: 현재완료 진행형으로 이 의미에 쓰지 않습니다 ✗","estaba conociendo: 과거진행형이라 처음 만난 순간을 나타내지 못합니다 ✗","conoció: 단순과거 '처음 만났다' → 정답 ✓","conocía: 불완료과거 '알고 있었다'라는 상태라 ✗"]},{"id":"G241","q":"____ autobús no va al aeropuerto.","o":["Esta","Estos","Este","Esto"],"a":2,"k":"지시형용사 este","t":"이 버스는 공항에 가지 않는다.","e":"autobús(버스)는 남성 단수 명사이므로 지시형용사는 este를 씁니다. esto는 명사 앞에 쓸 수 없는 중성 대명사로, 정체를 모르는 것을 가리킬 때 씁니다(¿Qué es esto? 이게 뭐야?).","x":["Esta: 여성형이라 ✗","Estos: 복수형이라 ✗","Este: 남성 단수 지시형용사 → 정답 ✓","Esto: 중성 대명사라 명사 앞에 쓸 수 없습니다 ✗"]},{"id":"G242","q":"____ termino de ver una serie de televisión interesante, me siento triste.","o":["Cada veces que","Cada vez que","Cada una vez","Cada vez"],"a":1,"k":"cada vez que","t":"재미있는 TV 시리즈를 다 볼 때마다 나는 슬퍼진다.","e":"'~할 때마다'는 'cada vez que + 문장'으로 표현합니다. cada는 항상 단수 명사와 쓰므로 'cada veces'는 틀립니다. 예: Cada vez que llueve, me duele la cabeza. (비가 올 때마다 머리가 아프다.)","x":["Cada veces que: cada 뒤에 복수 명사를 쓸 수 없습니다 ✗","Cada vez que: '~할 때마다' → 정답 ✓","Cada una vez: 문법적으로 맞지 않는 형태입니다 ✗","Cada vez: que가 없으면 뒤 문장을 이을 수 없습니다 ✗"]},{"id":"G243","q":"Laura siempre está mirándose ____ espejo.","o":["el","a la","a","al"],"a":3,"k":"mirarse al espejo","t":"라우라는 늘 거울을 보고 있다.","e":"'거울을 보다'는 관용적으로 'mirarse al espejo'라고 합니다(mirarse en el espejo도 씁니다). a + el이 축약되어 al이 됩니다. 자기 자신을 보는 것이므로 재귀형 mirarse를 씁니다.","x":["el: 전치사 없이는 이 관용 표현이 되지 않습니다 ✗","a la: espejo는 남성 명사라 여성 관사는 ✗","a: 관사가 빠져 a espejo는 어색합니다 ✗","al: mirarse al espejo → 정답 ✓"]},{"id":"G244","q":"A José Luis y a Elvira ____ encanta esquiar.","o":["le","lo","les","los"],"a":2,"k":"encantar + les","t":"호세 루이스와 엘비라는 스키 타는 것을 정말 좋아한다.","e":"encantar(정말 좋아하다)는 gustar처럼 좋아하는 사람을 간접목적격 대명사로 나타냅니다. 'A José Luis y a Elvira'는 두 사람(3인칭 복수)이므로 les입니다. 이 경우 'a + 사람'과 les를 함께 쓰는 것이 규칙입니다.","x":["le: 3인칭 단수라 두 사람과 맞지 않습니다 ✗","lo: 직접목적격이라 encantar 구문에 쓰지 않습니다 ✗","les: 3인칭 복수 간접목적격 → 정답 ✓","los: 직접목적격 복수라 ✗"]},{"id":"G245","q":"Nosotros también vamos ____ la biblioteca, si quieres, acompáñanos.","o":["tras","por","entre","hacia"],"a":3,"k":"방향 hacia","t":"우리도 도서관 쪽으로 가니까, 괜찮으면 같이 가자.","e":"hacia는 '~ 쪽으로, ~을 향해'라는 방향을 나타냅니다. 이동 동사 ir와 함께 써서 가는 방향을 표현합니다. 일반적으로 'ir a la biblioteca'도 자주 쓰지만, 보기 중에는 hacia만 방향을 나타냅니다.","x":["tras: '~ 뒤에'라서 방향을 나타내지 않습니다 ✗","por: '~을 지나서/근처로'라 목적지를 분명히 나타내지 못합니다 ✗","entre: '~ 사이에'라 ✗","hacia: '~ 쪽으로' 방향 → 정답 ✓"]},{"id":"G246","q":"Si puedo, ____ año próximo voy a viajar a China.","o":["lo","ø","el","en"],"a":2,"k":"el año próximo","t":"할 수 있다면, 내년에 중국으로 여행 갈 거야.","e":"'내년에'는 'el año próximo' 또는 'el año que viene'라고 하며, 전치사 en 없이 정관사 el만 붙입니다. 시간 표현은 이렇게 관사만으로 '~에'의 의미를 가지는 경우가 많습니다(el lunes 월요일에).","x":["lo: 중성 관사라 명사 앞에 쓸 수 없습니다 ✗","ø: año 앞에 관사가 필요합니다 ✗","el: el año próximo '내년에' → 정답 ✓","en: en el año라고 해야 하며 관사 없이 en만 쓸 수 없습니다 ✗"]},{"id":"G247","q":"¿Cuántas veces por semana hablas ____ tu novio?","o":["con","a","hacia","en"],"a":0,"k":"hablar con","t":"너는 일주일에 몇 번 남자친구와 통화하니?","e":"'~와 이야기하다'는 'hablar con + 사람'으로 씁니다. con은 '~와 함께'라는 뜻입니다. hablar a도 있지만 '~에게 (일방적으로) 말하다'라는 느낌이라 대화에는 con이 자연스럽습니다.","x":["con: hablar con '~와 이야기하다' → 정답 ✓","a: 일방적으로 말을 건다는 느낌이라 대화를 나타내기에 어색합니다 ✗","hacia: '~쪽으로'라서 ✗","en: '~안에서'라서 ✗"]},{"id":"G248","q":"¿____ es su nacionalidad?","o":["Cuál","Quién","De qué","Cómo"],"a":0,"k":"의문사 cuál","t":"그분의 국적은 무엇인가요?","e":"'¿Cuál es + 명사?'는 여러 가능성 중 하나를 묻는 질문으로, 국적·이름·주소·전화번호 등을 물을 때 씁니다. 한국어로는 '무엇'이지만 ser 앞에서는 qué가 아니라 cuál을 씁니다.","x":["Cuál: ¿Cuál es...? 정보를 묻는 의문사 → 정답 ✓","Quién: '누구'라서 국적을 묻지 않습니다 ✗","De qué: ¿De qué país eres?처럼 쓰며 이 구조와 맞지 않습니다 ✗","Cómo: '어떤'이 아니라 '어떻게'라 ✗"]},{"id":"G249","q":"____ cinco minutos, por favor.","o":["Esperadme","Esperarme","Me esperar","Esperad me"],"a":0,"k":"vosotros 명령형 + 대명사","t":"5분만 나를 기다려 줘(너희).","e":"vosotros 긍정 명령형은 원형의 -r을 -d로 바꿉니다(esperar → esperad). 긍정 명령에서는 목적격 대명사를 동사 끝에 붙여 'Esperadme'가 됩니다. 중남미에서는 ustedes를 써서 'Espérenme'라고 합니다.","x":["Esperadme: vosotros 명령형 + me → 정답 ✓","Esperarme: 동사원형 + me라 명령형이 아닙니다(구어에서는 쓰기도 하지만 비표준) ✗","Me esperar: 대명사를 원형 앞에 떼어 쓸 수 없습니다 ✗","Esperad me: 대명사는 붙여 써야 합니다 ✗"]},{"id":"G250","q":"No quiero que mi hijo ____ a vivir a otro país, pero no es decisión mía.","o":["se iría","se vaya","se irá","se va"],"a":1,"k":"no querer que + 접속법","t":"나는 아들이 다른 나라에 가서 살지 않았으면 좋겠지만, 내가 결정할 일은 아니다.","e":"'(no) querer que'는 바람을 나타내므로, 주어가 바뀌면 que 뒤에 접속법을 씁니다. irse(떠나다)의 3인칭 접속법 현재는 'se vaya'입니다.","x":["se iría: 조건법이라 ✗","se vaya: irse 접속법 현재 → 정답 ✓","se irá: 직설법 미래라 바람 표현 뒤에 쓸 수 없습니다 ✗","se va: 직설법 현재라 ✗"]},{"id":"G251","q":"Yo no duermo tanto ____ mis hermanos.","o":["de","cuanto","que","como"],"a":3,"k":"동등비교 tanto como","t":"나는 형제들만큼 많이 자지 않는다.","e":"동사를 꾸미는 동등비교 '~만큼 많이'는 'tanto como'로 표현합니다. 짝이 되는 말은 que가 아니라 como입니다. que는 우등·열등비교(más/menos ... que)에 씁니다.","x":["de: 비교 대상 앞에 쓰지 않습니다 ✗","cuanto: 이 구조에 쓰지 않습니다 ✗","que: más/menos와 짝을 이루므로 tanto와는 맞지 않습니다 ✗","como: tanto como '~만큼' → 정답 ✓"]},{"id":"G252","q":"____ pasado fin de semana no pude visitar a mis abuelos porque tenía que estudiar mucho.","o":["El","Un","Lo","La"],"a":0,"k":"시간 표현 + 정관사","t":"지난 주말에 나는 공부를 많이 해야 해서 조부모님을 찾아뵐 수 없었다.","e":"'지난 주말'은 'el pasado fin de semana' 또는 'el fin de semana pasado'라고 합니다. fin(끝)은 남성 명사이므로 정관사 el을 쓰고, 전치사 없이 '~에'의 의미가 됩니다.","x":["El: 남성 단수 정관사 → 정답 ✓","Un: '어떤 지난 주말'이 되어 특정한 시점이 아닙니다 ✗","Lo: 중성 관사라 명사 앞에 쓸 수 없습니다 ✗","La: 여성형인데 fin은 남성 명사라 ✗"]},{"id":"G253","q":"Por esta calle no pasa ____ después de la medianoche.","o":["alguien","ningún","alguno","nadie"],"a":3,"k":"부정어 nadie","t":"자정이 넘으면 이 길에는 아무도 지나가지 않는다.","e":"부정문에서 '아무도 ~않다'는 nadie를 씁니다. 스페인어는 no와 nadie를 함께 쓰는 이중 부정이 정상입니다. 반대로 긍정문의 '누군가'는 alguien입니다.","x":["alguien: '누군가'라서 부정문에 쓰지 않습니다 ✗","ningún: 뒤에 명사가 있어야 합니다(ningún coche) ✗","alguno: 부정문에서 '아무도'의 뜻으로 단독으로 쓰지 않습니다 ✗","nadie: 부정문 '아무도' → 정답 ✓"]},{"id":"G254","q":"Prefiero el café ____ azúcar, no me importa su sabor amargo.","o":["sin","con","sobre","de"],"a":0,"k":"전치사 sin","t":"나는 설탕 없이 커피를 마시는 게 좋아, 쓴맛은 상관없어.","e":"sin은 '~ 없이'라는 뜻의 전치사입니다. 뒤 문장의 '쓴맛은 상관없다'가 설탕을 넣지 않는다는 힌트입니다. 반대말 con은 '~와 함께, ~을 넣어서'입니다.","x":["sin: '~ 없이', 쓴맛 문맥과 일치 → 정답 ✓","con: '설탕을 넣어서'라 쓴맛 이야기와 맞지 않습니다 ✗","sobre: '~ 위에/~에 관해'라 ✗","de: café de azúcar라는 표현은 의미가 성립하지 않습니다 ✗"]},{"id":"G255","q":"Para vosotros, ¿cuál es ____ mejor película en lengua española?","o":["el","una","la","lo"],"a":2,"k":"최상급 la mejor","t":"너희에게 스페인어로 된 최고의 영화는 무엇이니?","e":"최상급 '가장 ~한'은 '정관사 + mejor/más + 명사'로 표현합니다. película(영화)는 여성 명사이므로 'la mejor película'입니다. vosotros(너희)는 스페인식 표현입니다.","x":["el: 남성형인데 película는 여성 명사라 ✗","una: 부정관사로는 최상급이 되지 않습니다 ✗","la: 여성 정관사 + mejor, 최상급 → 정답 ✓","lo: 중성 관사라 명사 앞에 쓸 수 없습니다 ✗"]},{"id":"G256","q":"Normalmente, salimos a la terraza ____ la pausa.","o":["hacia","a","entre","durante"],"a":3,"k":"전치사 durante","t":"보통 우리는 쉬는 시간 동안 테라스에 나간다.","e":"durante는 '~ 동안'이라는 뜻의 전치사로 뒤에 명사가 옵니다. la pausa(쉬는 시간)가 명사이므로 'durante la pausa'가 맞습니다. 뒤에 문장이 오면 mientras를 씁니다.","x":["hacia: '~쪽으로'라 시간에 쓰면 '무렵'이라는 뜻이 되어 어색합니다 ✗","a: a la pausa는 '쉬는 시간에(로)'라는 어색한 표현입니다 ✗","entre: '~ 사이에'라 ✗","durante: '~ 동안' + 명사 → 정답 ✓"]},{"id":"G257","q":"¿Quién ____ ha llevado mi paraguas?","o":["le lo","se","se la","lo"],"a":1,"k":"llevarse","t":"누가 내 우산을 가져갔어?","e":"llevarse는 '(무엇을) 가져가 버리다'라는 뜻의 재귀동사입니다. 주어 quién이 3인칭이므로 'se ha llevado'가 됩니다. llevar만 쓰면 '들고 가다, 지니다'라는 뜻이 됩니다.","x":["le lo: 이런 결합은 존재하지 않습니다 ✗","se: llevarse '가져가 버리다' → 정답 ✓","se la: paraguas는 남성 명사이고 이미 목적어가 있어 la가 필요 없습니다 ✗","lo: 목적어 mi paraguas가 이미 있어 대명사를 중복할 수 없습니다 ✗"]},{"id":"G258","q":"Mis resultados son ____ que los tuyos.","o":["más malo","tan malos","peor","peores"],"a":3,"k":"불규칙 비교급 peor","t":"내 결과는 네 것보다 더 나쁘다.","e":"malo(나쁜)의 비교급은 불규칙형 peor(더 나쁜)입니다. 주어 mis resultados가 복수이므로 peores가 됩니다. bueno의 비교급은 mejor(더 좋은)입니다.","x":["más malo: 성격을 말할 때 쓰기도 하지만 수도 맞지 않습니다 ✗","tan malos: 동등비교라 que가 아닌 como와 써야 합니다 ✗","peor: 단수형이라 복수 주어와 맞지 않습니다 ✗","peores: malo의 비교급 복수 → 정답 ✓"]},{"id":"G259","q":"____ que me interrumpan cuando hablo.","o":["Me molesto","Molesto","Me molesta","Yo molesto"],"a":2,"k":"molestar 구문","t":"나는 내가 말할 때 누가 끼어드는 게 싫다.","e":"molestar(짜증 나게 하다)는 gustar처럼 씁니다. 기분이 상하는 사람은 간접목적격(me)이고, 짜증 나게 하는 내용(que me interrumpan)이 주어입니다. 문장이 주어면 동사는 3인칭 단수이므로 'Me molesta'입니다.","x":["Me molesto: '내가 수고하다/화를 내다'라는 재귀 의미라 구조가 다릅니다 ✗","Molesto: '내가 (누구를) 귀찮게 한다'라는 뜻이라 ✗","Me molesta: gustar형 구문 3인칭 단수 → 정답 ✓","Yo molesto: '내가 귀찮게 한다'라 의미가 반대입니다 ✗"]},{"id":"G260","q":"¿____ qué frecuencia viajas en avión?","o":["A","De","Con","En"],"a":2,"k":"con qué frecuencia","t":"너는 얼마나 자주 비행기로 여행하니?","e":"'얼마나 자주'는 관용적으로 '¿Con qué frecuencia?'라고 합니다. frecuencia(빈도)는 con과 함께 씁니다. 같은 뜻의 질문: ¿Cada cuánto viajas en avión?","x":["A: frecuencia와 함께 쓰지 않습니다 ✗","De: 이 표현에 쓰지 않습니다 ✗","Con: con qué frecuencia '얼마나 자주' → 정답 ✓","En: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G261","q":"¿____ qué periódico leíste ese artículo?","o":["A","De","Desde","En"],"a":3,"k":"전치사 en (매체)","t":"그 기사를 어느 신문에서 읽었니?","e":"신문·책·인터넷 등 매체 '안에서' 읽거나 본 것은 en으로 나타냅니다. 'leer algo en el periódico(신문에서 ~을 읽다)'이므로 질문은 '¿En qué periódico...?'가 됩니다.","x":["A: 매체를 나타내지 않습니다 ✗","De: '어느 신문의'라는 뜻이 되어 동사 leíste와 맞지 않습니다 ✗","Desde: '~부터'라 ✗","En: 매체 안에서 '~에서' → 정답 ✓"]},{"id":"G262","q":"Mis abuelos tienen ____ dos perros y un gato.","o":["ø","unos","a","de los"],"a":0,"k":"숫자 앞 무관사","t":"우리 조부모님은 개 두 마리와 고양이 한 마리를 키우신다.","e":"숫자(dos) 앞에는 보통 관사를 붙이지 않습니다. tener 뒤의 사물 목적어에는 인칭의 a도 쓰지 않습니다. 그래서 'tienen dos perros'처럼 빈칸을 비웁니다.","x":["ø: 숫자 앞 관사 없음 → 정답 ✓","unos: 숫자 앞에 쓰면 '약 두 마리'처럼 어색해집니다 ✗","a: tener 뒤 동물 목적어에 인칭의 a를 쓰지 않습니다 ✗","de los: '~ 중에서'라는 뜻이 되어 ✗"]},{"id":"G263","q":"Isabel ____ profesora de francés.","o":["estará","es","va a estar","está"],"a":1,"k":"ser + 직업","t":"이사벨은 프랑스어 선생님이다.","e":"직업을 말할 때는 ser를 씁니다. 'Isabel es profesora'처럼 관사 없이 씁니다. estar를 쓰려면 'estar de + 직업' 형태로 '임시로 ~로 일하다'라는 뜻이 됩니다.","x":["estará: 미래형으로 현재 사실이 아니라 추측이 됩니다 ✗","es: ser + 직업 → 정답 ✓","va a estar: estar라서 직업을 나타내지 않습니다 ✗","está: estar는 직업을 직접 나타내지 않습니다 ✗"]},{"id":"G264","q":"Deberías ____ ir al médico si no estás bien.","o":["a","que","ø","para"],"a":2,"k":"deber + 동사원형","t":"몸이 안 좋으면 병원에 가 봐야 해.","e":"deber(~해야 한다) 뒤에는 바로 동사원형이 옵니다. 'Deberías ir'에서 deberías는 조건법으로 '~하는 게 좋겠다'는 부드러운 조언입니다. tener que와 달리 que가 필요 없습니다.","x":["a: deber 뒤에 a를 넣지 않습니다 ✗","que: tener que와 혼동한 것으로 deber 뒤에는 쓰지 않습니다 ✗","ø: deber + 동사원형 → 정답 ✓","para: '~하기 위해'라서 ✗"]},{"id":"G265","q":"____ las manzanas.","o":["Me encanto","Yo encanto","Me encantan","Me encanta"],"a":2,"k":"encantar 수 일치","t":"나는 사과를 정말 좋아한다.","e":"encantar는 gustar처럼 좋아하는 대상이 주어입니다. las manzanas(사과들)가 복수이므로 동사는 3인칭 복수 encantan이 되고, 좋아하는 사람 '나'는 me로 나타냅니다.","x":["Me encanto: '나 자신이 마음에 든다'라는 형태라 ✗","Yo encanto: 좋아하는 사람을 주어로 쓰지 않습니다 ✗","Me encantan: 복수 주어 las manzanas + 나에게 → 정답 ✓","Me encanta: 단수형이라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G266","q":"Yo tampoco ____ tengo hermanos, soy hijo único como tú.","o":["yo no","ø","ni","no"],"a":1,"k":"tampoco + 동사","t":"나도 형제가 없어, 너처럼 외동이야.","e":"tampoco(~도 아니다)가 동사 앞에 오면 그 자체로 부정이므로 no를 더 넣지 않습니다. 'Yo tampoco tengo'가 맞고, 'No tengo hermanos tampoco'처럼 동사 뒤로 보낼 때만 no가 필요합니다.","x":["yo no: yo가 중복되고 tampoco 뒤에 no를 넣지 않습니다 ✗","ø: tampoco가 이미 부정이라 빈칸을 비움 → 정답 ✓","ni: tampoco 뒤에 쓰지 않습니다 ✗","no: tampoco가 동사 앞에 있을 때 no를 더 쓰지 않습니다 ✗"]},{"id":"G267","q":"____ regar las plantas, lo haré esta tarde.","o":["Se me ha olvidado","Se me olvidará","Se me olvidaría","Se me está olvidando"],"a":0,"k":"se me olvidó (무의지)","t":"식물에 물 주는 걸 깜빡했네, 오늘 오후에 할게.","e":"'se me ha olvidado + 동사원형'은 '(나도 모르게) ~하는 것을 깜빡했다'라는 표현입니다. 잊어버린 일이 바로 지금과 연결되므로 현재완료를 씁니다. 중남미에서는 'Se me olvidó'라고 단순과거를 더 많이 씁니다.","x":["Se me ha olvidado: 현재완료 '깜빡했다' → 정답 ✓","Se me olvidará: 미래형 '잊을 것이다'라서 ✗","Se me olvidaría: 조건법이라 ✗","Se me está olvidando: 진행형 '잊어 가고 있다'라 어색합니다 ✗"]},{"id":"G268","q":"Ojalá ____ el autobús a su hora.","o":["llegue","llegará","ha llegado","llega"],"a":0,"k":"ojalá + 접속법","t":"버스가 제시간에 도착하면 좋겠다.","e":"ojalá(제발 ~하기를)는 바람을 나타내며 뒤에는 반드시 접속법을 씁니다. llegar의 3인칭 접속법 현재는 llegue입니다(g → gu 철자 변화에 주의).","x":["llegue: llegar 접속법 현재 → 정답 ✓","llegará: 직설법 미래라 ojalá 뒤에 쓸 수 없습니다 ✗","ha llegado: 직설법 현재완료라 ✗","llega: 직설법 현재라 ✗"]},{"id":"G269","q":"¿Todavía te duele ____ garganta?","o":["la","lo","una","ø"],"a":0,"k":"신체 부위 + 정관사","t":"아직도 목이 아프니?","e":"doler(아프다) 구문에서 아픈 신체 부위는 주어이며, 소유사 대신 정관사를 씁니다. garganta(목구멍)는 여성 명사이므로 'la garganta'입니다. 누가 아픈지는 te가 보여 줍니다.","x":["la: 신체 부위 앞 여성 정관사 → 정답 ✓","lo: 중성/대명사 형태라 명사 앞에 쓸 수 없습니다 ✗","una: 부정관사라 '어떤 목'이 되어 ✗","ø: 주어 명사 앞에 관사가 필요합니다 ✗"]},{"id":"G270","q":"He olvidado mi chaqueta, ¿me dejas ____?","o":["las tuyas","la tuya","lo tuyo","tuya"],"a":1,"k":"소유대명사 la tuya","t":"재킷을 놓고 왔어, 네 것 좀 빌려줄래?","e":"앞에 나온 chaqueta(재킷)를 반복하지 않고 '네 것'이라고 할 때 소유대명사 'la tuya'를 씁니다. chaqueta가 여성 단수이므로 la tuya입니다.","x":["las tuyas: 복수형이라 재킷 한 벌과 맞지 않습니다 ✗","la tuya: 여성 단수 소유대명사 → 정답 ✓","lo tuyo: 중성으로 '네 일/네 것들'이라는 막연한 뜻이 됩니다 ✗","tuya: 목적어로 쓰려면 정관사 la가 필요합니다 ✗"]},{"id":"G271","q":"____ varios poemas, pero no me gusta el resultado.","o":["He escrito","He escribido","Escribiré","Voy a escribir"],"a":0,"k":"현재완료 불규칙 분사","t":"시를 몇 편 썼는데, 결과물이 마음에 들지 않는다.","e":"현재완료는 haber + 과거분사로 만듭니다. escribir(쓰다)의 과거분사는 불규칙형 escrito입니다. 이미 쓴 결과가 지금 마음에 들지 않는다는 현재와의 연결이 있으므로 'He escrito'가 맞습니다.","x":["He escrito: 현재완료, 불규칙 분사 escrito → 정답 ✓","He escribido: escribir의 분사는 불규칙형 escrito라 틀린 형태입니다 ✗","Escribiré: 미래형이라 이미 결과가 있다는 뒷문장과 맞지 않습니다 ✗","Voy a escribir: 근접미래라 ✗"]},{"id":"G272","q":"Ahora estoy ocupada, te llamo ____ media hora.","o":["a","hasta","de","en"],"a":3,"k":"en + 시간","t":"지금은 바빠서, 30분 후에 전화할게.","e":"'en + 시간'은 '지금부터 ~ 후에'라는 뜻입니다. 'en media hora'는 '30분 후에'입니다. 스페인에서는 'dentro de media hora'도 자주 씁니다. 여기서 현재형 llamo는 가까운 미래를 나타냅니다.","x":["a: a media hora는 '30분 거리에'라는 뜻이 되어 ✗","hasta: '~까지'라서 ✗","de: 시간 길이 앞에 쓰지 않습니다 ✗","en: en + 시간 '~ 후에' → 정답 ✓"]},{"id":"G273","q":"¿A qué hora sale ____ su oficina?","o":["en","de","con","entre"],"a":1,"k":"salir de","t":"그는 몇 시에 사무실에서 나오나요?","e":"'~에서 나오다/떠나다'는 'salir de + 장소'로 씁니다. de는 출발점을 나타냅니다. 반대로 '~로 떠나다'는 'salir para/hacia + 장소'입니다.","x":["en: en은 장소 안을 나타내 출발점을 나타내지 못합니다 ✗","de: salir de '~에서 나오다' → 정답 ✓","con: '~와 함께'라서 ✗","entre: '~ 사이에'라서 ✗"]},{"id":"G274","q":"____ zapatos son demasiado pequeños para ti.","o":["Esto","Estos","Este","Estas"],"a":1,"k":"지시형용사 estos","t":"이 신발은 너에게 너무 작다.","e":"zapatos(신발)는 남성 복수 명사이므로 지시형용사는 estos를 씁니다. 동사 son이 복수인 것도 힌트입니다. esto는 명사 앞에 쓸 수 없는 중성형입니다.","x":["Esto: 중성 대명사라 명사 앞에 쓸 수 없습니다 ✗","Estos: 남성 복수 지시형용사 → 정답 ✓","Este: 단수형이라 ✗","Estas: 여성형이라 ✗"]},{"id":"G275","q":"Por favor, ____ a Lisa este DVD cuando la veas.","o":["das","le dé","da","dale"],"a":3,"k":"명령형 + 대명사","t":"부탁인데, 리사를 만나면 이 DVD를 그녀에게 줘.","e":"dar의 tú 긍정 명령형은 da이고, 긍정 명령에서는 간접목적격 대명사 le(그녀에게)를 동사 끝에 붙여 'dale'이 됩니다. 'a Lisa'가 있어도 le를 함께 쓰는 것이 자연스럽습니다.","x":["das: 현재형 '너는 준다'라서 명령이 아닙니다 ✗","le dé: usted 명령형(접속법)으로 문장의 tú(cuando la veas)와 맞지 않습니다 ✗","da: 명령형이지만 le가 빠져 덜 자연스럽습니다 ✗","dale: tú 명령형 + le → 정답 ✓"]},{"id":"G276","q":"No me gusta ____ té verde.","o":["al","la","ø","el"],"a":3,"k":"gustar + 정관사","t":"나는 녹차를 좋아하지 않는다.","e":"gustar 구문에서 좋아하거나 싫어하는 대상(주어)은 일반적인 의미라도 정관사를 붙입니다. té(차)는 남성 명사이므로 'el té verde'입니다. 예: Me gusta la música. (나는 음악을 좋아한다.)","x":["al: a + el로 주어 앞에 쓸 수 없습니다 ✗","la: 여성형인데 té는 남성 명사라 ✗","ø: gustar 구문의 주어 명사에는 관사가 필요합니다 ✗","el: 남성 정관사 → 정답 ✓"]},{"id":"G277","q":"Nunca ____ en Alemania, pero me gustaría ir.","o":["había estado","esté","he estado","estoy"],"a":2,"k":"현재완료 (경험)","t":"나는 독일에 가 본 적이 없지만, 가 보고 싶다.","e":"'~해 본 적이 있다/없다'라는 인생 경험은 현재완료로 표현합니다. nunca(한 번도 ~않다)와 함께 'nunca he estado'라고 하면 '한 번도 가 본 적이 없다'가 됩니다. 중남미에서는 'nunca estuve'처럼 단순과거도 씁니다.","x":["había estado: 과거완료라 기준이 되는 과거 시점이 없어 ✗","esté: 접속법이라 평서문에 쓸 수 없습니다 ✗","he estado: 현재완료, 경험 → 정답 ✓","estoy: 현재형 '지금 있다'라서 ✗"]},{"id":"G278","q":"____ a los candidatos antes de ayer.","o":["Entrevisto","Entrevistaba","Había entrevistado","Entrevisté"],"a":3,"k":"단순과거","t":"나는 그저께 지원자들을 면접했다.","e":"antes de ayer(그저께)는 이미 끝난 과거의 특정 시점이므로 단순과거를 씁니다. entrevistar의 yo 단순과거는 entrevisté이며, 마지막 é의 악센트에 주의하세요(entrevisté 내가 / entrevistó 그가).","x":["Entrevisto: 현재형이라 ✗","Entrevistaba: 불완료과거는 배경·습관에 써서 끝난 한 번의 일에는 어색합니다 ✗","Había entrevistado: 과거완료라 다른 과거 기준점이 필요합니다 ✗","Entrevisté: 단순과거 yo형 → 정답 ✓"]},{"id":"G279","q":"Todos los ciudadanos ____ respetar las leyes.","o":["hay","tienen","tienen que","hay que"],"a":2,"k":"tener que vs hay que","t":"모든 시민은 법을 지켜야 한다.","e":"주어가 있을 때 '~해야 한다'는 'tener que + 동사원형'으로, 주어에 맞춰 활용합니다. 주어 todos los ciudadanos가 3인칭 복수이므로 'tienen que'입니다. hay que는 주어 없이 '(일반적으로) ~해야 한다'라고 할 때만 씁니다.","x":["hay: '있다'라서 의미가 맞지 않습니다 ✗","tienen: que가 빠져 '가지고 있다'라는 뜻이 됩니다 ✗","tienen que: 주어 + tener que '~해야 한다' → 정답 ✓","hay que: 주어가 없을 때만 쓰므로 주어가 있는 이 문장에는 ✗"]},{"id":"G280","q":"____ hemos encontrado un apartamento adecuado para nosotros. ¡Qué bien!","o":["Ya","Todavía","Mientras","Entonces"],"a":0,"k":"ya (이미)","t":"우리에게 맞는 아파트를 드디어 찾았어. 정말 잘됐다!","e":"ya는 '이미, 벌써, 드디어'라는 뜻으로 완료된 일을 강조합니다. 'Ya hemos encontrado'는 '(마침내) 찾았다'라는 기쁜 소식이며, 뒤의 '¡Qué bien!'과 잘 어울립니다.","x":["Ya: '이미/드디어', 완료 강조 → 정답 ✓","Todavía: '아직'이라 부정어 없이 완료와 쓰면 어색합니다 ✗","Mientras: '~하는 동안'이라 ✗","Entonces: '그러면/그때'라 문장 첫머리에서 의미가 맞지 않습니다 ✗"]},{"id":"G281","q":"Todavía no ____ la última película de Almodóvar.","o":["vi","he visto","veía","veo"],"a":1,"k":"todavía no + 현재완료","t":"나는 아직 알모도바르의 최신 영화를 보지 못했다.","e":"'todavía no(아직 ~않았다)'는 지금까지의 경험을 말하므로 스페인에서는 현재완료와 씁니다. ver의 과거분사는 불규칙형 visto입니다. 중남미에서는 'Todavía no vi'처럼 단순과거도 자연스럽게 씁니다.","x":["vi: 단순과거로 중남미에서는 쓰지만 표준(스페인)에서는 현재완료를 씁니다 ✗","he visto: 현재완료, 불규칙 분사 visto → 정답 ✓","veía: 불완료과거라 ✗","veo: 현재형이라 '아직 안 본다'가 되어 어색합니다 ✗"]},{"id":"G282","q":"¿Dónde están ____ colegas?","o":["tuyas","tuyos","tu","tus"],"a":3,"k":"소유형용사 tus","t":"네 동료들은 어디 있어?","e":"명사 앞에 오는 '너의'는 tu이고, 복수 명사 앞에서는 tus입니다. colegas(동료들)가 복수이므로 tus입니다. tu/tus는 남녀 구분이 없습니다.","x":["tuyas: 명사 뒤에 오는 형태라 ✗","tuyos: 명사 뒤에 오는 형태라 ✗","tu: 단수형이라 복수 명사와 맞지 않습니다 ✗","tus: 명사 앞 2인칭 소유형용사 복수 → 정답 ✓"]},{"id":"G283","q":"¿Qué te ____ el espectáculo de anoche?","o":["había parecido","parecía","estaba pareciendo","pareció"],"a":3,"k":"parecer 단순과거","t":"어젯밤 공연 어땠어?","e":"'¿Qué te parece...?'는 '~ 어때?'라고 의견을 묻는 표현입니다. anoche(어젯밤)의 끝난 일에 대한 의견을 물으므로 단순과거 'pareció'를 씁니다. 주어는 el espectáculo(3인칭 단수)입니다.","x":["había parecido: 과거완료라 기준 과거 시점이 없어 ✗","parecía: 불완료과거라 끝난 공연에 대한 평가로는 어색합니다 ✗","estaba pareciendo: 진행형으로 이 동사에 쓰지 않습니다 ✗","pareció: 단순과거, 끝난 일에 대한 의견 → 정답 ✓"]},{"id":"G284","q":"Hoy el mar está ____ calma.","o":["a","por","de","en"],"a":3,"k":"estar en calma","t":"오늘은 바다가 잔잔하다.","e":"'estar en calma'는 '잔잔하다, 고요하다'라는 관용 표현입니다. 명사 calma(고요함) 앞에 en을 써서 상태를 나타냅니다. 비슷한 표현: estar en silencio (조용하다)","x":["a: a calma라는 표현은 없습니다 ✗","por: por calma라는 표현은 없습니다 ✗","de: de calma라는 표현은 이 의미로 쓰지 않습니다 ✗","en: estar en calma '잔잔하다' → 정답 ✓"]},{"id":"G285","q":"Margarita ____ el pelo cada día.","o":["me lavo","se lave","se lavan","se lava"],"a":3,"k":"재귀동사 lavarse","t":"마르가리타는 매일 머리를 감는다.","e":"lavarse el pelo(자기 머리를 감다)는 재귀동사입니다. 주어 Margarita가 3인칭 단수이므로 'se lava'가 됩니다. 사실을 말하는 평서문이므로 직설법을 씁니다.","x":["me lavo: '나는'이라 주어와 맞지 않습니다 ✗","se lave: 접속법이라 평서문에 쓸 수 없습니다 ✗","se lavan: 3인칭 복수라 ✗","se lava: 3인칭 단수 재귀동사 → 정답 ✓"]},{"id":"G286","q":"La chica ____ la camiseta azul va a la misma clase que yo.","o":["de","con","a","entre"],"a":0,"k":"특징 de","t":"파란 티셔츠를 입은 여자아이는 나와 같은 반이다.","e":"사람의 옷차림이나 특징으로 그 사람을 구별할 때는 'de + 특징'을 씁니다. 'la chica de la camiseta azul'은 '파란 티셔츠의 그 여자아이'라는 뜻입니다. 'con la camiseta azul'도 쓰기는 하지만 de가 가장 자연스럽고 일반적입니다.","x":["de: 특징으로 사람을 가리키는 de → 정답 ✓","con: 쓰이기도 하지만 사람을 구별할 때는 de가 더 일반적이라 교재 정답이 아닙니다 ✗","a: 이 의미로 쓰지 않습니다 ✗","entre: '~ 사이에'라서 ✗"]},{"id":"G287","q":"Aurora vive con ____ compañeras de trabajo en un piso.","o":["vuestra","sus","su","tu"],"a":1,"k":"소유형용사 sus","t":"아우로라는 직장 동료들과 함께 아파트에 산다.","e":"주어 Aurora(3인칭)의 동료이므로 '그녀의'는 su를 쓰고, compañeras가 복수이므로 sus가 됩니다. piso는 스페인에서 '아파트'를 뜻합니다.","x":["vuestra: '너희의'이고 단수형이라 ✗","sus: 3인칭 소유형용사 복수 → 정답 ✓","su: 단수형이라 복수 명사와 맞지 않습니다 ✗","tu: '너의'라서 주어와 맞지 않습니다 ✗"]},{"id":"G288","q":"Prefiero trabajar ____ mañana.","o":["la","para la","por la","en"],"a":2,"k":"por la mañana","t":"나는 오전에 일하는 것을 더 좋아한다.","e":"하루의 시간대 '오전에, 오후에, 밤에'는 'por la mañana / por la tarde / por la noche'로 씁니다. 중남미에서는 'en la mañana'라고도 하지만 보기의 'en'은 관사가 없어서 틀립니다.","x":["la: 전치사가 없어 시간대 표현이 되지 않습니다 ✗","para la: '오전을 위해'라는 뜻이 되어 ✗","por la: por la mañana '오전에' → 정답 ✓","en: 관사 없이 en mañana라고 쓰지 않습니다 ✗"]},{"id":"G289","q":"Están agotados, ____ ayer estuvieron trabajando sin descansar ni un momento.","o":["como","es que","por eso","así que"],"a":1,"k":"설명 es que","t":"그들은 녹초가 됐어, 어제 한순간도 쉬지 않고 일했거든.","e":"'es que'는 '그게 말이야, ~거든'처럼 앞의 상황에 대한 이유나 해명을 덧붙일 때 쓰는 구어 표현입니다. 녹초가 된 이유를 뒤에서 설명하므로 es que가 맞습니다.","x":["como: 이유의 como는 문장 맨 앞에 와야 해서 ✗","es que: 이유·해명을 덧붙이는 '~거든' → 정답 ✓","por eso: '그래서'라 원인과 결과가 뒤바뀝니다 ✗","así que: '그래서'라 원인과 결과가 뒤바뀝니다 ✗"]},{"id":"G290","q":"¿Cuántas horas dedicas ____ estudiar cada día?","o":["a","de","por","en"],"a":0,"k":"dedicar a","t":"너는 매일 몇 시간을 공부하는 데 쓰니?","e":"'dedicar + 시간 + a + 동사원형/명사'는 '~에 (시간을) 쓰다, 바치다'라는 뜻입니다. dedicar은 항상 전치사 a와 짝을 이룹니다. 예: Dedico una hora a leer. (나는 한 시간을 독서에 쓴다.)","x":["a: dedicar a '~에 시간을 쓰다' → 정답 ✓","de: dedicar과 함께 쓰지 않습니다 ✗","por: dedicar과 함께 쓰지 않습니다 ✗","en: 한국어 '~에'와 혼동하기 쉽지만 dedicar 뒤엔 a를 씁니다 ✗"]},{"id":"G291","q":"____ café le falta azúcar.","o":["Del","El","A","Al"],"a":3,"k":"faltar + 간접목적어","t":"커피에 설탕이 부족하다.","e":"faltar(부족하다)는 gustar처럼 씁니다. 부족한 것(azúcar)이 주어이고, 무언가가 부족한 대상(커피)은 'a + 명사'와 le로 나타냅니다. a + el café가 축약되어 'Al café le falta azúcar'가 됩니다.","x":["Del: de + el로 '커피의'라는 뜻이 되어 ✗","El: 커피가 주어가 되어 le와 맞지 않습니다 ✗","A: 정관사 el이 빠졌습니다 ✗","Al: a + el, 간접목적어 표시 → 정답 ✓"]},{"id":"G292","q":"¿Cómo ____ la paella? Nunca he hecho una.","o":["se hace","se hacen","hacerse","hecho"],"a":0,"k":"수동의 se","t":"빠에야는 어떻게 만들어요? 한 번도 만들어 본 적이 없어요.","e":"'se + 3인칭 동사'는 '(일반적으로) ~된다/~한다'는 수동·무인칭 표현입니다. 주어 la paella가 단수이므로 동사도 단수 'se hace'입니다. 요리법을 물을 때 자주 씁니다.","x":["se hace: 단수 주어 la paella + 수동의 se → 정답 ✓","se hacen: 복수형이라 단수 주어와 맞지 않습니다 ✗","hacerse: 동사원형이라 문장의 동사가 될 수 없습니다 ✗","hecho: 과거분사라 단독으로 쓸 수 없습니다 ✗"]},{"id":"G293","q":"Si me dan la beca, ____ en Alemania el año que viene.","o":["estudiar","he estudiado","estoy estudiando","estudiaré"],"a":3,"k":"si 조건문 + 미래","t":"장학금을 받으면 내년에 독일에서 공부할 거야.","e":"실현 가능한 조건문은 'Si + 현재형, 미래형/현재형'으로 씁니다. 조건(si me dan la beca)이 현재형이고, 결과는 미래 'estudiaré(공부할 것이다)'입니다.","x":["estudiar: 동사원형이라 ✗","he estudiado: 현재완료라 미래의 결과를 나타내지 못합니다 ✗","estoy estudiando: 현재진행형이라 el año que viene와 어울리지 않습니다 ✗","estudiaré: 미래형, 조건의 결과 → 정답 ✓"]},{"id":"G294","q":"No somos españoles, ____ mexicanos.","o":["o","sino","y","pero"],"a":1,"k":"sino","t":"우리는 스페인 사람이 아니라 멕시코 사람이다.","e":"'A가 아니라 B다'처럼 부정문 뒤에서 앞의 내용을 바로잡을 때는 sino를 씁니다. pero는 '하지만'으로 앞 내용을 인정하면서 덧붙일 때 씁니다. 예: No es rojo, sino azul. (빨간색이 아니라 파란색이다.)","x":["o: '또는'이라서 ✗","sino: '~이 아니라 ~이다' → 정답 ✓","y: '그리고'라서 대조를 나타내지 못합니다 ✗","pero: 앞 내용을 바로잡는 경우에는 sino를 씁니다 ✗"]},{"id":"G295","q":"¿Qué ____ tú en mi lugar?","o":["haríais","haría","harían","harías"],"a":3,"k":"조건법 (가정)","t":"네가 내 입장이라면 어떻게 하겠어?","e":"'~라면 어떻게 하겠어?'라는 가정은 조건법(~할 텐데)으로 나타냅니다. hacer의 조건법은 불규칙 어간 har-를 써서 haría, harías...가 됩니다. 주어가 tú이므로 harías입니다.","x":["haríais: vosotros형이라 tú와 맞지 않습니다 ✗","haría: yo/él형이라 ✗","harían: ellos/ustedes형이라 ✗","harías: tú 조건법 → 정답 ✓"]},{"id":"G296","q":"Ya les ____ la merienda a los chicos. Lo hice hace más de una hora.","o":["daba","di","dio","estaba dando"],"a":1,"k":"단순과거 (dar)","t":"아이들에게 간식은 이미 줬어. 한 시간도 더 전에 줬어.","e":"'hace más de una hora(한 시간도 더 전에)'처럼 끝난 과거의 일은 단순과거로 씁니다. dar의 yo 단순과거는 di(악센트 없음)입니다. 뒤 문장의 'Lo hice(내가 했다)'가 주어가 '나'임을 알려 줍니다.","x":["daba: 불완료과거로 습관·배경을 나타내 ✗","di: dar의 yo 단순과거 → 정답 ✓","dio: 3인칭 '그가 줬다'라 Lo hice(내가 했다)와 맞지 않습니다 ✗","estaba dando: 과거진행형이라 ✗"]},{"id":"G297","q":"Como ____ tan seria, pensé que Marta se había enfadado conmigo.","o":["estaría","estuviera","estaba","estará"],"a":2,"k":"불완료과거 (상태)","t":"마르타가 너무 심각한 표정이어서, 나는 그녀가 나에게 화가 났다고 생각했다.","e":"과거의 상태나 모습을 묘사할 때는 불완료과거를 씁니다. 이유를 나타내는 como 뒤에서 '그녀가 심각해 보였기 때문에'라는 배경을 말하므로 직설법 'estaba'가 맞습니다.","x":["estaría: 조건법이라 사실을 이유로 들지 못합니다 ✗","estuviera: 접속법 과거라 이유의 como 뒤에 쓰지 않습니다 ✗","estaba: 불완료과거, 과거 상태 묘사 → 정답 ✓","estará: 미래형이라 ✗"]},{"id":"G298","q":"Hace tres años ____ a Santiago de Compostela.","o":["iré","he ido","voy a ir","fui"],"a":3,"k":"단순과거 (hace)","t":"3년 전에 나는 산티아고 데 콤포스텔라에 갔다.","e":"'hace + 기간'은 '~ 전에'라는 뜻으로 끝난 과거 시점을 나타내므로 단순과거를 씁니다. ir의 yo 단순과거는 fui입니다(ser의 단순과거와 형태가 같음).","x":["iré: 미래형이라 ✗","he ido: 현재완료는 '~ 전에'라는 구체적 과거 시점과 함께 쓰지 않습니다 ✗","voy a ir: 근접미래라 ✗","fui: ir 단순과거 yo형 → 정답 ✓"]},{"id":"G299","q":"Señora, ¿le gusta cómo ____ queda la falda?","o":["la","le","se","se le"],"a":1,"k":"quedar + le (usted)","t":"손님, 치마가 어떻게 맞는지 마음에 드세요?","e":"quedar(옷이 ~하게 맞다)는 입는 사람을 간접목적격 대명사로 나타냅니다. Señora에게 존칭 usted로 말하므로 3인칭 간접목적격 le를 써서 'le queda'가 됩니다.","x":["la: 직접목적격이라 quedar 구문에 쓰지 않습니다(일부 지역의 laísmo는 비표준) ✗","le: usted에게 쓰는 간접목적격 → 정답 ✓","se: '치마가 남는다'라는 다른 뜻이 됩니다 ✗","se le: '(실수로) 그녀에게 남겨지다'라는 무의지 구문이 되어 ✗"]},{"id":"G300","q":"¿Es verdad que a ustedes ____ encanta el pescado de esta región?","o":["los","les","las","se"],"a":1,"k":"encantar + les","t":"여러분이 이 지역의 생선을 정말 좋아한다는 게 사실인가요?","e":"encantar는 좋아하는 사람을 간접목적격 대명사로 나타냅니다. 'a ustedes(여러분에게)'는 3인칭 복수로 취급하므로 les를 씁니다. ustedes는 중남미에서는 '너희'에게도 쓰는 일반적인 복수형입니다.","x":["los: 직접목적격이라 encantar 구문에 쓰지 않습니다 ✗","les: ustedes에 맞는 간접목적격 복수 → 정답 ✓","las: 직접목적격 여성 복수라 ✗","se: 재귀/무인칭 대명사라 맞지 않습니다 ✗"]},{"id":"G301","q":"Mi hijo no sabe leer ____, es demasiado pequeño.","o":["todavía","ya","todavía no","ya no"],"a":0,"k":"todavía no / ya no","t":"우리 아들은 아직 글을 읽을 줄 몰라요, 너무 어리거든요.","e":"'아직 ~하지 않다'는 스페인어로 'no + 동사 + todavía' 또는 'todavía no + 동사'로 씁니다. 이 문장은 이미 동사 앞에 no가 있으므로(No sabe leer) 문장 끝에 todavía만 붙이면 됩니다. 예: No ha llegado todavía.(그는 아직 도착하지 않았다.)","x":["todavía: 'no ~ todavía' 구조로 '아직 ~않다'가 되어 아이가 어려서 아직 못 읽는다는 뜻이 됩니다 ✓","ya: '이미'라는 뜻으로 no와 함께 문장 끝에 오면 어색하고 의미도 맞지 않습니다 ✗","todavía no: 이미 동사 앞에 no가 있으므로 no가 두 번 들어가 중복됩니다 ✗","ya no: '더 이상 ~않다'는 뜻으로, 예전엔 읽었는데 지금은 못 읽는다는 말이 되어 어색합니다 ✗"]},{"id":"G302","q":"¿Por qué ____ llorando el bebé?","o":["estás","son","está","es"],"a":2,"k":"estar + 현재분사","t":"아기가 왜 울고 있어요?","e":"'지금 ~하고 있다'는 진행형은 'estar + 현재분사(-ando/-iendo)'로 만듭니다. 주어는 el bebé(아기, 3인칭 단수)이므로 estar의 3인칭 단수형 está를 씁니다. 예: Está durmiendo.(그는 자고 있다.)","x":["estás: 2인칭 단수(너) 형태라 주어 el bebé와 맞지 않습니다 ✗","son: ser의 3인칭 복수형이며 진행형은 ser로 만들지 않습니다 ✗","está: estar의 3인칭 단수형으로 'está llorando(울고 있다)'가 됩니다 ✓","es: ser 동사는 진행형(llorando)과 함께 쓰지 않습니다 ✗"]},{"id":"G303","q":"¿____ opciones hay para ir al aeropuerto?","o":["Cuál","Quiénes","Qué","Cuántos"],"a":2,"k":"의문사 qué + 명사","t":"공항에 가는 데 어떤 방법들이 있나요?","e":"명사 바로 앞에서 '어떤 ~?'이라고 물을 때는 qué를 씁니다(qué + 명사). 스페인 스페인어에서 cuál은 보통 명사 앞에 직접 오지 않습니다. 예: ¿Qué libro quieres?(어떤 책을 원해?)","x":["Cuál: '어느 것'이라는 대명사로, 명사(opciones) 바로 앞에는 보통 쓰지 않으며 복수라면 cuáles여야 합니다 ✗","Quiénes: '누구들'로 사람에 대해 묻는 말이라 opciones(선택지)와 맞지 않습니다 ✗","Qué: 명사 앞에서 '어떤'이라는 뜻으로 쓰여 'qué opciones(어떤 선택지)'가 됩니다 ✓","Cuántos: '몇 개'라는 뜻은 가능하지만 opciones는 여성명사라 cuántas가 되어야 합니다 ✗"]},{"id":"G304","q":"Este es ____ CD de mi grupo favorito.","o":["el tercero","el tercer","tres","el tres"],"a":1,"k":"서수 tercero 어미 탈락","t":"이건 내가 가장 좋아하는 그룹의 세 번째 CD예요.","e":"서수 tercero(세 번째)와 primero(첫 번째)는 남성 단수 명사 앞에서 끝의 -o가 떨어져 tercer, primer가 됩니다. CD는 남성 명사이므로 'el tercer CD'가 맞습니다. 예: el primer día(첫째 날), la tercera vez(세 번째, 여성은 그대로)","x":["el tercero: 명사 앞에서는 -o가 탈락해야 하므로 틀립니다(명사 없이 단독으로 쓸 때만 tercero) ✗","el tercer: 남성 단수 명사 CD 앞에서 어미가 탈락한 올바른 형태입니다 ✓","tres: '셋'이라는 기수라 '세 번째'라는 순서를 나타내지 못하고 CD도 복수여야 합니다 ✗","el tres: '3번'이라는 숫자 자체를 가리키는 표현이라 '세 번째 CD'가 되지 않습니다 ✗"]},{"id":"G305","q":"Este es el computador ____ Benito.","o":["del","a","de","por"],"a":2,"k":"소유의 de","t":"이건 베니토의 컴퓨터예요.","e":"'~의(소유)'는 전치사 de로 나타냅니다. 사람 이름 앞에는 관사를 쓰지 않으므로 de Benito가 맞습니다. 참고로 computador는 중남미(특히 칠레·콜롬비아)에서 많이 쓰고, 스페인에서는 ordenador라고 합니다.","x":["del: de + el의 축약형이라 사람 이름 앞에는 쓰지 않습니다 ✗","a: '~에게/~로'라는 뜻이라 소유를 나타내지 못합니다 ✗","de: 소유를 나타내는 전치사로 'el computador de Benito(베니토의 컴퓨터)'가 됩니다 ✓","por: '~때문에/~에 의해'라는 뜻이라 소유 관계와 맞지 않습니다 ✗"]},{"id":"G306","q":"No sé ____ personas van a ir a la excursión.","o":["cuántas","cuánta","cuánto","cuántos"],"a":0,"k":"cuánto 성·수 일치","t":"소풍에 몇 명이 갈지 모르겠어요.","e":"cuánto(얼마나 많은)는 뒤의 명사와 성·수를 맞춥니다. personas는 여성 복수 명사이므로 cuántas가 됩니다. 이처럼 'No sé + 의문사' 형태의 간접 의문문에서도 악센트(á)는 그대로 씁니다.","x":["cuántas: 여성 복수 명사 personas와 일치하는 형태입니다 ✓","cuánta: 여성 단수형이라 복수 명사 personas와 맞지 않습니다 ✗","cuánto: 남성 단수형이라 성과 수가 모두 맞지 않습니다 ✗","cuántos: 남성 복수형인데 personas는 여성 명사라 틀립니다 ✗"]},{"id":"G307","q":"Tu ejercicio ____ bien.","o":["está","es","ser","estar"],"a":0,"k":"estar bien","t":"네 연습문제는 잘 됐어(맞았어).","e":"bien(잘, 좋게)은 부사이므로 ser가 아니라 estar와 함께 씁니다. '~이 잘 되어 있다, 맞다'는 'estar bien'입니다. 주어 tu ejercicio는 3인칭 단수라 está가 됩니다. 예: Todo está bien.(다 괜찮아요.)","x":["está: estar의 3인칭 단수형으로 'está bien(잘 됐다)'이 됩니다 ✓","es: ser는 부사 bien과 함께 쓰지 않습니다 ✗","ser: 동사원형이라 활용되지 않았고, bien과도 맞지 않습니다 ✗","estar: 동사원형 그대로라 주어에 맞게 활용해야 합니다 ✗"]},{"id":"G308","q":"Mi abuela está ____ bien, gracias por preguntar.","o":["muchos","mucho","mucha","muy"],"a":3,"k":"muy vs mucho","t":"할머니는 아주 잘 지내세요, 물어봐 줘서 고마워요.","e":"형용사나 부사 앞에서 '아주, 매우'는 muy를 씁니다. bien은 부사이므로 'muy bien'이 맞습니다. mucho는 동사 뒤(Trabaja mucho.)나 명사 앞(mucho dinero)에서 씁니다.","x":["muchos: 남성 복수 명사 앞에 쓰는 형태라 부사 bien 앞에 올 수 없습니다 ✗","mucho: 동사나 명사를 꾸미는 말이라 bien 앞에는 쓰지 않습니다 ✗","mucha: 여성 단수 명사 앞에 쓰는 형태라 맞지 않습니다 ✗","muy: 부사 bien을 꾸며 'muy bien(아주 잘)'이 됩니다 ✓"]},{"id":"G309","q":"Son ____ 10 de la mañana.","o":["la","ø","las","los"],"a":2,"k":"시간 표현 las","t":"오전 10시예요.","e":"시간을 말할 때는 hora(시간, 여성 명사)가 생략된 것으로 보아 여성 관사를 씁니다. 1시는 'Es la una', 2시 이상은 복수라 'Son las dos, Son las 10'처럼 las를 씁니다.","x":["la: 단수형으로 1시(Es la una)에만 씁니다 ✗","ø: 시간을 말할 때는 관사를 생략하지 않습니다 ✗","las: 여성 복수 관사로 'Son las 10(10시다)'이 됩니다 ✓","los: 남성 관사라 시간 표현에는 쓰지 않습니다 ✗"]},{"id":"G310","q":"¿Qué autobús debo tomar ____ ir a tu barrio?","o":["para","a","de","por"],"a":0,"k":"목적의 para","t":"너희 동네에 가려면 몇 번 버스를 타야 해?","e":"'~하기 위해(목적)'는 'para + 동사원형'으로 나타냅니다. 여기서는 '네 동네에 가기 위해'라는 목적이므로 para ir가 맞습니다. 참고로 autobús는 중남미에서 bus, camión(멕시코), colectivo(아르헨티나) 등으로도 부릅니다.","x":["para: 목적을 나타내 'para ir(가기 위해)'가 됩니다 ✓","a: 방향을 나타내지만 '~하기 위해'라는 목적 표현으로 동사원형 앞에 쓰지 않습니다 ✗","de: '~의, ~에서'라는 뜻이라 목적을 나타내지 못합니다 ✗","por: 원인·이유를 나타내는 경우가 많아 이 목적 문장에는 맞지 않습니다 ✗"]},{"id":"G311","q":"¿Han visto ____ Celia? Necesito hablar con ella.","o":["a la","la","ø","a"],"a":3,"k":"사람 목적어 앞 a","t":"셀리아 봤어요? 그녀와 얘기할 게 있어요.","e":"동사의 직접목적어(~을/를)가 특정한 사람일 때는 앞에 전치사 a를 붙입니다(인칭 a). 사람 이름 앞에는 관사를 쓰지 않으므로 'a Celia'가 맞습니다. 예: Conozco a Pedro.(나는 페드로를 안다.)","x":["a la: 사람 이름 앞에는 일반적으로 관사 la를 붙이지 않습니다 ✗","la: 인칭 a가 빠졌고 이름 앞 관사도 불필요합니다 ✗","ø: 사람 목적어 앞에는 a가 꼭 필요합니다 ✗","a: 사람 목적어 앞의 인칭 a로 'a Celia(셀리아를)'가 됩니다 ✓"]},{"id":"G312","q":"____ de allí es Carmen, mi profesora de matemáticas.","o":["Esta","Aquella","Aquel","Este"],"a":1,"k":"지시사 aquel/aquella","t":"저기 저 여자분이 제 수학 선생님 카르멘이에요.","e":"'allí(저기)'처럼 멀리 있는 것을 가리킬 때는 aquel/aquella(저, 저것)를 씁니다. 가리키는 대상이 Carmen(여성)이므로 여성형 aquella가 맞습니다. este/esta는 가까이 있는 '이(것)'입니다.","x":["Esta: '이 사람(여성)'으로 가까운 대상에 쓰여 de allí(저기)와 맞지 않습니다 ✗","Aquella: 멀리 있는 여성을 가리키는 '저 사람'으로 정답입니다 ✓","Aquel: 남성형이라 여성인 Carmen과 성이 맞지 않습니다 ✗","Este: 가까운 남성을 가리켜 거리와 성이 모두 맞지 않습니다 ✗"]},{"id":"G313","q":"____ más me gusta de mi ciudad es el clima.","o":["La que","Que","Lo","Lo que"],"a":3,"k":"lo que","t":"제 도시에서 가장 마음에 드는 것은 날씨예요.","e":"'~하는 것'처럼 정해지지 않은 내용을 가리킬 때는 중성 관계사 lo que를 씁니다. 'Lo que más me gusta'는 '내가 가장 좋아하는 것'이라는 뜻입니다. 예: Lo que dices es verdad.(네가 말하는 것은 사실이다.)","x":["La que: 특정 여성 명사를 받는 말인데, 여기서는 정해진 명사가 없어 맞지 않습니다 ✗","Que: 앞에 선행사나 lo가 없으면 '~하는 것'이라는 뜻이 되지 않습니다 ✗","Lo: que가 없어 뒤의 절을 이끌 수 없습니다 ✗","Lo que: '~하는 것'이라는 뜻으로 'Lo que más me gusta(가장 좋아하는 것)'가 됩니다 ✓"]},{"id":"G314","q":"Necesito que ____ pan y leche.","o":["compra","compran","compres","compras"],"a":2,"k":"necesitar que + 접속법","t":"네가 빵이랑 우유를 사 줬으면 해.","e":"'necesitar que(~가 ~하는 것이 필요하다)', 'querer que'처럼 다른 사람에게 바라거나 요구할 때 que 뒤에는 접속법(바람·요청 등을 나타내는 동사 형태)을 씁니다. comprar의 tú 접속법 현재형은 compres입니다.","x":["compra: 직설법 3인칭 단수(또는 명령형)라 접속법이 필요한 자리에 맞지 않습니다 ✗","compran: 직설법 3인칭 복수형이라 틀립니다 ✗","compres: comprar의 tú 접속법 현재형으로 정답입니다 ✓","compras: 직설법 tú 형태라 necesito que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G315","q":"Alicia es más alta ____ yo.","o":["que","a","de","como"],"a":0,"k":"비교급 más ~ que","t":"알리시아는 나보다 키가 커요.","e":"우등 비교(~보다 더 ~하다)는 'más + 형용사 + que + 비교 대상'으로 씁니다. 그래서 'más alta que yo(나보다 더 큰)'가 됩니다. 동등 비교는 'tan ~ como'를 씁니다.","x":["que: 'más ~ que'의 짝으로 비교 대상을 이끕니다 ✓","a: 비교 구문에서 쓰지 않는 전치사입니다 ✗","de: 'más de + 숫자(~이상)'에는 쓰지만 사람을 비교할 때는 쓰지 않습니다 ✗","como: 동등 비교 'tan ~ como'에 쓰는 말이라 más와 짝이 맞지 않습니다 ✗"]},{"id":"G316","q":"Mañana tengo que ir ____ banco.","o":["el","a","al","a el"],"a":2,"k":"축약 al","t":"내일 은행에 가야 해요.","e":"'ir a(~에 가다)' 뒤에 남성 관사 el이 오면 a + el이 반드시 al로 축약됩니다. banco는 남성 명사이므로 'ir al banco'가 맞습니다. 예: Voy al cine.(나는 영화관에 간다.)","x":["el: ir 뒤에 방향을 나타내는 a가 빠졌습니다 ✗","a: 관사 없이 'a banco'라고 하지 않습니다 ✗","al: a + el의 축약형으로 'ir al banco(은행에 가다)'가 됩니다 ✓","a el: 반드시 al로 줄여 써야 하므로 틀립니다 ✗"]},{"id":"G317","q":"Estoy ____ acuerdo con ustedes.","o":["a","por","de","con"],"a":2,"k":"estar de acuerdo","t":"여러분 의견에 동의해요.","e":"'estar de acuerdo con ~'는 '~에 동의하다'라는 고정 표현입니다. 전치사는 반드시 de를 씁니다. 참고로 ustedes는 스페인에서는 격식(여러분), 중남미에서는 격식·비격식 모두 '너희들'에 씁니다.","x":["a: 'estar a acuerdo'라는 표현은 없습니다 ✗","por: 이 관용 표현에는 por를 쓰지 않습니다 ✗","de: 'estar de acuerdo(동의하다)'의 고정 전치사입니다 ✓","con: con은 뒤에 'con ustedes'로 이미 쓰였고, 'estar con acuerdo'는 틀린 표현입니다 ✗"]},{"id":"G318","q":"Mientras tú vas al supermercado, yo hago ____ cena.","o":["ø","para la","la","a la"],"a":2,"k":"정관사 la","t":"네가 슈퍼마켓에 가는 동안 나는 저녁을 만들게.","e":"hacer la cena(저녁 식사를 만들다)처럼 '그날의 저녁 식사'를 말할 때는 정관사 la를 씁니다. hacer 동사의 직접목적어이므로 전치사는 필요 없습니다. 예: Hago la comida.(내가 점심을 만든다.)","x":["ø: 'hago cena'처럼 관사를 빼면 부자연스럽습니다 ✗","para la: '저녁을 위해'라는 뜻이 되어 무엇을 만드는지 목적어가 없어집니다 ✗","la: 정관사로 'hago la cena(저녁을 만든다)'가 됩니다 ✓","a la: 사물 목적어 앞에는 전치사 a를 쓰지 않습니다 ✗"]},{"id":"G319","q":"La película ____ a las 10.","o":["empieza","empiezo","empiece","empeza"],"a":0,"k":"어간 변화 e→ie","t":"영화는 10시에 시작해요.","e":"empezar(시작하다)는 현재형에서 어간의 e가 ie로 바뀌는 동사입니다(empiezo, empiezas, empieza…). 주어 la película는 3인칭 단수이므로 empieza가 맞습니다. 단, nosotros/vosotros는 바뀌지 않아요(empezamos).","x":["empieza: empezar의 3인칭 단수 현재형으로 정답입니다 ✓","empiezo: 1인칭 단수(나) 형태라 주어 película와 맞지 않습니다 ✗","empiece: 접속법 형태라 단순한 사실을 말하는 이 문장에 맞지 않습니다 ✗","empeza: 어간이 ie로 바뀌지 않은 잘못된 형태입니다 ✗"]},{"id":"G320","q":"¿Puede darme ____ para la tos?","o":["algún","alguna","alguien","algo"],"a":3,"k":"부정어 algo","t":"기침에 먹을 것 좀 주실 수 있나요?","e":"algo는 '무언가, 뭔가'라는 뜻의 대명사로 명사 없이 단독으로 쓰입니다. 약국에서 '기침에 좋은 뭔가'를 달라는 뜻이므로 algo가 맞습니다. 예: ¿Quieres algo?(뭐 원하는 거 있어?)","x":["algún: '어떤'이라는 형용사로 뒤에 남성 명사가 있어야 합니다 ✗","alguna: 뒤에 여성 명사가 필요한 형용사라 단독으로는 이 문장에 맞지 않습니다 ✗","alguien: '누군가'라는 사람을 가리키는 말이라 맞지 않습니다 ✗","algo: '무언가'라는 뜻의 대명사로 'darme algo(뭔가를 주다)'가 됩니다 ✓"]},{"id":"G321","q":"¿De qué ____ cuando llegó Marta?","o":["estabais hablando","estáis hablando","habéis hablado","estuvisteis hablando"],"a":0,"k":"과거진행 (불완료)","t":"마르타가 도착했을 때 너희는 무슨 이야기를 하고 있었니?","e":"과거의 어떤 순간(마르타가 도착했을 때)에 '진행 중이던 일'은 불완료과거 진행형 'estaba + 현재분사'로 나타냅니다. vosotros(너희) 형태는 estabais hablando입니다. 갑자기 일어난 일(llegó)은 단순과거, 배경 진행은 불완료로 씁니다.","x":["estabais hablando: 과거 특정 시점에 진행 중이던 동작을 나타내 정답입니다 ✓","estáis hablando: 현재진행형이라 과거 상황(llegó)과 시제가 맞지 않습니다 ✗","habéis hablado: 현재완료라 '도착했을 때 하고 있던' 진행의 의미가 없습니다 ✗","estuvisteis hablando: 단순과거 진행형으로 완결된 기간을 나타내 배경 설명에 맞지 않습니다 ✗"]},{"id":"G322","q":"Es ____ pena que haya personas viviendo en las calles.","o":["ø","una","la","un"],"a":1,"k":"ser una pena","t":"길거리에서 사는 사람들이 있다는 것은 안타까운 일이에요.","e":"'Es una pena que ~'는 '~라니 안타깝다/유감이다'라는 고정 표현으로 부정관사 una를 씁니다. pena는 여성 명사입니다. 이 표현 뒤 que절에는 감정을 나타내므로 접속법(haya)이 옵니다.","x":["ø: 'Es pena que'처럼 관사를 빼면 틀린 표현입니다 ✗","una: 'Es una pena(안타까운 일이다)'의 고정 표현으로 정답입니다 ✓","la: 'Es la pena'는 '그 안타까움이다'처럼 의미가 이상해집니다 ✗","un: 남성 관사라 여성 명사 pena와 맞지 않습니다 ✗"]},{"id":"G323","q":"¿____ vais a venir a nuestra nueva casa?","o":["Dónde","Cuánto","Quién","Cuándo"],"a":3,"k":"의문사 cuándo","t":"너희 언제 우리 새집에 올 거야?","e":"cuándo는 '언제'라는 때를 묻는 의문사입니다. 문장은 '우리 새집에 오다'라는 장소가 이미 나와 있으므로, 남은 정보인 시간을 묻는 cuándo가 자연스럽습니다. vais는 vosotros(너희) 형태로 스페인에서 쓰고, 중남미에서는 'van a venir(ustedes)'라고 합니다.","x":["Dónde: '어디'를 묻는데 장소(a nuestra nueva casa)가 이미 있어 맞지 않습니다 ✗","Cuánto: '얼마나'를 묻는 말이라 의미가 통하지 않습니다 ✗","Quién: '누가'인데 동사가 vais(너희)로 주어가 이미 정해져 있습니다 ✗","Cuándo: '언제'를 묻는 의문사로 정답입니다 ✓"]},{"id":"G324","q":"¿Puedes ____ el bote de mermelada?","o":["pasarme","pasar a mí","pasar me","me pasar"],"a":0,"k":"동사원형 + 대명사","t":"잼 병 좀 건네줄 수 있어?","e":"목적격 대명사(me, te, lo 등)는 동사원형 뒤에 붙여 한 단어로 씁니다: pasar + me → pasarme. 또는 활용된 동사 앞에 둘 수도 있어요(¿Me puedes pasar…?). 'me pasar'처럼 동사원형 바로 앞에 두거나 띄어 쓰면 안 됩니다.","x":["pasarme: 동사원형 뒤에 me를 붙인 올바른 형태입니다 ✓","pasar a mí: 대명사 me 없이 'a mí'만 쓰는 것은 틀린 표현입니다 ✗","pasar me: 동사원형과 대명사는 띄어 쓰지 않고 붙여 씁니다 ✗","me pasar: 대명사는 동사원형 앞에 올 수 없습니다(puedes 앞이면 가능) ✗"]},{"id":"G325","q":"¿Qué te llevarías a ____ isla desierta?","o":["uno","una","ø","un"],"a":1,"k":"부정관사 una","t":"무인도에 무엇을 가져가겠어요?","e":"isla(섬)는 여성 명사이고, 정해지지 않은 '어떤 무인도'를 가정하므로 부정관사 una를 씁니다. 'una isla desierta(무인도 하나)'는 자주 쓰는 표현입니다.","x":["uno: 명사 앞에서는 un으로 줄어들고, 여성 명사에는 쓰지 않습니다 ✗","una: 여성 단수 부정관사로 'una isla desierta(무인도)'가 됩니다 ✓","ø: 셀 수 있는 단수 명사 앞에서 관사를 생략하면 어색합니다 ✗","un: 남성 부정관사라 여성 명사 isla와 맞지 않습니다 ✗"]},{"id":"G326","q":"No tengo ____ problema, podemos quedar a la hora que quieras.","o":["ningún","alguna","ninguna","algún"],"a":0,"k":"ningún (부정 형용사)","t":"전혀 문제없어요, 원하는 시간에 만나요.","e":"부정문 'No tengo ~'에서 '아무 ~도(없다)'는 ninguno를 씁니다. ninguno는 남성 단수 명사 앞에서 -o가 떨어져 ningún이 됩니다. problema는 -a로 끝나지만 남성 명사(el problema)이므로 ningún problema가 맞습니다.","x":["ningún: 남성 명사 problema 앞의 부정 형용사로 '아무 문제도 없다'가 됩니다 ✓","alguna: 긍정의 '어떤'이고 여성형이라 부정문과 남성 명사에 맞지 않습니다 ✗","ninguna: 여성형인데 problema는 남성 명사라 틀립니다 ✗","algún: 긍정 표현이라 'No tengo' 부정문의 의미와 어울리지 않습니다 ✗"]},{"id":"G327","q":"A Inés le encanta bailar salsa y a mí ____.","o":["también","tampoco","además","sí"],"a":0,"k":"también / tampoco","t":"이네스는 살사 춤추는 걸 아주 좋아하고 나도 그래.","e":"앞 문장이 긍정(le encanta)일 때 '나도 그래'는 'a mí también'입니다. 앞 문장이 부정일 때는 'a mí tampoco(나도 안 그래)'를 씁니다. 앞 내용에 반대할 때는 긍정엔 'a mí no', 부정엔 'a mí sí'를 씁니다.","x":["también: 긍정 문장에 동의하는 '~도 그렇다'로 정답입니다 ✓","tampoco: 부정 문장에 동의할 때 쓰는 '~도 아니다'라 맞지 않습니다 ✗","además: '게다가'라는 뜻의 접속 부사라 'a mí además'는 틀린 표현입니다 ✗","sí: 앞 문장이 부정일 때 반대 의견을 말하는 표현이라 맞지 않습니다 ✗"]},{"id":"G328","q":"No puedo decirte lo que me contó Adela, ____ un secreto.","o":["haber","hay","está","es"],"a":3,"k":"ser + 명사","t":"아델라가 나한테 해 준 얘기는 말할 수 없어, 비밀이거든.","e":"'~은 ~이다'처럼 무엇인지 정체를 밝힐 때, 특히 뒤에 명사(un secreto)가 올 때는 ser를 씁니다. '(그것은) 비밀이다'이므로 es un secreto가 맞습니다.","x":["haber: 동사원형이고 '있다'는 존재 표현이라 맞지 않습니다 ✗","hay: '~이 있다'는 존재를 나타내 '비밀이다'라는 뜻이 되지 않습니다 ✗","está: estar는 상태·위치에 쓰고 명사 un secreto와 함께 쓰지 않습니다 ✗","es: 정체를 나타내는 ser의 3인칭 단수로 'es un secreto(비밀이다)'가 됩니다 ✓"]},{"id":"G329","q":"Mis sobrinos viven ____ Canadá.","o":["en","a","en la","al"],"a":0,"k":"장소 전치사 en","t":"내 조카들은 캐나다에 살아요.","e":"'~에 살다'는 'vivir en + 장소'입니다. 나라 이름에는 대부분 관사를 붙이지 않으므로 'en Canadá'가 맞습니다. 예: Vivo en Corea.(나는 한국에 산다.)","x":["en: 장소를 나타내 'vivir en Canadá(캐나다에 살다)'가 됩니다 ✓","a: 방향(~로)을 나타내 'vivir'와 함께 쓰지 않습니다 ✗","en la: Canadá 앞에는 관사를 붙이지 않으며 Canadá는 남성 명사이기도 합니다 ✗","al: a + el로 방향을 나타내 '살다'와 맞지 않습니다 ✗"]},{"id":"G330","q":"No ____ este juego, prefiero jugar a otra cosa.","o":["divierto","me divierto","se divierte","me divierte"],"a":3,"k":"divertir 구문","t":"이 게임은 재미없어, 다른 걸 하고 싶어.","e":"divertir(즐겁게 하다)는 gustar처럼 '재미를 주는 것'이 주어, '재미를 느끼는 사람'이 간접/직접목적격 대명사로 옵니다. 주어는 este juego(3인칭 단수)이고 나에게 재미를 주므로 'me divierte'가 됩니다. 'me divierto'는 '내가 즐긴다'라는 재귀 형태라 뒤에 con이 필요합니다(No me divierto con este juego).","x":["divierto: '내가 (누군가를) 즐겁게 한다'는 뜻이라 문장 의미와 맞지 않습니다 ✗","me divierto: 재귀형으로 '나는 즐긴다'이며, 이 문장처럼 쓰려면 'con este juego'가 필요합니다 ✗","se divierte: '그/그녀가 즐긴다'라는 뜻이라 나의 느낌을 말하는 문장과 맞지 않습니다 ✗","me divierte: '이 게임이 나를 즐겁게 한다'로 정답입니다 ✓"]},{"id":"G331","q":"Si ____ en casa en vez de salir con nosotros, te vas a aburrir.","o":["quedas","quedes","te quedas","te quedes"],"a":2,"k":"재귀동사 quedarse","t":"우리랑 나가는 대신 집에 있으면 너 심심할 거야.","e":"'(어떤 장소에) 머물다, 남다'는 재귀동사 quedarse를 씁니다. 실현 가능한 조건 'Si + 현재형'에서는 직설법 현재를 쓰므로 tú 형태인 'te quedas'가 맞습니다. Si 조건문에는 접속법 현재를 쓰지 않는다는 점도 기억하세요.","x":["quedas: 재귀대명사 te가 빠져 '집에 머물다'라는 뜻이 되지 않습니다 ✗","quedes: 접속법이고 재귀대명사도 없어 틀립니다 ✗","te quedas: quedarse의 tú 직설법 현재로 정답입니다 ✓","te quedes: si 조건문 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G332","q":"Estos son ____ calcetines y esos son los míos.","o":["los tuyos","tuyos","tu","tus"],"a":3,"k":"소유형용사 tus","t":"이건 네 양말이고 그건 내 거야.","e":"명사 앞에 오는 소유형용사는 짧은 형태(mi, tu, su…)를 쓰고, 명사의 수에 맞춥니다. calcetines(양말)가 복수이므로 tus가 됩니다. 뒤의 'los míos(내 것)'처럼 명사 없이 쓸 때는 긴 형태(el mío, los tuyos)를 씁니다.","x":["los tuyos: 명사 없이 '네 것들'을 뜻하는 소유대명사라 명사 앞에 올 수 없습니다 ✗","tuyos: 긴 형태는 명사 뒤에 오거나 ser 뒤에 쓰므로 명사 앞에는 틀립니다 ✗","tu: 단수형이라 복수 명사 calcetines와 수가 맞지 않습니다 ✗","tus: 복수 명사 앞에 오는 소유형용사로 'tus calcetines(네 양말)'가 됩니다 ✓"]},{"id":"G333","q":"Si no te sale bien esta actividad, debes volver a ____.","o":["la hacer","haciéndola","hacerla","hacer"],"a":2,"k":"volver a + 동사원형","t":"이 활동이 잘 안 되면 다시 해 봐야 해요.","e":"'volver a + 동사원형'은 '다시 ~하다'라는 뜻입니다. 앞의 esta actividad(여성 명사)를 대명사 la로 받아 동사원형 뒤에 붙여 hacerla가 됩니다. 예: Vuelve a llamarme.(다시 전화해 줘.)","x":["la hacer: 대명사는 동사원형 앞에 올 수 없습니다 ✗","haciéndola: 현재분사라 'volver a' 뒤에는 쓸 수 없습니다 ✗","hacerla: 동사원형 + 대명사 la로 '그것(활동)을 다시 하다'가 됩니다 ✓","hacer: 문법적으로는 가능하지만 무엇을 하는지 가리키는 대명사가 빠져 불완전합니다 ✗"]},{"id":"G334","q":"Úrsula es una mujer muy interesante, puedes hablar ____ muchos temas con ella.","o":["de","para","en","por"],"a":0,"k":"hablar de","t":"우르술라는 아주 흥미로운 사람이라 그녀와 여러 주제에 대해 이야기할 수 있어요.","e":"'~에 대해 이야기하다'는 'hablar de + 주제'로 씁니다. 그래서 'hablar de muchos temas(여러 주제에 대해 이야기하다)'가 됩니다. 비슷하게 'hablar sobre'도 가능합니다.","x":["de: 'hablar de(~에 대해 말하다)'의 전치사로 정답입니다 ✓","para: '~을 위해'라는 뜻이라 주제를 나타내지 못합니다 ✗","en: 'hablar en'은 언어를 말할 때(hablar en español) 쓰는 표현입니다 ✗","por: 'hablar por teléfono(전화로 말하다)'처럼 수단에 쓰여 맞지 않습니다 ✗"]},{"id":"G335","q":"Si necesitas ____, lo que sea, dímelo.","o":["algún","nadie","nada","algo"],"a":3,"k":"algo / nada","t":"뭔가 필요하면, 무엇이든 나한테 말해.","e":"긍정 조건문에서 '무언가'는 algo를 씁니다. nada(아무것도)는 부정문(no necesito nada)에 쓰는 말입니다. 뒤의 'lo que sea(무엇이든)'도 정해지지 않은 '무언가'를 강조합니다.","x":["algún: 뒤에 남성 명사가 필요한 형용사라 단독으로 쓸 수 없습니다 ✗","nadie: '아무도'라는 사람을 가리키는 부정어라 맞지 않습니다 ✗","nada: '아무것도'라는 부정어로 긍정 조건문에 어울리지 않습니다 ✗","algo: '무언가'라는 뜻으로 'necesitas algo(뭔가 필요하다)'가 됩니다 ✓"]},{"id":"G336","q":"Si pudiera, ____ contigo de vacaciones, pero esos días estaré trabajando.","o":["me iría","me vaya","me iré","me voy"],"a":0,"k":"가정문 si + 접속법 과거","t":"할 수만 있다면 너랑 휴가를 가겠지만, 그때 나는 일하고 있을 거야.","e":"현재 사실과 반대되거나 실현 가능성이 낮은 가정은 'Si + 접속법 과거(pudiera), 조건법(iría)'으로 표현합니다. irse(떠나다)의 yo 조건법 형태는 me iría입니다. 예: Si tuviera dinero, viajaría.(돈이 있다면 여행할 텐데.)","x":["me iría: 조건법으로 'pudiera'와 짝을 이루어 '~할 텐데'가 됩니다 ✓","me vaya: 접속법 현재라 가정문의 결과절에 쓰지 않습니다 ✗","me iré: 미래형이라 'Si pudiera' 가정과 맞지 않습니다 ✗","me voy: 현재형이라 실현 가능성이 낮은 가정의 결과로 맞지 않습니다 ✗"]},{"id":"G337","q":"____ oigo bien, no es necesario que grites.","o":["A ti","Te","Se","Os"],"a":1,"k":"직접목적격 대명사 te","t":"잘 들려, 소리 지를 필요 없어.","e":"oír(듣다)의 목적어 '너를'은 직접목적격 대명사 te로 나타내고 활용된 동사 앞에 둡니다. 뒤의 'grites(네가 소리 지르다)'로 보아 상대는 tú이므로 te가 맞습니다. 'a ti'는 강조용으로 대명사 te와 함께 써야 합니다(A ti te oigo).","x":["A ti: 대명사 te 없이 'a ti'만 쓸 수는 없습니다 ✗","Te: '너를'이라는 직접목적격 대명사로 'Te oigo bien(네 말 잘 들려)'가 됩니다 ✓","Se: 재귀나 3인칭 대명사라 '너를'의 뜻이 되지 않습니다 ✗","Os: vosotros(너희를)에 쓰는데 grites는 tú에 대한 말이라 맞지 않습니다 ✗"]},{"id":"G338","q":"¿Qué es ____ felicidad para ti?","o":["el","ø","la","lo"],"a":2,"k":"추상명사 + 정관사","t":"너에게 행복이란 무엇이니?","e":"스페인어에서는 felicidad(행복), amor(사랑)처럼 추상적인 개념을 일반적으로 말할 때 정관사를 붙입니다. felicidad는 여성 명사이므로 la felicidad가 됩니다. 예: El amor es importante.(사랑은 중요하다.)","x":["el: 남성 관사라 여성 명사 felicidad와 맞지 않습니다 ✗","ø: 추상 개념을 일반적으로 말할 때 관사를 빼면 어색합니다 ✗","la: 여성 정관사로 'la felicidad(행복)'가 됩니다 ✓","lo: 중성 관사로 형용사 앞에 쓰며(lo bueno) 명사 앞에는 쓰지 않습니다 ✗"]},{"id":"G339","q":"Mi moto está rota, así que voy a ir ____ pie al centro.","o":["por","de","a","en"],"a":2,"k":"ir a pie","t":"오토바이가 고장 나서 시내까지 걸어서 갈 거예요.","e":"'걸어서 가다'는 'ir a pie'라는 고정 표현입니다. 다른 교통수단은 'en coche, en autobús'처럼 en을 쓰지만, 걸어갈 때만 a pie를 씁니다. 참고로 일부 지역에서는 구어로 'de a pie'라고도 하지만 표준형은 a pie입니다.","x":["por: 'por pie'라는 표현은 없습니다 ✗","de: 'de pie'는 '서 있는'이라는 뜻이라 '걸어서'가 되지 않습니다 ✗","a: 'ir a pie(걸어서 가다)'의 고정 표현으로 정답입니다 ✓","en: 교통수단 앞에 쓰지만 pie(발)에는 쓰지 않습니다 ✗"]},{"id":"G340","q":"―¿____ camisa prefieres? ―La blanca.","o":["Por qué","Quién","Cómo","Qué"],"a":3,"k":"qué + 명사","t":"―어떤 셔츠가 더 좋아? ―흰색이요.","e":"명사(camisa) 바로 앞에서 '어떤/어느 ~'이라고 물을 때는 qué를 씁니다. 여러 개 중 하나를 고르는 질문이라도 명사가 바로 뒤에 오면 qué를 쓰는 것이 표준입니다. 중남미 일부 지역에서는 'cuál camisa'라고도 하지만 일반적으로는 qué를 씁니다.","x":["Por qué: '왜'라는 이유를 묻는 말이라 명사 앞에 오지 않습니다 ✗","Quién: '누구'라는 사람을 묻는 말이라 맞지 않습니다 ✗","Cómo: '어떻게'라는 방법·상태를 묻는 말이라 명사 앞에 올 수 없습니다 ✗","Qué: 명사 앞에서 '어떤'이라는 뜻으로 'Qué camisa(어떤 셔츠)'가 됩니다 ✓"]},{"id":"G341","q":"Hace años comía mucha carne, ____ ahora es vegetariano.","o":["o","ni","pero","entonces"],"a":2,"k":"접속사 pero","t":"몇 년 전엔 고기를 많이 먹었지만 지금은 채식주의자예요.","e":"pero(그러나, 하지만)는 앞뒤 내용이 서로 반대될 때 씁니다. '예전엔 고기를 많이 먹었다'와 '지금은 채식주의자다'는 대조되는 내용이므로 pero가 맞습니다.","x":["o: '또는'이라는 선택의 접속사라 대조의 의미가 없습니다 ✗","ni: '~도 아니다'로 부정문을 이을 때 씁니다 ✗","pero: 대조를 나타내는 '하지만'으로 정답입니다 ✓","entonces: '그래서, 그러면'이라는 결과를 나타내 앞뒤 관계와 맞지 않습니다 ✗"]},{"id":"G342","q":"En cuanto pueda, me mudaré a ____ casa.","o":["otro","el otro","una otra","otra"],"a":3,"k":"otro/otra 관사 없음","t":"할 수 있게 되면 바로 다른 집으로 이사할 거예요.","e":"otro(다른)는 앞에 부정관사 un/una를 붙이지 않습니다. 'una otra casa'가 아니라 'otra casa'라고 해야 합니다. casa는 여성 명사이므로 otra가 맞습니다.","x":["otro: 남성형이라 여성 명사 casa와 맞지 않습니다 ✗","el otro: 남성 관사와 남성형이라 성이 맞지 않고, 정해진 '그 다른 집'이라는 뜻이 됩니다 ✗","una otra: otro 앞에는 부정관사를 쓰지 않으므로 틀립니다 ✗","otra: 여성형으로 'otra casa(다른 집)'가 됩니다 ✓"]},{"id":"G343","q":"Ayer ____ tanta gente en el banco que decidí volver otro día.","o":["ha habido","había","hay","hubo"],"a":1,"k":"불완료과거 había","t":"어제 은행에 사람이 너무 많아서 다른 날 다시 가기로 했어요.","e":"과거의 상황이나 배경(사람이 많았다)을 묘사할 때는 불완료과거를 씁니다. haber의 존재 표현(~이 있다)은 불완료과거로 había입니다. 그 상황 속에서 일어난 행동(decidí)은 단순과거로 씁니다.","x":["ha habido: 현재완료라 ayer(어제)와 함께 쓰기 어렵습니다(스페인 기준) ✗","había: 과거의 배경 상황을 묘사하는 불완료과거로 정답입니다 ✓","hay: 현재형이라 ayer와 시제가 맞지 않습니다 ✗","hubo: 단순과거로 완결된 사건을 나타내며, 이유가 되는 배경 묘사에는 había가 더 자연스럽습니다 ✗"]},{"id":"G344","q":"Irene es ____ chica más simpática de mi clase.","o":["ø","el","la","una"],"a":2,"k":"최상급 정관사","t":"이레네는 우리 반에서 가장 상냥한 여자아이예요.","e":"최상급(가장 ~한)은 '정관사 + 명사 + más + 형용사 + de'로 씁니다. chica는 여성 명사이므로 정관사 la를 씁니다: la chica más simpática de mi clase.","x":["ø: 최상급에서는 정관사가 꼭 필요합니다 ✗","el: 남성 관사라 여성 명사 chica와 맞지 않습니다 ✗","la: 최상급을 만드는 여성 정관사로 정답입니다 ✓","una: 부정관사는 최상급(가장 ~한)을 만들 수 없습니다 ✗"]},{"id":"G345","q":"Hoy necesito ____ salir de casa un poco antes.","o":["a","por","de","ø"],"a":3,"k":"necesitar + 동사원형","t":"오늘은 집에서 조금 일찍 나가야 해요.","e":"necesitar(필요하다)는 뒤에 바로 동사원형을 씁니다. 전치사가 필요 없어 'necesito salir(나가야 한다)'가 됩니다. 비교: 'tener que + 동사원형'은 que가 필요합니다.","x":["a: necesitar 뒤에는 전치사 a가 오지 않습니다 ✗","por: 'necesitar por'라는 구조는 없습니다 ✗","de: necesitar는 동사원형 앞에 de를 쓰지 않습니다(명사 앞에서 드물게 사용) ✗","ø: 전치사 없이 바로 동사원형을 써서 'necesito salir'가 됩니다 ✓"]},{"id":"G346","q":"¿____ si pasamos por el estanco antes de ir a casa?","o":["Te importas","Importas","A ti importa","Te importa"],"a":3,"k":"¿Te importa si…?","t":"집에 가기 전에 담배 가게에 들러도 괜찮아?","e":"importar(신경 쓰이다)는 gustar처럼 사람을 간접목적격 대명사로 씁니다. '¿Te importa si ~?'는 '~해도 괜찮아?'라는 정중한 부탁 표현입니다. 참고로 estanco는 스페인에서 담배·우표 등을 파는 가게를 말합니다.","x":["Te importas: importar는 재귀형으로 쓰지 않고 3인칭 단수 importa를 씁니다 ✗","Importas: '네가 중요하다'라는 뜻이 되어 맞지 않습니다 ✗","A ti importa: 대명사 te가 빠져 틀립니다(A ti te importa라면 가능) ✗","Te importa: '너에게 신경 쓰이니?'로 '~해도 괜찮아?'라는 표현이 됩니다 ✓"]},{"id":"G347","q":"____ haría muy feliz que vinieras a mi boda.","o":["Me","A mí","Yo","Para mí"],"a":0,"k":"간접목적격 대명사 me","t":"네가 내 결혼식에 와 준다면 나는 정말 행복할 거야.","e":"이 문장의 주어는 'que vinieras a mi boda(네가 결혼식에 오는 것)'이고, 그것이 '나를' 행복하게 만듭니다. 그래서 '나'는 목적격 대명사 me로 동사 앞에 옵니다: Me haría muy feliz.","x":["Me: '나를'이라는 목적격 대명사로 'Me haría feliz(나를 행복하게 할 것이다)'가 됩니다 ✓","A mí: 강조 표현으로 대명사 me와 함께 써야 하며 단독으로는 틀립니다 ✗","Yo: 주어 형태인데 이 문장의 주어는 que절이라 맞지 않습니다 ✗","Para mí: '나에게는'이라는 의견 표현이라 haría의 목적어 역할을 못 합니다 ✗"]},{"id":"G348","q":"¿____ es tu libro preferido?","o":["Quién","Qué","Dónde","Cuál"],"a":3,"k":"cuál + ser","t":"네가 가장 좋아하는 책은 뭐야?","e":"'ser 동사 + 명사' 앞에서 여러 개 중 하나를 물을 때는 cuál을 씁니다. '¿Cuál es tu libro preferido?'처럼 정해진 범위 안에서 '어느 것'을 묻습니다. qué는 명사 바로 앞이나 정의를 물을 때(¿Qué es esto?) 씁니다.","x":["Quién: '누구'라는 사람을 묻는 말이라 libro(책)와 맞지 않습니다 ✗","Qué: 'Qué es ~'는 '무엇인가(정의)'를 물어 좋아하는 책을 고르는 질문에 맞지 않습니다 ✗","Dónde: '어디'라는 장소를 묻는 말이라 맞지 않습니다 ✗","Cuál: 'Cuál es ~'로 여러 중 하나를 묻는 표현이라 정답입니다 ✓"]},{"id":"G349","q":"A Berta ____ duele la cabeza con bastante frecuencia.","o":["ø","le","la","se la"],"a":1,"k":"doler 구문","t":"베르타는 꽤 자주 머리가 아파요.","e":"doler(아프다)는 gustar처럼 아픈 부위가 주어이고, 아픈 사람은 간접목적격 대명사로 씁니다. 'A Berta(베르타에게)'는 3인칭 단수이므로 le를 써서 'le duele la cabeza'가 됩니다.","x":["ø: 'a + 사람'이 있어도 간접목적격 대명사 le가 꼭 필요합니다 ✗","le: 3인칭 단수 간접목적격 대명사로 정답입니다 ✓","la: 직접목적격 대명사(그녀를)라 doler 구문에 쓰지 않습니다 ✗","se la: 대명사가 불필요하게 두 개 들어간 틀린 형태입니다 ✗"]},{"id":"G350","q":"El jefe no ____ de la fábrica hasta que hayan salido todos los empleados.","o":["vaya","irse","se va","va"],"a":2,"k":"irse + hasta que","t":"사장님은 직원들이 모두 나갈 때까지 공장을 떠나지 않아요.","e":"irse(떠나다)는 재귀동사로 'irse de + 장소(~에서 떠나다)'로 씁니다. 사장님의 평소 습관을 말하므로 직설법 현재 'no se va'가 맞습니다. 뒤의 'hasta que' 다음에는 아직 일어나지 않은 미래 일이라 접속법(hayan salido)을 씁니다.","x":["vaya: 접속법이라 습관을 말하는 주절에 쓰지 않습니다 ✗","irse: 동사원형이라 주어 el jefe에 맞게 활용해야 합니다 ✗","se va: irse의 3인칭 단수 현재형으로 '떠나다'가 됩니다 ✓","va: se가 없으면 '가다'라는 뜻이 되어 'de la fábrica(공장에서)'와 맞지 않습니다 ✗"]},{"id":"G351","q":"No recuerdo lo que pasó ____ noche.","o":["aquellas","aquellos","aquella","aquel"],"a":2,"k":"지시형용사 aquella","t":"그날 밤 무슨 일이 있었는지 기억나지 않아요.","e":"시간적으로 멀리 떨어진 과거(그날 밤)를 가리킬 때는 aquel/aquella를 씁니다. noche는 여성 단수 명사이므로 aquella noche가 됩니다. 예: aquel día(그날), aquella época(그 시절)","x":["aquellas: 여성 복수형이라 단수 명사 noche와 수가 맞지 않습니다 ✗","aquellos: 남성 복수형이라 성과 수가 모두 맞지 않습니다 ✗","aquella: 여성 단수 지시형용사로 'aquella noche(그날 밤)'가 됩니다 ✓","aquel: 남성 단수형이라 여성 명사 noche와 맞지 않습니다 ✗"]},{"id":"G352","q":"Todas ____ amigas de mi madre son simpatiquísimas.","o":["ø","las","la","unas"],"a":1,"k":"todos + 관사","t":"우리 엄마 친구분들은 모두 정말 상냥해요.","e":"'todo/toda(모든)' 뒤에 명사가 올 때는 보통 정관사를 함께 씁니다: todos los días(매일), todas las amigas(모든 친구들). amigas가 여성 복수이므로 las가 맞습니다.","x":["ø: 'todas amigas'처럼 관사를 빼면 틀립니다 ✗","las: 여성 복수 정관사로 'todas las amigas(모든 친구들)'가 됩니다 ✓","la: 단수형이라 복수 명사 amigas와 맞지 않습니다 ✗","unas: todos 뒤에는 부정관사를 쓰지 않습니다 ✗"]},{"id":"G353","q":"____ no he decidido dónde voy a pasar mis próximas vacaciones.","o":["Ya","Normalmente","Todavía","Cuando"],"a":2,"k":"todavía no","t":"다음 휴가를 어디서 보낼지 아직 정하지 못했어요.","e":"'아직 ~하지 않았다'는 'todavía no + 동사'로 씁니다. 문장에 이미 no가 있으므로 앞에 Todavía를 넣으면 'Todavía no he decidido(아직 정하지 않았다)'가 됩니다. 같은 뜻으로 'Aún no'도 씁니다.","x":["Ya: 'Ya no'는 '더 이상 ~않다'라는 뜻이라 문맥과 맞지 않습니다 ✗","Normalmente: '보통'이라는 뜻으로 현재완료 he decidido와 의미가 어울리지 않습니다 ✗","Todavía: 'Todavía no(아직 ~않다)'를 만들어 정답입니다 ✓","Cuando: '~할 때'라는 접속사라 뒤에 주절이 필요해 문장이 완성되지 않습니다 ✗"]},{"id":"G354","q":"¿____ ropa vais a poneros para ir a la ceremonia?","o":["Qué","Cómo","Quién","Cuáles"],"a":0,"k":"qué + 명사","t":"너희 그 행사에 어떤 옷 입고 갈 거야?","e":"명사(ropa) 바로 앞에서 '어떤 ~'을 물을 때는 qué를 씁니다. 'Qué ropa(어떤 옷)'가 됩니다. ponerse(입다)의 vosotros 형태 poneros는 스페인에서 쓰고, 중남미에서는 '¿Qué ropa se van a poner?'라고 합니다.","x":["Qué: 명사 ropa 앞에서 '어떤'이라는 뜻으로 정답입니다 ✓","Cómo: '어떻게'라는 뜻이라 명사 앞에 올 수 없습니다 ✗","Quién: '누구'라는 사람을 묻는 말이라 맞지 않습니다 ✗","Cuáles: 복수 대명사로 명사 앞에 직접 쓰지 않고 ropa는 단수입니다 ✗"]},{"id":"G355","q":"El anciano desapareció hace tres días. ____ lo ha visto desde entonces.","o":["Nadie","Algún","Ningunos","Alguien"],"a":0,"k":"부정어 nadie","t":"그 노인은 3일 전에 실종됐어요. 그 이후로 아무도 그를 보지 못했어요.","e":"nadie는 '아무도 (~않다)'라는 뜻의 부정 대명사입니다. 동사 앞에 nadie가 오면 따로 no를 쓰지 않습니다: Nadie lo ha visto. 동사 뒤에 올 때는 no가 필요해요(No lo ha visto nadie).","x":["Nadie: '아무도'라는 뜻으로 '아무도 그를 보지 못했다'가 됩니다 ✓","Algún: 형용사라 뒤에 명사가 필요하고 의미도 맞지 않습니다 ✗","Ningunos: ninguno는 보통 복수로 쓰지 않으며 명사도 없어 틀립니다 ✗","Alguien: '누군가'라는 긍정의 뜻이라 실종된 상황의 문맥과 맞지 않습니다 ✗"]},{"id":"G356","q":"¿Tienes ____ bolígrafo azul?","o":["otro","otros","uno otro","un otro"],"a":0,"k":"otro (관사 없음)","t":"파란색 볼펜 하나 더 있어?","e":"otro(다른, 또 하나의)는 앞에 un을 붙이지 않습니다. bolígrafo는 남성 단수이므로 'otro bolígrafo'가 맞습니다. 'un otro'는 영어 another를 직역한 흔한 실수입니다.","x":["otro: 남성 단수 명사 bolígrafo 앞에 관사 없이 쓰는 올바른 형태입니다 ✓","otros: 복수형이라 단수 명사 bolígrafo와 맞지 않습니다 ✗","uno otro: 이런 형태는 쓰지 않습니다 ✗","un otro: otro 앞에는 부정관사 un을 쓰지 않습니다 ✗"]},{"id":"G357","q":"¿____ es ese hombre? No lo conozco.","o":["Cuál","De quién","Qué","Quién"],"a":3,"k":"의문사 quién","t":"저 남자 누구예요? 저는 모르는 사람이에요.","e":"사람의 정체(누구인지)를 물을 때는 quién을 씁니다. '¿Quién es ese hombre?(저 남자는 누구야?)'가 됩니다. 뒤의 'No lo conozco(나는 그를 모른다)'가 힌트입니다.","x":["Cuál: 정해진 범위 중 '어느 것'을 물을 때 써서 사람의 정체를 묻기에는 맞지 않습니다 ✗","De quién: '누구의 것'이라는 소유를 묻는 말이라 의미가 다릅니다 ✗","Qué: 사람에게 쓰면 직업 등을 묻는 어색한 질문이 됩니다 ✗","Quién: 사람이 누구인지 묻는 의문사로 정답입니다 ✓"]},{"id":"G358","q":"Si ____ buen tiempo, podemos dar una vuelta por el parque.","o":["haría","haga","hace","hará"],"a":2,"k":"si + 직설법 현재","t":"날씨가 좋으면 공원에 산책하러 갈 수 있어요.","e":"실현 가능한 조건 '~하면'은 'Si + 직설법 현재'로 씁니다. 날씨 표현 'hacer buen tiempo(날씨가 좋다)'를 현재형으로 써서 'Si hace buen tiempo'가 됩니다. si 바로 뒤에는 미래형·조건법·접속법 현재를 쓰지 않습니다.","x":["haría: 조건법이라 si 바로 뒤에 쓰지 않습니다 ✗","haga: 접속법 현재는 si 조건문에 쓰지 않습니다 ✗","hace: 직설법 현재로 'Si hace buen tiempo(날씨가 좋으면)'가 됩니다 ✓","hará: 미래형은 si 바로 뒤에 쓰지 않습니다 ✗"]},{"id":"G359","q":"En Estados Unidos ____ muchas personas que hablan español.","o":["hay","son","están","ser"],"a":0,"k":"존재의 hay","t":"미국에는 스페인어를 말하는 사람이 많아요.","e":"'~이 있다(존재)'는 haber의 hay를 씁니다. hay는 단수·복수 상관없이 형태가 같습니다(hay un libro, hay muchas personas). 정해지지 않은 사람·사물이 있다고 할 때 씁니다.","x":["hay: 존재를 나타내 'hay muchas personas(많은 사람이 있다)'가 됩니다 ✓","son: ser는 '~이다'라는 뜻이라 존재를 나타내지 못합니다 ✗","están: estar는 정해진 대상의 위치에 쓰여 'muchas personas'와 어울리지 않습니다 ✗","ser: 동사원형이고 존재의 의미도 아닙니다 ✗"]},{"id":"G360","q":"____ los pies desde la semana pasada.","o":["Me duelen","Me duelo","Duelo","Duelen"],"a":0,"k":"doler 구문","t":"지난주부터 발이 아파요.","e":"doler(아프다)는 아픈 부위가 주어이므로 los pies(복수)에 맞춰 duelen을 씁니다. 아픈 사람(나)은 간접목적격 대명사 me로 나타냅니다: Me duelen los pies.","x":["Me duelen: 복수 주어 los pies에 맞춘 doler 구문으로 정답입니다 ✓","Me duelo: '내가 아프다'처럼 사람을 주어로 쓴 잘못된 형태입니다 ✗","Duelo: 1인칭 형태라 doler 구문에 맞지 않고 me도 빠졌습니다 ✗","Duelen: 누가 아픈지 나타내는 대명사 me가 빠졌습니다 ✗"]},{"id":"G361","q":"¿Has estado en Chile ____ vez?","o":["ninguna","algún","alguno","alguna"],"a":3,"k":"alguna vez","t":"칠레에 가 본 적 있어요?","e":"'~해 본 적 있어?'라고 경험을 물을 때는 'alguna vez(한 번이라도)'를 씁니다. vez는 여성 명사라 alguna가 됩니다. 부정 대답은 'nunca' 또는 'ninguna vez'를 씁니다.","x":["ninguna: '한 번도 (~않다)'라는 부정어라 경험을 묻는 질문에 맞지 않습니다 ✗","algún: 남성형이라 여성 명사 vez와 맞지 않습니다 ✗","alguno: 명사 앞에서 쓰지 않는 형태이고 성도 맞지 않습니다 ✗","alguna: 'alguna vez(한 번이라도)'로 경험을 묻는 표현이 됩니다 ✓"]},{"id":"G362","q":"Mi hermano se olvidó ____ mi cumpleaños, es muy despistado.","o":["con","de","ø","por"],"a":1,"k":"olvidarse de","t":"우리 오빠는 내 생일을 잊어버렸어요, 정말 덜렁거려요.","e":"olvidar(잊다)는 두 가지로 씁니다: 'olvidar algo' 또는 재귀형 'olvidarse de algo'. 문장에 se가 있으므로 전치사 de가 꼭 필요해 'se olvidó de mi cumpleaños'가 됩니다.","x":["con: olvidarse와 함께 쓰지 않는 전치사입니다 ✗","de: 'olvidarse de(~을 잊다)'의 고정 전치사로 정답입니다 ✓","ø: 재귀형 olvidarse에는 de가 필요합니다(se 없이 olvidó라면 가능) ✗","por: olvidarse와 함께 쓰지 않습니다 ✗"]},{"id":"G363","q":"Tenéis que ____ las manos antes de las comidas.","o":["lavaros","os laváis","lavarse","laváis"],"a":0,"k":"재귀동사 원형 lavaros","t":"너희는 식사 전에 손을 씻어야 해.","e":"'tener que + 동사원형' 뒤의 재귀동사는 주어에 맞는 재귀대명사를 원형 뒤에 붙입니다. 주어가 vosotros(tenéis)이므로 lavarse → lavaros가 됩니다(-r 뒤 os). 중남미에서는 ustedes를 써서 'Tienen que lavarse las manos'라고 합니다.","x":["lavaros: vosotros에 맞는 재귀대명사 os를 원형에 붙인 올바른 형태입니다 ✓","os laváis: tener que 뒤에는 활용형이 아닌 동사원형이 와야 합니다 ✗","lavarse: se는 3인칭(그/그들/ustedes)에 쓰여 tenéis(너희)와 맞지 않습니다 ✗","laváis: 활용형이고 재귀대명사도 없어 틀립니다 ✗"]},{"id":"G364","q":"Cuando ____ pequeña vivía en otro barrio.","o":["había sido","era","he sido","fui"],"a":1,"k":"불완료과거 era","t":"어렸을 때 저는 다른 동네에 살았어요.","e":"과거의 나이나 시기, 상태(어렸을 때)를 묘사할 때는 불완료과거를 씁니다. 'Cuando era pequeña(내가 어렸을 때)'는 아주 자주 쓰는 표현입니다. 뒤의 vivía도 과거의 지속 상황을 나타내는 불완료과거입니다.","x":["había sido: 과거완료라 과거 시기를 묘사하는 데 맞지 않습니다 ✗","era: ser의 불완료과거로 과거의 시기·상태를 나타내 정답입니다 ✓","he sido: 현재완료라 과거 어린 시절 묘사에 쓰지 않습니다 ✗","fui: 단순과거로 완결된 사건에 쓰여 배경 묘사에 어울리지 않습니다 ✗"]},{"id":"G365","q":"Estos lápices son ____ Lucía.","o":["de","a","con","desde"],"a":0,"k":"소유의 de","t":"이 연필들은 루시아 거예요.","e":"'ser de + 사람'은 '~의 것이다'라는 소유를 나타냅니다. 'Estos lápices son de Lucía(이 연필들은 루시아 것이다)'가 됩니다. 예: El coche es de mi padre.(그 차는 아빠 것이다.)","x":["de: 'ser de + 사람'으로 소유를 나타내 정답입니다 ✓","a: '~에게'라는 뜻이라 소유를 나타내지 않습니다 ✗","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗","desde: '~부터'라는 시작점을 나타내 의미가 맞지 않습니다 ✗"]},{"id":"G366","q":"Hoy tengo que trabajar ____ mediodía, por eso no puedo verte antes.","o":["después de la","hasta el","después","hasta la"],"a":1,"k":"hasta el mediodía","t":"오늘은 정오까지 일해야 해서 그 전에는 너를 볼 수 없어.","e":"hasta는 '~까지'라는 끝나는 시점을 나타냅니다. mediodía(정오)는 남성 명사이므로 'hasta el mediodía'가 됩니다. 뒤의 '그 전에는 볼 수 없다'로 보아 '~까지 일한다'는 뜻이 맞습니다.","x":["después de la: '~후에'라는 뜻이라 문맥과 반대이고 la도 성이 맞지 않습니다 ✗","hasta el: '정오까지'로 정답입니다 ✓","después: de가 빠져 명사 앞에 쓸 수 없고 의미도 맞지 않습니다 ✗","hasta la: mediodía는 남성 명사라 la를 쓸 수 없습니다 ✗"]},{"id":"G367","q":"Tengo ____ problemas económicos.","o":["mucho","muchos","mucha","muchas"],"a":1,"k":"mucho 성·수 일치","t":"저는 경제적인 문제가 많아요.","e":"명사 앞의 mucho(많은)는 명사와 성·수를 맞춥니다. problemas는 -a로 끝나지만 남성 명사(el problema)의 복수이므로 muchos가 됩니다. 같은 예: el tema → muchos temas, el día → muchos días","x":["mucho: 단수형이라 복수 명사 problemas와 맞지 않습니다 ✗","muchos: 남성 복수 명사 problemas와 일치하는 형태입니다 ✓","mucha: 여성 단수형이라 성·수 모두 맞지 않습니다 ✗","muchas: problema를 여성 명사로 착각한 오답입니다 ✗"]},{"id":"G368","q":"Anoche mi marido ____ una cena riquísima.","o":["hizo","hacía","ha hecho","hice"],"a":0,"k":"단순과거 hizo","t":"어젯밤 남편이 정말 맛있는 저녁을 만들어 줬어요.","e":"anoche(어젯밤)처럼 끝난 과거 시점에 한 번 일어난 완결된 행동은 단순과거로 씁니다. hacer의 3인칭 단수 단순과거는 불규칙형 hizo입니다(z에 주의).","x":["hizo: hacer의 3인칭 단수 단순과거로 정답입니다 ✓","hacía: 불완료과거라 습관이나 배경을 나타내 어젯밤 한 번의 행동에 맞지 않습니다 ✗","ha hecho: 현재완료라 anoche와 함께 쓰지 않습니다(스페인 기준) ✗","hice: 1인칭 단수(나) 형태라 주어 mi marido와 맞지 않습니다 ✗"]},{"id":"G369","q":"Quiero que me ____ cuando te hablo.","o":["escuchar","escuchas","escuches","escucháis"],"a":2,"k":"querer que + 접속법","t":"내가 말할 때는 내 말을 들어 줬으면 좋겠어.","e":"'querer que + 다른 주어'는 상대에게 바라는 것이므로 que 뒤에 접속법(바람을 나타내는 동사 형태)을 씁니다. escuchar의 tú 접속법 현재는 escuches입니다. 뒤의 'te hablo'로 보아 상대는 tú입니다.","x":["escuchar: 동사원형이라 que 뒤에 다른 주어가 올 때 쓸 수 없습니다 ✗","escuchas: 직설법이라 바람을 나타내는 querer que 뒤에 맞지 않습니다 ✗","escuches: tú 접속법 현재로 정답입니다 ✓","escucháis: 직설법이고 vosotros 형태라 te(너)와도 맞지 않습니다 ✗"]},{"id":"G370","q":"¿Dónde has puesto ____ carpetas de los alumnos de 1º?","o":["las","a las","a","ø"],"a":0,"k":"정관사 las","t":"1학년 학생들 파일 어디에 뒀어요?","e":"poner(놓다)의 직접목적어인 carpetas(파일들)는 사물이므로 전치사 a가 필요 없습니다. 특정한 '1학년 학생들의 파일'을 가리키므로 정관사 las를 씁니다. 1º는 primero(1학년)를 줄여 쓴 것입니다.","x":["las: 특정한 사물을 가리키는 여성 복수 정관사로 정답입니다 ✓","a las: 사물 목적어 앞에는 전치사 a를 쓰지 않습니다 ✗","a: 사물 목적어에 a를 쓰지 않고 관사도 빠졌습니다 ✗","ø: 특정한 파일들을 가리키므로 정관사가 필요합니다 ✗"]},{"id":"G371","q":"____ temas son complicados.","o":["Esta","Estos","Estas","Este"],"a":1,"k":"지시형용사 estos","t":"이 주제들은 복잡해요.","e":"지시형용사는 명사의 성·수에 맞춥니다. temas는 -a로 끝나지만 남성 명사(el tema)의 복수이므로 estos가 됩니다. 뒤의 complicados(남성 복수)도 힌트입니다.","x":["Esta: 여성 단수형이라 성·수 모두 맞지 않습니다 ✗","Estos: 남성 복수형으로 'estos temas(이 주제들)'가 됩니다 ✓","Estas: tema를 여성으로 착각한 오답입니다 ✗","Este: 단수형이라 복수 명사 temas와 맞지 않습니다 ✗"]},{"id":"G372","q":"Antes la gente en España tenía más hijos ____ ahora.","o":["como","que","de","en cuanto"],"a":1,"k":"비교급 más ~ que","t":"예전에 스페인 사람들은 지금보다 아이를 더 많이 낳았어요.","e":"'~보다 더 많이'는 'más + 명사 + que'로 씁니다. 'más hijos que ahora(지금보다 더 많은 자녀)'처럼 비교 대상이 시간 부사여도 que를 씁니다.","x":["como: 동등 비교(tan/tanto ~ como)에 쓰여 más와 짝이 맞지 않습니다 ✗","que: 'más ~ que'의 짝으로 정답입니다 ✓","de: 'más de'는 숫자 앞에서만(más de tres) 씁니다 ✗","en cuanto: '~하자마자'라는 뜻이라 비교와 관계없습니다 ✗"]},{"id":"G373","q":"Si no ____ las lentejas, no tomarás postre.","o":["tú comes","te comes","comes","te comen"],"a":1,"k":"comerse (다 먹다)","t":"렌틸콩을 다 먹지 않으면 디저트는 없어.","e":"comer에 재귀대명사를 붙인 comerse는 '(정해진 양을) 다 먹어 치우다'라는 완결의 뉘앙스를 줍니다. '렌틸콩(그 접시)을 다 먹지 않으면'이라는 뜻이라 'te comes'가 가장 자연스럽습니다. 일상에서 'Si no comes las lentejas'도 쓰이지만, 교재는 '다 먹다'의 뉘앙스를 묻고 있습니다.","x":["tú comes: 주어 tú를 굳이 넣어 강조할 이유가 없고 '다 먹다'의 뉘앙스도 없습니다 ✗","te comes: comerse로 '(그 렌틸콩을) 다 먹다'라는 뜻이 되어 정답입니다 ✓","comes: 문법적으로 가능하지만 '다 먹다'라는 완결의 뉘앙스가 약해 교재 정답이 아닙니다 ✗","te comen: '그들이 너를 먹는다'라는 뜻이 되어 의미가 이상합니다 ✗"]},{"id":"G374","q":"No sé ____ es ese hombre que está junto a la puerta.","o":["dónde","cuánto","de quién","quién"],"a":3,"k":"간접의문문 quién","t":"문 옆에 있는 저 남자가 누군지 모르겠어요.","e":"'No sé + 의문사'는 간접 의문문(~인지 모르다)입니다. 사람의 정체를 묻는 내용이므로 quién을 씁니다. 간접 의문문에서도 의문사에 악센트(é)를 붙입니다.","x":["dónde: '어디'를 묻는 말인데 위치(junto a la puerta)는 이미 나와 있습니다 ✗","cuánto: '얼마'를 묻는 말이라 사람에 대한 문장과 맞지 않습니다 ✗","de quién: '누구의 것'이라는 소유를 묻는 말이라 의미가 다릅니다 ✗","quién: 사람이 누구인지 묻는 의문사로 정답입니다 ✓"]},{"id":"G375","q":"Margarita ya no ____ a nuestro lado. ¿Qué le pasa?","o":["sienta","se sienta","se siente","siente"],"a":1,"k":"sentarse vs sentirse","t":"마르가리타가 이제 우리 옆에 앉지 않아요. 무슨 일 있나?","e":"sentarse(앉다)와 sentirse(느끼다)는 헷갈리기 쉬운 재귀동사입니다. '우리 옆에 앉다'는 sentarse로, 3인칭 단수 현재형은 se sienta입니다. sentirse의 3인칭은 se siente(~하게 느끼다)입니다.","x":["sienta: 재귀대명사 se가 없으면 '(누군가를) 앉히다'라는 뜻이 됩니다 ✗","se sienta: sentarse(앉다)의 3인칭 단수로 정답입니다 ✓","se siente: sentirse(느끼다)의 형태라 'a nuestro lado(우리 옆에)'와 의미가 맞지 않습니다 ✗","siente: sentir(느끼다)의 형태라 문맥과 맞지 않습니다 ✗"]},{"id":"G376","q":"¿Cómo prefiere las papas? ¿Fritas ____ en puré?","o":["ni","y","pero","o"],"a":3,"k":"접속사 o","t":"감자는 어떻게 드시겠어요? 튀김으로요, 아니면 으깬 감자로요?","e":"o는 '또는, 아니면'이라는 뜻으로 두 가지 중 하나를 고르게 할 때 씁니다. '튀긴 것 또는 퓌레'를 묻는 선택 질문이므로 o가 맞습니다. 참고로 papas는 중남미와 스페인 카나리아 제도에서 쓰고, 스페인 본토에서는 patatas라고 합니다.","x":["ni: '~도 아니다'라는 부정의 접속사라 선택 질문에 맞지 않습니다 ✗","y: '그리고'라서 둘 다 원하는지 묻는 뜻이 되어 선택 질문과 맞지 않습니다 ✗","pero: '하지만'이라는 대조의 접속사라 의미가 통하지 않습니다 ✗","o: '또는'으로 둘 중 하나를 고르게 하는 접속사입니다 ✓"]},{"id":"G377","q":"Ustedes ____ español con mucha fluidez. ¡Bien hecho!","o":["hablan","hablad","hablen","habláis"],"a":0,"k":"ustedes 동사 활용","t":"여러분은 스페인어를 아주 유창하게 하시네요. 잘했어요!","e":"ustedes(여러분, 당신들)는 의미상 2인칭이지만 동사는 3인칭 복수형으로 활용합니다. 그래서 hablar → hablan이 됩니다. 중남미에서는 '너희들'에도 ustedes를 쓰고, 스페인에서는 친한 사이에 vosotros(habláis)를 씁니다.","x":["hablan: ustedes에 맞는 3인칭 복수 현재형으로 정답입니다 ✓","hablad: vosotros에게 쓰는 명령형이라 맞지 않습니다 ✗","hablen: 접속법(또는 ustedes 명령형)이라 사실을 말하는 문장에 맞지 않습니다 ✗","habláis: vosotros 형태라 ustedes와 맞지 않습니다 ✗"]},{"id":"G378","q":"Estoy harta ____ tus tonterías.","o":["con","para","a","de"],"a":3,"k":"estar harto de","t":"네 바보 같은 짓에 진절머리가 나.","e":"'estar harto/a de ~'는 '~에 질리다, 진절머리가 나다'라는 표현으로 전치사 de를 씁니다. 말하는 사람이 여성이므로 harta입니다. 예: Estoy harto de esperar.(기다리는 데 지쳤어.)","x":["con: 'harto con'은 표준 표현이 아닙니다 ✗","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗","a: 'harto a'라는 표현은 없습니다 ✗","de: 'estar harta de(~에 질리다)'의 고정 전치사입니다 ✓"]},{"id":"G379","q":"¿____ llamas a Fernando a esta hora?","o":["De qué","Para qué","Qué","A qué"],"a":1,"k":"para qué (목적)","t":"이 시간에 페르난도한테 무엇 때문에(왜) 전화하는 거야?","e":"para qué는 '무엇을 위해, 무슨 목적으로'라는 뜻으로 목적을 묻습니다. 이 시간에 전화하는 목적을 묻고 있으므로 para qué가 맞습니다. 이유를 물을 때는 por qué를 씁니다.","x":["De qué: '무엇에 대해'라는 주제를 묻는 말이라 llamar와 어울리지 않습니다 ✗","Para qué: '무슨 목적으로'라는 뜻으로 정답입니다 ✓","Qué: '무엇을'이 되는데 llamar의 목적어는 이미 a Fernando라서 맞지 않습니다 ✗","A qué: 'a qué hora(몇 시에)'처럼 쓰지만 단독으로는 이 문장에 맞지 않습니다 ✗"]},{"id":"G380","q":"¿____ gente hay en tu clase de yoga?","o":["Cuánta","Cuántas","Cuánto","Cuántos"],"a":0,"k":"cuánta + 집합명사","t":"네 요가 수업에는 사람이 몇 명 있어?","e":"gente(사람들)는 뜻은 복수지만 문법적으로는 여성 단수 명사입니다. 그래서 cuánto도 여성 단수형 cuánta를 씁니다. 예: Hay mucha gente.(사람이 많다.)","x":["Cuánta: 여성 단수 명사 gente와 일치하는 형태입니다 ✓","Cuántas: gente는 단수 명사라 복수형을 쓰지 않습니다 ✗","Cuánto: 남성형이라 여성 명사 gente와 맞지 않습니다 ✗","Cuántos: 남성 복수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G381","q":"Últimamente veo ese anuncio en ____ partes.","o":["toda","todo","todos","todas"],"a":3,"k":"en todas partes","t":"요즘 그 광고를 여기저기서 봐요.","e":"'en todas partes'는 '모든 곳에서, 어디서나'라는 고정 표현입니다. partes는 여성 복수 명사이므로 todas가 됩니다. 비슷한 표현으로 'en todos lados'도 있습니다.","x":["toda: 단수형이라 복수 명사 partes와 맞지 않습니다 ✗","todo: 남성 단수형이라 성·수 모두 맞지 않습니다 ✗","todos: 남성 복수형이라 여성 명사 partes와 맞지 않습니다 ✗","todas: 여성 복수형으로 'en todas partes(어디서나)'가 됩니다 ✓"]},{"id":"G382","q":"No encuentro mis zapatillas de deporte, ¿sabes ____ están?","o":["dónde","de dónde","desde dónde","adónde"],"a":0,"k":"dónde + estar","t":"운동화를 못 찾겠어, 어디 있는지 알아?","e":"위치(~에 있다)를 물을 때는 dónde를 씁니다. 'estar(있다)'와 함께 '¿Dónde están?(어디에 있어?)'이 됩니다. 간접 의문문(¿sabes dónde…?)에서도 악센트를 씁니다.","x":["dónde: 위치를 묻는 의문사로 'dónde están(어디 있는지)'이 됩니다 ✓","de dónde: '어디에서(출신·출발점)'라는 뜻이라 위치를 묻는 문장과 맞지 않습니다 ✗","desde dónde: '어디서부터'라는 뜻이라 맞지 않습니다 ✗","adónde: '어디로'라는 방향을 나타내 ir 같은 이동 동사와 씁니다 ✗"]},{"id":"G383","q":"No entendí ____, ¿puede repetir, por favor?","o":["algún","nadie","nada","ningún"],"a":2,"k":"no + nada","t":"아무것도 이해하지 못했어요, 다시 한번 말씀해 주시겠어요?","e":"스페인어는 부정어를 두 번 써도 부정이 유지됩니다(이중 부정). 'No entendí nada'는 '아무것도 이해하지 못했다'입니다. nada는 사물, nadie는 사람에 씁니다.","x":["algún: 긍정의 형용사이고 뒤에 명사가 필요해 맞지 않습니다 ✗","nadie: '아무도'라는 사람을 가리키는 말이라 '이해하다'의 대상과 맞지 않습니다 ✗","nada: '아무것도'라는 뜻으로 'No entendí nada'가 됩니다 ✓","ningún: 뒤에 남성 명사가 와야 하는 형용사라 단독으로 쓸 수 없습니다 ✗"]},{"id":"G384","q":"No sé ____ de ese asunto, te lo digo en serio.","o":["ninguno","algo","nada","alguno"],"a":2,"k":"no saber nada","t":"그 일에 대해서는 아무것도 몰라요, 진심이에요.","e":"'No sé nada de ~'는 '~에 대해 아무것도 모른다'라는 표현입니다. 부정문에서는 algo 대신 nada를 씁니다. 예: No sé nada de él.(그에 대해 아무것도 몰라.)","x":["ninguno: 사람이나 정해진 명사를 받는 말이라 '아무것도'의 뜻이 되지 않습니다 ✗","algo: 긍정문에 쓰는 '무언가'라 부정문에서는 nada로 바꿔야 합니다 ✗","nada: 부정문의 '아무것도'로 정답입니다 ✓","alguno: 긍정의 '어떤 것'이라 부정문과 맞지 않습니다 ✗"]},{"id":"G385","q":"Nunca antes ____ he visto a esas personas.","o":["ø","nadie","ni","no"],"a":0,"k":"nunca + 동사 (no 없음)","t":"전에 그 사람들을 한 번도 본 적이 없어요.","e":"nunca(결코, 한 번도)가 동사 앞에 오면 따로 no를 쓰지 않습니다. 'Nunca antes he visto'로 이미 부정이 완성됩니다. 동사 뒤에 올 때는 no가 필요해요(No he visto nunca).","x":["ø: nunca가 동사 앞에 있어 다른 부정어가 필요 없습니다 ✓","nadie: 목적어가 이미 'a esas personas'라서 넣을 자리가 없습니다 ✗","ni: '~도 아니다'라는 뜻으로 이 구조에서 쓰지 않습니다 ✗","no: 동사 앞 nunca와 no를 겹쳐 쓰지 않습니다 ✗"]},{"id":"G386","q":"Siempre ____ puedo, ayudo económicamente a mis hermanos.","o":["ø","qué","que","como"],"a":2,"k":"siempre que","t":"할 수 있을 때마다 나는 형제들을 경제적으로 도와줘요.","e":"'siempre que'는 '~할 때마다'라는 접속사입니다. 반복되는 습관을 말할 때는 직설법(puedo)을 씁니다. 예: Siempre que viajo, compro un recuerdo.(여행할 때마다 기념품을 산다.)","x":["ø: 접속사 없이 두 문장을 이을 수 없습니다 ✗","qué: 악센트가 있는 qué는 의문사라 접속사로 쓸 수 없습니다 ✗","que: 'siempre que(~할 때마다)'를 만드는 접속사로 정답입니다 ✓","como: 'siempre como'라는 접속 표현은 없습니다 ✗"]},{"id":"G387","q":"Jorge ____ a vivir a Irlanda cuando todavía era un adolescente.","o":["va a irse","se fue","se va","se ha ido"],"a":1,"k":"단순과거 irse","t":"호르헤는 아직 청소년이었을 때 아일랜드로 살러 떠났어요.","e":"과거에 한 번 일어나고 끝난 사건(떠난 일)은 단순과거로 씁니다. irse의 3인칭 단수 단순과거는 se fue입니다. 'irse a vivir a ~'는 '~로 살러 떠나다'라는 자주 쓰는 표현입니다.","x":["va a irse: 미래 계획이라 과거 상황(era un adolescente)과 맞지 않습니다 ✗","se fue: irse의 단순과거로 과거에 완결된 사건을 나타내 정답입니다 ✓","se va: 현재형이라 과거 이야기와 시제가 맞지 않습니다 ✗","se ha ido: 현재완료라 먼 과거(청소년 시절) 사건에 맞지 않습니다 ✗"]},{"id":"G388","q":"¿Cuándo ____ a los padres de tu novia?","o":["estás conociendo","conoces","estabas conociendo","conociste"],"a":3,"k":"단순과거 conocer","t":"여자 친구 부모님은 언제 처음 만났어?","e":"conocer는 단순과거로 쓰면 '처음 알게 되다, 처음 만나다'라는 뜻입니다. 과거의 특정 시점을 묻는 질문이므로 tú 단순과거형 conociste가 맞습니다.","x":["estás conociendo: 현재진행형이라 '언제 처음 만났는지' 묻는 과거 질문과 맞지 않습니다 ✗","conoces: 현재형으로 '알고 있다'는 뜻이라 언제 만났는지 묻는 데 어색합니다 ✗","estabas conociendo: 과거진행형이라 한 번의 만남을 나타내기에 부적절합니다 ✗","conociste: 단순과거로 '처음 만났다'라는 완결된 사건을 나타냅니다 ✓"]},{"id":"G389","q":"¿____ son tus compañeros de clase?","o":["Esto","Estos","Estas","Esta"],"a":1,"k":"지시대명사 estos","t":"이 사람들이 네 반 친구들이야?","e":"지시대명사는 가리키는 대상의 성·수에 맞춥니다. compañeros(친구들)는 남성 복수이므로 estos가 됩니다. esto는 중성으로, 정체를 모르는 사물(¿Qué es esto?)에만 씁니다.","x":["Esto: 중성 지시대명사라 사람이나 복수 명사를 가리키지 않습니다 ✗","Estos: 남성 복수형으로 compañeros를 가리켜 정답입니다 ✓","Estas: 여성 복수형이라 남성 명사 compañeros와 맞지 않습니다 ✗","Esta: 여성 단수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G390","q":"Ayer tuve ____ día muy estresante.","o":["uno","un","una","ø"],"a":1,"k":"부정관사 un","t":"어제 정말 스트레스 많은 하루를 보냈어요.","e":"día(날)는 -a로 끝나지만 남성 명사입니다. 셀 수 있는 단수 명사가 형용사의 꾸밈을 받아 '어떤 ~한 날'이 될 때는 부정관사를 씁니다. 그래서 'un día muy estresante'가 됩니다.","x":["uno: 명사 앞에서는 un으로 줄여 써야 합니다 ✗","un: 남성 단수 명사 día 앞의 부정관사로 정답입니다 ✓","una: día를 여성 명사로 착각한 오답입니다 ✗","ø: 형용사가 붙은 단수 명사 앞에서 관사를 빼면 어색합니다 ✗"]},{"id":"G391","q":"Buscamos ____ nuevo guitarrista para nuestro grupo.","o":["un","una","uno","por un"],"a":0,"k":"부정관사 un","t":"우리 밴드에 새 기타리스트를 찾고 있어요.","e":"아직 정해지지 않은 '어떤 기타리스트'를 찾으므로 부정관사를 씁니다. guitarrista는 남녀 공용 명사지만 여기서는 nuevo(남성형)가 쓰였으므로 un이 맞습니다. 또 정해지지 않은 사람 목적어 앞에는 보통 인칭 a를 쓰지 않습니다.","x":["un: 남성 단수 부정관사로 nuevo와 일치해 정답입니다 ✓","una: nuevo가 남성형이라 성이 맞지 않습니다(여성이면 una nueva) ✗","uno: 명사 앞에서는 un으로 줄여 써야 합니다 ✗","por un: buscar는 전치사 없이 바로 목적어를 받습니다 ✗"]},{"id":"G392","q":"____ señora López está en su oficina.","o":["Las","ø","El","La"],"a":3,"k":"señora + 정관사","t":"로페스 부인은 사무실에 계세요.","e":"señor, señora, doctor 같은 호칭이 이름 앞에 오고 그 사람에 대해 말할 때는 정관사를 붙입니다: la señora López. 단, 그 사람에게 직접 말을 걸 때는 관사를 빼요(Buenos días, señora López).","x":["Las: 복수형이라 한 사람을 가리키지 못합니다 ✗","ø: 3인칭으로 그 사람에 대해 말할 때는 관사가 필요합니다 ✗","El: 남성 관사라 여성 호칭 señora와 맞지 않습니다 ✗","La: 여성 정관사로 'la señora López'가 됩니다 ✓"]},{"id":"G393","q":"¿Es verdad que ____ te peleaste con Aitor?","o":["luego","después","antiguamente","anoche"],"a":3,"k":"anoche + 단순과거","t":"어젯밤에 아이토르랑 싸웠다는 게 사실이야?","e":"te peleaste는 단순과거(완결된 과거 행동)이므로 과거의 특정 시점을 나타내는 anoche(어젯밤)와 잘 어울립니다. pelearse con은 '~와 싸우다'라는 뜻입니다.","x":["luego: '나중에, 그다음에'라는 뜻이라 단독으로 과거 시점을 나타내지 못합니다 ✗","después: '그 후에'라는 뜻으로 기준이 되는 일이 없어 어색합니다 ✗","antiguamente: '옛날에'라는 뜻으로 오래전의 습관에 쓰여 맞지 않습니다 ✗","anoche: '어젯밤'으로 단순과거와 어울려 정답입니다 ✓"]},{"id":"G394","q":"Antes ____ la moda, ahora no me interesa en absoluto.","o":["me estuvo interesando","me ha interesado","me interesaba","me estaba interesando"],"a":2,"k":"불완료과거 (예전 상태)","t":"예전에는 패션에 관심이 있었는데 지금은 전혀 관심이 없어요.","e":"'Antes ~, ahora ~(예전엔 ~, 지금은 ~)' 구조에서 과거의 지속적인 상태나 습관은 불완료과거로 씁니다. interesar의 3인칭 단수 불완료과거는 interesaba이고, gustar처럼 me를 함께 씁니다.","x":["me estuvo interesando: 단순과거 진행형으로 정해진 기간을 나타내 예전의 일반적 상태에 맞지 않습니다 ✗","me ha interesado: 현재완료라 '지금은 아니다'라는 대조와 맞지 않습니다 ✗","me interesaba: 과거의 지속적 상태를 나타내는 불완료과거로 정답입니다 ✓","me estaba interesando: 과거진행형으로 특정 순간의 진행을 나타내 맞지 않습니다 ✗"]},{"id":"G395","q":"Marcelo, ____ tu habitación ahora mismo.","o":["ordene","ordenes","ordenas","ordena"],"a":3,"k":"tú 긍정 명령형","t":"마르셀로, 지금 당장 네 방 정리해.","e":"친구나 가족(tú)에게 하는 긍정 명령은 직설법 현재 3인칭 단수와 같은 형태입니다: ordenar → ordena. 'tu habitación(네 방)'으로 보아 tú에게 말하고 있습니다. 부정 명령은 접속법을 써서 'No ordenes'가 됩니다.","x":["ordene: usted(당신)에게 하는 명령형이라 tu와 맞지 않습니다 ✗","ordenes: 접속법 형태로 부정 명령(no ordenes)에만 씁니다 ✗","ordenas: 직설법 현재로 '너는 정리한다'라는 서술문이 됩니다 ✗","ordena: tú 긍정 명령형으로 정답입니다 ✓"]},{"id":"G396","q":"Tengo ____ manos sucias, voy a lavármelas.","o":["ø","mis","las","los"],"a":2,"k":"신체 부위 + 정관사","t":"손이 더러워서 씻으러 갈게요.","e":"스페인어에서는 신체 부위를 말할 때 소유형용사(mis) 대신 정관사를 씁니다. 누구의 손인지는 동사(tengo)로 이미 알 수 있기 때문입니다. manos는 -o로 끝나지만 여성 명사(la mano)라 las를 씁니다.","x":["ø: 관사 없이 'tengo manos sucias'라고 하면 어색합니다 ✗","mis: 신체 부위에는 보통 소유형용사 대신 정관사를 씁니다 ✗","las: 여성 복수 정관사로 'las manos(손)'가 됩니다 ✓","los: mano는 여성 명사이므로 los를 쓸 수 없습니다 ✗"]},{"id":"G397","q":"En esta calle no ____ ninguna farmacia.","o":["hay","tiene","está","es"],"a":0,"k":"no hay ninguna","t":"이 거리에는 약국이 하나도 없어요.","e":"'~이 있다/없다'는 존재를 나타내는 hay를 씁니다. 'no hay ninguna farmacia'는 '약국이 하나도 없다'라는 뜻입니다. 정해지지 않은 대상이므로 estar가 아니라 hay를 씁니다.","x":["hay: 존재를 나타내 'no hay ninguna farmacia'가 됩니다 ✓","tiene: 주어가 없어 '거리가 가지고 있다'는 뜻으로 쓰기 어렵습니다 ✗","está: 정해진 대상의 위치에 쓰여 ninguna와 함께 쓰지 않습니다 ✗","es: ser는 존재를 나타내지 않습니다 ✗"]},{"id":"G398","q":"¿____ habitantes hay en esta ciudad?","o":["Cuánta","Cuántos","Cuántos de","Cuánto"],"a":1,"k":"cuántos + 명사","t":"이 도시에는 주민이 몇 명이나 있나요?","e":"cuánto는 뒤의 명사와 성·수를 맞춥니다. habitantes(주민들)는 남성 복수이므로 cuántos가 되고, 명사 앞에 바로 붙여 씁니다. 'cuántos de'는 'cuántos de ustedes(여러분 중 몇 명)'처럼 특정 집단 중 일부를 물을 때 씁니다.","x":["Cuánta: 여성 단수형이라 남성 복수 habitantes와 맞지 않습니다 ✗","Cuántos: 남성 복수형으로 'cuántos habitantes'가 됩니다 ✓","Cuántos de: 명사 앞에 de를 넣지 않습니다 ✗","Cuánto: 단수형이라 복수 명사와 맞지 않습니다 ✗"]},{"id":"G399","q":"Antonio Banderas nació ____ Málaga en 1960.","o":["a","en","de","desde"],"a":1,"k":"nacer en","t":"안토니오 반데라스는 1960년에 말라가에서 태어났어요.","e":"'~에서 태어나다'는 'nacer en + 장소'로 씁니다. 연도 앞에도 en을 씁니다(en 1960). 예: Nací en Seúl.(나는 서울에서 태어났다.)","x":["a: 방향을 나타내 '태어나다'와 함께 쓰지 않습니다 ✗","en: 장소를 나타내 'nació en Málaga'가 됩니다 ✓","de: 'ser de Málaga(말라가 출신이다)'에는 쓰지만 nacer와는 쓰지 않습니다 ✗","desde: '~부터'라는 뜻이라 출생지를 나타내지 않습니다 ✗"]},{"id":"G400","q":"Los cachorros no quieren separarse ____ su mamá.","o":["con","de","a","en"],"a":1,"k":"separarse de","t":"강아지들이 엄마와 떨어지고 싶어 하지 않아요.","e":"'separarse de ~'는 '~에게서 떨어지다, 헤어지다'라는 뜻으로 전치사 de를 씁니다. de는 출발점이나 분리를 나타냅니다. cachorros는 강아지·새끼 동물을 말합니다.","x":["con: 'separarse con'은 표준적인 표현이 아닙니다 ✗","de: 'separarse de(~에게서 떨어지다)'의 전치사로 정답입니다 ✓","a: 분리를 나타내지 못합니다 ✗","en: 장소를 나타내 이 동사와 맞지 않습니다 ✗"]},{"id":"G401","q":"Ni a Juana ____ a Eloísa les interesa el cine de este director.","o":["ni","tampoco","también","no"],"a":0,"k":"ni ~ ni","t":"후아나도 엘로이사도 이 감독의 영화에는 관심이 없어요.","e":"'ni A ni B'는 'A도 B도 아니다'라는 뜻입니다. 문장이 'Ni a Juana'로 시작하므로 짝을 맞춰 두 번째에도 ni를 씁니다. ni로 문장을 시작하면 동사 앞에 no를 따로 쓰지 않습니다.","x":["ni: 'ni A ni B(A도 B도 아닌)'의 짝으로 정답입니다 ✓","tampoco: '~도 역시 아니다'라는 부사로 ni와 짝을 이루지 않습니다 ✗","también: '~도 역시'라는 긍정 표현이라 부정문과 맞지 않습니다 ✗","no: 'ni A no B'라는 구조는 없습니다 ✗"]},{"id":"G402","q":"____ buena persona, es guapa.","o":["Además de","Además a","Además","Además por"],"a":0,"k":"además de","t":"그녀는 좋은 사람일 뿐 아니라 예쁘기도 해요.","e":"'además de + 명사/동사원형'은 '~외에도, ~일 뿐만 아니라'라는 뜻입니다. 뒤에 명사구(buena persona)가 오므로 전치사 de가 필요합니다. 예: Además de estudiar, trabaja.(그는 공부 외에 일도 한다.)","x":["Además de: '~일 뿐 아니라'로 뒤의 명사구와 연결되어 정답입니다 ✓","Además a: 'además a'라는 표현은 없습니다 ✗","Además: 단독으로는 '게다가'라는 부사라 명사구 buena persona를 바로 이끌 수 없습니다 ✗","Además por: 이런 표현은 쓰지 않습니다 ✗"]},{"id":"G403","q":"¿Sabes ____ cocinar?","o":["a","de","por","ø"],"a":3,"k":"saber + 동사원형","t":"요리할 줄 알아?","e":"'saber + 동사원형'은 '~할 줄 안다(능력)'라는 뜻으로 전치사 없이 바로 동사원형이 옵니다. 예: Sé nadar.(나는 수영할 줄 안다.)","x":["a: saber 뒤에는 전치사 a를 쓰지 않습니다 ✗","de: 'saber de'는 '~에 대해 알다'라는 뜻으로 동사원형 앞에는 쓰지 않습니다 ✗","por: saber와 동사원형 사이에 쓰지 않습니다 ✗","ø: 전치사 없이 'Sabes cocinar?(요리할 줄 알아?)'가 됩니다 ✓"]},{"id":"G404","q":"____ tenés mucha suerte.","o":["Vos","Usted","Vosotros","Ustedes"],"a":0,"k":"vos (voseo)","t":"너 정말 운이 좋구나.","e":"tenés는 vos(너)에 쓰는 동사 형태로, 아르헨티나·우루과이·중미 등에서 tú 대신 씁니다(voseo). tener의 vos 현재형은 tenés이고, tú라면 tienes가 됩니다. 이처럼 vos는 끝 음절에 악센트가 오는 특징이 있습니다(hablás, comés, vivís).","x":["Vos: tenés와 짝을 이루는 2인칭 단수 대명사로 정답입니다 ✓","Usted: usted는 3인칭 형태 tiene를 씁니다 ✗","Vosotros: 스페인에서 쓰는 '너희'로 동사는 tenéis가 됩니다 ✗","Ustedes: 3인칭 복수 형태 tienen을 씁니다 ✗"]},{"id":"G405","q":"Mi familia se despidió ____ mí en el aeropuerto.","o":["de","sobre","a","para"],"a":0,"k":"despedirse de","t":"가족들이 공항에서 나에게 작별 인사를 했어요.","e":"'despedirse de + 사람'은 '~와 작별 인사를 하다'라는 뜻으로 전치사 de를 씁니다. 전치사 뒤에서 '나'는 mí(악센트 있음)가 됩니다. 예: Me despedí de mis amigos.(친구들에게 작별 인사를 했다.)","x":["de: 'despedirse de(~와 작별하다)'의 전치사로 정답입니다 ✓","sobre: '~에 관하여'라는 뜻이라 이 동사와 쓰지 않습니다 ✗","a: despedirse는 a가 아니라 de를 씁니다 ✗","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G406","q":"No bebo ____ café desde hace un mes.","o":["el","del","ø","algún"],"a":2,"k":"무관사 (일반적 물질명사)","t":"한 달 전부터 커피를 안 마셔요.","e":"커피·물·빵처럼 셀 수 없는 물질명사를 '일반적으로' 먹거나 마신다고 할 때는 관사를 쓰지 않습니다. 'No bebo café'는 '나는 커피를 마시지 않는다'입니다. 'desde hace + 기간'은 '~전부터'라는 뜻입니다.","x":["el: 'el café'는 특정한 그 커피를 가리켜 일반적인 습관을 말하는 문장에 어색합니다 ✗","del: '그 커피 중 일부'라는 뜻이 되어 맞지 않습니다 ✗","ø: 일반적인 물질명사로 관사 없이 'No bebo café'가 됩니다 ✓","algún: 셀 수 있는 명사에 쓰는 형용사라 café에 맞지 않습니다 ✗"]},{"id":"G407","q":"Estamos esperando ____ tren.","o":["a","la","el","ø"],"a":2,"k":"esperar + 정관사","t":"우리는 기차를 기다리고 있어요.","e":"esperar(기다리다)는 전치사 없이 바로 목적어를 받습니다. 기차(tren)는 사물이므로 인칭 a가 필요 없고, 타려고 하는 특정 기차를 가리키므로 정관사 el을 씁니다. 사람을 기다릴 때는 a를 써요(Espero a María).","x":["a: 사물 목적어 앞에는 a를 쓰지 않습니다 ✗","la: tren은 남성 명사라 la를 쓸 수 없습니다 ✗","el: 남성 정관사로 'esperando el tren'이 됩니다 ✓","ø: 셀 수 있는 단수 명사 tren 앞에서 관사를 빼면 틀립니다 ✗"]},{"id":"G408","q":"¿Qué ____ vas a regalar a tus padres por Navidad?","o":["lo","los","le","les"],"a":3,"k":"간접목적격 les","t":"크리스마스에 부모님께 무엇을 선물할 거야?","e":"regalar(선물하다)에서 '받는 사람(~에게)'은 간접목적격 대명사로 나타냅니다. 'a tus padres(부모님께)'는 3인칭 복수이므로 les를 씁니다. 스페인어는 'a + 사람'이 있어도 대명사를 함께 쓰는 것이 자연스럽습니다.","x":["lo: 직접목적격(그것을)인데 무엇을 줄지는 qué가 이미 나타냅니다 ✗","los: 직접목적격 복수(그들을)라 '부모님에게'라는 뜻이 되지 않습니다 ✗","le: 3인칭 단수라 복수인 padres와 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격으로 '부모님께'가 됩니다 ✓"]},{"id":"G409","q":"Todos ____ viernes voy a la biblioteca de mi facultad.","o":["ø","algunos","los","las"],"a":2,"k":"todos los + 요일","t":"매주 금요일마다 나는 학부 도서관에 가요.","e":"'todos los + 요일 복수형'은 '매주 ~요일마다'라는 뜻입니다. 요일은 모두 남성 명사이므로 los를 씁니다. viernes는 단수·복수 형태가 같습니다. 예: todos los lunes(매주 월요일)","x":["ø: todos 뒤에 명사가 올 때는 정관사가 필요합니다 ✗","algunos: 'todos algunos'라는 표현은 없습니다 ✗","los: 남성 복수 정관사로 'todos los viernes(매주 금요일)'가 됩니다 ✓","las: 요일은 남성 명사라 las를 쓰지 않습니다 ✗"]},{"id":"G410","q":"Cuando ocurrió el accidente, ____ en el almacén.","o":["trabajaremos","estábamos trabajando","trabajásemos","estamos trabajando"],"a":1,"k":"과거진행 + 단순과거","t":"사고가 일어났을 때 우리는 창고에서 일하고 있었어요.","e":"과거에 어떤 일이 갑자기 일어났을 때(ocurrió) 그 순간 진행 중이던 배경 동작은 'estaba + 현재분사'로 씁니다. nosotros 형태는 estábamos trabajando입니다.","x":["trabajaremos: 미래형이라 과거 사건(ocurrió)과 시제가 맞지 않습니다 ✗","estábamos trabajando: 과거의 순간에 진행 중이던 일을 나타내 정답입니다 ✓","trabajásemos: 접속법 과거라 이 평서문에 쓸 이유가 없습니다 ✗","estamos trabajando: 현재진행형이라 과거 이야기와 맞지 않습니다 ✗"]},{"id":"G411","q":"Nunca me he montado ____ un helicóptero.","o":["sobre","encima de","en","a"],"a":2,"k":"montarse en","t":"저는 헬리콥터를 한 번도 타 본 적이 없어요.","e":"교통수단에 '타다'는 'montarse en / subirse a'를 씁니다. 헬리콥터 안에 들어가 타는 것이므로 en이 맞습니다. 'montar a caballo(말을 타다)'처럼 말에는 a를 쓰는 점도 알아 두세요.","x":["sobre: '~위에'라서 헬리콥터 지붕 위에 올라탄다는 뜻이 됩니다 ✗","encima de: '~의 위에'라는 뜻이라 탑승의 의미가 되지 않습니다 ✗","en: 'montarse en(~에 타다)'으로 정답입니다 ✓","a: 'montar a caballo'처럼 말 등에 쓰고 헬리콥터에는 쓰지 않습니다 ✗"]},{"id":"G412","q":"No escuché el timbre porque ____ música con los cascos.","o":["escuchaba","he escuchado","escuché","estaba escuchando"],"a":3,"k":"과거진행형","t":"헤드폰으로 음악을 듣고 있어서 초인종 소리를 못 들었어요.","e":"초인종이 울린 그 순간 '진행 중이던 동작'을 강조할 때는 'estaba + 현재분사'를 씁니다. 'estaba escuchando música(음악을 듣고 있었다)'가 이유가 되어 초인종을 못 들은 것입니다. 불완료과거 escuchaba도 비슷한 의미로 쓰일 수 있지만, 교재는 그 순간의 진행을 분명히 보여 주는 진행형을 정답으로 봅니다.","x":["escuchaba: 불완료과거로 가능은 하지만 그 순간 진행 중이었다는 뜻은 진행형이 더 분명합니다 ✗","he escuchado: 현재완료라 과거 사건(no escuché)과 시제가 맞지 않습니다 ✗","escuché: 단순과거로 완결된 행동이라 배경이 되는 진행 동작에 맞지 않습니다 ✗","estaba escuchando: 그 순간 진행 중이던 동작을 나타내는 과거진행형으로 정답입니다 ✓"]},{"id":"G413","q":"No me gusta ____ la pintura de este artista.","o":["mucho","muchos","mucha","muy"],"a":0,"k":"동사 + mucho","t":"이 화가의 그림은 별로 마음에 들지 않아요.","e":"동사를 꾸밀 때 '많이'는 형태가 변하지 않는 mucho를 씁니다. 'No me gusta mucho'는 '별로 좋아하지 않는다'라는 뜻입니다. muy는 형용사·부사 앞에서만 씁니다.","x":["mucho: 동사 gusta를 꾸미는 부사로 정답입니다 ✓","muchos: 남성 복수 명사 앞에 쓰는 형용사라 맞지 않습니다 ✗","mucha: 여기서는 la pintura를 꾸미는 것이 아니라 동사를 꾸미므로 형태가 변하지 않습니다 ✗","muy: 동사 앞뒤에는 쓰지 않고 형용사·부사 앞에만 씁니다 ✗"]},{"id":"G414","q":"No ____ ningún número de teléfono.","o":["recuerdo","me recuerdo","acuerdo","me acuerdo"],"a":0,"k":"recordar vs acordarse","t":"전화번호를 하나도 기억 못 해요.","e":"'기억하다'는 'recordar + 목적어' 또는 재귀형 'acordarse de + 목적어'로 씁니다. 빈칸 뒤에 de 없이 바로 목적어(ningún número)가 오므로 recordar의 yo 형태인 recuerdo가 맞습니다.","x":["recuerdo: recordar는 전치사 없이 목적어를 받아 정답입니다 ✓","me recuerdo: recordar는 이런 의미로 재귀형을 쓰지 않습니다 ✗","acuerdo: se 없는 acordar는 '합의하다'라는 다른 뜻이라 맞지 않습니다 ✗","me acuerdo: 'me acuerdo de ~'처럼 de가 필요해서 이 문장에는 맞지 않습니다 ✗"]},{"id":"G415","q":"____ alumnos de esta clase han obtenido el certificado.","o":["Todos","Todas las","Todos los","Todas"],"a":2,"k":"todos los + 명사","t":"이 반 학생들은 모두 자격증을 땄어요.","e":"'todos los + 복수 명사'는 '모든 ~'이라는 뜻입니다. alumnos는 남성 복수이므로 todos los alumnos가 됩니다. todos 뒤에 명사가 올 때는 정관사를 빼지 않습니다.","x":["Todos: 정관사 los가 빠져서 틀립니다 ✗","Todas las: 여성형이라 남성 명사 alumnos와 맞지 않습니다 ✗","Todos los: 남성 복수형과 정관사로 정답입니다 ✓","Todas: 여성형이고 관사도 빠졌습니다 ✗"]},{"id":"G416","q":"¿Dónde conocisteis ____ Daniel?","o":["al","ø","el","a"],"a":3,"k":"인칭 a","t":"너희 다니엘을 어디서 알게 됐어?","e":"conocer(알게 되다)의 직접목적어가 특정한 사람이면 앞에 인칭 a를 붙입니다. 사람 이름 앞에는 관사가 없으므로 a Daniel이 맞습니다. conocisteis는 vosotros(너희) 형태로 스페인에서 쓰입니다(중남미: conocieron).","x":["al: a + el이라 사람 이름 앞에는 쓰지 않습니다 ✗","ø: 사람 목적어 앞에는 인칭 a가 필요합니다 ✗","el: 인칭 a가 빠졌고 이름 앞 관사도 불필요합니다 ✗","a: 사람 목적어 앞 인칭 a로 정답입니다 ✓"]},{"id":"G417","q":"Ustedes no ____ paciencia.","o":["tened","tienes","tenéis","tienen"],"a":3,"k":"ustedes 동사 활용","t":"여러분은 인내심이 없군요.","e":"ustedes(여러분)는 동사를 3인칭 복수로 활용합니다. tener의 3인칭 복수 현재형은 tienen입니다. 스페인에서 친한 사이라면 vosotros tenéis를 쓰고, 중남미에서는 언제나 ustedes tienen을 씁니다.","x":["tened: vosotros 명령형이라 맞지 않습니다 ✗","tienes: tú(너) 형태라 ustedes와 맞지 않습니다 ✗","tenéis: vosotros 형태라 ustedes와 맞지 않습니다 ✗","tienen: ustedes에 맞는 3인칭 복수 현재형으로 정답입니다 ✓"]},{"id":"G418","q":"Esta tarde, cuando ____ de trabajar, voy a ir al centro comercial.","o":["termine","termino","terminaré","voy a terminar"],"a":0,"k":"cuando + 접속법(미래)","t":"오늘 오후에 일이 끝나면 쇼핑몰에 갈 거예요.","e":"cuando 뒤에 '아직 일어나지 않은 미래의 일'이 오면 접속법 현재를 씁니다. 'cuando termine(끝나면)'이 됩니다. 반대로 습관이나 과거 사실이면 직설법을 써요(Cuando termino, voy a casa.).","x":["termine: 미래의 일을 나타내는 접속법 현재로 정답입니다 ✓","termino: 직설법은 습관적인 일에 쓰여 오늘 오후의 미래 계획에는 맞지 않습니다 ✗","terminaré: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","voy a terminar: cuando 뒤에는 미래 표현 대신 접속법을 씁니다 ✗"]},{"id":"G419","q":"La directora ____ banco en el que tengo mi cuenta es amiga de mi madre.","o":["de","de la","del","de un"],"a":2,"k":"축약 del","t":"내 계좌가 있는 은행의 지점장은 우리 엄마 친구예요.","e":"'~의'를 나타내는 de 뒤에 남성 정관사 el이 오면 del로 축약됩니다. banco는 남성 명사이고 뒤의 'en el que tengo mi cuenta'가 특정한 은행을 가리키므로 'del banco'가 맞습니다.","x":["de: 정관사 없이 'de banco'라고 하면 '은행 출신'처럼 특정성이 없어집니다 ✗","de la: banco는 남성 명사라 la를 쓸 수 없습니다 ✗","del: de + el의 축약형으로 특정한 은행을 가리켜 정답입니다 ✓","de un: 관계절이 특정한 은행을 가리키므로 부정관사는 어색합니다 ✗"]},{"id":"G420","q":"A nosotros ____ las hamburguesas.","o":["nos encantan","encantan","encantamos","nos encanta"],"a":0,"k":"encantar 구문","t":"우리는 햄버거를 정말 좋아해요.","e":"encantar(아주 좋아하다)는 gustar처럼 좋아하는 대상이 주어입니다. las hamburguesas가 복수이므로 encantan이 되고, 좋아하는 사람(우리)은 nos로 나타냅니다. 'A nosotros'는 강조 표현이라 nos를 빼면 안 됩니다.","x":["nos encantan: 복수 주어 hamburguesas에 맞춘 encantar 구문으로 정답입니다 ✓","encantan: 대명사 nos가 빠졌습니다 ✗","encantamos: '우리가 (누군가를) 매료시킨다'는 뜻이 되어 틀립니다 ✗","nos encanta: 단수형이라 복수 주어 las hamburguesas와 맞지 않습니다 ✗"]},{"id":"G421","q":"No sé cómo ____ este ejercicio de física. ¿Me ayudas?","o":["me hace","se hace","hacerse","me hago"],"a":1,"k":"무인칭 se","t":"이 물리 문제를 어떻게 푸는지 모르겠어요. 도와줄래요?","e":"'se + 3인칭 동사'는 특정 주어 없이 '일반적으로 ~하다'라는 무인칭 표현입니다. '¿Cómo se hace?'는 '어떻게 하는 거지?'라는 뜻입니다. 예: ¿Cómo se dice 'gracias' en coreano?(한국어로 'gracias'를 어떻게 말해요?)","x":["me hace: '그것이 나를 ~하게 만든다'는 뜻이 되어 맞지 않습니다 ✗","se hace: 무인칭 se로 '(이 문제는) 어떻게 하는지'가 됩니다 ✓","hacerse: '~이 되다'라는 뜻의 원형이라 이 문장에 맞지 않습니다 ✗","me hago: '내가 ~이 된다'는 뜻이 되어 의미가 이상합니다 ✗"]},{"id":"G422","q":"Mi hijo nació ____ este hospital.","o":["en","de","a","por"],"a":0,"k":"nacer en","t":"제 아들은 이 병원에서 태어났어요.","e":"'~에서 태어나다'는 'nacer en + 장소'입니다. 도시나 나라뿐 아니라 건물(병원)에도 en을 씁니다.","x":["en: 장소를 나타내 'nació en este hospital'이 됩니다 ✓","de: 출신을 나타낼 때 ser de와 쓰며 nacer와는 맞지 않습니다 ✗","a: 방향을 나타내 '태어나다'와 함께 쓰지 않습니다 ✗","por: '~을 통해, ~근처'라는 뜻이라 출생 장소에 쓰지 않습니다 ✗"]},{"id":"G423","q":"Muchas gracias ____ avisarme.","o":["por","para","de","a"],"a":0,"k":"gracias por","t":"알려 줘서 정말 고마워요.","e":"감사의 이유를 말할 때는 'gracias por + 명사/동사원형'을 씁니다. por는 원인·이유를 나타냅니다. 예: Gracias por tu ayuda.(도와줘서 고마워.)","x":["por: 감사의 이유를 나타내는 전치사로 정답입니다 ✓","para: 목적을 나타내 감사의 이유에는 쓰지 않습니다 ✗","de: 'gracias de'는 표준적인 표현이 아닙니다 ✗","a: 'gracias a'는 '~덕분에'라는 뜻이라 동사원형과 쓰지 않습니다 ✗"]},{"id":"G424","q":"Si el bebé tiene hambre, ____ un potito.","o":["dala","dales","dale","dalo"],"a":2,"k":"명령형 + le","t":"아기가 배고프면 이유식 한 병 줘.","e":"dar(주다)의 tú 명령형은 da이고, '아기에게'라는 간접목적격 대명사 le를 뒤에 붙여 dale이 됩니다. 긍정 명령에서는 대명사를 동사 뒤에 붙여 씁니다. potito는 스페인에서 병에 든 아기 이유식을 말합니다.","x":["dala: la는 직접목적격(그녀를)이라 '아기에게'의 뜻이 되지 않습니다 ✗","dales: 3인칭 복수라 단수인 el bebé와 맞지 않습니다 ✗","dale: 3인칭 단수 간접목적격 le로 '아기에게 줘'가 됩니다 ✓","dalo: lo는 직접목적격이라 받는 사람을 나타내지 못합니다 ✗"]},{"id":"G425","q":"Las herramientas ya están en la caja, ____ recogió Francisco.","o":["se la","las","se","los"],"a":1,"k":"직접목적격 las","t":"공구들은 이미 상자에 있어요, 프란시스코가 정리했어요.","e":"앞에 나온 las herramientas(공구들, 여성 복수)를 다시 받아 '그것들을'이라고 할 때는 직접목적격 대명사 las를 씁니다. recoger(치우다, 정리하다)의 목적어이므로 'las recogió'가 됩니다.","x":["se la: 간접목적어가 없고 단수형이라 맞지 않습니다 ✗","las: 여성 복수 직접목적격으로 공구들을 가리켜 정답입니다 ✓","se: 재귀·무인칭 대명사라 '그것들을'의 뜻이 되지 않습니다 ✗","los: 남성형이라 여성 명사 herramientas와 맞지 않습니다 ✗"]},{"id":"G426","q":"Todavía tengo el libro de Carmen, ____ devolveré en cuanto pueda.","o":["se","se lo","le lo","le"],"a":1,"k":"이중 대명사 se lo","t":"아직 카르멘의 책을 갖고 있는데, 되도록 빨리 돌려줄 거예요.","e":"간접목적격(le, ~에게)과 직접목적격(lo, ~을)을 함께 쓸 때는 간접목적격이 앞에 오고, le/les는 se로 바뀝니다. '카르멘에게(le) 그 책을(lo)'이므로 le lo가 아니라 se lo가 됩니다. 예: Se lo dije.(그에게 그것을 말했다.)","x":["se: 직접목적격 lo(그 책을)가 빠졌습니다 ✗","se lo: le가 se로 바뀐 이중 대명사로 '그녀에게 그것을'이 됩니다 ✓","le lo: le와 lo가 함께 올 때는 반드시 se lo로 바꿔야 합니다 ✗","le: '그녀에게'만 있고 '그 책을'에 해당하는 lo가 없습니다 ✗"]},{"id":"G427","q":"¿Qué ____ tus empleados en este momento?","o":["haciendo","están haciendo","son haciendo","hacer"],"a":1,"k":"현재진행형","t":"지금 이 순간 당신 직원들은 무엇을 하고 있나요?","e":"'en este momento(지금 이 순간)' 진행 중인 동작은 'estar + 현재분사'로 표현합니다. 주어 tus empleados는 3인칭 복수이므로 están haciendo가 됩니다.","x":["haciendo: estar 동사 없이 현재분사만으로는 문장이 되지 않습니다 ✗","están haciendo: 3인칭 복수 현재진행형으로 정답입니다 ✓","son haciendo: 진행형은 ser가 아니라 estar로 만듭니다 ✗","hacer: 동사원형이라 주어에 맞게 활용되지 않았습니다 ✗"]},{"id":"G428","q":"Los bebés han estado llorando toda la tarde, ____ me duele la cabeza.","o":["aunque","porque","ya que","por eso"],"a":3,"k":"결과 접속사 por eso","t":"아기들이 오후 내내 울어서 머리가 아파요.","e":"por eso는 '그래서, 그 때문에'라는 뜻으로 앞의 내용이 원인이고 뒤가 결과일 때 씁니다. '아기들이 울었다(원인) → 머리가 아프다(결과)'이므로 por eso가 맞습니다. porque와 ya que는 반대로 뒤에 이유가 옵니다.","x":["aunque: '비록 ~지만'이라는 양보 접속사라 인과 관계와 맞지 않습니다 ✗","porque: 뒤에 이유가 와야 하는데, 두통은 결과라 순서가 맞지 않습니다 ✗","ya que: '~이니까'로 뒤에 이유가 오므로 맞지 않습니다 ✗","por eso: '그래서'로 원인 뒤에 결과를 이어 정답입니다 ✓"]},{"id":"G429","q":"____ es mi cantante preferida.","o":["Este","Esta","Estas","Esto"],"a":1,"k":"지시대명사 esta","t":"이 사람이 제가 가장 좋아하는 가수예요.","e":"지시대명사는 가리키는 대상의 성·수에 맞춥니다. 'mi cantante preferida'에서 preferida가 여성형이므로 여성 가수를 가리키는 esta를 씁니다. cantante는 남녀 공용 명사라 형용사로 성을 판단합니다.","x":["Este: 남성형이라 preferida(여성)와 맞지 않습니다 ✗","Esta: 여성 단수 지시대명사로 정답입니다 ✓","Estas: 복수형이라 단수 cantante와 맞지 않습니다 ✗","Esto: 중성형이라 사람을 가리키지 않습니다 ✗"]},{"id":"G430","q":"Entre Lucía y ____ hay una buena relación de amistad.","o":["mí","yo","a mí","me"],"a":1,"k":"entre + 주격 대명사","t":"루시아와 나 사이에는 좋은 우정이 있어요.","e":"보통 전치사 뒤에는 mí, ti를 쓰지만(para mí, para ti) 전치사 entre(~사이에)는 예외로 주격 대명사 yo, tú를 씁니다. 그래서 'entre Lucía y yo', 'entre tú y yo'가 됩니다.","x":["mí: 대부분의 전치사 뒤에는 mí를 쓰지만 entre는 예외입니다 ✗","yo: entre 뒤에는 주격 대명사를 쓰므로 정답입니다 ✓","a mí: 전치사가 중복되어 틀립니다 ✗","me: 목적격 대명사라 전치사 뒤에 쓸 수 없습니다 ✗"]},{"id":"G431","q":"Todavía ____ he recibido los resultados del examen.","o":["ø","no","tampoco","ni"],"a":1,"k":"todavía no","t":"아직 시험 결과를 받지 못했어요.","e":"'Todavía no + 동사'는 '아직 ~하지 않았다'라는 뜻입니다. todavía만으로는 부정이 되지 않으므로 no가 필요합니다. 예: Todavía no he comido.(아직 밥을 안 먹었어.)","x":["ø: 'Todavía he recibido'는 '아직도 받았다'처럼 어색한 뜻이 됩니다 ✗","no: 'Todavía no(아직 ~않다)'로 정답입니다 ✓","tampoco: '~도 역시 아니다'라는 뜻으로 todavía와 함께 쓰기 어색합니다 ✗","ni: '~도 아니다'로 단독으로 동사를 부정하는 데 쓰지 않습니다 ✗"]},{"id":"G432","q":"Puedes llamarme cuando ____.","o":["quieres","quieras","queréis","quiere"],"a":1,"k":"cuando + 접속법","t":"원할 때 언제든 전화해도 돼요.","e":"cuando 뒤가 '정해지지 않은 미래(네가 원하게 될 때)'를 나타내면 접속법 현재를 씁니다. querer의 tú 접속법 현재는 quieras입니다. 'cuando quieras(원할 때 언제든)'는 자주 쓰는 표현입니다.","x":["quieres: 직설법이라 정해지지 않은 미래의 때를 나타내지 못합니다 ✗","quieras: tú 접속법 현재로 'cuando quieras(원할 때 언제든)'가 됩니다 ✓","queréis: vosotros 직설법이라 주어(puedes, tú)와 맞지 않습니다 ✗","quiere: 3인칭 직설법이라 tú에게 하는 말과 맞지 않습니다 ✗"]},{"id":"G433","q":"Tu pedido ____ ha llegado, lo trajo el repartidor hace una hora.","o":["todavía","aún","mientras","ya"],"a":3,"k":"ya (이미)","t":"주문하신 물건은 이미 도착했어요, 한 시간 전에 배달원이 가져왔어요.","e":"ya는 '이미, 벌써'라는 뜻으로 완료된 일을 나타냅니다. '한 시간 전에 가져왔다'는 정보로 보아 이미 도착했으므로 'ya ha llegado'가 맞습니다. 반대로 todavía/aún은 '아직'입니다.","x":["todavía: '아직'이라는 뜻이라 이미 도착했다는 문맥과 반대됩니다 ✗","aún: todavía와 같은 '아직'이라 맞지 않습니다 ✗","mientras: '~하는 동안'이라는 접속사라 이 자리에 쓸 수 없습니다 ✗","ya: '이미'라는 뜻으로 정답입니다 ✓"]},{"id":"G434","q":"¿Quiere usted ____ más o eso es todo?","o":["nada","un","algún","algo"],"a":3,"k":"algo más","t":"더 필요하신 게 있나요, 아니면 이게 다인가요?","e":"'algo más(그 밖에 무언가)'는 가게에서 점원이 자주 하는 질문입니다. 긍정 의문문에서 '무언가'는 algo를 씁니다. 예: ¿Algo más? —No, eso es todo.(더 필요하신 거 있나요? —아니요, 그게 다예요.)","x":["nada: 부정어라 '아무것도 원하지 않으세요?'처럼 부정 의문문에 씁니다 ✗","un: 뒤에 명사가 필요한 관사라 단독으로 쓸 수 없습니다 ✗","algún: 뒤에 명사가 필요한 형용사입니다 ✗","algo: '무언가'라는 뜻으로 'algo más(더 필요한 것)'가 됩니다 ✓"]},{"id":"G435","q":"Afortunadamente, hoy Liliana se siente ____ que ayer.","o":["más mejor","mejor","tan bien","más bien"],"a":1,"k":"불규칙 비교급 mejor","t":"다행히 오늘 릴리아나는 어제보다 컨디션이 나아요.","e":"bien(잘)/bueno(좋은)의 비교급은 'más bien'이 아니라 불규칙형 mejor(더 잘, 더 좋은)입니다. 'mejor que ayer(어제보다 낫다)'가 됩니다. mejor 앞에 más를 다시 붙이면 안 됩니다.","x":["más mejor: mejor 자체가 비교급이라 más와 겹쳐 쓰지 않습니다 ✗","mejor: bien의 불규칙 비교급으로 정답입니다 ✓","tan bien: 동등 비교 'tan ~ como'에 쓰여 que와 짝이 맞지 않습니다 ✗","más bien: '오히려'라는 다른 뜻의 표현이라 비교급으로 쓰지 않습니다 ✗"]},{"id":"G436","q":"¿Dónde está ____ Sra. Gutiérrez?","o":["las","la","el","ø"],"a":1,"k":"Sra. + 정관사","t":"구티에레스 부인은 어디에 계세요?","e":"Sra.는 señora의 약자입니다. 그 사람에 대해 3인칭으로 말할 때는 호칭 앞에 정관사를 붙여 'la Sra. Gutiérrez'가 됩니다. 직접 부를 때는 관사 없이 'Sra. Gutiérrez'라고 합니다.","x":["las: 복수형이라 한 사람을 가리키지 못합니다 ✗","la: 여성 정관사로 'la Sra. Gutiérrez'가 됩니다 ✓","el: 남성 관사라 señora와 맞지 않습니다 ✗","ø: 3인칭으로 말할 때는 관사가 필요합니다 ✗"]},{"id":"G437","q":"En cuanto ____ al aeropuerto, mándame un mensaje, ¿vale?","o":["llegases","llegaras","llegues","llegarás"],"a":2,"k":"en cuanto + 접속법","t":"공항에 도착하자마자 메시지 보내 줘, 알았지?","e":"'en cuanto(~하자마자)' 뒤에 아직 일어나지 않은 미래 일이 오면 접속법 현재를 씁니다. llegar의 tú 접속법 현재는 llegues입니다(g 뒤에 u 추가). 주절이 명령형(mándame)이라 미래의 일임이 분명합니다.","x":["llegases: 접속법 과거라 명령형 주절과 시제가 맞지 않습니다 ✗","llegaras: 역시 접속법 과거라 현재·미래 상황에 맞지 않습니다 ✗","llegues: tú 접속법 현재로 정답입니다 ✓","llegarás: en cuanto 뒤에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G438","q":"El sábado vamos a llevar ____ niños al parque de atracciones.","o":["a los","al","los","a"],"a":0,"k":"인칭 a + 정관사","t":"토요일에 아이들을 놀이공원에 데려갈 거예요.","e":"llevar(데려가다)의 직접목적어가 특정한 사람(우리 아이들)이므로 인칭 a가 필요합니다. 여기에 정관사 los를 더해 'a los niños'가 됩니다. a + el만 al로 축약되고 a + los는 축약하지 않습니다.","x":["a los: 인칭 a와 남성 복수 정관사로 정답입니다 ✓","al: a + el(단수)이라 복수 명사 niños와 맞지 않습니다 ✗","los: 사람 목적어 앞의 인칭 a가 빠졌습니다 ✗","a: 특정한 아이들을 가리키므로 정관사가 필요합니다 ✗"]},{"id":"G439","q":"Hoy me siento ____ bien.","o":["muy","mucho","muchísimo","mucha"],"a":0,"k":"muy + bien","t":"오늘은 기분이 아주 좋아요.","e":"부사 bien 앞에서 '아주'는 muy를 씁니다. 'Me siento muy bien'은 '나는 기분이 아주 좋다'입니다. sentirse(느끼다) 뒤에 bien/mal로 상태를 나타냅니다.","x":["muy: 부사 bien을 꾸며 'muy bien(아주 좋게)'이 됩니다 ✓","mucho: 동사나 명사를 꾸미는 말이라 bien 앞에 오지 않습니다 ✗","muchísimo: mucho의 최상급으로 역시 bien 앞에 오지 않습니다 ✗","mucha: 여성 명사 앞에 쓰는 형용사라 맞지 않습니다 ✗"]},{"id":"G440","q":"¿Por qué ____ tarde anoche?","o":["llegaste","has llegado","llegas","llegabas"],"a":0,"k":"anoche + 단순과거","t":"어젯밤에 왜 늦게 왔어?","e":"anoche(어젯밤)처럼 끝난 과거 시점의 한 번의 행동은 단순과거로 씁니다. llegar의 tú 단순과거는 llegaste입니다.","x":["llegaste: tú 단순과거로 어젯밤의 한 번의 행동을 나타내 정답입니다 ✓","has llegado: 현재완료라 anoche와 함께 쓰지 않습니다 ✗","llegas: 현재형이라 과거 시점과 맞지 않습니다 ✗","llegabas: 불완료과거로 습관이나 배경을 나타내 한 번의 행동에 맞지 않습니다 ✗"]},{"id":"G441","q":"¿____ qué trata el libro que estás leyendo?","o":["De","En","Para","A"],"a":0,"k":"tratar de","t":"네가 읽고 있는 책은 무엇에 관한 내용이야?","e":"'tratar de ~'는 '(책·영화가) ~에 관한 내용이다'라는 뜻입니다. 의문문에서는 전치사 de가 의문사 앞으로 와서 '¿De qué trata…?'가 됩니다. 예: La película trata de una familia.(그 영화는 한 가족에 관한 이야기다.)","x":["De: 'tratar de(~에 관한 것이다)'의 전치사로 정답입니다 ✓","En: tratar와 함께 이런 의미로 쓰지 않습니다 ✗","Para: '무엇을 위해'라는 목적이 되어 맞지 않습니다 ✗","A: 'a qué'는 tratar와 함께 쓰지 않습니다 ✗"]},{"id":"G442","q":"Este celular cuesta ____ euros.","o":["cien veinte y cinco","ciento veinticinco","cien veinticinco","ciento veinte y cinco"],"a":1,"k":"숫자 125","t":"이 휴대폰은 125유로예요.","e":"100은 단독으로 cien이지만 뒤에 다른 숫자가 붙으면 ciento가 됩니다(101 = ciento uno). 21~29는 한 단어로 붙여 써서 veinticinco가 됩니다. 그래서 125는 ciento veinticinco입니다. celular는 중남미식 단어이고 스페인에서는 móvil이라고 합니다.","x":["cien veinte y cinco: cien은 ciento로 바꾸고 veinticinco는 붙여 써야 합니다 ✗","ciento veinticinco: 올바른 125 표기로 정답입니다 ✓","cien veinticinco: 100 뒤에 숫자가 오면 ciento를 씁니다 ✗","ciento veinte y cinco: 21~29는 veinticinco처럼 한 단어로 씁니다 ✗"]},{"id":"G443","q":"En este bloque no ____ ascensor.","o":["hay","es","haber","está"],"a":0,"k":"no hay (존재)","t":"이 건물에는 엘리베이터가 없어요.","e":"'~이 있다/없다'는 hay로 나타냅니다. 'no hay ascensor'는 '엘리베이터가 없다'입니다. 부정문에서 존재 여부만 말할 때는 관사를 생략하는 경우가 많습니다. bloque는 스페인에서 아파트 동(건물)을 말합니다.","x":["hay: 존재를 나타내 'no hay ascensor(엘리베이터가 없다)'가 됩니다 ✓","es: ser는 존재를 나타내지 않습니다 ✗","haber: 동사원형이라 활용해야 합니다 ✗","está: 정해진 대상의 위치를 말할 때 쓰여 존재 여부를 말하는 이 문장에 맞지 않습니다 ✗"]},{"id":"G444","q":"Necesito que me ____ cómo se hace esta tarta.","o":["explicaría","expliques","explicar","explicas"],"a":1,"k":"necesitar que + 접속법","t":"이 케이크를 어떻게 만드는지 나한테 설명해 줬으면 해.","e":"'Necesito que + 다른 주어'는 상대에게 요청하는 것이므로 que 뒤에 접속법을 씁니다. explicar의 tú 접속법 현재는 expliques입니다(c가 qu로 바뀜). me는 '나에게'라는 간접목적격입니다.","x":["explicaría: 조건법이라 necesito que 뒤에 쓰지 않습니다 ✗","expliques: tú 접속법 현재로 정답입니다 ✓","explicar: 동사원형은 que 뒤에 주어가 다를 때 쓸 수 없습니다 ✗","explicas: 직설법이라 요청을 나타내는 문장에 맞지 않습니다 ✗"]},{"id":"G445","q":"¿____ son esos chicos que están ahí sentados?","o":["De qué","Quiénes","Cuál","Quién"],"a":1,"k":"quiénes (복수)","t":"저기 앉아 있는 남자애들은 누구예요?","e":"quién(누구)은 복수의 사람을 물을 때 quiénes가 됩니다. 동사가 son(복수)이고 'esos chicos(저 남자애들)'도 복수이므로 quiénes가 맞습니다.","x":["De qué: '무엇에 대해/무엇으로'라는 뜻이라 사람을 묻지 못합니다 ✗","Quiénes: 복수의 사람을 묻는 의문사로 정답입니다 ✓","Cuál: 단수형이고 사람의 정체를 묻는 데 쓰지 않습니다 ✗","Quién: 단수형이라 복수 동사 son, 복수 chicos와 맞지 않습니다 ✗"]},{"id":"G446","q":"Para mí, ____ más importante en la vida es la salud.","o":["el","esto","lo","la"],"a":2,"k":"lo + 형용사","t":"나에게 인생에서 가장 중요한 것은 건강이에요.","e":"'lo + 형용사'는 '~한 것'이라는 추상적인 개념을 만듭니다. 'lo más importante'는 '가장 중요한 것'이라는 뜻입니다. 예: Lo bueno es que…(좋은 점은 ~이다)","x":["el: 남성 관사로, 뒤에 생략된 남성 명사가 없어 맞지 않습니다 ✗","esto: '이것'이라는 지시대명사라 'esto más importante'는 틀린 표현입니다 ✗","lo: 중성 관사로 'lo más importante(가장 중요한 것)'가 됩니다 ✓","la: 여성 관사로, 특정 여성 명사를 가리키지 않으므로 맞지 않습니다 ✗"]},{"id":"G447","q":"¿Cómo ____ tus mejores amigos?","o":["se llama","te llamas","llaman","se llaman"],"a":3,"k":"llamarse 활용","t":"네 가장 친한 친구들 이름이 뭐야?","e":"이름을 말할 때는 재귀동사 llamarse(~라고 불리다)를 씁니다. 주어 tus mejores amigos는 3인칭 복수이므로 se llaman이 됩니다. 예: ¿Cómo te llamas?(이름이 뭐야?)","x":["se llama: 3인칭 단수형이라 복수 주어 amigos와 맞지 않습니다 ✗","te llamas: '너는 이름이 뭐니'라는 tú 형태라 주어와 맞지 않습니다 ✗","llaman: se가 빠져 '그들이 부른다/전화한다'는 뜻이 됩니다 ✗","se llaman: 3인칭 복수 재귀형으로 정답입니다 ✓"]},{"id":"G448","q":"____ he participado en una manifestación.","o":["Nunca no","Todavía","Nunca","Aún"],"a":2,"k":"nunca (경험 부정)","t":"저는 시위에 한 번도 참여해 본 적이 없어요.","e":"nunca는 '한 번도 ~않다'라는 뜻으로, 동사 앞에 오면 no 없이 혼자서 부정을 만듭니다. 현재완료와 함께 '~해 본 적이 없다'라는 경험을 나타냅니다.","x":["Nunca no: nunca가 동사 앞에 있을 때 no를 함께 쓰지 않습니다 ✗","Todavía: '아직'이라는 뜻으로 no 없이 쓰면 '아직도 참여했다'처럼 어색합니다 ✗","Nunca: '한 번도 ~않다'로 정답입니다 ✓","Aún: todavía와 같은 '아직'이라 no 없이는 의미가 통하지 않습니다 ✗"]},{"id":"G449","q":"Ese grupo ____ ha acabado la prueba todavía.","o":["sí","también","ø","no"],"a":3,"k":"no ~ todavía","t":"그 그룹은 아직 시험을 끝내지 못했어요.","e":"문장 끝에 todavía(아직)가 있으므로 '아직 ~하지 않았다'라는 부정문이 되려면 동사 앞에 no가 필요합니다. 'no ha acabado todavía'는 'todavía no ha acabado'와 같은 뜻입니다.","x":["sí: 긍정 강조라 '아직'과 함께 쓰면 의미가 통하지 않습니다 ✗","también: '~도 역시'라는 뜻으로 문맥과 맞지 않습니다 ✗","ø: no가 없으면 '아직도 끝냈다'처럼 어색한 문장이 됩니다 ✗","no: 'no ~ todavía(아직 ~않다)'로 정답입니다 ✓"]},{"id":"G450","q":"Hoy me siento ____ que ayer.","o":["muy bien","mejor","más bien","más mejor"],"a":1,"k":"비교급 mejor","t":"오늘은 어제보다 기분이 나아요.","e":"bien(잘)의 비교급은 불규칙형 mejor(더 좋게)입니다. 'que ayer(어제보다)'와 짝을 이루어 'mejor que ayer'가 됩니다. 'más bien'이나 'más mejor'는 비교급으로 쓰지 않습니다.","x":["muy bien: 비교급이 아니라서 'que ayer(어제보다)'와 짝이 맞지 않습니다 ✗","mejor: bien의 불규칙 비교급으로 정답입니다 ✓","más bien: '오히려, 차라리'라는 다른 뜻의 표현입니다 ✗","más mejor: mejor에 más를 겹쳐 쓰지 않습니다 ✗"]},{"id":"G451","q":"¿Qué ____ pasa a José? Parece triste.","o":["se","te","le","me"],"a":2,"k":"간접목적격 대명사","t":"호세에게 무슨 일이 있어? 슬퍼 보여.","e":"pasar(일이 일어나다)는 '누구에게' 일이 생기는지를 간접목적격 대명사(~에게에 해당)로 나타냅니다. 호세는 3인칭 단수이므로 le가 맞습니다. '¿Qué le pasa?'는 '그(그녀)에게 무슨 일이야?'라는 아주 자주 쓰는 표현입니다.","x":["se: 재귀 대명사(자기 자신)로, '호세에게'를 나타낼 수 없습니다 ✗","te: 2인칭 단수(너에게)라서 호세와 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격(그에게) → 정답 ✓","me: 1인칭 단수(나에게)라서 호세와 맞지 않습니다 ✗"]},{"id":"G452","q":"Nadie ____ dónde está el encendedor.","o":["saben","sabe","sé","sabes"],"a":1,"k":"nadie + 3인칭 단수","t":"라이터가 어디 있는지 아무도 모른다.","e":"nadie(아무도 ~않다)는 문법적으로 3인칭 단수 취급을 합니다. 그래서 동사 saber(알다)도 3인칭 단수 sabe를 씁니다. nadie가 동사 앞에 오면 no를 따로 쓰지 않는다는 점도 기억하세요.","x":["saben: 3인칭 복수(그들이 안다)라서 nadie와 맞지 않습니다 ✗","sabe: 3인칭 단수 → nadie와 일치하므로 정답 ✓","sé: 1인칭 단수(나는 안다)라서 주어와 맞지 않습니다 ✗","sabes: 2인칭 단수(너는 안다)라서 주어와 맞지 않습니다 ✗"]},{"id":"G453","q":"No quiero ____ pasar por esa situación tan desagradable.","o":["volver a","soler","acabar de","dejar de"],"a":0,"k":"volver a + 동사원형","t":"그렇게 불쾌한 상황을 다시는 겪고 싶지 않다.","e":"volver a + 동사원형은 '다시 ~하다'라는 뜻의 동사 구문입니다. 문장은 '그런 상황을 또 겪고 싶지 않다'는 뜻이므로 volver a가 자연스럽습니다. 예: Volví a leer el libro.(나는 그 책을 다시 읽었다.)","x":["volver a: '다시 ~하다' → 문맥에 맞아 정답 ✓","soler: '~하곤 하다(습관)'라는 뜻이고 뒤에 a 없이 동사원형이 와서 맞지 않습니다 ✗","acabar de: '막 ~했다'라는 뜻이라 '원하지 않다'와 어울리지 않습니다 ✗","dejar de: '~하는 것을 그만두다'라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"G454","q":"Ya hemos hecho ____ ejercicio por hoy, ahora vamos a descansar.","o":["bastantes","bastante","algunos","alguno"],"a":1,"k":"bastante (부사)","t":"오늘은 운동을 충분히 했으니, 이제 쉬자.","e":"여기서 ejercicio는 '운동(활동)'이라는 셀 수 없는 의미로 쓰였고, 단수 형태입니다. 그래서 단수형 bastante(충분한, 꽤 많은)가 어울립니다. bastante는 단수 명사 앞에서는 bastante, 복수 명사 앞에서는 bastantes로 씁니다.","x":["bastantes: 복수형이라 단수 ejercicio와 맞지 않습니다 ✗","bastante: 단수 명사 ejercicio와 일치하며 '충분히'라는 의미 → 정답 ✓","algunos: '몇몇의'라는 복수형이라 단수 명사와 맞지 않습니다 ✗","alguno: 명사 앞에서는 algún으로 줄어야 하고, '어떤'이라는 뜻도 문맥에 맞지 않습니다 ✗"]},{"id":"G455","q":"¿Dónde ____ el Museo del Prado?","o":["tiene","está","es","hay"],"a":1,"k":"estar (위치)","t":"프라도 미술관은 어디에 있나요?","e":"이미 알려진 특정 장소(프라도 미술관)의 위치를 물을 때는 estar를 씁니다. hay는 '(어떤 것이) 있다'처럼 존재 여부를 말할 때, 주로 정해지지 않은 대상에 씁니다. 예: ¿Dónde está la estación?(역은 어디 있나요?)","x":["tiene: '가지고 있다'라는 뜻이라 위치를 묻는 데 쓰지 않습니다 ✗","está: 특정 장소의 위치를 나타내는 estar → 정답 ✓","es: ser는 사건이 열리는 장소에는 쓰지만, 건물의 위치에는 쓰지 않습니다 ✗","hay: 정해지지 않은 것의 존재에 쓰며, 고유한 장소 이름과 쓰지 않습니다 ✗"]},{"id":"G456","q":"Greta habla muy bien inglés porque ____ madre es de Inglaterra.","o":["suya","la suya","su","sus"],"a":2,"k":"소유형용사 su","t":"그레타는 엄마가 영국 출신이라서 영어를 아주 잘한다.","e":"명사 앞에 오는 소유형용사(~의)는 su(단수)/sus(복수)입니다. madre는 단수이므로 su madre(그녀의 어머니)가 맞습니다. suya, la suya는 명사 뒤에 오거나 명사 없이 쓰는 형태입니다.","x":["suya: 명사 뒤에 오는 형태(una amiga suya)라서 명사 앞에는 못 씁니다 ✗","la suya: '그녀의 것'이라는 소유대명사라 뒤에 명사가 올 수 없습니다 ✗","su: 명사 앞 단수 소유형용사 → 정답 ✓","sus: 복수형이라 단수 madre와 맞지 않습니다 ✗"]},{"id":"G457","q":"Antes fumaba mucho, ahora no ____ nada.","o":["fumó","fuma","fumaría","fume"],"a":1,"k":"직설법 현재","t":"예전에는 담배를 많이 피웠지만, 지금은 전혀 피우지 않는다.","e":"ahora(지금)가 있으므로 현재의 상태를 나타내는 직설법 현재가 필요합니다. 주어는 앞의 fumaba와 같은 3인칭 단수(그/그녀)로 볼 수 있어 fuma가 맞습니다. antes(예전에)의 습관은 불완료과거(fumaba), 지금은 현재형으로 대비시키는 구조입니다.","x":["fumó: 단순과거(피웠다)라서 ahora와 맞지 않습니다 ✗","fuma: 직설법 현재 3인칭 단수 → 정답 ✓","fumaría: 가정법 조건(피울 텐데)이라 사실을 말하는 문장에 맞지 않습니다 ✗","fume: 접속법(바람·의심 등에 쓰는 형태)이라 단순한 사실 서술에 맞지 않습니다 ✗"]},{"id":"G458","q":"Ya no ponen en la tele el programa que ____ te gusta.","o":["tantos","tanto","tan","tanta"],"a":1,"k":"부사 tanto","t":"네가 그렇게 좋아하는 프로그램을 이제 TV에서 안 해 준다.","e":"동사 gusta를 꾸며 '그렇게 많이'라는 뜻을 나타낼 때는 부사 tanto를 씁니다. 부사는 형태가 변하지 않습니다. tan은 형용사나 부사 앞에서만(tan bonito) 씁니다.","x":["tantos: 남성 복수 형용사라 명사가 필요하며 동사를 꾸밀 수 없습니다 ✗","tanto: 동사를 꾸미는 부사 '그렇게 많이' → 정답 ✓","tan: 형용사·부사 앞에만 쓰고 동사 앞에는 쓰지 않습니다 ✗","tanta: 여성 단수 형용사라 동사를 꾸밀 수 없습니다 ✗"]},{"id":"G459","q":"¿____ a Carlota? Llevo una hora buscándola.","o":["Estaban viendo","Vieran","Veían","Han visto"],"a":3,"k":"현재완료","t":"카를로타 봤어요? 한 시간째 그녀를 찾고 있어요.","e":"지금 막 혹은 최근에 일어난 일을 현재와 연결해서 물을 때는 현재완료(haber + 과거분사)를 씁니다. '지금까지 카를로타를 본 적 있냐'는 질문이므로 Han visto가 자연스럽습니다. 스페인에서는 가까운 과거에 현재완료를 많이 씁니다.","x":["Estaban viendo: 과거진행(보고 있었다)이라 질문의 의도와 맞지 않습니다 ✗","Vieran: 접속법 과거라 단독 의문문에 쓰지 않습니다 ✗","Veían: 불완료과거(보곤 했다)라 지금 상황과 맞지 않습니다 ✗","Han visto: 현재완료 '봤나요?' → 정답 ✓"]},{"id":"G460","q":"El test va a empezar a las nueve ____ punto.","o":["de","en","para","a"],"a":1,"k":"en punto (정각)","t":"시험은 9시 정각에 시작할 것이다.","e":"'정각'은 스페인어로 en punto라는 고정 표현입니다. a las nueve en punto는 '9시 정각에'라는 뜻입니다. 예: Llegó a las tres en punto.(그는 3시 정각에 도착했다.)","x":["de: de punto라는 표현은 없습니다 ✗","en: en punto '정각' → 정답 ✓","para: para punto라는 표현은 없습니다 ✗","a: a punto는 '막 ~하려는(a punto de)'이라는 다른 뜻입니다 ✗"]},{"id":"G461","q":"Me he enganchado ____ programa de radio que te gusta.","o":["al","a la","a","a lo"],"a":0,"k":"a + el = al","t":"네가 좋아하는 라디오 프로그램에 나도 빠져 버렸어.","e":"engancharse a(~에 빠지다, 중독되다)는 전치사 a를 씁니다. programa는 -a로 끝나지만 남성 명사(el programa)이므로 a + el이 합쳐진 al이 됩니다. -ma로 끝나는 problema, tema, programa 등은 남성 명사인 경우가 많으니 주의하세요.","x":["al: a + el, 남성 명사 programa와 맞음 → 정답 ✓","a la: 여성 관사라 남성 명사 programa와 맞지 않습니다 ✗","a: 관사 없이 쓰면 특정한 프로그램을 가리킬 수 없습니다 ✗","a lo: lo는 중성 관사라 명사 programa 앞에 쓰지 않습니다 ✗"]},{"id":"G462","q":"Es una historia increíble, nunca ____ olvidaré.","o":["las","la","les","le"],"a":1,"k":"직접목적격 대명사","t":"정말 놀라운 이야기야, 절대 잊지 못할 거야.","e":"olvidar(잊다)는 '무엇을'을 직접목적격 대명사(~을/를에 해당)로 받습니다. 앞에 나온 una historia는 여성 단수이므로 la를 씁니다. 대명사는 활용된 동사(olvidaré) 앞에 놓입니다.","x":["las: 여성 복수라 단수 historia와 맞지 않습니다 ✗","la: 여성 단수 직접목적격(그것을) → 정답 ✓","les: 복수 간접목적격(그들에게)이라 맞지 않습니다 ✗","le: 간접목적격(그에게)이라 '이야기를'을 받을 수 없습니다 ✗"]},{"id":"G463","q":"No aguanto la luz, necesito mis gafas ____ sol.","o":["de","por","a","para"],"a":0,"k":"전치사 de (용도)","t":"빛을 못 견디겠어, 선글라스가 필요해.","e":"gafas de sol(선글라스)처럼 'de + 명사'는 물건의 종류나 용도를 나타냅니다. 비슷한 예로 crema de sol(선크림), traje de baño(수영복)가 있습니다. 하나의 단어처럼 외워 두면 좋습니다.","x":["de: gafas de sol '선글라스' → 정답 ✓","por: '~때문에, ~을 통해'의 의미라 물건 종류를 나타내지 않습니다 ✗","a: gafas a sol이라는 표현은 없습니다 ✗","para: 의미는 통할 것 같지만 '선글라스'의 정해진 표현은 gafas de sol입니다 ✗"]},{"id":"G464","q":"____ cuidado cuando conduzcas, debes prestar atención en todo momento.","o":["Tened","Ten","Tenga","Tiene"],"a":1,"k":"tú 긍정 명령형","t":"운전할 때 조심해, 항상 주의를 기울여야 해.","e":"문장 뒤의 conduzcas, debes가 tú(너) 형태이므로 명령도 tú에게 하는 것입니다. tener의 tú 긍정 명령형은 불규칙형 ten입니다. tener cuidado는 '조심하다'라는 표현입니다.","x":["Tened: vosotros(너희들) 명령형이라 tú 문장과 맞지 않습니다 ✗","Ten: tener의 tú 긍정 명령형(불규칙) → 정답 ✓","Tenga: usted(당신) 명령형이라 뒤의 tú와 맞지 않습니다 ✗","Tiene: 직설법 현재 3인칭(그가 가진다)이라 명령이 아닙니다 ✗"]},{"id":"G465","q":"Está llorando ____ echa de menos a su mamá.","o":["por que","por qué","porque","porqué"],"a":2,"k":"porque/por qué","t":"엄마가 보고 싶어서 울고 있다.","e":"이유를 설명하는 접속사 '왜냐하면, ~해서'는 붙여 쓰고 악센트가 없는 porque입니다. por qué는 '왜?'라는 의문사, porqué는 '이유'라는 명사, por que는 '전치사 por + 관계사 que'입니다. 네 가지를 구별해서 기억하세요.","x":["por que: 전치사 + 관계사 조합으로 이유 접속사가 아닙니다 ✗","por qué: '왜?'라는 의문사라 설명 문장에 맞지 않습니다 ✗","porque: '~때문에'라는 이유 접속사 → 정답 ✓","porqué: '이유'라는 명사(el porqué)라 맞지 않습니다 ✗"]},{"id":"G466","q":"Estos patines son ____ que esos.","o":["más peores","tan buenos","peores","mejor"],"a":2,"k":"비교급 peor","t":"이 롤러스케이트는 저것들보다 더 나쁘다.","e":"malo(나쁜)의 비교급은 불규칙형 peor(더 나쁜)이며, 복수 명사 patines에 맞춰 peores가 됩니다. peor에 이미 '더'의 뜻이 들어 있어서 más를 붙이지 않습니다. 뒤의 que(~보다)와도 잘 어울립니다.","x":["más peores: peor에 이미 '더'가 포함되어 más를 붙이면 틀립니다 ✗","tan buenos: 동등비교는 tan ... como를 써야 하므로 que와 맞지 않습니다 ✗","peores: 복수 비교급 '더 나쁜' → 정답 ✓","mejor: 단수형이라 복수 patines와 맞지 않습니다 ✗"]},{"id":"G467","q":"Ya no queda ____ pan, voy a la panadería.","o":["ø","un","el","la"],"a":0,"k":"관사 생략","t":"빵이 더 이상 안 남았어, 빵집에 갈게.","e":"pan(빵)처럼 셀 수 없는 명사를 '조금이라도, 일반적으로' 말할 때는 관사를 쓰지 않습니다. no queda pan은 '빵이 남아 있지 않다'는 뜻입니다. 예: No hay leche.(우유가 없다.)","x":["ø: 셀 수 없는 명사를 일반적으로 말할 때 관사 생략 → 정답 ✓","un: '빵 한 개'라는 뜻이 되어 문맥상 어색합니다 ✗","el: 특정한 빵을 가리키게 되어 '빵이 전혀 없다'는 의미와 맞지 않습니다 ✗","la: pan은 남성 명사라 여성 관사와 맞지 않습니다 ✗"]},{"id":"G468","q":"____ en primavera, por eso ves jardines con tantas flores.","o":["Estemos","Somos","Estamos","Seamos"],"a":2,"k":"estar en + 계절","t":"지금은 봄이야, 그래서 꽃이 이렇게 많은 정원들이 보이는 거야.","e":"'(우리는) 지금 ~계절에 있다'는 estar en + 계절로 표현합니다. 사실을 말하는 문장이므로 직설법 현재 estamos가 맞습니다. 참고로 'Es primavera.(봄이다)'처럼 관사·전치사 없이 ser를 쓰는 표현도 있습니다.","x":["Estemos: 접속법이라 단순한 사실 서술에 쓰지 않습니다 ✗","Somos: ser는 en primavera(봄에)와 함께 '우리가 봄에 있다'는 의미를 만들지 못합니다 ✗","Estamos: estar en primavera '봄이다' → 정답 ✓","Seamos: ser의 접속법이라 문장에 맞지 않습니다 ✗"]},{"id":"G469","q":"Tengo ____ hacer muchas cosas esta tarde.","o":["ø","de","que","a"],"a":2,"k":"tener que + 원형","t":"오늘 오후에 해야 할 일이 많다.","e":"tener que + 동사원형은 '~해야 한다'라는 의무 표현입니다. Tengo que hacer는 '나는 해야 한다'가 됩니다. 예: Tienes que estudiar.(너는 공부해야 해.)","x":["ø: tener 뒤에 바로 동사원형이 올 수 없습니다 ✗","de: tener de라는 의무 표현은 현대 스페인어에서 쓰지 않습니다(haber de와 혼동 주의) ✗","que: tener que '~해야 한다' → 정답 ✓","a: tener a + 원형이라는 표현은 없습니다 ✗"]},{"id":"G470","q":"Esteban ya es igual de alto ____ su padre.","o":["con","como","que","a"],"a":2,"k":"igual de...que","t":"에스테반은 이제 아빠만큼 키가 크다.","e":"'~만큼 …하다'는 igual de + 형용사 + que로 표현합니다. tan alto como와 같은 뜻이지만, igual de 뒤에는 como가 아니라 que를 씁니다. 예: Es igual de difícil que el otro.(그것은 다른 것만큼 어렵다.)","x":["con: igual con이라는 비교 구문은 없습니다 ✗","como: tan ... como와 섞인 형태로, 일상에서 들리지만 규범적으로는 que를 씁니다 ✗","que: igual de ... que '~만큼 …한' → 정답 ✓","a: igual a는 '~와 똑같다'로 형용사가 끼면 쓰지 않습니다 ✗"]},{"id":"G471","q":"Tu habitación está muy desordenada, ____.","o":["ordena la","ordénala","ordénalo","ordenarla"],"a":1,"k":"명령형 + 대명사","t":"네 방이 너무 지저분하구나, 정리해.","e":"긍정 명령형에서는 목적격 대명사를 동사 뒤에 붙여 한 단어로 씁니다. habitación은 여성 명사이므로 la를 쓰고, 붙인 뒤 원래 강세를 지키기 위해 악센트를 찍어 ordénala가 됩니다.","x":["ordena la: 긍정 명령형에서는 대명사를 띄어 쓰지 않고 붙입니다 ✗","ordénala: 명령형 + la(그것을), 악센트도 정확 → 정답 ✓","ordénalo: lo는 남성이라 여성 명사 habitación과 맞지 않습니다 ✗","ordenarla: 동사원형이라 명령문으로 쓸 수 없습니다 ✗"]},{"id":"G472","q":"Sara nunca espera ____ nadie, es la persona más impaciente que conozco.","o":["para","a","por","ø"],"a":1,"k":"사람 목적어 a","t":"사라는 절대 누구도 기다리지 않아, 내가 아는 가장 참을성 없는 사람이야.","e":"직접목적어가 사람일 때는 앞에 전치사 a를 붙입니다(사람 목적어의 a). nadie(아무도)도 사람을 가리키므로 esperar a nadie가 됩니다. 예: Espero a mi hermano.(나는 동생을 기다린다.)","x":["para: '~를 위해'라는 뜻이라 맞지 않습니다 ✗","a: 사람 직접목적어 앞의 a → 정답 ✓","por: esperar por는 일부 중남미에서 들리지만 표준적인 형태는 아닙니다 ✗","ø: 사람 목적어 앞에는 a가 필요합니다 ✗"]},{"id":"G473","q":"Mi amigo Eloy está ____ camarero en una cafetería.","o":["ø","por","de","a"],"a":2,"k":"estar de + 직업","t":"내 친구 엘로이는 한 카페에서 웨이터로 일하고 있다.","e":"estar de + 직업은 '(임시로) ~로 일하고 있다'라는 뜻입니다. 원래 직업이 아니거나 일시적인 일일 때 자주 씁니다. 반면 'Es camarero.'는 그의 직업이 웨이터라는 일반적인 설명입니다.","x":["ø: estar 바로 뒤에 직업 명사를 쓸 수 없습니다 ✗","por: estar por는 '~할 참이다/~에 찬성이다'라는 다른 뜻입니다 ✗","de: estar de camarero '웨이터로 일하는 중' → 정답 ✓","a: estar a camarero라는 표현은 없습니다 ✗"]},{"id":"G474","q":"Alicia está enamorada ____ David.","o":["con","por","a","de"],"a":3,"k":"enamorado de","t":"알리시아는 다비드를 사랑하고 있다.","e":"'~에게 반하다, ~를 사랑하다'는 enamorarse de / estar enamorado de로 전치사 de를 씁니다. 한국어로는 '~에게'라서 a나 con을 고르기 쉽지만 de가 정답입니다. 예: Me enamoré de ella.(나는 그녀에게 반했다.)","x":["con: 영어 in love with를 떠올리기 쉽지만 스페인어에서는 쓰지 않습니다 ✗","por: enamorado por라는 표현은 쓰지 않습니다 ✗","a: enamorado a라는 표현은 쓰지 않습니다 ✗","de: estar enamorado de '~를 사랑하다' → 정답 ✓"]},{"id":"G475","q":"____ años los niños hacían más actividades físicas que en la actualidad.","o":["Desde","Antes de","Hace","Desde hace"],"a":2,"k":"hace + 기간","t":"몇 년 전에는 아이들이 요즘보다 신체 활동을 더 많이 했다.","e":"hace + 기간은 '~ 전에'라는 뜻으로, 과거의 한 시점을 나타냅니다. Hace años는 '몇 년 전에(옛날에)'라는 의미이며 뒤의 과거형 hacían과 어울립니다. 예: Hace dos días llovió.(이틀 전에 비가 왔다.)","x":["Desde: '~부터'라는 시작점이라 뒤에 기간만 오면 어색합니다 ✗","Antes de: '~하기 전에'로 뒤에 사건·시간이 와야 하며 años만으로는 맞지 않습니다 ✗","Hace: hace años '몇 년 전에' → 정답 ✓","Desde hace: '~ 전부터 (지금까지)'라는 계속의 의미라 과거형과 맞지 않습니다 ✗"]},{"id":"G476","q":"Voy a abrir la ventana ____ entre el aire.","o":["por que","para que","de que","a que"],"a":1,"k":"para que + 접속법","t":"공기가 들어오도록 창문을 열게.","e":"para que는 '~하도록, ~하기 위해'라는 목적을 나타내며, 뒤에는 항상 접속법(바람·목적 등을 나타내는 동사 형태)이 옵니다. entre는 entrar의 접속법 현재형입니다. 주어가 달라질 때(나 ↔ 공기) para que를 씁니다.","x":["por que: 전치사 + 관계사 조합이라 목적을 나타내지 않습니다 ✗","para que: 목적 '~하도록' + 접속법 → 정답 ✓","de que: 목적의 의미가 없습니다 ✗","a que: 일부 동사 뒤(venir a que)에서만 쓰며 여기서는 어색합니다 ✗"]},{"id":"G477","q":"Mis hijos se llevan ____, no suelen discutir.","o":["bien","buen","buena","bueno"],"a":0,"k":"부사 bien","t":"우리 아이들은 사이가 좋아서 별로 다투지 않는다.","e":"llevarse bien은 '사이가 좋다'라는 표현입니다. 동사를 꾸미므로 형용사(bueno)가 아닌 부사 bien을 씁니다. 반대는 llevarse mal(사이가 나쁘다)입니다.","x":["bien: 동사를 꾸미는 부사, llevarse bien '사이가 좋다' → 정답 ✓","buen: 남성 단수 명사 앞에 오는 형용사라 동사를 꾸밀 수 없습니다 ✗","buena: 여성형 형용사라 동사를 꾸밀 수 없습니다 ✗","bueno: 형용사라 동사를 꾸밀 수 없습니다 ✗"]},{"id":"G478","q":"No se puede ____ usar la cámara en esta sala, lo siento.","o":["a","con","de","ø"],"a":3,"k":"poder + 원형","t":"죄송하지만, 이 전시실에서는 카메라를 사용할 수 없습니다.","e":"poder(~할 수 있다) 뒤에는 전치사 없이 바로 동사원형이 옵니다. se puede는 '(일반적으로) ~할 수 있다'라는 무인칭 표현입니다. 예: No se puede entrar.(들어갈 수 없습니다.)","x":["a: poder 뒤에 a를 넣지 않습니다 ✗","con: poder 뒤에 con을 넣지 않습니다 ✗","de: poder 뒤에 de를 넣지 않습니다 ✗","ø: poder + 동사원형을 바로 연결 → 정답 ✓"]},{"id":"G479","q":"No sé dónde ____ dentro de cinco años.","o":["estaré","esté","estoy","estuve"],"a":0,"k":"단순미래","t":"5년 후에 내가 어디에 있을지 모르겠다.","e":"dentro de cinco años(5년 후에)는 미래 시점이므로 단순미래 estaré를 씁니다. no sé dónde처럼 간접의문문(의문사가 문장 안에 들어간 형태) 안에서는 접속법이 아니라 직설법을 씁니다. 예: No sé qué haré mañana.(내일 무엇을 할지 모르겠다.)","x":["estaré: 미래형 '있을 것이다' → 정답 ✓","esté: 접속법이라 간접의문문 dónde 뒤에 쓰지 않습니다 ✗","estoy: 현재형이라 5년 후라는 미래 시점과 맞지 않습니다 ✗","estuve: 단순과거라 미래 시점과 맞지 않습니다 ✗"]},{"id":"G480","q":"Mercedes tiene ____ años.","o":["cuarenta un","cuarenta y un","cuarenta y uno","cuarenta uno"],"a":1,"k":"숫자 (y + un)","t":"메르세데스는 41살이다.","e":"31부터 99까지는 십의 자리와 일의 자리 사이에 y를 넣어 씁니다(cuarenta y uno). 또 uno는 남성 명사 앞에서 un으로 줄어들기 때문에 años 앞에서는 cuarenta y un이 됩니다. 예: veintiún años(21살), treinta y un días(31일).","x":["cuarenta un: y가 빠져서 틀립니다 ✗","cuarenta y un: y 포함 + 명사 앞 un → 정답 ✓","cuarenta y uno: 남성 명사 años 앞에서는 un으로 줄여야 합니다 ✗","cuarenta uno: y도 빠지고 un으로 줄이지도 않아 틀립니다 ✗"]},{"id":"G481","q":"Gracias a esta dieta, Marga ha adelgazado ____.","o":["muchos","mucha","muchísima","muchísimo"],"a":3,"k":"부사 muchísimo","t":"이 다이어트 덕분에 마르가는 살이 아주 많이 빠졌다.","e":"adelgazar(살이 빠지다)라는 동사를 꾸미므로 형태가 변하지 않는 부사가 필요합니다. muchísimo는 mucho(많이)의 최상급(-ísimo)으로 '아주 많이'라는 뜻입니다. 부사로 쓸 때는 항상 -o 형태입니다.","x":["muchos: 남성 복수 형용사라 동사를 꾸밀 수 없습니다 ✗","mucha: 여성 단수 형용사라 동사를 꾸밀 수 없습니다 ✗","muchísima: 여성형 형용사라 동사를 꾸밀 수 없습니다 ✗","muchísimo: 동사를 꾸미는 부사 '아주 많이' → 정답 ✓"]},{"id":"G482","q":"Niños, ____ aquí, tengo que deciros una cosa.","o":["venís","venid","vengan","vienen"],"a":1,"k":"vosotros 명령형","t":"얘들아, 이리 와, 너희에게 할 말이 있어.","e":"뒤의 deciros(너희에게 말하다)에서 상대가 vosotros(너희들)임을 알 수 있습니다. vosotros 긍정 명령형은 동사원형의 -r를 -d로 바꿔 만들므로 venir → venid가 됩니다. 중남미에서는 vosotros 대신 ustedes를 써서 vengan이라고 합니다.","x":["venís: 직설법 현재(너희가 온다)라 명령이 아닙니다 ✗","venid: vosotros 긍정 명령형 → 정답 ✓","vengan: ustedes 명령형으로 중남미에서는 쓰지만, deciros(vosotros)와 맞지 않습니다 ✗","vienen: 직설법 현재 3인칭 복수라 명령이 아닙니다 ✗"]},{"id":"G483","q":"Cada sábado ____ al fútbol con mi grupo de amigos.","o":["jugué","juego","juegue","jugo"],"a":1,"k":"직설법 현재 (습관)","t":"매주 토요일 나는 친구들과 축구를 한다.","e":"cada sábado(매주 토요일)는 반복되는 습관을 나타내므로 직설법 현재를 씁니다. jugar는 어간이 u → ue로 바뀌는 불규칙 동사라 1인칭 단수는 juego입니다. jugar al fútbol(축구를 하다)도 함께 기억하세요.","x":["jugué: 단순과거(나는 했다)라 반복 습관과 맞지 않습니다 ✗","juego: jugar의 현재 1인칭 단수(u→ue) → 정답 ✓","juegue: 접속법이라 사실 서술에 맞지 않습니다 ✗","jugo: 동사 형태가 아니라 '주스'라는 명사입니다 ✗"]},{"id":"G484","q":"Compré aguacates ____ hacer guacamole.","o":["para","hasta","a","por"],"a":0,"k":"para + 원형 (목적)","t":"과카몰리를 만들려고 아보카도를 샀다.","e":"'~하기 위해서'라는 목적은 para + 동사원형으로 나타냅니다. 아보카도를 산 목적이 과카몰리를 만드는 것이므로 para가 맞습니다. 예: Estudio para aprobar.(나는 합격하려고 공부한다.)","x":["para: 목적 '~하기 위해' → 정답 ✓","hasta: '~까지'라는 뜻이라 맞지 않습니다 ✗","a: 이동 동사 뒤(Voy a comprar)가 아니면 목적을 나타내지 않습니다 ✗","por: 원인·이유를 나타내서 목적의 의미와 맞지 않습니다 ✗"]},{"id":"G485","q":"Según ____, ¿quién es la mejor jugadora del equipo?","o":["ti","tú","tu","te"],"a":1,"k":"según + 주격 대명사","t":"네 생각에는 팀에서 누가 최고의 선수야?","e":"대부분의 전치사 뒤에는 ti, mí 같은 전치격 대명사를 쓰지만, según(~에 따르면), entre(~사이에)는 예외로 주격 대명사(yo, tú)를 씁니다. 그래서 según tú(네 생각에는)가 맞습니다. 예: según yo(내 생각에는)는 맞고, según mí는 틀립니다.","x":["ti: 일반 전치사 뒤의 형태지만 según 뒤에는 쓰지 않습니다 ✗","tú: según 뒤에는 주격 대명사 → 정답 ✓","tu: 악센트 없는 tu는 소유형용사(너의)라 뒤에 명사가 필요합니다 ✗","te: 목적격 대명사라 전치사 뒤에 올 수 없습니다 ✗"]},{"id":"G486","q":"¿____ has finalizado tus estudios universitarios?","o":["Aún","Ya no","Ya","Todavía"],"a":2,"k":"ya (벌써, 이미)","t":"대학 공부를 벌써 마쳤어?","e":"ya는 현재완료와 함께 '벌써, 이미 ~했다'라는 뜻으로 씁니다. 대학 공부를 끝냈는지 묻는 문장이므로 ¿Ya has finalizado...?가 자연스럽습니다. 부정은 todavía no / aún no(아직 ~ 안 했다)입니다.","x":["Aún: 긍정문에서는 '아직도 ~하다'라는 뜻이라 '마쳤다'와 맞지 않습니다 ✗","Ya no: '더 이상 ~않다'라는 뜻이라 문맥에 맞지 않습니다 ✗","Ya: '벌써 ~했어?' → 정답 ✓","Todavía: 긍정 의미로는 '아직도'라서 완료된 일과 맞지 않습니다 ✗"]},{"id":"G487","q":"¿____ de los dos celulares tiene batería?","o":["Cuándo","Cuál","Qué","Quién"],"a":1,"k":"의문사 cuál","t":"두 휴대폰 중에 어느 것이 배터리가 있어?","e":"정해진 여러 개 중 '어느 것'을 고를 때는 cuál을 씁니다. de los dos(둘 중에서)가 있어 선택의 의미가 분명하므로 Cuál이 맞습니다. celular는 중남미에서 쓰는 '휴대폰'이며, 스페인에서는 móvil이라고 합니다.","x":["Cuándo: '언제'라는 시간 의문사라 맞지 않습니다 ✗","Cuál: 정해진 것 중 '어느 것' → 정답 ✓","Qué: 명사 없이 'de los dos' 앞에서 선택을 나타내지 않습니다 ✗","Quién: '누구'라서 사람에게만 씁니다 ✗"]},{"id":"G488","q":"____ una telenovela tranquilamente cuando, de pronto, escuché un fuerte ruido.","o":["Estuve viendo","Vi","Estaba viendo","Veía"],"a":2,"k":"과거진행 (배경)","t":"편하게 드라마를 보고 있었는데, 갑자기 큰 소리가 들렸다.","e":"과거에 어떤 행동이 진행 중일 때 다른 일이 갑자기 끼어드는 경우, 진행 중이던 배경은 estaba + 현재분사(과거진행)로, 끼어든 사건은 단순과거로 씁니다. 그래서 Estaba viendo(보고 있었다) + escuché(들었다)가 됩니다. telenovela는 '텔레비전 연속극(드라마)'입니다.","x":["Estuve viendo: 단순과거 진행으로, 끝난 기간 전체를 말할 때 써서 배경 묘사에 맞지 않습니다 ✗","Vi: 단순과거라 '진행 중이던 배경'을 나타내지 못합니다 ✗","Estaba viendo: 과거진행 '보고 있던 중' → 정답 ✓","Veía: 배경으로 가능은 하지만 '그 순간 진행 중'임을 강조하는 데는 과거진행이 가장 알맞습니다 ✗"]},{"id":"G489","q":"Por favor, no me ____ en ese tono.","o":["hablas","habla","hables","hablad"],"a":2,"k":"부정 명령 (접속법)","t":"제발 나한테 그런 말투로 말하지 마.","e":"부정 명령(~하지 마)은 no + 접속법 현재로 만듭니다. tú에 대한 hablar의 부정 명령은 no hables입니다. 긍정 명령 habla와 형태가 다르다는 점에 주의하세요.","x":["hablas: 직설법 현재(너는 말한다)라 명령이 아닙니다 ✗","habla: tú 긍정 명령형이라 no와 함께 쓰지 않습니다 ✗","hables: no + 접속법, tú 부정 명령 → 정답 ✓","hablad: vosotros 긍정 명령형이라 no와 함께 쓰지 않습니다 ✗"]},{"id":"G490","q":"Todavía no ____ listos para salir.","o":["estamos","hemos estado","somos","hemos sido"],"a":0,"k":"estar listo","t":"우리는 아직 나갈 준비가 안 됐다.","e":"listo는 ser와 쓰면 '똑똑하다', estar와 쓰면 '준비가 되다'라는 뜻이 됩니다. 나갈 준비를 말하므로 estar를 쓰고, 지금 상태이므로 현재형 estamos가 맞습니다. 예: ¿Estás listo?(준비됐어?)","x":["estamos: estar listo '준비되다' 현재형 → 정답 ✓","hemos estado: 현재완료라 '아직 준비 안 됐다'는 현재 상태와 맞지 않습니다 ✗","somos: ser listo는 '똑똑하다'라는 뜻이 됩니다 ✗","hemos sido: ser의 현재완료라 뜻도 시제도 맞지 않습니다 ✗"]},{"id":"G491","q":"Somos vegetarianos, no comemos casi ____ producto de origen animal.","o":["ninguno","ningún","nada","algún"],"a":1,"k":"ningún","t":"우리는 채식주의자라서 동물성 제품은 거의 아무것도 먹지 않는다.","e":"ninguno(어떤 ~도 아닌)는 남성 단수 명사 앞에서 ningún으로 줄어듭니다. producto는 남성 단수이므로 ningún producto가 됩니다. no ... ningún처럼 이중 부정을 쓰는 것이 스페인어에서는 자연스럽습니다.","x":["ninguno: 명사 앞에서는 ningún으로 줄여야 합니다 ✗","ningún: 남성 단수 명사 앞 축약형 → 정답 ✓","nada: '아무것도'라는 대명사라 명사 앞에 형용사처럼 쓰지 않습니다 ✗","algún: '어떤'이라는 긍정 의미라 부정문 no와 맞지 않습니다 ✗"]},{"id":"G492","q":"Mariano ____ mal porque apenas tiene dinero para llegar a fin de mes.","o":["es","está","siente","tiene"],"a":1,"k":"estar mal (상태)","t":"마리아노는 월말까지 버틸 돈이 거의 없어서 사정이 안 좋다.","e":"estar mal은 '상태가 좋지 않다, 힘든 상황이다'라는 뜻으로, 일시적인 상태를 나타내는 estar를 씁니다. 돈이 부족한 지금의 상황을 말하므로 está mal이 맞습니다. llegar a fin de mes는 '월말까지 버티다(생활비가 충분하다)'라는 관용 표현입니다.","x":["es: ser mal은 쓰지 않으며, 상태를 말할 때는 estar를 씁니다 ✗","está: estar mal '상황이 안 좋다' → 정답 ✓","siente: 기분을 말하려면 재귀형 se siente mal이 필요합니다 ✗","tiene: tener mal이라는 표현은 쓰지 않습니다 ✗"]},{"id":"G493","q":"El arma que tiene ese tipo es muy ____.","o":["peligrosa","peligrosas","peligroso","peligrosos"],"a":0,"k":"el + 여성 명사","t":"그 남자가 가진 무기는 아주 위험하다.","e":"arma(무기)는 여성 명사지만, 강세가 있는 a-로 시작하기 때문에 발음상 단수 관사로 el을 씁니다(el arma). 그래도 명사 자체는 여성이므로 형용사는 여성형 peligrosa를 씁니다. 같은 예: el agua fría(차가운 물).","x":["peligrosa: 여성 단수 형용사, 여성 명사 arma와 일치 → 정답 ✓","peligrosas: 복수형이라 단수 arma와 맞지 않습니다 ✗","peligroso: el 때문에 남성으로 착각하기 쉽지만 arma는 여성 명사입니다 ✗","peligrosos: 남성 복수라 성과 수가 모두 맞지 않습니다 ✗"]},{"id":"G494","q":"Marcos ____ abogado.","o":["eres","es","está","estás"],"a":1,"k":"ser + 직업","t":"마르코스는 변호사다.","e":"직업을 말할 때는 ser를 쓰고, 관사 없이 직업 명사를 바로 씁니다. 주어 Marcos는 3인칭 단수이므로 es가 맞습니다. 참고로 일시적인 일은 estar de + 직업으로 표현합니다.","x":["eres: 2인칭 단수(너는 ~이다)라 주어와 맞지 않습니다 ✗","es: ser 3인칭 단수, 직업 표현 → 정답 ✓","está: estar는 직업 명사를 바로 받지 못합니다(estar de abogado처럼 써야 함) ✗","estás: 2인칭이고 estar라서 두 가지 다 맞지 않습니다 ✗"]},{"id":"G495","q":"Mis últimos exámenes serán ____ julio.","o":["antes","de","a","en"],"a":3,"k":"en + 달","t":"내 마지막 시험들은 7월에 있을 것이다.","e":"달(월) 앞에는 전치사 en을 써서 '~월에'를 나타냅니다. en julio는 '7월에'입니다. 날짜를 말할 때는 el 5 de julio처럼 de를 씁니다.","x":["antes: antes de julio처럼 de가 필요하며 그대로는 틀립니다 ✗","de: 날짜 표현(el 5 de julio)에서만 쓰고 단독으로는 맞지 않습니다 ✗","a: 달 앞에 a를 쓰지 않습니다 ✗","en: en julio '7월에' → 정답 ✓"]},{"id":"G496","q":"¡____ bien tocas el piano!","o":["Por qué","Cómo","Cuánto","Qué"],"a":3,"k":"감탄문 qué","t":"너 피아노 정말 잘 친다!","e":"¡Qué + 형용사/부사!는 '정말 ~하구나!'라는 감탄 표현입니다. bien(잘)이라는 부사 앞이므로 ¡Qué bien...!이 됩니다. 예: ¡Qué bonito!(정말 예쁘다!)","x":["Por qué: '왜'라는 의문사라 감탄문에 맞지 않습니다 ✗","Cómo: ¡Cómo tocas el piano!(어쩜 그렇게 치니!)는 되지만 bien 앞에는 쓰지 않습니다 ✗","Cuánto: '얼마나 많이'라서 부사 bien 앞에 쓰지 않습니다 ✗","Qué: ¡Qué + 부사! '정말 ~하다!' → 정답 ✓"]},{"id":"G497","q":"No ____ nada bien la ropa de color beis.","o":["me queda","quedarme","quede","me quedo"],"a":0,"k":"quedar (어울리다)","t":"베이지색 옷은 나한테 전혀 안 어울린다.","e":"quedar bien/mal은 '(옷 등이) ~에게 잘 어울린다/안 어울린다'라는 뜻으로, gustar처럼 사람을 간접목적격 대명사(me, te, le…)로 씁니다. 주어는 la ropa(3인칭 단수)이므로 me queda가 맞습니다. 예: Esa camisa te queda muy bien.(그 셔츠 너한테 잘 어울려.)","x":["me queda: '나에게 어울린다', 주어 la ropa와 일치 → 정답 ✓","quedarme: 동사원형이라 문장의 본동사가 될 수 없습니다 ✗","quede: 접속법이고 대명사도 없어 맞지 않습니다 ✗","me quedo: 재귀형 quedarse는 '머물다'라는 다른 뜻입니다 ✗"]},{"id":"G498","q":"El sábado es ____ día de la semana.","o":["seis","el seis","el sexto","sexto"],"a":2,"k":"서수 sexto","t":"토요일은 일주일 중 여섯 번째 날이다.","e":"'몇 번째'는 서수(primero, segundo, tercero…)로 나타냅니다. 스페인어권에서는 월요일을 한 주의 첫날로 보기 때문에 토요일은 여섯 번째(sexto)입니다. 특정한 날을 가리키므로 정관사를 붙여 el sexto día가 됩니다.","x":["seis: 기수(6)라 '여섯 번째'를 나타내지 못합니다 ✗","el seis: '6일, 6번'이라는 뜻이라 맞지 않습니다 ✗","el sexto: 정관사 + 서수 '여섯 번째' → 정답 ✓","sexto: 이 문장에서는 특정한 날이므로 정관사가 필요합니다 ✗"]},{"id":"G499","q":"En mi estuche hay lápices, bolis, una goma y ____ sacapuntas metálico.","o":["uno","un","unos","unas"],"a":1,"k":"부정관사 un","t":"내 필통에는 연필, 볼펜, 지우개 하나, 그리고 금속 연필깎이 하나가 있다.","e":"sacapuntas(연필깎이)는 -s로 끝나지만 단수와 복수가 같은 남성 명사입니다. 여기서는 '하나'를 말하므로 남성 단수 부정관사 un을 씁니다. metálico(남성 단수)라는 형용사로도 단수임을 알 수 있습니다.","x":["uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","unos: 복수형이라 단수형 형용사 metálico와 맞지 않습니다 ✗","unas: 여성 복수형이라 성과 수가 맞지 않습니다 ✗"]},{"id":"G500","q":"Prefiero hacer gimnasia por ____ tarde.","o":["la","ø","las","el"],"a":0,"k":"por la tarde","t":"나는 오후에 체조하는 것을 더 좋아한다.","e":"하루의 시간대는 por la mañana(오전에), por la tarde(오후에), por la noche(밤에)처럼 por + 정관사로 표현합니다. tarde는 여성 명사이므로 la를 씁니다. 중남미에서는 en la tarde라고도 합니다.","x":["la: por la tarde '오후에' → 정답 ✓","ø: 관사 없이 por tarde라고 하지 않습니다 ✗","las: 복수형이라 맞지 않습니다(a las tres처럼 시각에 씀) ✗","el: tarde는 여성 명사라 남성 관사와 맞지 않습니다 ✗"]},{"id":"G501","q":"El oro es más caro ____ la plata.","o":["como","de","que","a"],"a":2,"k":"más ... que","t":"금은 은보다 더 비싸다.","e":"우등비교(~보다 더 …하다)는 más + 형용사 + que로 나타냅니다. 금과 은을 비교하므로 más caro que la plata가 맞습니다. 숫자 앞에서만 más de(más de cien euros)를 씁니다.","x":["como: 동등비교 tan ... como에서 쓰는 단어입니다 ✗","de: 숫자·양 앞에서만 쓰고 비교 대상 앞에는 쓰지 않습니다 ✗","que: más ... que '~보다 더' → 정답 ✓","a: 비교 구문에 a를 쓰지 않습니다(superior a 등 예외 제외) ✗"]},{"id":"G502","q":"¿Alguna vez ____ un fantasma?","o":["veían","verían","han visto","vean"],"a":2,"k":"현재완료 (경험)","t":"유령을 본 적 있어요?","e":"alguna vez(언젠가, 한 번이라도)와 함께 '~해 본 적 있다'는 경험을 물을 때는 현재완료를 씁니다. han visto는 haber + visto(ver의 불규칙 과거분사)입니다. 예: ¿Has estado alguna vez en México?(멕시코에 가 본 적 있어?)","x":["veían: 불완료과거(보곤 했다)라 경험을 묻는 데 맞지 않습니다 ✗","verían: 가정법 조건(볼 텐데)이라 맞지 않습니다 ✗","han visto: 현재완료 경험 '본 적 있다' → 정답 ✓","vean: 접속법이라 단독 의문문에 맞지 않습니다 ✗"]},{"id":"G503","q":"¿Cuántos huevos necesitamos ____ hacer la tortilla?","o":["para","a","de","por"],"a":0,"k":"para + 원형 (목적)","t":"토르티야를 만들려면 계란이 몇 개 필요해?","e":"'~하기 위해'라는 목적은 para + 동사원형으로 나타냅니다. 계란이 필요한 목적이 토르티야를 만드는 것이므로 para hacer가 맞습니다. 스페인의 tortilla는 감자와 계란으로 만든 두툼한 오믈렛입니다(멕시코의 토르티야와 다름).","x":["para: 목적 '~하기 위해' → 정답 ✓","a: 이동 동사 뒤가 아니면 목적을 나타내지 않습니다 ✗","de: 목적의 의미가 없습니다 ✗","por: 원인·이유를 나타내어 목적과 맞지 않습니다 ✗"]},{"id":"G504","q":"Ahora no hago ____ deporte como antes porque no tengo tiempo.","o":["tan","tanta","tanto","tantas"],"a":2,"k":"tanto ... como","t":"시간이 없어서 지금은 예전만큼 운동을 많이 하지 않는다.","e":"명사의 양을 비교할 때는 tanto/tanta/tantos/tantas + 명사 + como(~만큼 많은)를 쓰고, 명사의 성·수에 맞춥니다. deporte는 남성 단수이므로 tanto가 맞습니다. 형용사·부사 앞에서는 tan을 씁니다.","x":["tan: 형용사·부사 앞에서만 쓰고 명사 앞에는 쓰지 않습니다 ✗","tanta: 여성 단수라 남성 명사 deporte와 맞지 않습니다 ✗","tanto: 남성 단수 명사 deporte와 일치 → 정답 ✓","tantas: 여성 복수라 성과 수가 맞지 않습니다 ✗"]},{"id":"G505","q":"Necesito ____ champú especial para pelo seco.","o":["un","uno","una","de una"],"a":0,"k":"부정관사 un","t":"건성 모발용 특수 샴푸가 필요해.","e":"champú(샴푸)는 남성 명사이고 '하나의, 어떤'을 말하므로 남성 단수 부정관사 un을 씁니다. especial은 남녀 형태가 같은 형용사입니다. 예: un champú, una crema.","x":["un: 남성 단수 명사 앞 부정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","una: 여성형이라 남성 명사 champú와 맞지 않습니다 ✗","de una: 필요 없는 전치사가 들어가고 성도 맞지 않습니다 ✗"]},{"id":"G506","q":"¿Puede ayudarme ____ a llevar estas cajas?","o":["algún","algo","alguien","algunos"],"a":2,"k":"부정대명사 alguien","t":"누가 이 상자들 나르는 거 좀 도와줄 수 있나요?","e":"alguien은 '누군가'라는 뜻의 대명사로, 사람을 가리키며 혼자서 주어가 될 수 있습니다. 상자를 들어 줄 '누군가'를 찾는 문장이므로 alguien이 맞습니다. 반대말은 nadie(아무도)입니다.","x":["algún: 명사 앞에만 쓰는 형용사라 혼자 주어가 될 수 없습니다 ✗","algo: '무언가'로 사물을 가리켜 맞지 않습니다 ✗","alguien: '누군가'(사람) → 정답 ✓","algunos: 복수라서 3인칭 단수 동사 puede와 맞지 않습니다 ✗"]},{"id":"G507","q":"Aquí no ____ fumar, está prohibido.","o":["se pueden","te puedes","se puede","poder"],"a":2,"k":"무인칭 se puede","t":"여기서는 담배를 피울 수 없어요, 금지되어 있어요.","e":"se + 3인칭 단수 동사는 '(사람들이 일반적으로) ~한다'라는 무인칭 표현입니다. 뒤에 동사원형 fumar가 오므로 단수 se puede를 씁니다. 예: Aquí no se puede aparcar.(여기는 주차 금지입니다.)","x":["se pueden: 복수형은 뒤에 복수 명사가 올 때 쓰며 동사원형 앞에서는 단수입니다 ✗","te puedes: 재귀형이라 '너 자신을'이 되어 문장과 맞지 않습니다 ✗","se puede: 무인칭 '~할 수 있다' → 정답 ✓","poder: 동사원형이라 본동사로 쓸 수 없습니다 ✗"]},{"id":"G508","q":"Necesitamos que nos ____ de lo que ha pasado.","o":["informarán","informar","informan","informen"],"a":3,"k":"necesitar que","t":"무슨 일이 있었는지 우리에게 알려 줄 필요가 있어요.","e":"necesitar que(~가 …해 주기를 필요로 하다)처럼 바람·요구를 나타내는 동사 뒤에 주어가 바뀌면 접속법(바람·의심 등을 나타내는 동사 형태)을 씁니다. 여기서 informen은 informar의 접속법 현재 3인칭 복수입니다. 예: Necesito que me ayudes.(네가 나를 도와줘야 해.)","x":["informarán: 직설법 미래라 바람의 que 뒤에 쓰지 않습니다 ✗","informar: 동사원형은 que 뒤에 올 수 없습니다 ✗","informan: 직설법 현재라 바람의 que 뒤에 맞지 않습니다 ✗","informen: 접속법 현재 → 정답 ✓"]},{"id":"G509","q":"¿Qué pensás ____ de todo esto?","o":["vosotros","tú","vos","ustedes"],"a":2,"k":"vos (보세오)","t":"너는 이 모든 것에 대해 어떻게 생각해?","e":"pensás는 아르헨티나·우루과이 등에서 tú 대신 쓰는 vos의 현재형입니다(tú piensas = vos pensás). vos 활용에서는 어간 변화(e→ie)가 일어나지 않고 끝에 강세가 옵니다. 그래서 주어는 vos가 맞습니다.","x":["vosotros: 스페인의 '너희들' 형태는 pensáis입니다 ✗","tú: tú의 활용형은 piensas입니다 ✗","vos: vos pensás(중남미 보세오) → 정답 ✓","ustedes: ustedes의 활용형은 piensan입니다 ✗"]},{"id":"G510","q":"Tengo que reservar nuestro viaje a Galicia ____ 24 de octubre.","o":["después","antes del","nada más","en cuanto"],"a":1,"k":"antes de (시간)","t":"10월 24일 전에 갈리시아 여행을 예약해야 한다.","e":"antes de는 '~ 전에'라는 뜻이고, 날짜 앞에는 관사 el이 붙어 de + el = del이 됩니다. 그래서 antes del 24 de octubre(10월 24일 전에)가 맞습니다. 반대말은 después del(~ 후에)입니다.","x":["después: '후에'는 después del처럼 de가 필요해 그대로는 틀립니다 ✗","antes del: antes de + el '~일 전에' → 정답 ✓","nada más: nada más + 동사원형(~하자마자)으로 쓰며 날짜 앞에는 맞지 않습니다 ✗","en cuanto: '~하자마자'라는 접속사로 뒤에 문장이 와야 합니다 ✗"]},{"id":"G511","q":"Este barrio es menos caro ____ el barrio en el que vivo yo.","o":["de","que","de que","como"],"a":1,"k":"menos ... que","t":"이 동네는 내가 사는 동네보다 덜 비싸다.","e":"열등비교(~보다 덜 …하다)는 menos + 형용사 + que로 나타냅니다. 두 동네를 비교하므로 menos caro que el barrio...가 맞습니다. 숫자 앞에서만 menos de(menos de diez)를 씁니다.","x":["de: 숫자·양 앞에서만 쓰고 비교 대상 앞에는 쓰지 않습니다 ✗","que: menos ... que '~보다 덜' → 정답 ✓","de que: 비교 대상이 명사(el barrio)일 때는 de que를 쓰지 않습니다 ✗","como: 동등비교 tan ... como에 쓰는 단어입니다 ✗"]},{"id":"G512","q":"Estoy lleno, ya no puedo comer nada ____.","o":["mucho","menos","mucha","más"],"a":3,"k":"nada más (더 이상)","t":"배불러, 더 이상 아무것도 못 먹겠어.","e":"no ... nada más는 '더 이상 아무것도 ~않다'라는 뜻입니다. 배가 부르다(Estoy lleno)는 상황이므로 '더(más)'가 자연스럽습니다. 예: No quiero nada más, gracias.(더는 필요 없어요, 고마워요.)","x":["mucho: nada mucho라는 표현은 쓰지 않습니다 ✗","menos: '덜'이라는 뜻이라 배부른 상황과 맞지 않습니다 ✗","mucha: 여성형 형용사라 nada 뒤에 쓰지 않습니다 ✗","más: nada más '더 이상 아무것도' → 정답 ✓"]},{"id":"G513","q":"____ mucho tiempo que no veo a mi tío Pepe.","o":["Hace","Hizo","Ha hecho","Hacía"],"a":0,"k":"hace + 기간 + que","t":"페페 삼촌을 못 본 지 오래됐다.","e":"hace + 기간 + que + 현재형은 '~한 지 (기간)이 되었다'라는 표현입니다. 지금까지 계속 못 보고 있으므로 현재형 hace를 씁니다. 예: Hace dos años que vivo aquí.(여기 산 지 2년 됐어.)","x":["Hace: hace + 기간 + que '~한 지 …되다' → 정답 ✓","Hizo: 과거형이라 현재형 no veo와 맞지 않습니다 ✗","Ha hecho: 이 시간 표현에는 현재완료를 쓰지 않습니다 ✗","Hacía: 과거 기준(~한 지 …되었었다)이라 현재형 veo와 맞지 않습니다 ✗"]},{"id":"G514","q":"¿Quién es más inteligente? ¿Norberto ____ Óscar?","o":["y","u","o","e"],"a":1,"k":"o → u","t":"누가 더 똑똑해? 노르베르토 아니면 오스카?","e":"'또는'을 뜻하는 o는 뒤의 단어가 o- 또는 ho-로 시작하면 발음이 겹치지 않도록 u로 바뀝니다. Óscar가 o로 시작하므로 Norberto u Óscar가 됩니다. 같은 원리로 y(그리고)는 i-, hi- 앞에서 e로 바뀝니다(padre e hijo).","x":["y: '그리고'라서 선택을 묻는 질문에 맞지 않습니다 ✗","u: o- 앞에서 o가 u로 바뀐 형태 → 정답 ✓","o: '또는'이지만 Óscar 앞에서는 u로 바꿔야 합니다 ✗","e: y가 i- 앞에서 바뀐 형태라 '그리고'의 뜻이고 위치도 맞지 않습니다 ✗"]},{"id":"G515","q":"____ conoció a su nuevo amor, está muy cambiada.","o":["Desde","Hace","Desde que","Desde hace"],"a":2,"k":"desde que","t":"새로운 사랑을 만난 뒤로 그녀는 많이 변했다.","e":"desde que + 문장은 '~한 이후로'라는 뜻으로, 그때부터 지금까지 이어지는 변화를 나타냅니다. 뒤에 동사(conoció)가 있는 문장이 오므로 que가 필요합니다. desde 단독은 명사나 시점(desde 2020) 앞에 씁니다.","x":["Desde: 뒤에 활용된 동사 문장이 오려면 que가 필요합니다 ✗","Hace: 뒤에 기간이 와야 하며 문장을 바로 받지 않습니다 ✗","Desde que: '~한 이후로' + 문장 → 정답 ✓","Desde hace: 뒤에 기간(desde hace dos años)이 와야 합니다 ✗"]},{"id":"G516","q":"No ____ el pescado, prefiero la carne.","o":["me gusta","gusto","me gusto","gusta a mí"],"a":0,"k":"gustar 구문","t":"나는 생선을 안 좋아해, 고기가 더 좋아.","e":"gustar는 '~가 (나에게) 마음에 들다'라는 구조라서, 좋아하는 사람은 me(나에게)로, 좋아하는 대상(el pescado)이 주어가 됩니다. 주어가 단수이므로 me gusta입니다. a mí를 쓰려면 A mí no me gusta처럼 me도 함께 써야 합니다.","x":["me gusta: 간접목적격 me + 3인칭 단수 → 정답 ✓","gusto: '나는 마음에 든다'가 되어 생선을 좋아한다는 뜻이 되지 않습니다 ✗","me gusto: '내가 나 자신이 마음에 든다'는 뜻이 됩니다 ✗","gusta a mí: me가 빠져 있고 어순도 틀립니다 ✗"]},{"id":"G517","q":"Si no te ____ ese traje, no te lo compres.","o":["gustas","gusta","gustaría","guste"],"a":1,"k":"si + 직설법 현재","t":"그 정장이 마음에 들지 않으면 사지 마.","e":"실제 가능한 조건 si(만약 ~하면) 뒤에는 직설법 현재를 씁니다. gustar 구문이라 주어는 ese traje(3인칭 단수)이므로 te gusta가 됩니다. si 뒤에 접속법 현재(guste)는 쓰지 않는다는 점이 중요합니다.","x":["gustas: '네가 (누군가의) 마음에 든다'는 뜻이 되어 맞지 않습니다 ✗","gusta: si + 직설법 현재, 주어 traje와 일치 → 정답 ✓","gustaría: 조건법이라 실제 조건 si 뒤에 쓰지 않습니다 ✗","guste: 접속법 현재는 si 뒤에 쓰지 않습니다 ✗"]},{"id":"G518","q":"Alba y Javier ____ casaron el año pasado.","o":["ø","se","le","les"],"a":1,"k":"재귀동사 casarse","t":"알바와 하비에르는 작년에 결혼했다.","e":"casarse(결혼하다)는 재귀 동사로 항상 재귀 대명사와 함께 씁니다. 주어가 3인칭 복수(Alba y Javier)이므로 se casaron이 됩니다. '~와 결혼하다'는 casarse con입니다. 예: Me casé con ella.(나는 그녀와 결혼했다.)","x":["ø: 재귀 대명사가 없으면 '(누군가를) 결혼시켰다'라는 뜻이 됩니다 ✗","se: 3인칭 복수 재귀 대명사 → 정답 ✓","le: 간접목적격 단수라 맞지 않습니다 ✗","les: 간접목적격(그들에게)이라 재귀 표현이 되지 않습니다 ✗"]},{"id":"G519","q":"Que yo ____, nadie se ha quejado de nuestros servicios.","o":["sé","sepa","sabré","estoy sabiendo"],"a":1,"k":"que yo sepa","t":"내가 알기로는, 아무도 우리 서비스에 불만을 제기하지 않았다.","e":"Que yo sepa는 '내가 아는 한'이라는 관용 표현으로, 항상 접속법(sepa)을 씁니다. 확실하지 않고 자기가 아는 범위 안에서 말한다는 뉘앙스가 있습니다. 비슷한 표현: que yo recuerde(내가 기억하는 한).","x":["sé: 직설법이라 이 관용 표현에 맞지 않습니다 ✗","sepa: 관용 표현 que yo sepa '내가 아는 한' → 정답 ✓","sabré: 미래형이라 맞지 않습니다 ✗","estoy sabiendo: saber는 진행형으로 거의 쓰지 않습니다 ✗"]},{"id":"G520","q":"Los estudiantes de bachillerato ____ esta tarde al museo de historia.","o":["van a ir","van ir","vais a ir","va a ir"],"a":0,"k":"ir a + 원형","t":"고등학생들은 오늘 오후에 역사 박물관에 갈 것이다.","e":"ir a + 동사원형은 '~할 것이다'라는 가까운 미래 표현입니다. 주어 los estudiantes는 3인칭 복수이므로 van a ir가 맞습니다. a를 빠뜨리지 않도록 주의하세요.","x":["van a ir: 3인칭 복수 + a + 원형 → 정답 ✓","van ir: 전치사 a가 빠졌습니다 ✗","vais a ir: vosotros(너희) 형태라 주어와 맞지 않습니다 ✗","va a ir: 단수라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G521","q":"¿____ cuándo vives aquí?","o":["Por","Desde","De","En"],"a":1,"k":"¿Desde cuándo?","t":"언제부터 여기 살았어?","e":"¿Desde cuándo + 현재형?은 '언제부터 ~하고 있어?'라는 질문으로, 지금도 계속되는 일의 시작점을 묻습니다. 그래서 동사는 현재형 vives를 씁니다. 대답 예: Desde 2019.(2019년부터.)","x":["Por: por cuándo라는 표현은 쓰지 않습니다 ✗","Desde: ¿Desde cuándo? '언제부터?' → 정답 ✓","De: de cuándo는 '언제 것인지(¿De cuándo es?)'를 묻는 다른 표현입니다 ✗","En: en cuándo라는 표현은 쓰지 않습니다 ✗"]},{"id":"G522","q":"Mi padre quiere que ____ otro trabajo, dice que este no es para mí.","o":["estoy buscando","busco","busque","buscaría"],"a":2,"k":"querer que+접속법","t":"아빠는 내가 다른 일을 찾기를 원하신다, 이 일은 나에게 맞지 않는다고 하신다.","e":"querer que(~가 …하기를 원하다)처럼 바람을 나타내는 동사 뒤에 주어가 다르면(아빠 ↔ 나) 접속법을 씁니다. buscar의 접속법 현재 1인칭은 철자가 바뀌어 busque(c → qu)입니다. 예: Quiero que vengas.(네가 오면 좋겠어.)","x":["estoy buscando: 직설법 현재진행이라 바람의 que 뒤에 맞지 않습니다 ✗","busco: 직설법 현재라 querer que 뒤에 쓰지 않습니다 ✗","busque: 접속법 현재 1인칭 → 정답 ✓","buscaría: 조건법이라 현재형 quiere와 맞지 않습니다 ✗"]},{"id":"G523","q":"―¿Dónde sueles ir cuando estás de vacaciones? ―Normalmente no voy a ____ sitio.","o":["alguno","algún","ninguno","ningún"],"a":3,"k":"ningún (부정)","t":"―휴가 때 보통 어디 가? ―보통은 아무 데도 안 가.","e":"부정문(no voy)에서 '아무 ~도'는 ninguno를 쓰고, 남성 단수 명사(sitio) 앞에서는 ningún으로 줄어듭니다. 스페인어는 no ... ningún처럼 이중 부정이 자연스럽습니다. a ningún sitio(아무 데도)는 a ningún lado와 같은 뜻입니다.","x":["alguno: 긍정 의미이고 명사 앞에서는 algún으로 줄어야 합니다 ✗","algún: 긍정문에 쓰는 '어떤'이라 부정문 no와 맞지 않습니다 ✗","ninguno: 명사 앞에서는 ningún으로 줄여야 합니다 ✗","ningún: 남성 단수 명사 앞 부정 축약형 → 정답 ✓"]},{"id":"G524","q":"Este castillo ____ hace siglos.","o":["se construye","se estaba construyendo","se construía","se construyó"],"a":3,"k":"수동의 se","t":"이 성은 수백 년 전에 지어졌다.","e":"se + 3인칭 동사는 '~되다'라는 수동의 의미를 나타냅니다(수동의 se). hace siglos(수백 년 전에)는 끝난 과거의 사건이므로 단순과거 se construyó가 맞습니다. 예: La casa se vendió el año pasado.(그 집은 작년에 팔렸다.)","x":["se construye: 현재형이라 hace siglos와 맞지 않습니다 ✗","se estaba construyendo: '지어지고 있던 중'이라 완료된 사건을 나타내지 못합니다 ✗","se construía: 불완료과거라 한 번에 끝난 사건에 맞지 않습니다 ✗","se construyó: 단순과거 수동 '지어졌다' → 정답 ✓"]},{"id":"G525","q":"Comprendo que ____ aburridos.","o":["estéis","está","sois","es"],"a":0,"k":"comprender que","t":"너희가 지루해하는 거 이해해.","e":"comprender que, entender que가 '(상대의 감정·상황을) 이해한다, 그럴 만하다'는 뜻일 때는 뒤에 접속법이 옵니다. aburrido는 ser와 쓰면 '지루한 사람', estar와 쓰면 '지루해하는 상태'라서 estar를 씁니다. aburridos(복수)에 맞는 vosotros의 접속법 estéis가 정답입니다.","x":["estéis: estar의 접속법 vosotros 형태, 복수 aburridos와 일치 → 정답 ✓","está: 단수라 복수 aburridos와 맞지 않습니다 ✗","sois: ser라서 '너희는 지루한 사람들이다'라는 뜻이 됩니다 ✗","es: 단수이고 ser라서 두 가지 모두 맞지 않습니다 ✗"]},{"id":"G526","q":"Estoy buscando ____ un piso en este barrio. Quiero mudarme aquí.","o":["para","sobre","ø","por"],"a":2,"k":"buscar + 목적어","t":"이 동네에서 아파트를 찾고 있어. 여기로 이사 오고 싶거든.","e":"buscar는 '~을 찾다'라는 뜻으로, 영어 look for와 달리 전치사 없이 바로 목적어를 받습니다. 그래서 buscando un piso가 맞습니다. piso는 스페인에서 '아파트'를 뜻하며, 중남미에서는 apartamento나 departamento를 많이 씁니다.","x":["para: buscar 뒤에 '~를 위해'를 넣으면 뜻이 달라져 맞지 않습니다 ✗","sobre: '~에 대해'라는 뜻이라 맞지 않습니다 ✗","ø: buscar + 직접목적어(전치사 없음) → 정답 ✓","por: buscar por는 '~에서(장소) 찾다'라는 뜻으로 목적어 앞에 쓰지 않습니다 ✗"]},{"id":"G527","q":"Cuando termino de entrenar, ____ una ducha relajante.","o":["doy a mí","doy","yo doy","me doy"],"a":3,"k":"darse una ducha","t":"훈련을 마치면 나는 편안하게 샤워를 한다.","e":"darse una ducha는 '(자기 자신에게) 샤워를 하다'라는 재귀 표현입니다. 1인칭이므로 재귀 대명사 me를 써서 me doy una ducha가 됩니다. 비슷한 표현: darse un baño(목욕하다), darse prisa(서두르다).","x":["doy a mí: 재귀 표현은 대명사 me로 나타내야 하며 a mí만으로는 틀립니다 ✗","doy: 재귀 대명사가 빠져 '샤워를 준다'처럼 어색해집니다 ✗","yo doy: 주어만 추가했을 뿐 재귀 대명사가 없습니다 ✗","me doy: 재귀 표현 darse una ducha → 정답 ✓"]},{"id":"G528","q":"Ana Isabel trabaja ____ como Alejandro.","o":["tanta","tanto","tantas","tan"],"a":1,"k":"tanto como (부사)","t":"아나 이사벨은 알레한드로만큼 일을 많이 한다.","e":"동사(trabajar)를 꾸며 '~만큼 많이'라고 할 때는 동사 + tanto como를 씁니다. 이때 tanto는 부사라 형태가 변하지 않습니다. 형용사 앞이면 tan ... como(tan alta como)를 씁니다.","x":["tanta: 여성 단수 형용사라 명사가 필요합니다 ✗","tanto: 동사를 꾸미는 부사 tanto como → 정답 ✓","tantas: 여성 복수 형용사라 명사가 필요합니다 ✗","tan: 형용사·부사 앞에만 쓰고 como 바로 앞에는 쓰지 않습니다 ✗"]},{"id":"G529","q":"Cuando mi hermana me vio, me ____ un abrazo.","o":["estaba dando","dio","daba","di"],"a":1,"k":"단순과거","t":"언니가 나를 보았을 때, 나를 안아 주었다.","e":"과거에 한 번 일어나고 끝난 동작은 단순과거로 씁니다. 언니가 나를 본 순간(vio) 이어서 안아 준 것도 완료된 사건이므로 dio(dar의 3인칭 단수 단순과거)가 맞습니다. dar un abrazo는 '포옹하다'라는 표현입니다.","x":["estaba dando: 과거진행이라 '보았을 때'에 이어 일어난 한 번의 사건과 맞지 않습니다 ✗","dio: 단순과거 3인칭 단수 '주었다' → 정답 ✓","daba: 불완료과거(주곤 했다)라 한 번의 사건과 맞지 않습니다 ✗","di: 1인칭 단수(내가 주었다)라 주어 mi hermana와 맞지 않습니다 ✗"]},{"id":"G530","q":"¿Te pasa ____? Te noto muy tensa.","o":["alguno","alguna","algo","nada"],"a":2,"k":"부정대명사 algo","t":"무슨 일 있어? 너 많이 긴장한 것 같아.","e":"algo는 '무언가'라는 뜻의 대명사로 형태가 변하지 않습니다. ¿Te pasa algo?는 '너한테 무슨 일 있어?'라는 아주 흔한 질문입니다. 부정 대답은 No me pasa nada.(아무 일도 없어.)입니다.","x":["alguno: 명사를 대신할 때 '어떤 것(하나)'의 뜻이라 이 질문에 맞지 않습니다 ✗","alguna: 여성형이라 받는 명사가 없어 맞지 않습니다 ✗","algo: '무언가' → 정답 ✓","nada: '아무것도'라는 부정어라 긍정 의문문에서 상대를 걱정하는 뜻이 되지 않습니다 ✗"]},{"id":"G531","q":"Llevamos muchos años viviendo ____ Chile.","o":["a","en","desde","hasta"],"a":1,"k":"전치사 en (장소)","t":"우리는 칠레에서 여러 해째 살고 있다.","e":"'~에서 살다'처럼 머무는 장소를 나타낼 때는 전치사 en을 씁니다. llevar + 기간 + 현재분사는 '~째 …하고 있다'라는 표현입니다. 예: Llevo dos años estudiando español.(나는 2년째 스페인어를 공부하고 있다.)","x":["a: 이동의 방향(ir a)에 쓰고 머무는 장소에는 쓰지 않습니다 ✗","en: 장소 '~에서' → 정답 ✓","desde: '~부터'라는 출발점이라 vivir의 장소에 맞지 않습니다 ✗","hasta: '~까지'라는 한계를 나타내어 맞지 않습니다 ✗"]},{"id":"G532","q":"Mi padre siempre viaja ____ su carro.","o":["por","de","en","a"],"a":2,"k":"en + 교통수단","t":"우리 아빠는 늘 자기 차로 여행한다.","e":"교통수단을 타고 이동한다고 할 때는 en을 씁니다(en tren, en avión, en coche). carro는 중남미에서 쓰는 '자동차'이며, 스페인에서는 coche라고 합니다. 예외로 '걸어서'는 a pie입니다.","x":["por: por carretera(도로로)처럼 경로를 말할 때 쓰며 차량 앞에는 맞지 않습니다 ✗","de: '~의'라는 뜻이라 교통수단을 나타내지 않습니다 ✗","en: en + 교통수단 '~를 타고' → 정답 ✓","a: a pie, a caballo 같은 경우만 쓰고 차에는 쓰지 않습니다 ✗"]},{"id":"G533","q":"Gracias por ____ tan comprensiva.","o":["eres","sido","ser","siendo"],"a":2,"k":"전치사 + 동사원형","t":"그렇게 이해해 줘서 고마워.","e":"스페인어에서 전치사 뒤에 동사가 올 때는 항상 동사원형을 씁니다. gracias por + 동사원형은 '~해 줘서 고마워'라는 뜻입니다. 예: Gracias por venir.(와 줘서 고마워.)","x":["eres: 활용된 동사라 전치사 por 바로 뒤에 올 수 없습니다 ✗","sido: 과거분사라 haber 없이 단독으로 쓸 수 없습니다(por haber sido는 가능) ✗","ser: 전치사 뒤 동사원형 → 정답 ✓","siendo: 현재분사는 전치사 뒤에 쓰지 않습니다 ✗"]},{"id":"G534","q":"Para mí, la mejor carne es la ____ ternera.","o":["con","por","de","para"],"a":2,"k":"la de + 명사","t":"내 생각에 최고의 고기는 송아지 고기다.","e":"앞에 나온 명사 carne를 반복하지 않기 위해 관사만 남기고 la de ternera(송아지의 그것)라고 합니다. carne de ternera(송아지 고기)처럼 재료·종류는 de로 나타냅니다. 예: carne de cerdo(돼지고기), carne de pollo(닭고기).","x":["con: '~와 함께'라는 뜻이라 고기의 종류를 나타내지 않습니다 ✗","por: 원인·경로를 나타내어 맞지 않습니다 ✗","de: carne de ternera '송아지 고기' → 정답 ✓","para: '~용'이라는 목적이라 고기 종류를 나타내지 않습니다 ✗"]},{"id":"G535","q":"Te cambio mi reloj ____ el tuyo. ¿Qué dices?","o":["por","en","con","para"],"a":0,"k":"교환의 por","t":"내 시계를 네 것과 바꿔 줄게. 어때?","e":"교환을 나타낼 때 '~ 대신, ~와 맞바꾸어'는 전치사 por를 씁니다. cambiar A por B는 'A를 B와 바꾸다'라는 뜻입니다. 예: Cambié euros por dólares.(나는 유로를 달러로 바꿨다.)","x":["por: 교환 '~와 맞바꾸어' → 정답 ✓","en: cambiar en은 '~로 변하다'라는 다른 의미입니다 ✗","con: '~와 함께'라는 뜻이라 교환 대상 앞에는 쓰지 않습니다 ✗","para: 목적·대상을 나타내어 교환에는 쓰지 않습니다 ✗"]},{"id":"G536","q":"Ya puedo hacer la compra, el supermercado ____ abierto.","o":["está","es","están","son"],"a":0,"k":"estar abierto","t":"이제 장 보러 갈 수 있어, 슈퍼마켓이 열려 있어.","e":"abierto(열린)처럼 결과 상태를 나타내는 형용사는 estar와 함께 씁니다. 주어 el supermercado는 단수이므로 está가 맞습니다. 반대는 estar cerrado(닫혀 있다)입니다.","x":["está: estar + 상태 형용사, 단수 주어 → 정답 ✓","es: ser는 일시적인 열림 상태를 나타내지 않습니다 ✗","están: 복수형이라 단수 주어와 맞지 않습니다 ✗","son: ser이고 복수라 둘 다 맞지 않습니다 ✗"]},{"id":"G537","q":"Me encanta la geografía, por eso hay ____ mapas en las paredes de mi casa.","o":["de tantas","tantos","tanto","tantas"],"a":1,"k":"tantos + 명사","t":"나는 지리를 무척 좋아해서, 우리 집 벽에는 지도가 아주 많다.","e":"tanto가 명사 앞에서 '그렇게 많은'이라는 형용사로 쓰일 때는 명사의 성·수에 맞춥니다. mapa는 -a로 끝나지만 남성 명사(el mapa)이므로 복수형 tantos가 맞습니다. -ma로 끝나는 problema, mapa, día 등의 성에 주의하세요.","x":["de tantas: 불필요한 de가 있고 여성형이라 틀립니다 ✗","tantos: 남성 복수 명사 mapas와 일치 → 정답 ✓","tanto: 단수형이라 복수 명사와 맞지 않습니다 ✗","tantas: 여성형이라 남성 명사 mapa와 맞지 않습니다 ✗"]},{"id":"G538","q":"____ está gritando.","o":["Algún","Algunos","Alguien","Algo"],"a":2,"k":"부정대명사 alguien","t":"누군가 소리를 지르고 있다.","e":"소리를 지르는 것은 사람이므로 '누군가'를 뜻하는 alguien을 씁니다. alguien은 혼자 주어가 될 수 있고 동사는 3인칭 단수입니다. algo는 사물(무언가)에 씁니다.","x":["Algún: 명사 앞에만 쓰는 형용사라 혼자 주어가 될 수 없습니다 ✗","Algunos: 복수라 단수 동사 está와 맞지 않습니다 ✗","Alguien: '누군가'(사람), 3인칭 단수 → 정답 ✓","Algo: '무언가'(사물)라서 소리를 지를 수 없습니다 ✗"]},{"id":"G539","q":"Ayer ____ tan cansado que me acosté dos horas antes de lo habitual.","o":["he estado","estuve","estaba","había estado"],"a":2,"k":"불완료과거 (상태)","t":"어제는 너무 피곤해서 평소보다 두 시간 일찍 잤다.","e":"과거의 상태나 상황(피곤했다)을 배경으로 묘사할 때는 불완료과거 estaba를 씁니다. 그 결과로 일어난 사건(me acosté, 잠자리에 들었다)은 단순과거로 씁니다. tan ... que는 '너무 ~해서 …하다'라는 결과 표현입니다.","x":["he estado: 현재완료라 ayer(어제)와 함께 쓰기 어렵습니다 ✗","estuve: 상태를 하나의 완료된 사건처럼 보는 형태라, 배경 묘사로는 estaba가 더 자연스럽습니다 ✗","estaba: 과거 상태 묘사 불완료과거 → 정답 ✓","había estado: 과거완료(이미 ~했었다)라 시간 관계가 맞지 않습니다 ✗"]},{"id":"G540","q":"Conozco ____ canciones de Shakira.","o":["algunas","ningunos","ningunas","algunos"],"a":0,"k":"algunas (형용사)","t":"나는 샤키라의 노래를 몇 곡 안다.","e":"alguno는 명사의 성·수에 맞게 변하며 '몇몇의'라는 뜻입니다. canción은 여성 명사이고 복수 canciones이므로 algunas가 맞습니다. ninguno는 부정어라 긍정문에 쓰지 않고, 보통 복수형으로도 잘 쓰지 않습니다.","x":["algunas: 여성 복수 명사 canciones와 일치 → 정답 ✓","ningunos: 부정어라 긍정문과 맞지 않고 성도 다릅니다 ✗","ningunas: 부정어라 긍정문 Conozco와 맞지 않습니다 ✗","algunos: 남성형이라 여성 명사 canciones와 맞지 않습니다 ✗"]},{"id":"G541","q":"Si ____ ayuda, solo tenéis que decírmelo.","o":["necesitáis","necesitaste","necesitaron","necesitéis"],"a":0,"k":"si + 직설법 현재","t":"도움이 필요하면, 나한테 말하기만 하면 돼.","e":"실제로 일어날 수 있는 조건 'si(만약) ~하면'에는 직설법 현재를 씁니다. 뒤의 tenéis, decírmelo로 보아 상대는 vosotros(너희들)이므로 necesitáis가 맞습니다. 주의: si 뒤에는 접속법 현재를 쓰지 않습니다.","x":["necesitáis: si + 직설법 현재, vosotros 형태 → 정답 ✓","necesitaste: 단순과거 tú 형태라 주어와 시제가 맞지 않습니다 ✗","necesitaron: 단순과거 3인칭 복수라 맞지 않습니다 ✗","necesitéis: 접속법 현재는 si 뒤에 쓰지 않습니다 ✗"]},{"id":"G542","q":"¿Para qué sirve ____?","o":["esta","esto","este","estos"],"a":1,"k":"중성 지시대명사 esto","t":"이건 어디에 쓰는 거야?","e":"무엇인지 모르는 물건을 가리킬 때는 성이 정해지지 않은 중성 지시대명사 esto(이것)를 씁니다. esto는 명사 앞에 쓰지 않고 혼자 씁니다. 예: ¿Qué es esto?(이게 뭐야?)","x":["esta: 여성 지시사라 성을 아는 명사가 있어야 합니다 ✗","esto: 정체를 모르는 것을 가리키는 중성형 '이것' → 정답 ✓","este: 남성 지시사라 성을 아는 명사가 있어야 합니다 ✗","estos: 복수형이라 단수 동사 sirve와 맞지 않습니다 ✗"]},{"id":"G543","q":"Todos ____ ayudar a nuestro amigo.","o":["hay","tenemos","tenemos que","hay que"],"a":2,"k":"tener que (의무)","t":"우리 모두가 친구를 도와야 한다.","e":"주어(todos = 우리 모두)가 있을 때 '~해야 한다'는 tener que + 동사원형으로 씁니다. hay que도 '~해야 한다'이지만 주어가 없는 무인칭 표현이라 todos 같은 주어와 함께 쓰지 않습니다. 예: Hay que estudiar.(공부해야 한다.)","x":["hay: 뒤에 que 없이 동사원형을 받을 수 없습니다 ✗","tenemos: que가 없으면 '가지고 있다'가 되어 동사원형과 연결되지 않습니다 ✗","tenemos que: 주어가 있는 의무 표현 → 정답 ✓","hay que: 무인칭 표현이라 주어 todos와 함께 쓰지 않습니다 ✗"]},{"id":"G544","q":"Mi novio me regaló un ramo de ____ flores.","o":["el","las","ø","los"],"a":2,"k":"관사 생략 (de + 명사)","t":"남자친구가 나에게 꽃다발을 선물해 주었다.","e":"un ramo de flores(꽃다발)처럼 'de + 명사'가 내용물이나 종류를 나타낼 때는 명사 앞에 관사를 쓰지 않습니다. 비슷한 예: una taza de café(커피 한 잔), un vaso de agua(물 한 잔).","x":["el: 단수 남성 관사라 복수 여성 명사 flores와 맞지 않습니다 ✗","las: 성·수는 맞지만 '특정한 꽃들'이 되어 꽃다발의 일반 표현과 맞지 않습니다 ✗","ø: un ramo de flores, 관사 생략 → 정답 ✓","los: 남성 관사라 flores와 맞지 않습니다 ✗"]},{"id":"G545","q":"¡Qué comida tan rica! ¿La has hecho ____?","o":["tú","vosotros","ustedes","usted"],"a":0,"k":"주격 대명사 tú","t":"정말 맛있는 음식이야! 네가 만든 거야?","e":"동사 has hecho는 tú(너)의 현재완료 형태입니다. 그래서 주어로 tú가 맞습니다. 스페인어는 보통 주어를 생략하지만, '네가 직접?'처럼 강조할 때 주어를 동사 뒤에 넣기도 합니다.","x":["tú: 2인칭 단수, has hecho와 일치 → 정답 ✓","vosotros: 동사가 habéis hecho여야 합니다 ✗","ustedes: 동사가 han hecho여야 합니다 ✗","usted: 동사가 ha hecho여야 합니다 ✗"]},{"id":"G546","q":"No ____ enfadarse por tonterías.","o":["debes","hay que","tienes que","deberías"],"a":1,"k":"hay que + 원형","t":"사소한 일로 화내면 안 된다.","e":"hay que + 동사원형은 주어 없이 '(일반적으로) ~해야 한다'라는 무인칭 표현입니다. 빈칸 뒤 enfadarse는 재귀 대명사가 se로 되어 있어 특정 인물(tú)이 아닌 일반적인 말임을 알 수 있습니다. debes, tienes que를 쓰려면 enfadarte가 되어야 합니다.","x":["debes: tú 주어이므로 enfadarte가 되어야 해서 맞지 않습니다 ✗","hay que: 무인칭 '~해야 한다', enfadarse와 일치 → 정답 ✓","tienes que: tú 주어라 enfadarte여야 합니다 ✗","deberías: tú 주어라 enfadarte여야 합니다 ✗"]},{"id":"G547","q":"El Volga es ____ río más largo de Europa.","o":["un","lo","ø","el"],"a":3,"k":"최상급 el más","t":"볼가강은 유럽에서 가장 긴 강이다.","e":"최상급(가장 ~한)은 정관사 + 명사 + más + 형용사 + de로 만듭니다. río는 남성 명사이므로 el río más largo de Europa가 됩니다. 예: la ciudad más grande del país(그 나라에서 가장 큰 도시).","x":["un: 부정관사를 쓰면 '가장 긴'이라는 최상급이 되지 않습니다 ✗","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","ø: 최상급에는 정관사가 필요합니다 ✗","el: 정관사 + 명사 + más 최상급 → 정답 ✓"]},{"id":"G548","q":"____ días en un colegio nuevo no suelen ser fáciles.","o":["Los primeros","Primeros","Las primeras","Primeras"],"a":0,"k":"서수 + 관사","t":"새 학교에서의 첫 며칠은 보통 쉽지 않다.","e":"día는 -a로 끝나지만 남성 명사입니다(el día). 그래서 서수도 남성 복수 primeros를 쓰고, 주어 자리의 특정한 날들이므로 정관사 los가 필요합니다. los primeros días는 '처음 며칠'이라는 뜻입니다.","x":["Los primeros: 남성 복수 + 정관사 → 정답 ✓","Primeros: 주어 자리에서 정관사가 빠져 어색합니다 ✗","Las primeras: 여성형이라 남성 명사 día와 맞지 않습니다 ✗","Primeras: 여성형이고 관사도 없어 틀립니다 ✗"]},{"id":"G549","q":"No me ____ despierto, voy a llegar muy tarde.","o":["esperaste","esperas","esperes","esperabas"],"a":2,"k":"부정 명령 (접속법)","t":"나 기다리느라 깨어 있지 마, 아주 늦게 도착할 거야.","e":"tú에게 하는 부정 명령은 no + 접속법 현재입니다. esperar의 접속법 현재 tú 형태는 esperes입니다. no me esperes despierto는 '나를 깨어서 기다리지 마(먼저 자)'라는 자연스러운 표현입니다.","x":["esperaste: 단순과거라 명령이 아닙니다 ✗","esperas: 직설법 현재라 부정 명령에 쓰지 않습니다 ✗","esperes: no + 접속법, tú 부정 명령 → 정답 ✓","esperabas: 불완료과거라 명령이 아닙니다 ✗"]},{"id":"G550","q":"Me encantó la última película ____ Guillermo del Toro.","o":["para","a","de","por"],"a":2,"k":"전치사 de (작가)","t":"기예르모 델 토로의 최신 영화가 정말 좋았다.","e":"작품의 작가나 감독을 나타낼 때는 de(~의)를 씁니다. la película de Guillermo del Toro는 '기예르모 델 토로의 영화'라는 뜻입니다. 수동문에서는 dirigida por(~에 의해 감독된)처럼 por를 씁니다.","x":["para: '~를 위한'이라는 뜻이라 감독을 나타내지 않습니다 ✗","a: 소유나 작가를 나타내지 않습니다 ✗","de: 작품의 작가·감독 '~의' → 정답 ✓","por: 수동 표현(hecha por)에 쓰며 명사 뒤에 바로 쓰면 어색합니다 ✗"]},{"id":"G551","q":"____ conmigo a la piscina si no tienes nada mejor que hacer.","o":["Vienes","Ven","Viene","Venís"],"a":1,"k":"tú 긍정 명령형","t":"더 좋은 할 일이 없으면 나랑 수영장에 가자.","e":"뒤의 tienes로 보아 상대는 tú(너)이며, 문장은 '나와 함께 와'라는 권유입니다. venir의 tú 긍정 명령형은 불규칙형 ven입니다. 불규칙 tú 명령형 8개(ven, di, sal, haz, ten, ve, pon, sé)는 꼭 외워 두세요.","x":["Vienes: 직설법 현재(너는 온다)라 명령이 아닙니다 ✗","Ven: venir의 tú 긍정 명령형(불규칙) → 정답 ✓","Viene: 3인칭 단수 현재형이라 tú와 맞지 않습니다 ✗","Venís: vosotros 직설법 현재(또는 vos 형태)라 tienes와 맞지 않습니다 ✗"]},{"id":"G552","q":"Anoche me llamaron ____ teléfono desde un número desconocido.","o":["en","a","para","por"],"a":3,"k":"por teléfono","t":"어젯밤 모르는 번호로 나에게 전화가 왔다.","e":"수단·방법(~으로, ~을 통해)을 나타낼 때 por를 씁니다. por teléfono(전화로), por correo(우편으로), por internet(인터넷으로)는 자주 쓰는 표현입니다. 참고로 hablar por teléfono는 '통화하다'입니다.","x":["en: en teléfono라는 표현은 쓰지 않습니다 ✗","a: a teléfono라는 표현은 쓰지 않습니다 ✗","para: 목적을 나타내어 수단에 맞지 않습니다 ✗","por: 수단 '전화로' → 정답 ✓"]},{"id":"G553","q":"Blanca ____ la directora de esta compañía.","o":["estará","es","ser","está"],"a":1,"k":"ser + 직위","t":"블랑카는 이 회사의 사장이다.","e":"사람의 직업이나 직위, 정체성을 말할 때는 ser를 씁니다. 주어 Blanca는 3인칭 단수이므로 es가 맞습니다. 특정 직위를 가리키므로 la directora처럼 정관사가 붙어 있습니다.","x":["estará: estar라서 직위를 나타내지 않고 미래형도 문맥에 맞지 않습니다 ✗","es: ser + 직위 → 정답 ✓","ser: 동사원형이라 본동사가 될 수 없습니다 ✗","está: estar는 직업·직위를 나타내지 않습니다 ✗"]},{"id":"G554","q":"Está ____ nervioso que no le salen las palabras.","o":["tanto","muy","tan","mucho"],"a":2,"k":"tan...que (결과)","t":"그는 너무 긴장해서 말이 나오지 않는다.","e":"tan + 형용사/부사 + que는 '너무 ~해서 …하다'라는 결과 표현입니다. nervioso는 형용사이므로 tan을 씁니다. 예: Es tan caro que no lo compro.(너무 비싸서 안 사.)","x":["tanto: 형용사 앞에서는 tan으로 줄여야 합니다 ✗","muy: '매우'라는 뜻이지만 뒤의 que(결과)와 연결되지 않습니다 ✗","tan: tan + 형용사 + que '너무 ~해서' → 정답 ✓","mucho: 형용사 앞에 쓰지 않습니다 ✗"]},{"id":"G555","q":"Me gusta que ____ contento.","o":["eres","estás","estés","seas"],"a":2,"k":"감정 + que + 접속법","t":"네가 행복해서 좋아.","e":"me gusta que, me alegra que처럼 감정을 나타내는 표현 뒤에 다른 주어가 오면 접속법을 씁니다. contento(기쁜, 만족한)는 기분 상태라 estar를 쓰므로 estar의 접속법 estés가 맞습니다. 예: Me alegra que estés aquí.(네가 여기 있어서 기뻐.)","x":["eres: ser의 직설법이라 감정 표현 뒤 접속법이 필요하고 동사도 맞지 않습니다 ✗","estás: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","estés: estar의 접속법 현재 → 정답 ✓","seas: 접속법이지만 contento는 상태라 estar를 써야 합니다 ✗"]},{"id":"G556","q":"Esos dos chicos ____ parecen mucho porque son hermanos.","o":["ø","se","les","lo"],"a":1,"k":"parecerse (닮다)","t":"그 두 남자아이는 형제라서 아주 닮았다.","e":"parecerse는 '(서로) 닮다'라는 재귀 동사입니다. 주어가 3인칭 복수(esos dos chicos)이므로 재귀 대명사 se를 써서 se parecen이 됩니다. 재귀 대명사 없이 parecer만 쓰면 '~처럼 보이다'라는 다른 뜻이 됩니다.","x":["ø: 대명사가 없으면 '~처럼 보이다'가 되어 뜻이 달라집니다 ✗","se: parecerse '닮다', 3인칭 복수 재귀 → 정답 ✓","les: 간접목적격(그들에게)이라 '그들에게 많이 ~처럼 보이다'로 어색해집니다 ✗","lo: 직접목적격이라 parecer와 쓰지 않습니다 ✗"]},{"id":"G557","q":"Lorena dijo que ____ con nosotros, pero no apareció.","o":["viene","va a venir","vendrá","vendría"],"a":3,"k":"과거 속 미래 (조건법)","t":"로레나는 우리와 함께 오겠다고 했지만, 나타나지 않았다.","e":"과거 시제(dijo)로 누군가의 말을 전할 때, 그 사람이 말한 '미래'는 가정법 조건(조건법, -ría 형태)으로 바꿉니다. 그녀가 'Vendré(갈게)'라고 말한 것을 dijo que vendría로 전하는 구조입니다. 실제로는 오지 않았다는 점에서도 과거 기준임이 분명합니다.","x":["viene: 현재형이라 과거 시점의 말 전달에 맞지 않습니다 ✗","va a venir: 현재 기준 미래라 dijo, no apareció와 시제가 맞지 않습니다 ✗","vendrá: 단순미래는 현재 기준이라 이미 지난 일에 맞지 않습니다 ✗","vendría: 과거에서 본 미래(조건법) → 정답 ✓"]},{"id":"G558","q":"Las vistas ____ esta ventana son maravillosas.","o":["de","desde la","del","desde"],"a":3,"k":"전치사 desde (시점)","t":"이 창문에서 보이는 경치는 정말 멋지다.","e":"desde는 '~에서(부터)'라는 출발점을 나타내며, 어디에서 바라보는지 시점을 말할 때 씁니다. las vistas desde esta ventana는 '이 창문에서 본 경치'입니다. 지시사 esta가 이미 있으므로 관사를 더 붙이지 않습니다.","x":["de: 소유·소속의 의미라 '창문의 경치'가 되어 바라보는 위치를 나타내지 못합니다 ✗","desde la: 관사 la와 지시사 esta를 함께 쓸 수 없습니다 ✗","del: de + el인데 esta 앞에 관사를 쓸 수 없습니다 ✗","desde: 바라보는 위치 '~에서' → 정답 ✓"]},{"id":"G559","q":"Tengo ____ problema con el inglés, me cuesta mucho pronunciarlo bien.","o":["uno","un","una","unos"],"a":1,"k":"부정관사 un","t":"나는 영어에 문제가 하나 있어, 발음을 제대로 하기가 너무 어려워.","e":"problema는 -a로 끝나지만 남성 명사(el problema)입니다. 그래서 '하나의 문제'는 남성 단수 부정관사 un을 써서 un problema가 됩니다. me cuesta + 동사원형은 '~하기가 힘들다'라는 표현입니다.","x":["uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","un: 남성 단수 명사 problema 앞 → 정답 ✓","una: problema는 남성 명사라 여성 관사와 맞지 않습니다 ✗","unos: 복수형이라 단수 명사와 맞지 않습니다 ✗"]},{"id":"G560","q":"Mi nieta quiere ____ ser enfermera.","o":["a","ø","de","que"],"a":1,"k":"querer + 원형","t":"내 손녀는 간호사가 되고 싶어 한다.","e":"querer(원하다) 뒤에는 전치사 없이 바로 동사원형을 씁니다. 주어가 같을 때(손녀가 되고 싶다)는 quiere ser처럼 원형을 쓰고, 주어가 다르면 quiere que + 접속법을 씁니다. 예: Quiero viajar.(나는 여행하고 싶다.)","x":["a: querer 뒤에 a를 넣지 않습니다 ✗","ø: querer + 동사원형 바로 연결 → 정답 ✓","de: querer 뒤에 de를 넣지 않습니다 ✗","que: que 뒤에는 원형이 아닌 활용된 동사(접속법)가 와야 합니다 ✗"]},{"id":"G561","q":"¿____ veces has puesto la misma canción hoy?","o":["Cuántos","Cuántas de","Cuántas","Cuánto"],"a":2,"k":"의문사 cuántas","t":"오늘 같은 노래를 몇 번이나 틀었어?","e":"cuánto(얼마나 많은)는 뒤에 오는 명사의 성·수에 맞춥니다. vez(번, 횟수)는 여성 명사이고 복수 veces이므로 cuántas가 맞습니다. ¿Cuántas veces...?는 '몇 번이나…?'라는 표현입니다.","x":["Cuántos: 남성형이라 여성 명사 veces와 맞지 않습니다 ✗","Cuántas de: 불필요한 de가 들어가 틀립니다 ✗","Cuántas: 여성 복수 명사 veces와 일치 → 정답 ✓","Cuánto: 남성 단수형이라 성과 수가 맞지 않습니다 ✗"]},{"id":"G562","q":"Todavía no ____ la tarea de la escuela. Necesito cinco minutos más.","o":["terminaba","estoy terminando","termino","he terminado"],"a":3,"k":"todavía no+완료","t":"아직 학교 숙제를 끝내지 못했어. 5분만 더 필요해.","e":"todavía no(아직 ~ 않았다)는 지금까지 완료되지 않은 일을 말하므로 현재완료와 잘 어울립니다. he terminado는 haber + terminado로 '끝냈다'입니다. 중남미에서는 todavía no terminé처럼 단순과거를 쓰기도 합니다.","x":["terminaba: 불완료과거라 현재와 연결된 '아직 못 끝냈다'와 맞지 않습니다 ✗","estoy terminando: '끝내는 중이다'라서 todavía no와 함께 쓰면 어색합니다 ✗","termino: 현재형 '끝낸다'는 todavía no와 함께 쓰면 습관·미래처럼 들려 어색합니다 ✗","he terminado: 현재완료 '아직 못 끝냈다' → 정답 ✓"]},{"id":"G563","q":"¿____ cuestan estas blusas?","o":["Por qué","Cuándo","Cuánto","Cómo"],"a":2,"k":"가격 묻기 cuánto","t":"이 블라우스들은 얼마예요?","e":"가격을 물을 때는 ¿Cuánto cuesta/cuestan...?을 씁니다. 여기서 cuánto는 동사를 꾸미는 부사라 형태가 변하지 않으며, 동사는 주어(estas blusas)에 맞춰 cuestan(복수)입니다. 예: ¿Cuánto cuesta este libro?(이 책은 얼마예요?)","x":["Por qué: '왜'라는 뜻이라 가격 질문에 맞지 않습니다 ✗","Cuándo: '언제'라는 뜻이라 맞지 않습니다 ✗","Cuánto: 가격 '얼마' → 정답 ✓","Cómo: '어떻게'라는 뜻이라 가격 질문에 맞지 않습니다 ✗"]},{"id":"G564","q":"Me gustaría cambiar ____ decoración de mi casa.","o":["ø","la","el","lo"],"a":1,"k":"정관사 la","t":"우리 집 인테리어를 바꾸고 싶다.","e":"decoración(장식, 인테리어)은 -ción으로 끝나는 여성 명사이며, '우리 집의' 특정한 인테리어를 말하므로 정관사 la를 씁니다. -ción, -sión으로 끝나는 명사는 거의 모두 여성입니다. 예: la canción, la televisión.","x":["ø: 특정한 대상이라 관사가 필요합니다 ✗","la: 여성 명사 decoración 앞 정관사 → 정답 ✓","el: 남성 관사라 여성 명사와 맞지 않습니다 ✗","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G565","q":"Niños, ____ aquí, es la hora de la merienda.","o":["vienes","venid","venís","vengáis"],"a":1,"k":"vosotros 명령형","t":"얘들아, 이리 와, 간식 시간이야.","e":"Niños(얘들아)라고 여러 명에게 친근하게 말하므로 vosotros(너희들) 명령형을 씁니다. venir → venid처럼 원형의 -r를 -d로 바꿉니다. 중남미에서는 ustedes 명령형 vengan을 씁니다.","x":["vienes: tú의 직설법 현재라 명령이 아니고 대상도 한 명입니다 ✗","venid: vosotros 긍정 명령형 → 정답 ✓","venís: vosotros 직설법 현재(너희가 온다)라 명령이 아닙니다 ✗","vengáis: 접속법으로 부정 명령(no vengáis)에만 씁니다 ✗"]},{"id":"G566","q":"No me gustan las películas del oeste ____ me aburren.","o":["así que","para que","como","porque"],"a":3,"k":"porque (이유)","t":"나는 서부 영화를 좋아하지 않아, 지루하거든.","e":"porque는 '왜냐하면, ~해서'라는 이유를 나타내는 접속사로, 보통 주절 뒤에 옵니다. 지루하다는 것이 서부 영화를 싫어하는 이유이므로 porque가 맞습니다. como도 이유를 나타내지만 문장 맨 앞에서만 씁니다(Como me aburren, no las veo).","x":["así que: '그래서'라는 결과 접속사라 원인과 결과가 뒤바뀝니다 ✗","para que: '~하도록'이라는 목적이라 맞지 않습니다 ✗","como: 이유를 뜻할 때는 문장 앞에만 오므로 이 위치에 맞지 않습니다 ✗","porque: 이유 '~때문에' → 정답 ✓"]},{"id":"G567","q":"Si te gustó este libro, ____ este otro. Es del mismo autor.","o":["leed","lea","lee","lees"],"a":2,"k":"tú 긍정 명령형","t":"이 책이 마음에 들었다면, 이 다른 책도 읽어 봐. 같은 작가 거야.","e":"앞의 te gustó로 보아 상대는 tú(너)입니다. 규칙 동사의 tú 긍정 명령형은 직설법 현재 3인칭 단수와 같아서 leer → lee가 됩니다. 추천하는 말투이므로 명령형이 자연스럽습니다.","x":["leed: vosotros 명령형이라 tú와 맞지 않습니다 ✗","lea: usted 명령형이라 te와 맞지 않습니다 ✗","lee: tú 긍정 명령형 → 정답 ✓","lees: 직설법 현재(너는 읽는다)라 명령이 아닙니다 ✗"]},{"id":"G568","q":"____ di algo de dinero para que se compraran algunas golosinas.","o":["Les","A ellos","Los","Las"],"a":0,"k":"간접목적격 les","t":"그들이 사탕을 좀 살 수 있도록 돈을 조금 줬다.","e":"dar(주다)에서 '누구에게'는 간접목적격 대명사(~에게에 해당)로 씁니다. se compraran(그들이 사도록)으로 보아 받는 사람은 3인칭 복수이므로 les가 맞습니다. a ellos만 쓰고 les를 빼면 틀린 문장이 됩니다.","x":["Les: 3인칭 복수 간접목적격(그들에게) → 정답 ✓","A ellos: 강조로 덧붙일 수는 있지만 les 없이 단독으로 쓰면 틀립니다 ✗","Los: 직접목적격(그들을)이라 '돈을 그들에게 주다'와 맞지 않습니다 ✗","Las: 여성 복수 직접목적격(그녀들을)이라 맞지 않습니다 ✗"]},{"id":"G569","q":"Te quiero ____, eres el amor de mi vida.","o":["mucho","mucha","muchos","muy"],"a":0,"k":"부사 mucho","t":"너를 정말 많이 사랑해, 너는 내 인생의 사랑이야.","e":"동사 quiero(사랑하다)를 꾸미므로 형태가 변하지 않는 부사 mucho(많이)를 씁니다. muy(매우)는 형용사·부사 앞에서만 씁니다. Te quiero mucho는 '정말 사랑해'라는 대표적인 표현입니다.","x":["mucho: 동사를 꾸미는 부사 '많이' → 정답 ✓","mucha: 여성형 형용사라 동사를 꾸밀 수 없습니다 ✗","muchos: 복수형 형용사라 동사를 꾸밀 수 없습니다 ✗","muy: 형용사·부사 앞에만 쓰고 동사 뒤에 혼자 쓰지 않습니다 ✗"]},{"id":"G570","q":"Si no tienes paciencia, no ____ a la enseñanza.","o":["dedícate","dediques","te dediques","dedicas"],"a":2,"k":"부정 명령 + 재귀","t":"인내심이 없다면 교직에 종사하지 마.","e":"dedicarse a(~에 종사하다, ~을 직업으로 하다)는 재귀 동사입니다. 부정 명령에서는 대명사가 동사 앞으로 오고 동사는 접속법이므로 no te dediques가 됩니다. 긍정 명령이라면 dedícate(종사해)처럼 대명사를 뒤에 붙입니다.","x":["dedícate: 긍정 명령형이라 no와 함께 쓰지 않습니다 ✗","dediques: 재귀 대명사 te가 빠져 있습니다 ✗","te dediques: no + te + 접속법, 부정 명령 → 정답 ✓","dedicas: 직설법이고 재귀 대명사도 없어 명령이 아닙니다 ✗"]},{"id":"G571","q":"No sé ____ qué día estamos hoy. ¿Es martes?","o":["de","con","por","a"],"a":3,"k":"estar a + 날짜","t":"오늘이 며칠인지 모르겠어. 화요일이야?","e":"날짜·요일을 물을 때 ¿A qué día estamos?(오늘이 무슨 날이지?)라는 관용 표현을 씁니다. 대답은 Estamos a martes.(화요일이야.)처럼 estar a + 요일/날짜입니다. 그래서 no sé a qué día estamos가 됩니다.","x":["de: de qué día라고 하지 않습니다 ✗","con: con qué día라고 하지 않습니다 ✗","por: por qué día라고 하지 않습니다 ✗","a: 날짜 표현 estar a + 날짜 → 정답 ✓"]},{"id":"G572","q":"En la fiesta que dio Gloria había ____ gente, fue un éxito.","o":["muchísimo","poquísima","muchísima","poquísimo"],"a":2,"k":"muchísima (형용사)","t":"글로리아가 연 파티에는 사람이 정말 많아서 대성공이었다.","e":"gente(사람들)는 뜻은 복수지만 문법적으로 여성 단수 명사입니다. 그래서 형용사도 여성 단수 muchísima(정말 많은)를 씁니다. 파티가 성공했다(fue un éxito)고 했으므로 사람이 '많았다'는 뜻이 맞습니다.","x":["muchísimo: 남성형이라 여성 명사 gente와 맞지 않습니다 ✗","poquísima: 성·수는 맞지만 '아주 적은'이라는 뜻이라 대성공과 모순됩니다 ✗","muchísima: 여성 단수 '정말 많은' → 정답 ✓","poquísimo: 남성형이고 뜻도 반대입니다 ✗"]},{"id":"G573","q":"Nos veremos ____ 1 de la tarde.","o":["a la","a las","al","la"],"a":0,"k":"시각 a la una","t":"오후 1시에 만나자.","e":"시각은 a + 정관사 + 숫자로 나타내고, 관사는 hora(시)에 맞춰 여성형을 씁니다. 1시는 단수라서 a la una, 2시부터는 복수라서 a las dos가 됩니다. 문장에서는 숫자 1로 썼지만 읽을 때는 a la una de la tarde입니다.","x":["a la: 1시는 단수 여성 관사 → 정답 ✓","a las: 2시 이상에만 씁니다 ✗","al: 남성 관사라 시각에는 쓰지 않습니다 ✗","la: 전치사 a가 없으면 '~시에'가 되지 않습니다 ✗"]},{"id":"G574","q":"Están escuchando ____ música clásica.","o":["a la","ø","a","por"],"a":1,"k":"관사 생략","t":"그들은 클래식 음악을 듣고 있다.","e":"escuchar(듣다)는 전치사 없이 직접목적어를 받습니다. 또한 '(어떤 종류의) 음악'을 일반적으로 말할 때는 관사를 쓰지 않아 escuchar música clásica가 자연스럽습니다. 예: Bebo café.(나는 커피를 마신다.)","x":["a la: 사물 목적어 앞에 a를 쓰지 않습니다 ✗","ø: 일반적인 음악 장르는 관사 생략 → 정답 ✓","a: 사람이 아닌 목적어 앞에는 a를 쓰지 않습니다 ✗","por: escuchar 뒤에 por를 쓰지 않습니다 ✗"]},{"id":"G575","q":"Ni Julia ni Cristina ____ alemán.","o":["hablen","hablamos","habláis","hablan"],"a":3,"k":"ni ... ni + 복수","t":"훌리아도 크리스티나도 독일어를 하지 못한다.","e":"ni A ni B(A도 B도 ~않다)가 동사 앞에 오면 보통 두 사람을 합쳐 복수 동사를 씁니다. 훌리아와 크리스티나는 '그녀들'(3인칭 복수)이므로 hablan이 맞습니다. 사실을 말하는 문장이라 직설법을 씁니다.","x":["hablen: 접속법이라 사실 서술에 맞지 않습니다 ✗","hablamos: 1인칭 복수(우리)라 주어와 맞지 않습니다 ✗","habláis: 2인칭 복수(너희)라 주어와 맞지 않습니다 ✗","hablan: 3인칭 복수 직설법 → 정답 ✓"]},{"id":"G576","q":"Si no tienes entradas para el concierto, yo puedo venderte ____.","o":["lo","un","una","la"],"a":2,"k":"명사 생략 una","t":"콘서트 표가 없으면 내가 한 장 팔 수 있어.","e":"앞에 나온 명사 entrada(입장권, 표)를 반복하지 않을 때, 부정관사 대신 대명사 uno/una를 씁니다. entrada는 여성 명사이므로 una(한 장)가 맞습니다. 예: ¿Tienes un bolígrafo? Sí, tengo uno.(펜 있어? 응, 하나 있어.)","x":["lo: 남성 단수 직접목적격이라 여성 명사 entradas와 맞지 않습니다 ✗","un: 명사 없이 혼자 쓸 수 없고 남성형입니다 ✗","una: 여성 명사 entrada를 대신하는 '한 장' → 정답 ✓","la: '그 표를'이 되어 앞의 복수 entradas 중 특정한 것을 가리키게 되어 맞지 않습니다 ✗"]},{"id":"G577","q":"____, ¿qué hace? Aquí no se puede aparcar.","o":["Oigan","Oyes","Oye","Oiga"],"a":3,"k":"usted 명령형 (oír)","t":"저기요, 뭐 하시는 거예요? 여기는 주차할 수 없어요.","e":"뒤의 ¿qué hace?가 usted(당신) 형태이므로, 모르는 사람의 주의를 끌 때도 usted 명령형 oiga(저기요)를 씁니다. 친구에게는 tú 명령형 oye(야, 있잖아)를 씁니다. 여러 명에게는 oigan입니다.","x":["Oigan: ustedes(여러분) 명령형이라 단수 hace와 맞지 않습니다 ✗","Oyes: 직설법 현재(너는 듣는다)라 부르는 말이 아닙니다 ✗","Oye: tú 명령형이라 usted 형태 hace와 맞지 않습니다 ✗","Oiga: usted 명령형 '저기요' → 정답 ✓"]},{"id":"G578","q":"Mi carro no es tan grande ____ tuyo.","o":["al","que el","como el","del"],"a":2,"k":"tan ... como","t":"내 차는 네 차만큼 크지 않다.","e":"동등비교(~만큼 …하다)는 tan + 형용사 + como로 씁니다. 여기서 el tuyo(네 것)는 el carro tuyo를 줄인 소유대명사입니다. 그래서 tan grande como el tuyo가 됩니다. carro는 중남미에서 '자동차'라는 뜻입니다(스페인: coche).","x":["al: 비교 구문에 a를 쓰지 않습니다 ✗","que el: que는 más/menos 비교에 쓰며 tan과 함께 쓰지 않습니다 ✗","como el: tan ... como + 소유대명사 → 정답 ✓","del: 비교 구문에 de를 쓰지 않습니다 ✗"]},{"id":"G579","q":"Ernesto ya ha recuperado su carné, ____ devolvieron ayer.","o":["se le","se los","le lo","se lo"],"a":3,"k":"se lo (이중 대명사)","t":"에르네스토는 이미 신분증을 되찾았다, 어제 그에게 돌려주었다.","e":"간접목적격 le(그에게)와 직접목적격 lo(그것을)가 함께 오면 le가 se로 바뀌어 se lo가 됩니다. 여기서 lo는 남성 단수 carné(신분증)를 가리킵니다. 예: Se lo di ayer.(어제 그것을 그에게 줬어.)","x":["se le: 직접목적격(그것을)이 빠져 있습니다 ✗","se los: los는 복수라 단수 carné와 맞지 않습니다 ✗","le lo: le는 lo 앞에서 반드시 se로 바뀌어야 합니다 ✗","se lo: le → se + lo(그것을) → 정답 ✓"]},{"id":"G580","q":"Pedro es igual de responsable ____ Fernando.","o":["tanto","como","que","de"],"a":2,"k":"igual de...que","t":"페드로는 페르난도만큼 책임감이 있다.","e":"igual de + 형용사 + que는 '~만큼 …하다'라는 동등비교입니다. tan responsable como와 같은 뜻이지만, igual de 뒤에는 como가 아닌 que를 씁니다. 예: Es igual de alto que yo.(그는 나만큼 키가 크다.)","x":["tanto: 비교 대상 앞에 tanto를 쓰지 않습니다 ✗","como: tan ... como와 섞인 형태로 일상에서 들리지만 규범적으로는 que를 씁니다 ✗","que: igual de ... que → 정답 ✓","de: 비교 대상 앞에 de를 쓰지 않습니다 ✗"]},{"id":"G581","q":"Esta carta no es ____.","o":["mi","mí","mía","de mí"],"a":2,"k":"소유형용사 mía","t":"이 편지는 내 것이 아니다.","e":"ser 뒤에서 '내 것'을 말할 때는 명사 뒤에 오는 강세형 소유형용사 mío/mía를 씁니다. carta(편지)는 여성 명사이므로 mía가 맞습니다. 예: Este libro es mío.(이 책은 내 것이다.)","x":["mi: 명사 앞에만 쓰는 소유형용사(나의)라 혼자 쓸 수 없습니다 ✗","mí: 전치사 뒤에 쓰는 대명사(para mí)라 맞지 않습니다 ✗","mía: 여성 단수 강세형 소유형용사 '내 것' → 정답 ✓","de mí: 소유를 나타낼 때 쓰지 않는 형태입니다 ✗"]},{"id":"G582","q":"No me gustan ____ miércoles porque tengo clase de química.","o":["ø","las","los","el"],"a":2,"k":"요일 + 정관사","t":"나는 수요일이 싫어, 화학 수업이 있거든.","e":"요일은 남성 명사이며, '매주 ~요일마다(일반적으로)'라는 뜻일 때는 복수 정관사 los를 씁니다. miércoles는 단수와 복수 형태가 같지만, 동사 gustan이 복수이므로 los miércoles가 맞습니다. 예: Los lunes trabajo.(월요일마다 일한다.)","x":["ø: gustar의 주어 자리에는 관사가 필요합니다 ✗","las: 요일은 남성 명사라 여성 관사와 맞지 않습니다 ✗","los: 남성 복수 정관사, 복수 동사 gustan과 일치 → 정답 ✓","el: 단수형이라 복수 동사 gustan과 맞지 않습니다 ✗"]},{"id":"G583","q":"Marga suele ____ la versión digital de los periódicos que más le gustan.","o":["lee","leer","leyendo","a leer"],"a":1,"k":"soler + 원형","t":"마르가는 좋아하는 신문을 보통 디지털판으로 읽는다.","e":"soler + 동사원형은 '보통 ~하다, ~하곤 하다'라는 습관 표현입니다. soler 뒤에는 전치사 없이 바로 동사원형이 옵니다. 예: Suelo levantarme temprano.(나는 보통 일찍 일어난다.)","x":["lee: 활용된 동사라 soler 뒤에 올 수 없습니다 ✗","leer: soler + 동사원형 → 정답 ✓","leyendo: 현재분사는 soler 뒤에 쓰지 않습니다 ✗","a leer: soler 뒤에 a를 넣지 않습니다 ✗"]},{"id":"G584","q":"¿Te apetece tomar ____ trozo de pastel?","o":["otro","otros","otra","un otro"],"a":0,"k":"otro (관사 없이)","t":"케이크 한 조각 더 먹을래?","e":"otro(다른, 또 하나의)는 앞에 부정관사 un을 붙이지 않습니다. trozo(조각)는 남성 단수이므로 otro trozo가 맞습니다. 영어의 another를 생각해 un otro라고 하기 쉬우니 주의하세요.","x":["otro: 남성 단수, 관사 없이 '또 하나의' → 정답 ✓","otros: 복수형이라 단수 trozo와 맞지 않습니다 ✗","otra: 여성형이라 남성 명사 trozo와 맞지 않습니다 ✗","un otro: otro 앞에는 un을 쓰지 않습니다 ✗"]},{"id":"G585","q":"No ____ nadar, por eso no me meto en el agua.","o":["se","sabré","sabía","sé"],"a":3,"k":"saber + 원형 (능력)","t":"나는 수영을 못해, 그래서 물에 안 들어가.","e":"saber + 동사원형은 배워서 할 줄 아는 능력(~할 줄 알다)을 나타냅니다. 현재의 사실이고 뒤의 me meto로 보아 주어는 yo이므로 sé가 맞습니다. 악센트가 있는 sé(나는 안다)와 없는 se(대명사)를 구별하세요.","x":["se: 악센트 없는 se는 대명사라 동사가 아닙니다 ✗","sabré: 미래형이라 현재 사실과 맞지 않습니다 ✗","sabía: 불완료과거라 현재형 me meto와 맞지 않습니다 ✗","sé: saber 현재 1인칭 '할 줄 안다' → 정답 ✓"]},{"id":"G586","q":"Te dije que ese tipo no te ____ el dinero y no me equivoqué.","o":["devolvería","devolvió","devolviera","ha devuelto"],"a":0,"k":"과거 속 미래 (조건법)","t":"그 녀석이 너한테 돈을 돌려주지 않을 거라고 했잖아, 내 말이 틀리지 않았지.","e":"과거에 말한 내용(te dije que) 속의 미래는 가정법 조건(조건법, -ría 형태)으로 나타냅니다. 당시 'No te devolverá el dinero.(돈 안 돌려줄 거야)'라고 했던 말을 과거로 옮겨 no te devolvería가 됩니다. tipo는 구어에서 '녀석, 그 사람'을 뜻합니다.","x":["devolvería: 과거에서 본 미래(조건법) → 정답 ✓","devolvió: 단순과거라 그때 '돌려주지 않을 것'이라는 예측을 나타내지 못합니다 ✗","devolviera: 접속법 과거라 decir que(전달) 뒤에 쓰지 않습니다(명령 전달일 때만 가능) ✗","ha devuelto: 현재완료라 과거 시점의 예측과 맞지 않습니다 ✗"]},{"id":"G587","q":"En ____ bar los precios de las bebidas son muy altos.","o":["este","esta","estos","esto"],"a":0,"k":"지시형용사 este","t":"이 바에서는 음료 가격이 아주 비싸다.","e":"지시형용사는 뒤의 명사와 성·수를 맞춥니다. bar는 남성 단수이므로 este bar(이 바)가 됩니다. esto는 중성 대명사라 명사 앞에 쓰지 않습니다.","x":["este: 남성 단수 지시형용사 → 정답 ✓","esta: 여성형이라 남성 명사 bar와 맞지 않습니다 ✗","estos: 복수형이라 단수 bar와 맞지 않습니다 ✗","esto: 중성 대명사라 명사 앞에 쓸 수 없습니다 ✗"]},{"id":"G588","q":"____ tienes sed, será mejor que bebas agua en vez de una bebida azucarada.","o":["Si","Por","Aunque","Porque"],"a":0,"k":"조건 si","t":"목이 마르면 단 음료 대신 물을 마시는 게 좋을 거야.","e":"si는 '만약 ~하면'이라는 조건을 나타내며, 실제로 일어날 수 있는 조건에는 직설법 현재(tienes)를 씁니다. 목이 마른 경우에 대한 조언이므로 Si가 맞습니다. será mejor que + 접속법(bebas)은 '~하는 게 좋겠다'라는 표현입니다.","x":["Si: 조건 '만약 ~하면' → 정답 ✓","Por: 전치사라 뒤에 활용된 동사가 올 수 없습니다 ✗","Aunque: '비록 ~지만'이라는 양보라 조언의 의미와 맞지 않습니다 ✗","Porque: 이유 접속사는 보통 문장 맨 앞에 쓰지 않고, 뜻도 조건과 다릅니다 ✗"]},{"id":"G589","q":"____ estás libre este sábado, podemos ir al restaurante de mi primo.","o":["Así que","Cuando","En cuanto","Si"],"a":3,"k":"조건 si","t":"이번 토요일에 시간이 되면, 내 사촌의 식당에 갈 수 있어.","e":"'만약 ~라면'이라는 조건은 si + 직설법 현재로 나타냅니다. 토요일에 시간이 될지 확실하지 않은 조건이므로 Si가 맞습니다. cuando, en cuanto는 미래 일에 쓸 때 뒤에 접속법이 와야 해서 estás와 맞지 않습니다.","x":["Así que: '그래서'라는 결과 접속사라 문장 앞 조건에 맞지 않습니다 ✗","Cuando: 미래의 일이면 cuando estés(접속법)여야 합니다 ✗","En cuanto: '~하자마자'이고 미래면 접속법이 필요해 맞지 않습니다 ✗","Si: 조건 '만약 ~면' + 직설법 → 정답 ✓"]},{"id":"G590","q":"A los mexicanos ____ gusta celebrar el Día de Muertos de una forma muy especial.","o":["le","les","los","se"],"a":1,"k":"gustar + les","t":"멕시코 사람들은 망자의 날을 아주 특별한 방식으로 기념하는 것을 좋아한다.","e":"gustar 구문에서 좋아하는 사람은 간접목적격 대명사로 나타냅니다. a los mexicanos(멕시코 사람들에게)는 3인칭 복수이므로 les가 맞습니다. 동사 gusta는 뒤의 동사원형(celebrar)이 주어이기 때문에 단수입니다.","x":["le: 3인칭 단수라 복수 los mexicanos와 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격 → 정답 ✓","los: 직접목적격이라 gustar 구문에 쓰지 않습니다 ✗","se: 재귀 대명사라 gustar 구문과 맞지 않습니다 ✗"]},{"id":"G591","q":"Óscar es estudiante ____ Medicina.","o":["de","en la","por","de la"],"a":0,"k":"estudiante de","t":"오스카는 의대생이다.","e":"전공을 말할 때는 estudiante de + 학문 이름으로 쓰며, 학문 이름 앞에는 관사를 쓰지 않습니다. estudiante de Medicina는 '의학 전공 학생(의대생)'입니다. 예: Soy estudiante de Derecho.(나는 법학과 학생이다.)","x":["de: estudiante de + 전공(관사 없음) → 정답 ✓","en la: estudiante en la는 장소(학교) 앞에 쓰며 전공 앞에는 맞지 않습니다 ✗","por: 전공을 나타내지 않습니다 ✗","de la: 전공 이름 앞에는 관사를 붙이지 않습니다 ✗"]},{"id":"G592","q":"____ mi pueblo, la Pascua se celebra de una forma muy especial.","o":["Entre","Desde","De","En"],"a":3,"k":"전치사 en (장소)","t":"우리 마을에서는 부활절을 아주 특별한 방식으로 기념한다.","e":"어떤 일이 일어나는 장소 '~에서'는 전치사 en으로 나타냅니다. En mi pueblo는 '우리 마을에서'라는 뜻입니다. Pascua(부활절)는 스페인어권에서 중요한 종교 행사입니다.","x":["Entre: '~ 사이에'라는 뜻이라 맞지 않습니다 ✗","Desde: '~에서부터'라는 출발점이라 맞지 않습니다 ✗","De: '~의, ~출신'이라는 뜻이라 장소를 나타내기에 맞지 않습니다 ✗","En: 장소 '~에서' → 정답 ✓"]},{"id":"G593","q":"Elvira y José Miguel se divorciaron ____ dos años.","o":["de hace","desde hace","hace","desde"],"a":2,"k":"hace + 기간","t":"엘비라와 호세 미겔은 2년 전에 이혼했다.","e":"과거의 한 시점 '~ 전에'는 hace + 기간으로 나타냅니다. se divorciaron(이혼했다)이 한 번에 끝난 사건이므로 hace dos años(2년 전에)가 맞습니다. desde hace는 '~ 전부터 지금까지 계속'이라는 뜻이라 현재형과 씁니다.","x":["de hace: 명사를 꾸밀 때(un amigo de hace años) 쓰고 여기서는 맞지 않습니다 ✗","desde hace: 계속을 나타내 현재형과 쓰므로 단순과거와 맞지 않습니다 ✗","hace: '~ 전에' → 정답 ✓","desde: 뒤에 기간이 아닌 시점이 와야 합니다(desde 2020) ✗"]},{"id":"G594","q":"____ abrir la puerta, vi una caja en el felpudo.","o":["Al","Por","A","En"],"a":0,"k":"al + 원형","t":"문을 열었을 때, 현관 매트 위에 상자가 하나 보였다.","e":"al + 동사원형은 '~할 때, ~하자'라는 뜻으로, 두 동작이 동시에 일어남을 나타냅니다. Al abrir la puerta는 '문을 열자'라는 의미입니다. 예: Al llegar a casa, me duché.(집에 도착하자 샤워했다.)","x":["Al: al + 동사원형 '~할 때' → 정답 ✓","Por: por + 원형은 '~때문에'라는 이유라 맞지 않습니다 ✗","A: 관사가 없으면 '~할 때'의 의미가 되지 않습니다 ✗","En: en + 원형은 이런 시간 표현에 쓰지 않습니다 ✗"]},{"id":"G595","q":"Creo que ____ españoles son muy expresivos.","o":["ø","las","los","el"],"a":2,"k":"정관사 (일반화)","t":"스페인 사람들은 표현력이 아주 풍부한 것 같다.","e":"어떤 집단 전체를 일반적으로 말할 때는 정관사를 씁니다. españoles는 남성 복수이므로 los españoles(스페인 사람들)가 됩니다. 스페인어에서는 주어 자리의 일반 명사 앞에 관사를 생략하지 않습니다.","x":["ø: 주어 자리에서 집단 전체를 말할 때는 관사가 필요합니다 ✗","las: 여성형이라 남성 복수 españoles와 맞지 않습니다 ✗","los: 남성 복수 정관사, 일반화 → 정답 ✓","el: 단수형이라 복수 명사와 맞지 않습니다 ✗"]},{"id":"G596","q":"Hay ____ sal, no olvides comprar un paquete cuando vayas a la tienda.","o":["poca","mucha","bastante","suficiente"],"a":0,"k":"poca (적은)","t":"소금이 조금밖에 없어, 가게 가면 한 봉지 사는 거 잊지 마.","e":"소금을 사 와야 한다고 했으므로 남은 양이 '적다'는 뜻의 poca가 맞습니다. sal(소금)은 여성 명사라 poco의 여성형 poca를 씁니다. hay poca sal은 '소금이 조금밖에 없다(부족하다)'라는 의미입니다.","x":["poca: '적은', 여성 명사 sal과 일치 → 정답 ✓","mucha: '많은'이라 소금을 사 오라는 말과 모순됩니다 ✗","bastante: '충분한, 꽤 많은'이라 문맥과 맞지 않습니다 ✗","suficiente: '충분한'이라 사러 갈 이유와 모순됩니다 ✗"]},{"id":"G597","q":"____, si no te importa llámame en media hora.","o":["Cené","Ceno","Estoy cenando","Estar cenando"],"a":2,"k":"현재진행","t":"지금 저녁 먹는 중이야, 괜찮으면 30분 후에 전화해 줘.","e":"말하는 순간 하고 있는 행동은 estar + 현재분사(현재진행)로 나타냅니다. Estoy cenando는 '나 지금 저녁 먹고 있어'라는 뜻입니다. en media hora는 '30분 후에'라는 의미입니다.","x":["Cené: 단순과거라 지금 전화를 미루는 이유가 되지 않습니다 ✗","Ceno: 현재형은 습관을 나타내어 '지금 진행 중'이라는 뜻이 약합니다 ✗","Estoy cenando: 현재진행 '먹는 중' → 정답 ✓","Estar cenando: 동사원형이라 본동사가 될 수 없습니다 ✗"]},{"id":"G598","q":"Este gorro no es mío, es ____ mi madre.","o":["por","desde","de","a"],"a":2,"k":"ser de (소유)","t":"이 모자는 내 것이 아니라 우리 엄마 거야.","e":"ser de + 사람은 '~의 것이다'라는 소유 표현입니다. es de mi madre는 '우리 엄마의 것이다'라는 뜻입니다. 예: ¿De quién es este libro?(이 책 누구 거야?)","x":["por: 소유를 나타내지 않습니다 ✗","desde: '~부터'라는 출발점이라 맞지 않습니다 ✗","de: ser de '~의 것이다' → 정답 ✓","a: 소유를 나타내지 않습니다 ✗"]},{"id":"G599","q":"El domingo vi a Esperanza y ____ noté muy contenta.","o":["lo","le","la","se"],"a":2,"k":"직접목적격 la","t":"일요일에 에스페란사를 봤는데, 아주 기뻐 보였다.","e":"notar(알아차리다, ~해 보이다)는 직접목적어를 받습니다. 에스페란사는 여성 단수이므로 직접목적격 대명사 la를 씁니다. contenta(여성형)에서도 여성임을 알 수 있습니다. 스페인 일부 지역에서는 le를 쓰기도 하지만(레이스모) 표준은 la입니다.","x":["lo: 남성 직접목적격이라 여성 Esperanza와 맞지 않습니다 ✗","le: 간접목적격이라 직접목적어 자리에 표준적으로 쓰지 않습니다 ✗","la: 여성 단수 직접목적격(그녀를) → 정답 ✓","se: 재귀 대명사라 주어 자신을 가리키게 되어 맞지 않습니다 ✗"]},{"id":"G600","q":"Los domingos ____ la mañana suelo dar un paseo con mi novio por la playa.","o":["de","para","con","por"],"a":3,"k":"por la mañana","t":"일요일 아침마다 나는 보통 남자친구와 해변을 산책한다.","e":"하루의 시간대는 por la mañana(아침에), por la tarde(오후에), por la noche(밤에)처럼 por로 나타냅니다. los domingos por la mañana는 '일요일 아침마다'라는 뜻입니다. 정확한 시각이 있을 때는 a las diez de la mañana처럼 de를 씁니다.","x":["de: 정확한 시각 뒤(a las diez de la mañana)에만 씁니다 ✗","para: '~까지(기한)'나 목적이라 시간대를 나타내지 않습니다 ✗","con: 시간대를 나타내지 않습니다 ✗","por: por la mañana '아침에' → 정답 ✓"]},{"id":"G601","q":"____ nada de sal, la ensalada está sosa.","o":["Con","Por","Sin","De"],"a":2,"k":"전치사 sin","t":"소금이 전혀 없어서 샐러드가 싱겁다.","e":"sin은 '~없이, ~이 없는'이라는 뜻의 전치사입니다. 문장 앞의 'Sin nada de sal(소금이 하나도 없이)'이 샐러드가 싱거운(sosa) 이유를 나타냅니다. 'nada de + 명사'는 '~이 전혀 없는'이라는 강조 표현이라 sin과 잘 어울립니다.","x":["Con: '~와 함께, ~을 넣고'라는 뜻이라 소금이 없어서 싱겁다는 의미와 반대입니다 ✗","Por: '~때문에, ~을 통해'라는 뜻이지만 'Por nada de sal'은 쓰지 않는 표현입니다 ✗","Sin: '~없이'라는 뜻으로 소금이 없는 상태를 나타냄 → 정답 ✓","De: '~의, ~로부터'라는 뜻으로 이 자리에서 의미가 통하지 않습니다 ✗"]},{"id":"G602","q":"Están buscando ____ un sustituto del profesor de latín.","o":["para","por","ø","sobre"],"a":2,"k":"buscar + 목적어","t":"그들은 라틴어 선생님의 대리 교사를 찾고 있다.","e":"buscar(찾다)는 원래 전치사 없이 바로 목적어를 받습니다. 사람이 목적어일 때는 보통 'a'를 붙이지만, 'un sustituto(어떤 대리 교사)'처럼 아직 정해지지 않은 불특정한 사람이면 'a'를 생략합니다. 그래서 빈칸에는 아무것도 넣지 않습니다. 예: Busco a mi hermano.(내 남동생을 찾고 있어.) / Busco un profesor.(선생님 한 분을 구하고 있어.)","x":["para: '~를 위해'라는 뜻이라 buscar의 목적어 앞에 쓰지 않습니다 ✗","por: buscar por는 '~을 뒤지며 찾다(장소)'에 쓰여 여기서는 맞지 않습니다 ✗","ø: buscar는 바로 목적어를 받고, 불특정한 사람이라 a도 생략 → 정답 ✓","sobre: '~에 관하여, ~위에'라는 뜻으로 이 구조에 맞지 않습니다 ✗"]},{"id":"G603","q":"No me gusta la carne ____ el pescado.","o":["e","o","y","ni"],"a":3,"k":"부정 접속사 ni","t":"나는 고기도 생선도 좋아하지 않는다.","e":"부정문에서 '~도 ~도 아니다'라고 말할 때는 y(그리고) 대신 ni를 씁니다. 'No me gusta la carne ni el pescado'는 고기와 생선 둘 다 싫다는 뜻입니다. 예: No bebo café ni té.(나는 커피도 차도 안 마셔.)","x":["e: y의 변형으로 i-/hi-로 시작하는 단어 앞에서 쓰며, 부정문 연결에는 맞지 않습니다 ✗","o: '또는'이라는 뜻이라 둘 다 싫다는 의미가 약해집니다 ✗","y: '그리고'라는 뜻으로 부정문에서 두 대상을 모두 부정할 때는 보통 ni를 씁니다 ✗","ni: 부정문에서 '~도 (아니다)'를 연결 → 정답 ✓"]},{"id":"G604","q":"¿____ es ese hombre que está fuera?","o":["Cuál","Qué","Dónde","Quién"],"a":3,"k":"의문사 quién","t":"밖에 있는 저 남자는 누구야?","e":"사람의 정체를 물을 때는 quién(누구)을 씁니다. 'ese hombre(저 남자)'가 누구인지 묻고 있으므로 ¿Quién es...?가 맞습니다. 의문사에는 항상 악센트(é)가 붙는다는 점도 기억하세요.","x":["Cuál: 여러 개 중 '어느 것'을 고를 때 쓰며 사람의 정체를 묻는 데는 어색합니다 ✗","Qué: '무엇'이라는 뜻으로 ¿Qué es ese hombre?는 직업 등을 묻는 느낌이라 어색합니다 ✗","Dónde: '어디'를 묻는 의문사라 의미가 맞지 않습니다 ✗","Quién: 사람이 '누구'인지 묻는 의문사 → 정답 ✓"]},{"id":"G605","q":"Estoy intentando ____ concentrarme. ¿Podéis hacer menos ruido?","o":["de","ø","por","a"],"a":1,"k":"intentar + 동사원형","t":"집중하려고 노력하는 중이야. 좀 덜 시끄럽게 해 줄래?","e":"intentar(시도하다, 애쓰다)는 전치사 없이 바로 동사원형을 붙입니다. 'intentar concentrarme(집중하려고 애쓰다)'처럼요. 재귀대명사 me는 동사원형 뒤에 붙여 씁니다. 예: Intento dormir.(자려고 해.)","x":["de: tratar de(~하려고 하다)와 헷갈리기 쉽지만 intentar 뒤에는 쓰지 않습니다 ✗","ø: intentar는 바로 동사원형을 받음 → 정답 ✓","por: luchar por처럼 다른 동사와 쓰이며 intentar와는 쓰지 않습니다 ✗","a: empezar a처럼 다른 동사와 쓰이며 intentar 뒤에는 오지 않습니다 ✗"]},{"id":"G606","q":"____ amigos, Julio es el más extrovertido.","o":["De mis","Mis","A mis","Por mis"],"a":0,"k":"최상급 + de","t":"내 친구들 중에서 훌리오가 가장 외향적이다.","e":"'~중에서 가장 ...하다'라는 최상급에서는 비교 범위를 de로 나타냅니다. 문장 앞으로 나와 'De mis amigos(내 친구들 중에서)'가 되었고, 뒤에 'el más extrovertido(가장 외향적인 사람)'가 이어집니다. 예: Es el más alto de la clase.(그는 반에서 제일 키가 커.)","x":["De mis: 최상급의 비교 범위 '~중에서' → 정답 ✓","Mis: 전치사가 없으면 '내 친구들'이 문장 속에서 역할이 없어집니다 ✗","A mis: '내 친구들에게'라는 뜻이 되어 의미가 맞지 않습니다 ✗","Por mis: '내 친구들 때문에/을 통해'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G607","q":"¿Por qué ____ de Pedrito?","o":["burláis","burlaros","vosotros burláis","os burláis"],"a":3,"k":"재귀동사 burlarse","t":"너희는 왜 페드리토를 놀리니?","e":"burlarse de(~를 놀리다, 비웃다)는 재귀대명사가 꼭 필요한 동사입니다. 주어가 vosotros(너희, 스페인식)이므로 재귀대명사 os를 활용형 burláis 앞에 둡니다. 중남미에서는 vosotros 대신 ustedes를 써서 '¿Por qué se burlan de Pedrito?'라고 합니다.","x":["burláis: 재귀대명사 os가 빠져서 틀립니다 ✗","burlaros: 동사원형이라 활용된 동사가 필요한 자리에 맞지 않습니다 ✗","vosotros burláis: 주어는 있지만 여전히 재귀대명사 os가 빠졌습니다 ✗","os burláis: 재귀대명사 os + 2인칭 복수 활용형 → 정답 ✓"]},{"id":"G608","q":"Vamos a tomarnos ____ café, ¿quieres venir con nosotros?","o":["uno","ø","una","un"],"a":3,"k":"부정관사 un","t":"우리 커피 한잔하러 갈 건데, 같이 갈래?","e":"café(커피)는 남성 단수 명사이므로 부정관사 un을 씁니다. 'tomarse un café'는 '커피 한잔하다'라는 아주 흔한 표현입니다. uno는 명사 없이 혼자 쓸 때의 형태이고, 명사 앞에서는 un으로 줄어듭니다.","x":["uno: 명사 없이 단독으로 쓰는 형태이며 명사 앞에서는 un이 됩니다 ✗","ø: 관사를 빼면 '커피 한잔하다'라는 자연스러운 표현이 되지 않습니다 ✗","una: 여성형이라 남성명사 café와 맞지 않습니다 ✗","un: 남성 단수 명사 앞의 부정관사 → 정답 ✓"]},{"id":"G609","q":"Julia se casó cuando solo ____ diecinueve años.","o":["ha tenido","tuvo","había tenido","tenía"],"a":3,"k":"불완료과거(나이)","t":"훌리아는 겨우 열아홉 살이었을 때 결혼했다.","e":"과거의 나이처럼 그 당시의 상태나 배경을 말할 때는 불완료과거(과거의 상태·배경·습관을 나타내는 과거형)를 씁니다. 결혼한 사건(se casó)은 단순과거로, 그때의 나이(tenía 19 años)는 불완료과거로 표현합니다. 예: Cuando tenía diez años, vivía en Seúl.(열 살 때 서울에 살았어.)","x":["ha tenido: 현재완료라 과거 특정 시점의 나이를 말할 수 없습니다 ✗","tuvo: 단순과거는 완결된 사건에 쓰며 나이 같은 배경 상태에는 쓰지 않습니다 ✗","había tenido: 대과거로 '이미 가졌었다'는 의미가 되어 어색합니다 ✗","tenía: 과거 시점의 나이(상태)를 나타내는 불완료과거 → 정답 ✓"]},{"id":"G610","q":"No ha entrado ____ a nuestra tienda en toda la mañana.","o":["alguien","algún","nadie","algo"],"a":2,"k":"부정어 nadie","t":"오전 내내 우리 가게에 아무도 들어오지 않았다.","e":"부정문(No ha entrado...)에서 '아무도'라고 할 때는 nadie를 씁니다. 스페인어는 no와 nadie를 함께 쓰는 이중부정이 정상입니다. 예: No hay nadie en casa.(집에 아무도 없어.)","x":["alguien: '누군가'라는 긍정 표현이라 부정문 no와 함께 쓰지 않습니다 ✗","algún: 명사 앞에 붙는 형용사형(어떤)이라 단독으로 쓸 수 없습니다 ✗","nadie: 부정문에서 '아무도' → 정답 ✓","algo: '무언가'라는 사물을 가리키며 가게에 들어오는 사람과 맞지 않습니다 ✗"]},{"id":"G611","q":"Esta semana ____ dos veces a la oficina de correos.","o":["iba","estaba yendo","había ido","he ido"],"a":3,"k":"현재완료","t":"이번 주에 나는 우체국에 두 번 갔다.","e":"'Esta semana(이번 주)'처럼 아직 끝나지 않은 시간 범위 안의 일은 스페인 스페인어에서 현재완료(haber + 과거분사)로 말합니다. 'he ido(갔다)'는 ir의 현재완료입니다. 중남미에서는 이런 경우에도 단순과거 'fui'를 많이 씁니다.","x":["iba: 과거의 습관·배경을 나타내는 불완료과거라 횟수를 센 사건에는 맞지 않습니다 ✗","estaba yendo: 과거진행형으로 '가는 중이었다'라는 뜻이라 맞지 않습니다 ✗","había ido: 대과거로 과거보다 더 이전의 일을 나타내 어색합니다 ✗","he ido: 이번 주(현재와 연결된 시간) 안에 일어난 일 → 정답 ✓"]},{"id":"G612","q":"¿Cuándo vais a ir ____ casa de vuestros abuelos?","o":["de","para","a","en"],"a":2,"k":"ir a + 장소","t":"너희는 언제 할아버지 할머니 댁에 갈 거니?","e":"ir(가다) 뒤에 목적지를 쓸 때는 전치사 a를 씁니다. 'ir a casa de alguien'은 '~의 집에 가다'라는 뜻입니다. 앞의 'vais a ir(갈 것이다)'는 미래 표현 ir a + 동사원형이고, 뒤의 a는 방향을 나타냅니다.","x":["de: '~로부터'라는 출발점을 나타내 방향과 반대입니다 ✗","para: '~쪽으로'라는 뜻도 있지만 ir 뒤 목적지에는 보통 a를 씁니다 ✗","a: 이동 동사 ir의 목적지 '~에, ~로' → 정답 ✓","en: '~에서(안에)'라는 위치를 나타내며 이동 방향에는 쓰지 않습니다 ✗"]},{"id":"G613","q":"Los ladrones entraron en nuestro hogar mientras ____ de vacaciones.","o":["estemos","estábamos","estaríamos","habíamos estado"],"a":1,"k":"mientras+불완료과거","t":"우리가 휴가 중일 때 도둑들이 우리 집에 들어왔다.","e":"과거에 어떤 사건(도둑이 들어옴, entraron)이 일어났을 때 진행 중이던 배경 상황은 불완료과거로 나타냅니다. 'mientras estábamos de vacaciones(우리가 휴가 중이던 동안)'가 그 배경입니다. 'estar de vacaciones'는 '휴가 중이다'라는 표현입니다.","x":["estemos: 접속법 현재라 과거 사실을 말하는 이 문장에 맞지 않습니다 ✗","estábamos: 과거 사건의 배경을 나타내는 불완료과거 → 정답 ✓","estaríamos: 가능법(~할 텐데)이라 실제 있었던 일과 맞지 않습니다 ✗","habíamos estado: 대과거로 '이미 휴가를 다녀왔었다'는 뜻이 되어 어색합니다 ✗"]},{"id":"G614","q":"Cuando estoy muy nervioso, me ____ las manos.","o":["tiemblan","tiemblen","temblaban","temblaron"],"a":0,"k":"현재시제(습관)","t":"나는 아주 긴장하면 손이 떨린다.","e":"'Cuando estoy muy nervioso(내가 매우 긴장할 때)'처럼 반복되는 일반적인 상황에는 현재시제를 씁니다. temblar(떨리다)는 e→ie로 바뀌는 불규칙 동사이고, 주어가 'las manos(손들)'이므로 3인칭 복수 tiemblan입니다. me는 '내' 손이라는 소유를 나타냅니다.","x":["tiemblan: 일반적 사실을 나타내는 직설법 현재 3인칭 복수 → 정답 ✓","tiemblen: 접속법 현재라 사실을 말하는 문장에 맞지 않습니다 ✗","temblaban: 과거형이라 현재시제인 estoy와 시제가 맞지 않습니다 ✗","temblaron: 단순과거라 현재의 습관을 말할 수 없습니다 ✗"]},{"id":"G615","q":"No me gusta nada la moda de este año, ____ horrible.","o":["me parecen","me parece","a mí parece","me parezco"],"a":1,"k":"parecer 구문","t":"올해 유행은 전혀 마음에 안 들어, 끔찍해 보여.","e":"parecer(~처럼 보이다/생각되다)는 gustar처럼 '보는 사람'을 간접목적격 대명사(me, te, le...)로 씁니다. 주어는 'la moda(유행)'로 단수이므로 동사는 parece입니다. 'me parece horrible'은 '내가 보기엔 끔찍하다'라는 뜻입니다.","x":["me parecen: 3인칭 복수형이라 단수 주어 la moda와 맞지 않습니다 ✗","me parece: 단수 주어 la moda + 간접목적격 me → 정답 ✓","a mí parece: 'a mí'를 쓰더라도 대명사 me가 반드시 필요합니다 ✗","me parezco: parecerse(닮다)의 1인칭 형태라 '내가 닮았다'는 뜻이 됩니다 ✗"]},{"id":"G616","q":"Ayer ____ una noticia impactante.","o":["leí","lee","he leído","leo"],"a":0,"k":"단순과거","t":"어제 나는 충격적인 뉴스를 읽었다.","e":"'Ayer(어제)'처럼 이미 끝난 과거의 특정 시점에 일어난 일은 단순과거(완료된 과거 사건을 나타내는 과거형)로 씁니다. leer의 1인칭 단수 단순과거는 leí입니다. 스페인에서는 ayer와 함께 현재완료를 쓰지 않습니다.","x":["leí: 어제 끝난 일을 나타내는 단순과거 1인칭 단수 → 정답 ✓","lee: 현재시제 3인칭 단수라 시제도 인칭도 맞지 않습니다 ✗","he leído: 현재완료는 hoy, esta semana 같은 시간 표현과 쓰며 ayer와는 쓰지 않습니다 ✗","leo: 현재시제라 '어제'와 맞지 않습니다 ✗"]},{"id":"G617","q":"Ayer ____ a nuestro profesor de inglés en el cine.","o":["estábamos viendo","estuvimos viendo","vimos","veíamos"],"a":2,"k":"단순과거 vs 불완료","t":"어제 우리는 영화관에서 우리 영어 선생님을 봤다.","e":"어제 영화관에서 선생님을 '본(마주친)' 것은 한순간에 끝난 사건이므로 단순과거 vimos를 씁니다. 진행형이나 불완료과거는 배경이나 지속되는 동작에 쓰입니다. ver의 nosotros 단순과거는 vimos입니다.","x":["estábamos viendo: '보고 있는 중이었다'라는 배경 진행이라 한 번 마주친 사건과 맞지 않습니다 ✗","estuvimos viendo: 일정 시간 동안 계속 봤다는 뜻이라 사람을 마주친 의미와 어색합니다 ✗","vimos: 과거의 한 번 일어난 사건을 나타내는 단순과거 → 정답 ✓","veíamos: 과거의 습관(자주 보곤 했다)이라 ayer와 맞지 않습니다 ✗"]},{"id":"G618","q":"____ el alquiler de este apartamento es demasiado caro, voy a mudarme a otro.","o":["Cuanto","Como","Que","Cuando"],"a":1,"k":"이유 접속사 como","t":"이 아파트 월세가 너무 비싸서 다른 곳으로 이사할 거야.","e":"como가 문장 맨 앞에 오면 '~이기 때문에, ~해서'라는 이유를 나타냅니다. 이유를 먼저 말하고 결과(voy a mudarme)를 뒤에 말하는 구조입니다. porque는 보통 문장 앞에 오지 않고, 이렇게 앞에 이유를 둘 때는 como를 씁니다. 예: Como llueve, me quedo en casa.(비가 와서 집에 있을래.)","x":["Cuanto: '~할수록, ~만큼'이라는 뜻이라 이유를 나타내지 못합니다 ✗","Como: 문장 앞에서 이유 '~이니까' → 정답 ✓","Que: 문장 맨 앞에서 이유를 나타내는 접속사로 쓰지 않습니다 ✗","Cuando: '~할 때'라는 시간 표현이라 의미가 맞지 않습니다 ✗"]},{"id":"G619","q":"Ni Rocío ni yo ____ hijos.","o":["tenemos","tenéis","tienes","tienen"],"a":0,"k":"ni...ni 주어 일치","t":"로시오도 나도 아이가 없다.","e":"'Ni Rocío ni yo(로시오도 나도 ~아니다)'처럼 주어에 yo가 포함되면 전체를 '우리(nosotros)'로 보고 1인칭 복수로 활용합니다. 그래서 tener의 nosotros형 tenemos가 맞습니다. 예: Ni tú ni yo sabemos.(너도 나도 몰라.)","x":["tenemos: yo가 포함된 복수 주어 → 1인칭 복수 → 정답 ✓","tenéis: 2인칭 복수(너희)라 주어와 맞지 않습니다 ✗","tienes: 2인칭 단수(너)라 맞지 않습니다 ✗","tienen: 3인칭 복수(그들)지만 yo가 포함되면 1인칭 복수를 씁니다 ✗"]},{"id":"G620","q":"____ tema no me interesa nada.","o":["Esta","Estos","Esto","Este"],"a":3,"k":"지시형용사 este","t":"이 주제는 나에게 전혀 흥미가 없다.","e":"tema(주제)는 -a로 끝나지만 남성명사입니다(el tema). 그래서 남성 단수 지시형용사 este를 씁니다. 그리스어에서 온 -ma 단어(el problema, el idioma, el sistema)는 대부분 남성이라는 점을 기억하세요.","x":["Esta: 여성 단수형이라 남성명사 tema와 맞지 않습니다 ✗","Estos: 남성 복수형이라 단수 tema와 맞지 않습니다 ✗","Esto: 중성 대명사(이것)로 명사 앞에 쓰지 않습니다 ✗","Este: 남성 단수 지시형용사 → 정답 ✓"]},{"id":"G621","q":"¿Cuál ____ tu color preferido?","o":["es","eres","está","hay"],"a":0,"k":"¿Cuál es...?","t":"네가 가장 좋아하는 색은 뭐야?","e":"'¿Cuál es tu...?'는 여러 가능성 중 하나를 물을 때 쓰는 기본 표현입니다. 좋아하는 색을 묻는 것은 정체(무엇인지)를 묻는 것이므로 ser 동사의 3인칭 단수 es를 씁니다. 예: ¿Cuál es tu número de teléfono?(네 전화번호가 뭐야?)","x":["es: 정체를 묻는 ser의 3인칭 단수 → 정답 ✓","eres: ser의 2인칭 단수(너는 ~이다)라 주어 'tu color'와 맞지 않습니다 ✗","está: estar는 위치나 상태를 나타내 정체를 묻는 데 쓰지 않습니다 ✗","hay: '~이 있다'라는 존재 표현이라 맞지 않습니다 ✗"]},{"id":"G622","q":"No tengo ____ prisa, puedes prepararte tranquilamente.","o":["una","ninguna","nada","alguna"],"a":1,"k":"부정어 ninguna","t":"나 전혀 안 바빠, 천천히 준비해도 돼.","e":"부정문에서 '어떤 ~도 (없다)'라고 강조할 때 ninguno/ninguna를 씁니다. prisa(급함)는 여성명사라 ninguna가 됩니다. 'No tengo ninguna prisa'는 '전혀 서두를 것 없다'는 뜻입니다.","x":["una: '하나의'라는 뜻으로 부정문의 강조와 맞지 않습니다 ✗","ninguna: 부정문에서 여성명사 앞 '어떤 ~도' → 정답 ✓","nada: 부사·대명사로 'nada de prisa'처럼 써야 하며 명사 바로 앞에는 쓰지 않습니다 ✗","alguna: 긍정 표현 '어떤'이라 부정문 no와 어울리지 않습니다 ✗"]},{"id":"G623","q":"Hoy voy a trabajar ____ las 7 hasta las 3.","o":["en","de","a","desde"],"a":3,"k":"desde...hasta","t":"오늘 나는 7시부터 3시까지 일할 거야.","e":"시간의 범위 '~부터 ~까지'는 'desde ... hasta ...' 또는 'de ... a ...' 짝으로 씁니다. 뒤에 hasta가 있으므로 앞에는 짝이 맞는 desde가 옵니다. 예: de 9 a 5 / desde las 9 hasta las 5.","x":["en: 시간의 범위 시작을 나타내지 못합니다 ✗","de: de는 a와 짝을 이루며(de...a), hasta와는 짝이 맞지 않습니다 ✗","a: '~에, ~까지'를 나타내며 시작점이 될 수 없습니다 ✗","desde: hasta와 짝을 이루는 '~부터' → 정답 ✓"]},{"id":"G624","q":"Si el vuelo ____ pasada la medianoche, tomaremos un taxi desde el aeropuerto.","o":["llegaría","llega","llegue","llegará"],"a":1,"k":"현실 조건문 si","t":"비행기가 자정 넘어서 도착하면 우리는 공항에서 택시를 탈 거야.","e":"실제로 일어날 수 있는 조건을 말할 때는 'si + 직설법 현재, 미래형' 구조를 씁니다. si 뒤에는 미래형이나 접속법 현재를 쓰지 않는다는 점이 중요합니다. 예: Si llueve, no saldré.(비가 오면 안 나갈 거야.)","x":["llegaría: 가능법이라 이 조건문 구조에 맞지 않습니다 ✗","llega: si 뒤 현실 조건은 직설법 현재 → 정답 ✓","llegue: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","llegará: si 조건절에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G625","q":"____ en Buenos Aires tres veces.","o":["Estábamos","Estamos","Estaríamos","Hemos estado"],"a":3,"k":"현재완료(경험)","t":"우리는 부에노스아이레스에 세 번 가 봤다.","e":"'~한 적이 있다, ~번 해 봤다'처럼 지금까지의 경험을 말할 때는 현재완료를 씁니다. 'Hemos estado en ...'은 '~에 가 본 적이 있다'라는 뜻입니다. 여기서 estar는 '(어떤 장소에) 있어 봤다'는 의미입니다.","x":["Estábamos: 과거의 상태·배경이라 경험 횟수와 맞지 않습니다 ✗","Estamos: 현재 '지금 있다'라는 뜻이라 tres veces와 맞지 않습니다 ✗","Estaríamos: 가능법(~있을 텐데)이라 의미가 맞지 않습니다 ✗","Hemos estado: 지금까지의 경험을 나타내는 현재완료 → 정답 ✓"]},{"id":"G626","q":"Adiós, señora Esteban, que ____ un buen día.","o":["tiene","tienes","tenga","tengas"],"a":2,"k":"que + 접속법(기원)","t":"안녕히 가세요, 에스테반 부인. 좋은 하루 보내세요.","e":"'Que + 접속법'은 '~하기를 바랍니다'라는 기원을 나타냅니다. 'señora Esteban'에게 말하므로 존칭 usted에 맞춘 접속법 현재 tenga를 씁니다. 친구에게는 'Que tengas un buen día'라고 합니다.","x":["tiene: 직설법이라 바람·기원을 나타내지 못합니다 ✗","tienes: 직설법 2인칭이라 기원도 존칭도 맞지 않습니다 ✗","tenga: usted에 맞춘 접속법 현재로 기원 표현 → 정답 ✓","tengas: 접속법이지만 tú(반말)형이라 señora에게는 맞지 않습니다 ✗"]},{"id":"G627","q":"Estamos ____ punto de cerrar, ¿le importa venir mañana?","o":["en","a","desde","de"],"a":1,"k":"estar a punto","t":"저희 곧 문을 닫으려는 참인데, 내일 오셔도 괜찮으실까요?","e":"'estar a punto de + 동사원형'은 '막 ~하려는 참이다'라는 고정 표현입니다. 전치사 a와 de가 정해져 있으니 통째로 외워 두세요. 예: El tren está a punto de salir.(기차가 막 출발하려고 해.)","x":["en: 'en punto'는 '정각'이라는 다른 표현입니다 ✗","a: 'estar a punto de(막 ~하려 하다)'의 고정 전치사 → 정답 ✓","desde: '~부터'라는 뜻으로 이 표현에 쓰지 않습니다 ✗","de: 'de punto'는 '뜨개질(로 짠)'이라는 다른 의미입니다 ✗"]},{"id":"G628","q":"¿____ estás tan enojada?","o":["Dónde","Por qué","Qué","Cuándo"],"a":1,"k":"의문사 por qué","t":"너 왜 그렇게 화가 났어?","e":"이유를 물을 때는 '¿Por qué...?(왜)'를 씁니다. 두 단어로 띄어 쓰고 qué에 악센트를 붙입니다. 'enojada(화난)'는 중남미에서 많이 쓰고, 스페인에서는 'enfadada'를 더 많이 씁니다.","x":["Dónde: '어디'를 묻는 의문사라 의미가 맞지 않습니다 ✗","Por qué: 이유 '왜'를 묻는 의문사 → 정답 ✓","Qué: '무엇'이라는 뜻이라 '무엇 그렇게 화났니'가 되어 어색합니다 ✗","Cuándo: '언제'를 묻는 의문사라 맞지 않습니다 ✗"]},{"id":"G629","q":"¿Dónde quieres que ____ estas cosas?","o":["ponga","pongo","poner","voy a poner"],"a":0,"k":"querer que+접속법","t":"이 물건들을 내가 어디에 놓았으면 좋겠어?","e":"'querer que + 다른 주어 + 접속법'은 '(다른 사람이) ~하기를 원하다'라는 뜻입니다. 원하는 사람(tú)과 행동하는 사람(yo)이 다르므로 poner의 접속법 현재 1인칭 ponga를 씁니다. 예: Quiero que vengas.(네가 왔으면 좋겠어.)","x":["ponga: querer que 뒤 접속법 현재 1인칭 단수 → 정답 ✓","pongo: 직설법이라 querer que 뒤에 쓸 수 없습니다 ✗","poner: 동사원형은 que 없이 주어가 같을 때만 씁니다 ✗","voy a poner: 미래 표현(직설법)이라 querer que 뒤에 맞지 않습니다 ✗"]},{"id":"G630","q":"Creo que Ricardo ____.","o":["está mintiendo","mienta","es mintiendo","esté mintiendo"],"a":0,"k":"creer que + 직설법","t":"리카르도가 거짓말을 하고 있는 것 같아.","e":"긍정문 'Creo que ...(~라고 생각한다)' 뒤에는 직설법을 씁니다. 진행 중인 행동이므로 'estar + 현재분사(-ando/-iendo)' 형태의 진행형 'está mintiendo'가 맞습니다. 반대로 'No creo que...'처럼 부정문이면 접속법(esté mintiendo)을 씁니다.","x":["está mintiendo: creer que 뒤 직설법 현재진행형 → 정답 ✓","mienta: 접속법이라 긍정문 creo que 뒤에 맞지 않습니다 ✗","es mintiendo: 진행형은 ser가 아니라 estar로 만듭니다 ✗","esté mintiendo: 접속법이라 'No creo que' 같은 부정문에서 씁니다 ✗"]},{"id":"G631","q":"Entonces, señora, ¿____ gustaría reservar una habitación doble?","o":["ø","la","lo","le"],"a":3,"k":"gustar 구문 le","t":"그럼 부인, 2인실을 예약하고 싶으신가요?","e":"gustar는 '좋아하는 사람'을 간접목적격 대명사로 나타냅니다. señora(부인)는 존칭 usted이므로 3인칭 단수 간접목적격 le를 씁니다. '¿Le gustaría...?'는 '~하고 싶으신가요?'라는 정중한 제안 표현입니다.","x":["ø: gustar 구문에는 간접목적격 대명사가 반드시 필요합니다 ✗","la: 직접목적격(그녀를)이라 gustar 구문에 쓰지 않습니다 ✗","lo: 직접목적격(그를/그것을)이라 맞지 않습니다 ✗","le: usted(당신)에게 해당하는 간접목적격 → 정답 ✓"]},{"id":"G632","q":"Este texto es difícil, por eso debes ____ con atención.","o":["leer lo","leerla","leerlo","leerlos"],"a":2,"k":"동사원형 + 목적격","t":"이 글은 어려우니까 주의 깊게 읽어야 해.","e":"직접목적격 대명사(~을/를에 해당)는 동사원형 뒤에 붙여서 한 단어로 씁니다. 'este texto(이 글)'는 남성 단수이므로 lo를 붙여 leerlo가 됩니다. 예: Quiero comprarlo.(그것을 사고 싶어.)","x":["leer lo: 동사원형 뒤 대명사는 띄어 쓰지 않고 붙여 씁니다 ✗","leerla: la는 여성 단수라 남성명사 texto와 맞지 않습니다 ✗","leerlo: 남성 단수 texto를 받는 lo를 붙인 형태 → 정답 ✓","leerlos: los는 복수라 단수 texto와 맞지 않습니다 ✗"]},{"id":"G633","q":"La calculadora está ____ esa mesa, ¿no la ves?","o":["entre","sobre","a","por"],"a":1,"k":"전치사 sobre","t":"계산기는 저 탁자 위에 있어, 안 보여?","e":"sobre는 '~위에'라는 뜻으로 물건이 어떤 표면 위에 놓여 있을 때 씁니다. 'sobre esa mesa'는 '저 탁자 위에'입니다. 같은 의미로 'encima de'도 많이 쓰입니다.","x":["entre: '~사이에'라는 뜻으로 두 개 이상의 대상이 필요합니다 ✗","sobre: '~위에' → 정답 ✓","a: 위치를 나타낼 때 'a la derecha'처럼 쓰지만 탁자 위를 뜻하지 못합니다 ✗","por: '~쯤에, ~을 지나서'라는 막연한 위치·경로를 나타내 어색합니다 ✗"]},{"id":"G634","q":"Niños, ____ los papeles a la papelera, por favor.","o":["tiras","tires","tiráis","tirad"],"a":3,"k":"vosotros 명령형","t":"얘들아, 종이는 휴지통에 버려 주렴.","e":"여러 아이들(Niños)에게 하는 긍정 명령은 스페인에서는 vosotros 명령형을 씁니다. 동사원형의 끝 -r를 -d로 바꾸면 되므로 tirar → tirad입니다. 중남미에서는 ustedes형 'tiren'을 씁니다.","x":["tiras: 직설법 2인칭 단수(너는 버린다)라 명령이 아닙니다 ✗","tires: 접속법이며 부정명령(no tires)에 쓰는 형태입니다 ✗","tiráis: 직설법 2인칭 복수(너희는 버린다)라 명령이 아닙니다 ✗","tirad: vosotros 긍정 명령형 → 정답 ✓"]},{"id":"G635","q":"Si no ____ qué hacer, pídele consejo a Ignacio.","o":["sabrías","sabías","sabes","sepas"],"a":2,"k":"si + 직설법 현재","t":"뭘 해야 할지 모르겠으면 이그나시오에게 조언을 구해.","e":"현실적인 조건 'si(만약 ~라면)' 뒤에는 직설법 현재를 씁니다. 결과 부분은 명령형(pídele)이 올 수도 있습니다. saber의 tú형 현재는 sabes입니다.","x":["sabrías: 가능법이라 si 조건절에 쓰지 않습니다 ✗","sabías: 과거형이라 현재 조언하는 문맥과 맞지 않습니다 ✗","sabes: si 뒤 현실 조건의 직설법 현재 → 정답 ✓","sepas: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G636","q":"Es la primera vez que veo a ____ personas.","o":["esa","esas","esos","ese"],"a":1,"k":"지시형용사 일치","t":"저 사람들을 보는 건 처음이야.","e":"지시형용사는 뒤 명사의 성·수에 맞춥니다. personas(사람들)는 여성 복수이므로 esas가 맞습니다. persona는 남자를 가리켜도 문법적으로 항상 여성명사입니다.","x":["esa: 여성 단수형이라 복수 personas와 맞지 않습니다 ✗","esas: 여성 복수 지시형용사 → 정답 ✓","esos: 남성 복수형이라 여성명사 personas와 맞지 않습니다 ✗","ese: 남성 단수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G637","q":"____. ¡Vamos a hacer un muñeco de nieve!","o":["Nieva","Nevar","Nevando","Está nevando"],"a":3,"k":"현재진행형","t":"눈이 오고 있어. 눈사람 만들자!","e":"지금 이 순간 눈이 내리고 있다는 것을 강조할 때는 'estar + 현재분사' 진행형을 씁니다. nevar(눈이 오다)는 주어 없이 3인칭 단수로만 쓰는 날씨 동사라 'Está nevando'가 됩니다. 'Nieva'는 '(일반적으로) 눈이 온다'는 느낌이 강합니다.","x":["Nieva: 현재형으로 문법적으로는 가능하지만 지금 진행 중인 느낌은 진행형이 더 자연스럽습니다 ✗","Nevar: 동사원형이라 혼자 문장이 될 수 없습니다 ✗","Nevando: 현재분사만으로는 문장을 만들 수 없습니다 ✗","Está nevando: 지금 눈이 오는 중임을 나타내는 현재진행형 → 정답 ✓"]},{"id":"G638","q":"Begoña es ____ psicóloga, tiene su propia consulta en Madrid.","o":["una","ø","un","la"],"a":1,"k":"직업 앞 관사 생략","t":"베고냐는 심리학자이고, 마드리드에 자기 상담소를 가지고 있다.","e":"ser 동사 뒤에 직업을 말할 때는 관사를 쓰지 않습니다. 'Es psicóloga'(그녀는 심리학자다)가 자연스럽습니다. 다만 형용사가 붙으면 관사를 씁니다. 예: Es una psicóloga excelente.(그녀는 훌륭한 심리학자다.)","x":["una: 형용사 없이 직업만 말할 때는 관사를 쓰지 않습니다 ✗","ø: ser + 직업은 관사 없이 → 정답 ✓","un: 남성형이고 관사 자체도 필요 없습니다 ✗","la: 정관사를 쓰면 '그 (특정한) 심리학자'가 되어 어색합니다 ✗"]},{"id":"G639","q":"Esta libreta es muy pequeña, ____ otras son más grandes.","o":["los","la","unas","las"],"a":3,"k":"정관사 las otras","t":"이 수첩은 너무 작아, 다른 것들은 더 크다.","e":"'las otras'는 '나머지 다른 것들'이라는 뜻으로, 여기서는 'las otras libretas(다른 수첩들)'에서 명사를 생략한 것입니다. libreta(수첩)가 여성명사이고 otras가 복수이므로 정관사 las를 씁니다.","x":["los: 남성 복수형이라 여성명사 libreta와 맞지 않습니다 ✗","la: 단수형이라 복수 otras와 맞지 않습니다 ✗","unas: 'unas otras'라는 표현은 쓰지 않습니다 ✗","las: 여성 복수 정관사, '나머지 것들' → 정답 ✓"]},{"id":"G640","q":"A José María no le interesa el golf y a mí ____.","o":["tampoco","también","no","tampoco no"],"a":0,"k":"tampoco","t":"호세 마리아는 골프에 관심이 없고 나도 관심이 없다.","e":"앞 사람의 부정적인 말에 '나도 (아니다)'라고 동의할 때는 tampoco를 씁니다. 긍정문에 동의할 때는 también을 씁니다. 예: —No me gusta. —A mí tampoco.(—난 싫어. —나도.)","x":["tampoco: 부정문에 대한 동의 '나도 아니다' → 정답 ✓","también: 긍정문에 대한 동의라 부정 문맥과 맞지 않습니다 ✗","no: 'a mí no'는 '나는 아니다(반대)'라는 뜻이 되어 정반대 의미입니다 ✗","tampoco no: tampoco 자체가 부정어라 no를 덧붙이지 않습니다 ✗"]},{"id":"G641","q":"¡Qué reloj tan bonito! ¿Dónde ____ has comprado?","o":["las","lo","los","la"],"a":1,"k":"직접목적격 lo","t":"정말 예쁜 시계다! 어디서 샀어?","e":"앞에 나온 'reloj(시계)'를 다시 가리키는 직접목적격 대명사가 필요합니다. reloj는 남성 단수이므로 lo를 씁니다. 대명사는 활용된 동사(has comprado) 앞에 둡니다.","x":["las: 여성 복수형이라 맞지 않습니다 ✗","lo: 남성 단수 reloj를 받는 직접목적격 → 정답 ✓","los: 남성 복수형이라 단수 reloj와 맞지 않습니다 ✗","la: 여성 단수형이라 남성명사 reloj와 맞지 않습니다 ✗"]},{"id":"G642","q":"Si tienes algo que decirme, ____ ahora.","o":["dime lo","dimelo","dímelo","lo me dices"],"a":2,"k":"명령형 + 대명사","t":"나에게 할 말이 있으면 지금 말해.","e":"긍정 명령형에서는 대명사를 동사 뒤에 붙여 한 단어로 씁니다. 순서는 간접목적어(me) → 직접목적어(lo)입니다. di + me + lo = dímelo가 되며, 원래 강세 위치를 지키기 위해 í에 악센트를 붙입니다.","x":["dime lo: 대명사는 띄어 쓰지 않고 명령형에 붙여 씁니다 ✗","dimelo: 붙여 썼지만 강세 표시(í)가 빠졌습니다 ✗","dímelo: 명령형 + me + lo, 악센트까지 정확 → 정답 ✓","lo me dices: 대명사 순서(me lo)가 틀렸고 명령형도 아닙니다 ✗"]},{"id":"G643","q":"Siempre que puedo, me desplazo ____ metro.","o":["por","a","de","en"],"a":3,"k":"교통수단 en","t":"나는 가능할 때마다 지하철로 이동한다.","e":"교통수단을 이용해 이동할 때는 'en + 교통수단'을 씁니다. 'en metro(지하철로)', 'en coche(차로)', 'en autobús(버스로)'처럼요. 단, 걸어서는 'a pie', 말을 타고는 'a caballo'입니다.","x":["por: 'por la calle'처럼 경로를 나타내며 교통수단에는 보통 쓰지 않습니다 ✗","a: 'a pie(걸어서)' 같은 일부 표현에만 쓰며 metro에는 쓰지 않습니다 ✗","de: 출발점이나 소유를 나타내 교통수단 표현이 아닙니다 ✗","en: '~을 타고(교통수단)' → 정답 ✓"]},{"id":"G644","q":"Alfonso está enfermo, por eso no ____ vemos últimamente.","o":["lo","él","a él","la"],"a":0,"k":"직접목적격 lo","t":"알폰소가 아파서 요즘 우리는 그를 못 보고 있다.","e":"ver(보다)의 목적어인 '알폰소(그를)'는 남성 단수 직접목적격 대명사 lo로 받습니다. 대명사는 활용된 동사 vemos 앞에 둡니다. 스페인 일부 지역에서는 남성 사람을 le로 받기도(leísmo) 하지만, 표준은 lo입니다.","x":["lo: 남성 단수 사람을 받는 직접목적격 → 정답 ✓","él: 주격 대명사(그는)라 목적어 자리에 쓸 수 없습니다 ✗","a él: 강조용으로 쓸 수는 있지만 대명사 lo 없이 단독으로 동사 앞에 쓰지 않습니다 ✗","la: 여성형이라 남성 Alfonso와 맞지 않습니다 ✗"]},{"id":"G645","q":"¿Por qué no ____ ir a la cena de Navidad de la empresa? Estuvo muy bien.","o":["estabas queriendo","quisiste","quieres","querrás"],"a":1,"k":"단순과거 querer","t":"왜 회사 크리스마스 저녁 모임에 안 가려고 했어? 정말 좋았는데.","e":"뒤의 'Estuvo muy bien(아주 좋았어)'를 보면 모임은 이미 끝났습니다. 과거의 특정한 결정, 즉 '가기를 원하지 않았다(거절했다)'는 단순과거 'no quisiste'로 표현합니다. querer는 단순과거에서 quis- 어간을 쓰는 불규칙 동사입니다.","x":["estabas queriendo: querer는 진행형으로 거의 쓰지 않으며 의미도 어색합니다 ✗","quisiste: 과거의 결정을 나타내는 단순과거 2인칭 단수 → 정답 ✓","quieres: 현재형이라 이미 끝난 모임과 시제가 맞지 않습니다 ✗","querrás: 미래형이라 과거 사건과 맞지 않습니다 ✗"]},{"id":"G646","q":"A José ____ vi por última vez hace un año y medio.","o":["ø","lo","se lo","los"],"a":1,"k":"목적어 중복 lo","t":"호세는 1년 반 전에 마지막으로 봤다.","e":"직접목적어(A José)를 문장 앞으로 꺼내면 같은 대상을 직접목적격 대명사로 한 번 더 써야 합니다. José는 남성 단수이므로 lo를 씁니다. 예: Ese libro lo leí ayer.(그 책은 어제 읽었어.)","x":["ø: 목적어가 동사 앞에 나오면 대명사를 반드시 반복해야 합니다 ✗","lo: 앞에 나온 남성 단수 목적어를 다시 받는 대명사 → 정답 ✓","se lo: se는 간접목적어가 함께 있을 때 쓰는 형태라 맞지 않습니다 ✗","los: 복수형이라 José 한 사람과 맞지 않습니다 ✗"]},{"id":"G647","q":"¿____ es su número de zapato?","o":["De quién","Cuál","Qué","Cuánto"],"a":1,"k":"¿Cuál es...?","t":"신발 사이즈가 어떻게 되세요?","e":"ser 동사 앞에서 번호·이름·주소 같은 정보를 물을 때는 qué가 아니라 cuál을 씁니다. '¿Cuál es su número de zapato?'는 '신발 사이즈가 몇이세요?'라는 뜻입니다. 여기서 su는 존칭 usted의 소유형(당신의)입니다.","x":["De quién: '누구의'라는 뜻이라 사이즈를 묻는 의미와 맞지 않습니다 ✗","Cuál: ser 앞에서 정보(번호)를 묻는 의문사 → 정답 ✓","Qué: '¿Qué es...?'는 정의(그게 뭔지)를 묻는 표현이라 맞지 않습니다 ✗","Cuánto: '얼마나'라는 양을 묻는 말로 이 구조에 어색합니다 ✗"]},{"id":"G648","q":"Llegué ____ mi trabajo a las 9 en punto de la mañana.","o":["hasta","en","a","sobre"],"a":2,"k":"llegar a","t":"나는 오전 9시 정각에 직장에 도착했다.","e":"llegar(도착하다)는 도착 장소 앞에 전치사 a를 씁니다. 'llegar a casa(집에 도착하다)', 'llegar a Madrid(마드리드에 도착하다)'처럼요. 중남미 일부에서는 'llegar en'도 들리지만 표준은 a입니다.","x":["hasta: '~까지'라는 뜻으로 '도착하다'의 장소에는 보통 쓰지 않습니다 ✗","en: 위치(~안에)를 나타내며 표준 스페인어에서는 llegar a를 씁니다 ✗","a: llegar의 도착 장소 '~에' → 정답 ✓","sobre: '~위에, ~쯤'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G649","q":"Mi vecino vino a casa para ____ un favor.","o":["me pedir","pedirme","pedir me","que me pide"],"a":1,"k":"para + 동사원형","t":"이웃이 나에게 부탁을 하려고 집에 왔다.","e":"전치사(para) 뒤에는 동사원형이 오고, 목적격 대명사는 동사원형 뒤에 붙입니다. 그래서 'para pedirme un favor(나에게 부탁하려고)'가 됩니다. 'pedir un favor'는 '부탁하다'라는 표현입니다.","x":["me pedir: 동사원형 앞에 대명사를 둘 수 없습니다 ✗","pedirme: 동사원형 뒤에 대명사를 붙인 형태 → 정답 ✓","pedir me: 대명사는 띄어 쓰지 않고 붙여 씁니다 ✗","que me pide: para que 뒤에는 접속법이 필요하고 여기서는 구조가 맞지 않습니다 ✗"]},{"id":"G650","q":"Ahora no puedo salir del baño, ____ estoy afeitando.","o":["mí","se","me","yo"],"a":2,"k":"재귀동사 afeitarse","t":"나 지금 면도 중이라 화장실에서 못 나가.","e":"afeitarse(자기 수염을 깎다, 면도하다)는 재귀동사(행동이 자기 자신에게 돌아오는 동사)입니다. 주어가 yo(estoy)이므로 재귀대명사 me를 씁니다. 진행형에서는 'me estoy afeitando' 또는 'estoy afeitándome' 둘 다 가능합니다.","x":["mí: 전치사 뒤에 쓰는 형태(para mí)라 동사 앞에 쓸 수 없습니다 ✗","se: 3인칭 재귀대명사라 주어 yo와 맞지 않습니다 ✗","me: 1인칭 단수 재귀대명사 → 정답 ✓","yo: 주격 대명사라 재귀대명사 자리에 쓸 수 없습니다 ✗"]},{"id":"G651","q":"Llegaron muy tarde a la celebración, por eso ya no ____ comida ni bebida.","o":["había","hay","ha habido","va a haber"],"a":0,"k":"불완료과거 había","t":"그들이 축하 파티에 아주 늦게 도착해서 이미 음식도 음료도 없었다.","e":"과거 시점(도착했을 때)의 상황이나 상태를 묘사할 때는 불완료과거를 씁니다. '있다'라는 존재의 hay는 불완료과거로 había가 됩니다. haber의 존재 표현은 복수 명사가 와도 항상 단수형(había)입니다.","x":["había: 과거 시점의 상황(존재)을 나타내는 불완료과거 → 정답 ✓","hay: 현재형이라 과거 이야기와 시제가 맞지 않습니다 ✗","ha habido: 현재완료라 과거 특정 시점의 상태를 묘사하지 못합니다 ✗","va a haber: 미래 표현이라 맞지 않습니다 ✗"]},{"id":"G652","q":"Si ____ sigue doliendo el cuello, vaya al médico.","o":["se","te","lo","le"],"a":3,"k":"doler + 간접목적어","t":"목이 계속 아프시면 병원에 가 보세요.","e":"doler(아프다)는 gustar처럼 '아픈 사람'을 간접목적격 대명사로 씁니다. 뒤의 'vaya(가세요)'가 usted 명령형이므로 존칭 usted에 해당하는 le를 씁니다. 'seguir + 현재분사'는 '계속 ~하다'라는 뜻입니다.","x":["se: 재귀대명사라 doler 구문의 간접목적어로 쓰지 않습니다 ✗","te: tú(너)에게 쓰는 형태라 usted 명령형 vaya와 맞지 않습니다 ✗","lo: 직접목적격이라 doler 구문에 맞지 않습니다 ✗","le: usted에 해당하는 간접목적격 → 정답 ✓"]},{"id":"G653","q":"Hoy ____ sin parar toda la tarde.","o":["estaba trabajando","he estado trabajando","trabajaba","había trabajado"],"a":1,"k":"현재완료 진행형","t":"오늘 나는 오후 내내 쉬지 않고 일했다.","e":"'Hoy(오늘)'처럼 현재와 연결된 시간에 계속 이어진 행동은 현재완료 진행형 'haber + estado + 현재분사'로 표현합니다. 'he estado trabajando'는 '(오늘 내내) 일하고 있었다'는 뜻입니다.","x":["estaba trabajando: 과거 진행으로 다른 사건의 배경일 때 쓰며 hoy와 어색합니다 ✗","he estado trabajando: hoy와 함께 지속된 행동을 나타내는 현재완료 진행 → 정답 ✓","trabajaba: 과거의 습관·배경을 나타내 hoy와 맞지 않습니다 ✗","había trabajado: 대과거로 과거보다 앞선 일을 나타내 맞지 않습니다 ✗"]},{"id":"G654","q":"A Martín ____ molesta mucho el ruido que hacen sus vecinos.","o":["ø","les","lo","le"],"a":3,"k":"molestar 구문","t":"마르틴은 이웃들이 내는 소음 때문에 몹시 짜증이 난다.","e":"molestar(신경 쓰이게 하다, 거슬리다)는 gustar처럼 '영향을 받는 사람'을 간접목적격 대명사로 씁니다. 'A Martín'은 3인칭 단수이므로 le를 함께 씁니다. 주어는 'el ruido(소음)'입니다.","x":["ø: 'a + 사람'이 앞에 있으면 간접목적격 대명사가 꼭 필요합니다 ✗","les: 3인칭 복수형이라 Martín 한 사람과 맞지 않습니다 ✗","lo: 직접목적격이라 molestar(감정 동사) 구문에서는 보통 쓰지 않습니다 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓"]},{"id":"G655","q":"El que más me gusta es el helado ____ fresa.","o":["a","por","en","de"],"a":3,"k":"전치사 de(맛)","t":"내가 제일 좋아하는 건 딸기 아이스크림이야.","e":"음식의 맛이나 재료를 나타낼 때는 'de + 재료'를 씁니다. 'helado de fresa(딸기 아이스크림)', 'tarta de chocolate(초콜릿 케이크)'처럼요.","x":["a: 'a la plancha'처럼 조리 방식에 쓰지만 맛 표현에는 쓰지 않습니다 ✗","por: '~때문에, ~을 통해'라는 뜻이라 맞지 않습니다 ✗","en: '~안에'라는 위치 표현이라 맞지 않습니다 ✗","de: 맛·재료를 나타내는 '~맛의' → 정답 ✓"]},{"id":"G656","q":"¿____ estás tan desanimado?","o":["Por que","Porque","Por qué","Porqué"],"a":2,"k":"por qué 철자","t":"너 왜 그렇게 기운이 없어?","e":"의문문에서 '왜'는 두 단어 por qué로 쓰고 qué에 악센트를 붙입니다. porque(붙여 씀, 악센트 없음)는 '왜냐하면'이라는 대답용, el porqué(명사)는 '이유'라는 뜻입니다.","x":["Por que: 악센트가 없어 의문사가 아니게 됩니다 ✗","Porque: '왜냐하면'이라는 대답에 쓰는 접속사입니다 ✗","Por qué: 의문문 '왜' → 정답 ✓","Porqué: '이유'라는 뜻의 명사(el porqué)입니다 ✗"]},{"id":"G657","q":"No va ____ gimnasio porque tiene máquinas para ejercitarse en su casa.","o":["a","en el","al","el"],"a":2,"k":"a + el = al","t":"그는 집에 운동 기구가 있어서 헬스장에 가지 않는다.","e":"ir a(~에 가다) 뒤에 남성 정관사 el이 오면 a + el이 합쳐져 al이 됩니다. 그래서 'ir al gimnasio(헬스장에 가다)'가 됩니다. 'a el'로 따로 쓰지 않는다는 점이 중요합니다.","x":["a: 관사 없이 'ir a gimnasio'라고 하지 않습니다 ✗","en el: '~안에서'라는 위치라 ir와 함께 목적지를 나타내지 못합니다 ✗","al: a + el의 축약형 → 정답 ✓","el: 이동 동사 ir 뒤에 전치사 a가 빠졌습니다 ✗"]},{"id":"G658","q":"No quiero más zumo, ya he bebido ____.","o":["poco","bastantes","poquísimo","suficiente"],"a":3,"k":"suficiente","t":"주스 더 안 마실래, 이미 충분히 마셨어.","e":"suficiente는 '충분한, 충분히'라는 뜻으로 '이제 더는 필요 없다'는 문맥에 딱 맞습니다. 여기서는 명사 없이 '충분한 양'을 나타냅니다. 비슷한 표현으로 'bastante'도 쓸 수 있지만 복수형 bastantes는 zumo(단수)와 맞지 않습니다.","x":["poco: '조금'이라는 뜻이라 '더 안 마시겠다'는 이유와 맞지 않습니다 ✗","bastantes: 복수형이라 단수 zumo를 받을 수 없습니다 ✗","poquísimo: '아주 조금'이라는 뜻이라 문맥과 반대입니다 ✗","suficiente: '충분히' → 정답 ✓"]},{"id":"G659","q":"Tienen un ____ profesor de educación física.","o":["buen","bien","buena","bueno"],"a":0,"k":"bueno → buen","t":"그들에게는 좋은 체육 선생님이 계신다.","e":"bueno(좋은)는 남성 단수 명사 앞에 올 때 -o가 탈락해 buen이 됩니다. 'un buen profesor(좋은 선생님)'처럼요. 명사 뒤에 오거나 여성형일 때는 줄지 않습니다(un profesor bueno, una buena profesora).","x":["buen: 남성 단수 명사 앞에서 줄어든 형태 → 정답 ✓","bien: '잘'이라는 부사라 명사를 꾸밀 수 없습니다 ✗","buena: 여성형이라 남성명사 profesor와 맞지 않습니다 ✗","bueno: 남성 단수 명사 앞에서는 buen으로 줄여 써야 합니다 ✗"]},{"id":"G660","q":"Intento ____ no comer productos con azúcar.","o":["de","ø","a","para"],"a":1,"k":"intentar + 동사원형","t":"나는 설탕이 든 제품을 먹지 않으려고 노력한다.","e":"intentar(애쓰다)는 전치사 없이 바로 동사원형을 받습니다. 부정할 때는 동사원형 앞에 no를 넣어 'intentar no + 동사원형(~하지 않으려고 하다)'이 됩니다. 예: Intento no llegar tarde.(늦지 않으려고 해.)","x":["de: tratar de와 혼동한 형태로 intentar 뒤에는 쓰지 않습니다 ✗","ø: intentar는 바로 동사원형(no comer)을 받음 → 정답 ✓","a: 'empezar a'처럼 다른 동사와 쓰는 전치사입니다 ✗","para: '~하기 위해'라는 목적을 나타내 intentar의 목적어로 쓰지 않습니다 ✗"]},{"id":"G661","q":"Espero que ____ una persona paciente, es una cualidad necesaria en tu profesión.","o":["estés","seas","eres","estás"],"a":1,"k":"esperar que+접속법","t":"네가 인내심 있는 사람이길 바라. 그건 네 직업에 꼭 필요한 자질이야.","e":"'Espero que ...(~하기를 바란다)' 뒤에는 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태)을 씁니다. 또 '인내심 있는 사람'은 성격(본질)을 말하므로 estar가 아니라 ser를 씁니다. 그래서 ser의 접속법 현재 tú형 seas가 정답입니다.","x":["estés: 접속법이지만 estar는 일시적 상태에 쓰며 사람의 성격에는 쓰지 않습니다 ✗","seas: 성격을 나타내는 ser의 접속법 현재 → 정답 ✓","eres: 직설법이라 espero que 뒤에 쓸 수 없습니다 ✗","estás: 직설법이고 동사(estar)도 맞지 않습니다 ✗"]},{"id":"G662","q":"____ la tele si no la estás viendo, por favor.","o":["Apagas","Apague","Apagues","Apaga"],"a":3,"k":"tú 긍정 명령형","t":"TV 안 보고 있으면 꺼 줘.","e":"tú(너)에게 하는 긍정 명령은 대부분 직설법 현재 3인칭 단수와 같은 형태입니다. apagar(끄다) → apaga. 뒤의 'si no la estás viendo'에서 tú로 말하고 있으므로 tú 명령형을 씁니다.","x":["Apagas: 직설법 현재(너는 끈다)라 명령이 아닙니다 ✗","Apague: usted(당신) 명령형이라 tú로 말하는 문장과 맞지 않습니다 ✗","Apagues: 접속법 형태로 부정 명령(no apagues)에 씁니다 ✗","Apaga: tú 긍정 명령형 → 정답 ✓"]},{"id":"G663","q":"No ____ tanto, te vas a poner malo.","o":["comes","coma","comer","comas"],"a":3,"k":"tú 부정 명령형","t":"그렇게 많이 먹지 마, 탈 나겠다.","e":"부정 명령(~하지 마)은 'no + 접속법 현재'로 만듭니다. tú에게 말하므로 comer의 접속법 현재 2인칭 단수 comas를 씁니다. 'ponerse malo'는 스페인에서 '몸이 아파지다'라는 표현입니다.","x":["comes: 직설법이라 'no comes'는 '너는 안 먹는다'는 뜻이 됩니다 ✗","coma: usted에 대한 부정 명령이라 tú(te vas)와 맞지 않습니다 ✗","comer: 동사원형으로는 일반적인 부정 명령을 만들지 않습니다 ✗","comas: tú 부정 명령 no + 접속법 → 정답 ✓"]},{"id":"G664","q":"¿____ puedo hacer para memorizar todas estas palabras?","o":["Qué","Cuánto","Para qué","Cuál"],"a":0,"k":"의문사 qué","t":"이 단어들을 다 외우려면 내가 뭘 할 수 있을까?","e":"'무엇을' 할 수 있는지 묻고 있으므로 의문사 qué를 씁니다. qué는 동사 앞에서 '무엇'을 뜻하고, cuál은 보통 여러 선택지 중 '어느 것'을 고를 때 씁니다. 예: ¿Qué haces?(뭐 해?)","x":["Qué: 동사 hacer의 목적어 '무엇을' → 정답 ✓","Cuánto: '얼마나'라는 양을 묻는 의문사라 맞지 않습니다 ✗","Para qué: '무엇을 위해'라는 목적을 묻는 말이라 뒤의 para memorizar와 겹칩니다 ✗","Cuál: 정해진 선택지 중 고를 때 쓰며 '무엇을 할 수 있나'에는 qué를 씁니다 ✗"]},{"id":"G665","q":"Mi hija no ____ sola porque es demasiado pequeña.","o":["se viste","viste","está vistiendo","va a vestir"],"a":0,"k":"재귀동사 vestirse","t":"우리 딸은 너무 어려서 혼자 옷을 입지 못한다.","e":"vestirse는 '(자기 자신이) 옷을 입다'라는 재귀동사입니다. 재귀대명사 se가 없으면 vestir는 '(다른 사람에게) 옷을 입히다'라는 뜻이 됩니다. 매일의 일반적인 능력을 말하므로 현재형 'se viste'를 씁니다.","x":["se viste: 스스로 옷을 입다(재귀동사 현재) → 정답 ✓","viste: se가 없으면 '남에게 옷을 입히다'라는 뜻이 됩니다 ✗","está vistiendo: 지금 진행 중이라는 뜻이고 재귀대명사도 없습니다 ✗","va a vestir: 미래 표현이고 재귀대명사도 빠졌습니다 ✗"]},{"id":"G666","q":"Esta maleta no es ____, es de esos señores de allí.","o":["mi","de mí","a mí","mía"],"a":3,"k":"소유대명사 mía","t":"이 여행 가방은 내 것이 아니라 저기 계신 분들의 것이다.","e":"ser 동사 뒤에서 '내 것'이라고 말할 때는 강세형 소유사 mío/mía를 씁니다. maleta(여행 가방)가 여성명사이므로 mía가 됩니다. mi는 명사 앞에만 쓸 수 있습니다(mi maleta).","x":["mi: 명사 앞에만 쓰는 소유형이라 혼자 쓸 수 없습니다 ✗","de mí: '나에 대하여/나로부터'라는 뜻이라 소유 표현으로 쓰지 않습니다 ✗","a mí: '나에게'라는 뜻이라 소유를 나타내지 못합니다 ✗","mía: 여성 단수 강세형 소유사 '내 것' → 정답 ✓"]},{"id":"G667","q":"Fue castigado ____ su mal comportamiento.","o":["porque","ya que","a pesar de","por"],"a":3,"k":"이유의 전치사 por","t":"그는 나쁜 행동 때문에 벌을 받았다.","e":"명사 앞에서 '~때문에'라는 이유를 나타낼 때는 전치사 por를 씁니다. 'por su mal comportamiento(그의 나쁜 행동 때문에)'처럼요. porque와 ya que는 뒤에 주어와 동사가 있는 문장이 와야 합니다.","x":["porque: 뒤에 동사가 있는 절이 와야 하므로 명사 앞에는 쓸 수 없습니다 ✗","ya que: '~이므로'라는 접속사라 뒤에 절이 필요합니다 ✗","a pesar de: '~에도 불구하고'라는 뜻이라 의미가 반대입니다 ✗","por: 명사 앞 이유 '~때문에' → 정답 ✓"]},{"id":"G668","q":"El baño está muy limpio, ____ limpié anoche.","o":["le","la","lo","los"],"a":2,"k":"직접목적격 lo","t":"화장실이 아주 깨끗해, 어젯밤에 내가 청소했거든.","e":"앞에 나온 'el baño(화장실)'를 다시 가리키는 직접목적격 대명사가 필요합니다. baño는 남성 단수이므로 lo를 써서 'lo limpié(그것을 청소했다)'가 됩니다.","x":["le: 간접목적격(~에게)이라 '청소하다'의 대상에 쓰지 않습니다 ✗","la: 여성형이라 남성명사 baño와 맞지 않습니다 ✗","lo: 남성 단수 직접목적격 → 정답 ✓","los: 복수형이라 단수 baño와 맞지 않습니다 ✗"]},{"id":"G669","q":"____ a una mujer que habla cinco idiomas.","o":["Sé","He sabido","Conozco","Conocido"],"a":2,"k":"conocer/saber","t":"나는 5개 국어를 하는 여자를 알고 있다.","e":"사람이나 장소를 '알다(만나 본 적이 있다)'라고 할 때는 conocer를 씁니다. saber는 정보·사실이나 '~할 줄 안다'라는 능력에 씁니다. 사람 목적어 앞에는 전치사 a가 붙어 'Conozco a una mujer'가 됩니다.","x":["Sé: saber는 사실·정보를 알 때 쓰며 사람에게는 쓰지 않습니다 ✗","He sabido: saber의 현재완료로 사람을 아는 의미가 아닙니다 ✗","Conozco: 사람을 알다(conocer)의 1인칭 현재 → 정답 ✓","Conocido: 과거분사만으로는 문장의 동사가 될 수 없습니다 ✗"]},{"id":"G670","q":"Llevo dos horas buscando ____ mis apuntes de lengua.","o":["por","para","a","ø"],"a":3,"k":"buscar + 목적어","t":"나는 두 시간째 국어 필기 노트를 찾고 있다.","e":"buscar(찾다)는 전치사 없이 바로 목적어를 받습니다. 'buscar mis apuntes(내 노트를 찾다)'처럼요. 'llevar + 시간 + 현재분사'는 '~째 …하고 있다'라는 뜻입니다. 예: Llevo un año estudiando español.(스페인어를 1년째 공부하고 있어.)","x":["por: 'buscar por'는 장소를 뒤질 때 쓰며 찾는 대상 앞에는 쓰지 않습니다 ✗","para: '~를 위해'라는 뜻이라 목적어 앞에 쓰지 않습니다 ✗","a: 사람 목적어 앞에만 쓰고 사물(apuntes) 앞에는 쓰지 않습니다 ✗","ø: buscar는 사물 목적어를 바로 받음 → 정답 ✓"]},{"id":"G671","q":"Aquí no hay ____, ¿dónde están todos?","o":["ningún","nadie","alguno","algún"],"a":1,"k":"부정어 nadie","t":"여기 아무도 없네, 다들 어디 있어?","e":"부정문(No hay...)에서 '아무도'라고 할 때는 nadie를 씁니다. 뒤의 '¿dónde están todos?(다들 어디 있어?)'로 사람이 없다는 뜻임을 알 수 있습니다. ningún은 명사 앞에만 쓸 수 있습니다.","x":["ningún: 명사 앞에 붙는 형태라 혼자 쓸 수 없습니다 ✗","nadie: 부정문에서 '아무도' → 정답 ✓","alguno: '누군가, 어떤 것'이라는 긍정 표현이라 부정문 no와 맞지 않습니다 ✗","algún: 명사 앞에 붙는 긍정 형태라 혼자 쓸 수 없습니다 ✗"]},{"id":"G672","q":"____ me conoce como mi marido, es la persona que más sabe de mí.","o":["Nadie","Alguien","Nada","Alguna"],"a":0,"k":"nadie가 주어","t":"그 누구도 내 남편만큼 나를 잘 알지 못한다. 그는 나에 대해 가장 많이 아는 사람이다.","e":"nadie가 동사 앞(주어 자리)에 오면 no 없이 그 자체로 부정문이 됩니다. 'Nadie me conoce como mi marido'는 '내 남편만큼 나를 아는 사람은 아무도 없다'는 뜻입니다. 예: Nadie sabe la respuesta.(아무도 답을 몰라.)","x":["Nadie: 동사 앞에서 '아무도 ~않다' → 정답 ✓","Alguien: '누군가'라는 뜻이라 문장 의미가 이상해집니다 ✗","Nada: '아무것도'라는 사물에 쓰며 사람을 가리키지 못합니다 ✗","Alguna: 여성형 '어떤'으로 단독 주어로 어색하고 의미도 맞지 않습니다 ✗"]},{"id":"G673","q":"¿Puedo cambiar ____ habitación? Esta es demasiado grande para mí.","o":["de","a","por","en"],"a":0,"k":"cambiar de","t":"방을 바꿀 수 있을까요? 이 방은 저한테 너무 커요.","e":"같은 종류의 것을 다른 것으로 바꿀 때는 'cambiar de + 관사 없는 명사'를 씁니다. 'cambiar de habitación(방을 바꾸다)', 'cambiar de casa(이사하다)', 'cambiar de opinión(생각을 바꾸다)'처럼요.","x":["de: '~을 다른 것으로 바꾸다'의 cambiar de → 정답 ✓","a: 'cambiar a'는 '~로 바뀌다/옮기다'라는 다른 의미입니다 ✗","por: 'cambiar A por B'는 'A를 B와 맞바꾸다'라는 뜻이라 맞지 않습니다 ✗","en: 'cambiar en'은 이 의미로 쓰지 않습니다 ✗"]},{"id":"G674","q":"Vos no sos tan alto ____ él.","o":["que","de","como","a"],"a":2,"k":"동등비교 tan...como","t":"너는 그만큼 키가 크지 않아.","e":"'tan + 형용사 + como'는 '~만큼 …하다'라는 동등비교입니다. 부정문이면 '~만큼 …하지 않다'가 됩니다. 'Vos sos'는 아르헨티나·우루과이 등에서 쓰는 voseo(tú 대신 vos를 쓰는 방식)로 'Tú eres'와 같은 뜻입니다.","x":["que: 'más/menos ... que'의 비교급에 쓰며 tan과는 짝이 아닙니다 ✗","de: 숫자 앞 비교(más de diez)나 최상급에 쓰는 전치사입니다 ✗","como: tan과 짝을 이루는 동등비교 → 정답 ✓","a: 비교 표현에 쓰지 않습니다 ✗"]},{"id":"G675","q":"Antes tenía el pelo largo, pero ahora ____ prefiero corto.","o":["le","la","lo","los"],"a":2,"k":"직접목적격 lo","t":"예전엔 머리가 길었는데, 지금은 짧은 게 더 좋아.","e":"앞의 'el pelo(머리카락)'를 다시 가리키는 직접목적격 대명사가 필요합니다. pelo는 남성 단수이므로 lo를 써서 'lo prefiero corto(그것을 짧게 하는 게 더 좋다)'가 됩니다. corto도 pelo에 맞춰 남성형입니다.","x":["le: 간접목적격(~에게)이라 '선호하다'의 대상에 쓰지 않습니다 ✗","la: 여성형이라 남성명사 pelo와 맞지 않습니다 ✗","lo: 남성 단수 pelo를 받는 직접목적격 → 정답 ✓","los: 복수형이라 단수 pelo와 맞지 않습니다 ✗"]},{"id":"G676","q":"¿Te importa cortar ____ carne que hay en ese plato?","o":["la","un","el","ø"],"a":0,"k":"정관사 la","t":"저 접시에 있는 고기 좀 썰어 줄래?","e":"'que hay en ese plato(저 접시에 있는)'로 특정한 고기를 가리키므로 정관사를 씁니다. carne(고기)는 여성명사라 la가 맞습니다. 셀 수 없는 명사(carne)라 부정관사 un/una도 어색합니다.","x":["la: 특정한 여성명사 carne 앞의 정관사 → 정답 ✓","un: 남성 부정관사라 여성명사 carne와 맞지 않습니다 ✗","el: 남성 정관사라 여성명사 carne와 맞지 않습니다 ✗","ø: 특정한 고기를 가리키므로 관사가 필요합니다 ✗"]},{"id":"G677","q":"____ a ese museo.","o":["Nunca no he ido","No he ido nunca","No nunca he ido","He ido nunca"],"a":1,"k":"이중부정 no...nunca","t":"나는 그 박물관에 한 번도 가 본 적이 없다.","e":"nunca(결코, 한 번도)를 동사 뒤에 두면 동사 앞에 no를 꼭 넣어야 합니다: 'No he ido nunca'. 반대로 nunca를 동사 앞에 두면 no 없이 'Nunca he ido'라고 합니다. 'Nunca no'처럼 둘을 함께 앞에 쓰지는 않습니다.","x":["Nunca no he ido: nunca가 동사 앞에 있으면 no를 쓰지 않습니다 ✗","No he ido nunca: no + 동사 + nunca의 이중부정 → 정답 ✓","No nunca he ido: no와 nunca를 나란히 동사 앞에 둘 수 없습니다 ✗","He ido nunca: 동사 뒤 nunca 앞에는 no가 필요합니다 ✗"]},{"id":"G678","q":"A mi hermano le encanta lo salado, pero a su novia ____.","o":["no","también","ni","tampoco"],"a":0,"k":"동의/반대 a mí no","t":"내 남동생은 짠 음식을 아주 좋아하지만, 그의 여자친구는 그렇지 않다.","e":"앞 문장이 긍정(le encanta)이고 다른 사람은 반대 의견일 때는 'a + 사람 + no'를 씁니다. 'pero(하지만)'가 있어 대조를 나타내므로 'a su novia no(그녀는 아니다)'가 맞습니다. 긍정에 동의하면 también, 부정에 동의하면 tampoco입니다.","x":["no: 긍정문에 대한 반대 '~는 아니다' → 정답 ✓","también: '~도 그렇다'라는 동의라 pero의 대조와 맞지 않습니다 ✗","ni: '~도 아니다'를 연결하는 말로 이 구조에서 단독으로 쓰지 않습니다 ✗","tampoco: 부정문에 동의할 때 쓰며 앞 문장이 긍정이라 맞지 않습니다 ✗"]},{"id":"G679","q":"¿____ es tu futbolista preferido?","o":["Cuándo","Qué","Cuál","Dónde"],"a":2,"k":"¿Cuál es...?","t":"네가 가장 좋아하는 축구 선수는 누구야?","e":"여러 선수 중 한 명을 고르라는 질문이므로 '¿Cuál es tu ... preferido?'를 씁니다. ser 동사 앞에서 선택을 물을 때는 qué가 아니라 cuál이 자연스럽습니다. 'futbolista(축구 선수)'는 남녀 모두 같은 형태입니다.","x":["Cuándo: '언제'를 묻는 의문사라 맞지 않습니다 ✗","Qué: ser 앞에서 '무엇'은 정의를 묻는 질문이 되어 어색합니다 ✗","Cuál: 여러 중 하나를 묻는 의문사 → 정답 ✓","Dónde: '어디'를 묻는 의문사라 맞지 않습니다 ✗"]},{"id":"G680","q":"No hay ____ agua caliente, así que tendré que ducharme con agua fría.","o":["una","el","la","ø"],"a":3,"k":"hay + 무관사 명사","t":"뜨거운 물이 안 나와서 찬물로 샤워해야겠다.","e":"'hay(~이 있다)' 뒤에는 정관사(el, la)를 쓰지 않습니다. 또 agua처럼 셀 수 없는 명사는 보통 관사 없이 'No hay agua caliente(뜨거운 물이 없다)'라고 합니다. 예: Hay leche en la nevera.(냉장고에 우유가 있어.)","x":["una: 셀 수 없는 명사 agua 앞에 부정관사를 쓰지 않습니다 ✗","el: hay 뒤에는 정관사를 쓰지 않습니다 ✗","la: hay 뒤에는 정관사를 쓰지 않습니다 ✗","ø: hay + 관사 없는 셀 수 없는 명사 → 정답 ✓"]},{"id":"G681","q":"¿Ustedes también están esperando ____ señora García?","o":["al","de","a la","ø"],"a":2,"k":"사람 목적어 앞 a","t":"여러분도 가르시아 부인을 기다리고 계신가요?","e":"직접목적어가 특정한 사람일 때는 앞에 전치사 a를 붙입니다(인칭의 a). 'la señora García'는 특정 인물이므로 'a la señora García'가 됩니다. 남성이면 a + el = al(al señor García)이 됩니다.","x":["al: a + el이라 남성명사 앞에 쓰며 여성 señora와 맞지 않습니다 ✗","de: 'esperar de'는 '~에게 기대하다'라는 다른 의미입니다 ✗","a la: 특정 사람 앞 인칭의 a + 여성 정관사 → 정답 ✓","ø: 특정한 사람 목적어 앞에는 a가 필요합니다 ✗"]},{"id":"G682","q":"En la siguiente calle tienes que girar ____ derecha.","o":["a","hacia","hasta","a la"],"a":3,"k":"방향 a la derecha","t":"다음 거리에서 오른쪽으로 돌아야 해.","e":"방향을 말할 때는 'a la derecha(오른쪽으로)', 'a la izquierda(왼쪽으로)'처럼 정관사 la를 넣어 씁니다. derecha는 원래 'la mano derecha(오른손)'에서 온 여성명사입니다. 길 안내에서 매우 자주 쓰는 표현입니다.","x":["a: 정관사 la가 빠져서 'a derecha'라는 어색한 표현이 됩니다 ✗","hacia: '~쪽으로'라는 뜻이지만 정관사 없이 쓰면 틀립니다 ✗","hasta: '~까지'라는 뜻이라 방향 전환과 맞지 않습니다 ✗","a la: 'a la derecha(오른쪽으로)' 고정 표현 → 정답 ✓"]},{"id":"G683","q":"Creo que ____ Sebastián le pasa algo, está muy serio.","o":["en","de","ø","a"],"a":3,"k":"pasar + 간접목적어","t":"세바스티안에게 무슨 일이 있는 것 같아, 아주 심각해 보여.","e":"'pasarle algo a alguien'은 '누군가에게 무슨 일이 생기다'라는 표현입니다. 간접목적격 le가 가리키는 사람을 명확히 하기 위해 'a + 사람(a Sebastián)'을 함께 씁니다. 예: ¿Qué te pasa?(무슨 일 있어?)","x":["en: '~안에'라는 위치 표현이라 맞지 않습니다 ✗","de: '~의, ~에 대해'라는 뜻이라 le와 함께 쓸 수 없습니다 ✗","ø: 사람 이름이 간접목적어이므로 전치사 a가 필요합니다 ✗","a: 간접목적어 '~에게'를 나타내는 전치사 → 정답 ✓"]},{"id":"G684","q":"¿En qué planta viven? ¿En la segunda o en la ____?","o":["tres","tercero","tercera","tercer"],"a":2,"k":"서수 tercera","t":"몇 층에 사세요? 2층이요, 아니면 3층이요?","e":"층(planta)을 말할 때는 서수(첫째, 둘째…)를 씁니다. planta는 여성명사이므로 tercero의 여성형 tercera를 씁니다. 남성명사 앞에서는 tercer로 줄어듭니다(el tercer piso).","x":["tres: 기수(셋)라 몇 번째 층인지 말할 때는 서수를 씁니다 ✗","tercero: 남성형이라 여성명사 planta와 맞지 않습니다 ✗","tercera: 여성 서수 '세 번째' → 정답 ✓","tercer: 남성 단수 명사 바로 앞에서만 쓰는 줄임형입니다 ✗"]},{"id":"G685","q":"A mí no me gusta la leche y a mi hermana ____.","o":["también","no","ni","tampoco"],"a":3,"k":"tampoco","t":"나는 우유를 좋아하지 않고, 우리 언니도 좋아하지 않는다.","e":"앞 문장이 부정(no me gusta)이고 다른 사람도 같은 의견일 때는 tampoco(~도 아니다)를 씁니다. 'a mi hermana tampoco'는 '언니도 안 좋아한다'는 뜻입니다. también은 긍정문에 동의할 때 씁니다.","x":["también: 긍정문에 대한 동의라 부정 문맥과 맞지 않습니다 ✗","no: '언니는 (좋아하지) 않는다'로 대조를 나타낼 때 쓰며 같은 의견에는 tampoco를 씁니다 ✗","ni: 이 구조에서 단독으로 쓰지 않습니다 ✗","tampoco: 부정문에 대한 동의 '~도 아니다' → 정답 ✓"]},{"id":"G686","q":"No, ____ metro no llega hasta esta parte de la ciudad.","o":["lo","un","ø","el"],"a":3,"k":"정관사 el","t":"아니, 지하철은 도시의 이 지역까지는 안 와.","e":"여기서 metro는 그 도시의 '지하철(시스템)'이라는 특정하고 유일한 대상이므로 정관사 el을 씁니다. 'El metro llega hasta...'는 '지하철이 ~까지 간다'는 뜻입니다.","x":["lo: 중성 관사/대명사라 남성명사 metro 앞에 쓰지 않습니다 ✗","un: '어떤 지하철 한 대'라는 뜻이 되어 어색합니다 ✗","ø: 주어 자리의 명사에는 보통 관사가 필요합니다 ✗","el: 특정한 대상(그 도시의 지하철) 앞 정관사 → 정답 ✓"]},{"id":"G687","q":"Fuimos a Guadalajara ____ muchos años.","o":["antes","desde hace","desde","hace"],"a":3,"k":"hace + 기간","t":"우리는 오래전에 과달라하라에 갔었다.","e":"'hace + 기간'은 '(지금으로부터) ~전에'라는 뜻으로 과거의 한 시점을 나타냅니다. 'hace muchos años'는 '여러 해 전에'입니다. 'desde hace'는 '~전부터 (지금까지 계속)'라는 뜻이라 지속되는 상황에 씁니다.","x":["antes: 'muchos años antes'처럼 뒤에 와야 하며 기간 앞에 쓰지 않습니다 ✗","desde hace: '~전부터 계속'이라는 뜻이라 단순과거(fuimos)와 맞지 않습니다 ✗","desde: '~부터'라는 시작점이라 기간(muchos años) 앞에 쓰지 않습니다 ✗","hace: '~전에' → 정답 ✓"]},{"id":"G688","q":"Ángela va a cumplir ____ años. Su cumpleaños es la semana que viene.","o":["diez ocho","diez y ocho","dieciochos","dieciocho"],"a":3,"k":"숫자 dieciocho","t":"앙헬라는 열여덟 살이 될 거야. 생일이 다음 주거든.","e":"16~19는 한 단어로 붙여 씁니다: dieciséis, diecisiete, dieciocho, diecinueve. 숫자는 복수형 -s를 붙이지 않습니다. 'cumplir ~ años'는 '~살이 되다'라는 표현입니다.","x":["diez ocho: 띄어 쓰지 않고 한 단어로 씁니다 ✗","diez y ocho: 옛 표기로 현재는 한 단어 dieciocho를 씁니다 ✗","dieciochos: 숫자에는 복수 -s를 붙이지 않습니다 ✗","dieciocho: 18의 올바른 표기 → 정답 ✓"]},{"id":"G689","q":"Para ti, ¿____ es la vida en Pekín?","o":["cómo","quién","cuándo","qué"],"a":0,"k":"의문사 cómo","t":"너한테 베이징 생활은 어때?","e":"'¿Cómo es...?'는 사람·장소·생활 등이 '어떤지(특징)'를 물을 때 쓰는 표현입니다. 'la vida en Pekín(베이징에서의 생활)'이 어떤지 묻고 있으므로 cómo가 맞습니다. Pekín은 스페인어로 베이징입니다.","x":["cómo: '어떠한지'를 묻는 의문사 → 정답 ✓","quién: '누구'를 묻는 의문사라 생활(vida)에 맞지 않습니다 ✗","cuándo: '언제'를 묻는 의문사라 맞지 않습니다 ✗","qué: '¿Qué es la vida?'는 '삶이란 무엇인가'라는 정의 질문이 됩니다 ✗"]},{"id":"G690","q":"¿Es verdad que has comprado todo esto ____ solo veinte dólares?","o":["por","en","a","para"],"a":0,"k":"가격의 por","t":"이걸 다 겨우 20달러에 샀다는 게 사실이야?","e":"무언가를 사고팔 때 '~(가격)에'는 전치사 por를 씁니다. 'comprar algo por 20 dólares(20달러에 사다)'처럼 교환·대가를 나타내는 por입니다. 예: Lo vendí por cien euros.(그걸 100유로에 팔았어.)","x":["por: 교환·대가(가격)를 나타내는 '~에' → 정답 ✓","en: 일부 지역에서 'en 20 dólares'라고도 하지만 표준적인 정답은 por입니다 ✗","a: 단가(a 2 euros el kilo)를 말할 때 쓰며 총 구매 가격에는 por를 씁니다 ✗","para: '~를 위해'라는 목적이라 가격을 나타내지 못합니다 ✗"]},{"id":"G691","q":"Prefiero ir ____ metro al centro, así llego antes.","o":["de","en","a","con"],"a":1,"k":"교통수단 en","t":"나는 시내에 지하철로 가는 게 더 좋아, 그러면 더 빨리 도착하거든.","e":"교통수단으로 이동할 때는 'en + 교통수단'을 씁니다. 'ir en metro(지하철로 가다)', 'ir en tren(기차로 가다)'처럼 관사 없이 씁니다. 걸어서 갈 때만 'a pie'라고 합니다.","x":["de: 출발점·소유를 나타내 교통수단에는 쓰지 않습니다 ✗","en: '~을 타고' 교통수단 표현 → 정답 ✓","a: 'a pie(걸어서)'처럼 일부 표현에만 쓰며 metro와는 쓰지 않습니다 ✗","con: '~와 함께'라는 뜻이라 교통수단을 나타내지 못합니다 ✗"]},{"id":"G692","q":"Esta noche vamos a ir ____ bar de Juan.","o":["al","a la","en el","a"],"a":0,"k":"a + el = al","t":"오늘 밤 우리는 후안의 바에 갈 거야.","e":"ir a(~에 가다) 뒤에 남성명사 bar의 정관사 el이 오면 a + el = al로 축약합니다. 그래서 'ir al bar de Juan(후안의 바에 가다)'가 됩니다. 축약은 정관사 el에만 일어나고 la, los, las와는 축약하지 않습니다.","x":["al: a + el 축약형, 남성명사 bar 앞 → 정답 ✓","a la: 여성형이라 남성명사 bar와 맞지 않습니다 ✗","en el: '~안에서'라는 위치라 ir의 목적지에 쓰지 않습니다 ✗","a: 특정한 장소(후안의 바)라 정관사가 필요합니다 ✗"]},{"id":"G693","q":"Voy a llevar ____ mi madre al centro de salud.","o":["a","en","ø","de"],"a":0,"k":"사람 목적어 앞 a","t":"나는 엄마를 보건소에 모셔다 드릴 거야.","e":"llevar(데려가다)의 직접목적어가 사람(mi madre)이므로 그 앞에 '인칭의 a'를 붙입니다. 그래서 'llevar a mi madre(엄마를 모셔다 드리다)'가 됩니다. 뒤의 'al centro de salud'의 a는 목적지를 나타내는 a입니다.","x":["a: 특정 사람 목적어 앞에 붙는 인칭의 a → 정답 ✓","en: '~안에'라는 위치라 맞지 않습니다 ✗","ø: 사람이 직접목적어이므로 a가 필요합니다 ✗","de: '~의, ~로부터'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G694","q":"Estoy contenta, la entrevista de trabajo ____ muy bien.","o":["estuvo saliendo","salió","saldría","salía"],"a":1,"k":"단순과거 salir","t":"나 기분 좋아, 면접이 아주 잘 됐거든.","e":"면접은 이미 끝난 하나의 사건이고 그 결과를 말하므로 단순과거를 씁니다. 'salir bien/mal'은 '(일이) 잘/잘못 되다'라는 표현입니다. salir의 3인칭 단수 단순과거는 salió입니다.","x":["estuvo saliendo: '한동안 나가고 있었다'는 지속의 의미라 결과를 말하지 못합니다 ✗","salió: 끝난 사건의 결과를 나타내는 단순과거 → 정답 ✓","saldría: 가능법(~될 텐데)이라 실제 결과와 맞지 않습니다 ✗","salía: 불완료과거로 과거의 습관·배경이라 맞지 않습니다 ✗"]},{"id":"G695","q":"El deporte ____ más me gusta es el baloncesto y, en segundo lugar, el tenis.","o":["lo que","que","el que","quien"],"a":1,"k":"관계대명사 que","t":"내가 가장 좋아하는 운동은 농구이고, 두 번째는 테니스이다.","e":"명사(el deporte) 바로 뒤에서 그 명사를 꾸미는 문장을 이어 줄 때는 관계대명사 que를 씁니다. 'el deporte que más me gusta'는 '내가 가장 좋아하는 운동'이라는 뜻입니다. el que는 앞에 명사가 없을 때(El que más me gusta es...) 씁니다.","x":["lo que: '~하는 것'이라는 뜻으로 앞에 명사가 없을 때 씁니다 ✗","que: 앞 명사를 꾸미는 관계대명사 → 정답 ✓","el que: 앞에 이미 'el deporte'가 있어 관사가 겹칩니다 ✗","quien: 사람만 가리키는 관계대명사라 운동(deporte)에 쓸 수 없습니다 ✗"]},{"id":"G696","q":"Esos chicos de ahí son ____ primos.","o":["míos","de mí","mi","mis"],"a":3,"k":"소유형용사 mis","t":"저기 있는 저 남자애들은 내 사촌들이야.","e":"명사 앞에 오는 소유형용사는 명사의 수에 맞춥니다. primos(사촌들)가 복수이므로 mis를 씁니다. míos는 명사 뒤나 단독으로 쓰는 형태입니다(Son primos míos / Son míos).","x":["míos: 명사 앞에 쓰지 않고 뒤에 씁니다(primos míos) ✗","de mí: 소유를 나타내는 표현으로 쓰지 않습니다 ✗","mi: 단수형이라 복수 primos와 맞지 않습니다 ✗","mis: 복수 명사 앞 소유형용사 → 정답 ✓"]},{"id":"G697","q":"Pasado mañana ____ a Lisboa.","o":["hemos ido","fuimos","vamos a ir","habíamos ido"],"a":2,"k":"ir a + 동사원형","t":"모레 우리는 리스본에 갈 거야.","e":"'Pasado mañana(모레)'는 미래이므로 미래 표현이 필요합니다. 'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래·계획을 나타냅니다. 'vamos a ir'는 '우리는 갈 것이다'입니다.","x":["hemos ido: 현재완료라 과거 경험을 나타냅니다 ✗","fuimos: 단순과거라 미래인 모레와 맞지 않습니다 ✗","vamos a ir: 가까운 미래 계획 → 정답 ✓","habíamos ido: 대과거라 미래 시점과 맞지 않습니다 ✗"]},{"id":"G698","q":"Dame otra vez ____ número de teléfono, que he perdido mi móvil.","o":["tu","el tuyo","tú","tus"],"a":0,"k":"소유형용사 tu","t":"네 전화번호 다시 알려 줘, 휴대폰을 잃어버렸거든.","e":"명사(número) 앞에서 '너의'라고 할 때는 악센트 없는 tu를 씁니다. 악센트가 있는 tú는 주격 대명사 '너'입니다. 'el tuyo'는 '네 것'이라는 뜻으로 명사 없이 씁니다.","x":["tu: 단수 명사 앞 소유형용사 '너의' → 정답 ✓","el tuyo: '네 것'이라는 소유대명사라 뒤에 명사가 올 수 없습니다 ✗","tú: 악센트가 있으면 주격 대명사 '너는'입니다 ✗","tus: 복수형이라 단수 número와 맞지 않습니다 ✗"]},{"id":"G699","q":"Para llegar a esta calle, ____ recto y después gire a la izquierda.","o":["sigue","sigas","siga","sigues"],"a":2,"k":"usted 명령형","t":"이 거리로 오시려면 직진하신 다음 왼쪽으로 도세요.","e":"뒤의 'gire(도세요)'가 usted 명령형이므로 앞의 동사도 usted 명령형으로 맞춥니다. seguir(계속 가다)의 usted 명령형은 접속법 형태인 siga입니다. 'seguir recto'는 '직진하다'라는 길 안내 표현입니다.","x":["sigue: tú 명령형이라 usted형 gire와 맞지 않습니다 ✗","sigas: tú 부정명령(no sigas)에 쓰는 형태입니다 ✗","siga: usted 긍정 명령형 → 정답 ✓","sigues: 직설법 현재(너는 계속 간다)라 명령이 아닙니다 ✗"]},{"id":"G700","q":"¿Por qué no te caen bien los vecinos ____ tercero?","o":["de","desde","del","desde el"],"a":2,"k":"de + el = del","t":"너는 왜 3층 이웃들을 안 좋아해?","e":"'el tercero'는 '3층(el tercer piso)'을 줄여 말한 것입니다. '3층의 이웃들'이라는 소속을 나타내는 de 뒤에 el이 오면 축약해서 del이 됩니다. 'caer bien/mal a alguien'은 '~에게 호감/비호감이다'라는 표현입니다.","x":["de: 정관사 el이 빠져서 '3층'이라는 특정 장소를 가리키지 못합니다 ✗","desde: '~부터'라는 출발점이라 소속을 나타내지 못합니다 ✗","del: de + el 축약형, '3층의' → 정답 ✓","desde el: '3층부터'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G701","q":"No sé ____ de informática, no es lo mío.","o":["alguna","ninguna","nada","algo"],"a":2,"k":"부정어 nada","t":"나는 컴퓨터는 하나도 몰라, 내 분야가 아니야.","e":"부정문에서 '아무것도, 전혀'라고 할 때는 nada를 씁니다. 'No sé nada de ...'는 '~에 대해 아무것도 모른다'는 뜻입니다. 'no es lo mío'는 '내 체질/분야가 아니다'라는 자주 쓰는 표현입니다.","x":["alguna: 여성형 '어떤'이라 명사 없이 쓸 수 없고 긍정 표현입니다 ✗","ninguna: 여성 명사 앞에 쓰는 형태라 여기서는 맞지 않습니다 ✗","nada: 부정문에서 '아무것도' → 정답 ✓","algo: '무언가'라는 긍정 표현이라 부정문 no와 어울리지 않습니다 ✗"]},{"id":"G702","q":"Tengo que ____ algo importante.","o":["contar te","contarte","te contar","contar a ti"],"a":1,"k":"동사원형 + 대명사","t":"너에게 중요한 걸 말해야 해.","e":"간접목적격 대명사 te(너에게)는 동사원형 뒤에 붙여 한 단어로 씁니다: contarte. 또는 활용 동사 앞에 둘 수도 있습니다: Te tengo que contar algo. 'contar'는 여기서 '이야기하다, 털어놓다'라는 뜻입니다.","x":["contar te: 대명사를 띄어 쓰지 않고 붙여 씁니다 ✗","contarte: 동사원형 + te를 붙인 형태 → 정답 ✓","te contar: 대명사를 동사원형 바로 앞에 둘 수 없습니다 ✗","contar a ti: 'a ti'만 쓰고 대명사 te 없이 쓰지 않습니다 ✗"]},{"id":"G703","q":"Si todos ____ listos, podemos salir ya.","o":["están","estén","sean","son"],"a":0,"k":"estar listo","t":"모두 준비됐으면 이제 출발할 수 있어.","e":"listo는 ser와 쓰면 '똑똑하다', estar와 쓰면 '준비되다'라는 뜻입니다. 여기서는 출발 준비가 된 상태이므로 estar를 씁니다. 또 si 조건절에는 직설법을 쓰므로 están이 정답입니다.","x":["están: estar(준비된 상태) + si 뒤 직설법 → 정답 ✓","estén: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","sean: 접속법이고, ser listo는 '똑똑하다'라는 뜻이 됩니다 ✗","son: 'son listos'는 '똑똑하다'라는 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"G704","q":"Hoy los tomates están ____ 2 euros el kilo.","o":["en","a","por","con"],"a":1,"k":"가격 estar a","t":"오늘 토마토는 1킬로에 2유로이다.","e":"시장 가격처럼 변동하는 가격을 말할 때는 'estar a + 가격'을 씁니다. '¿A cuánto están los tomates?(토마토 얼마예요?)'처럼 묻고 'Están a 2 euros el kilo'처럼 답합니다.","x":["en: 가격 표현 estar 뒤에 쓰지 않습니다 ✗","a: 변동 가격을 나타내는 estar a → 정답 ✓","por: 사고팔 때의 대가(comprar por)에 쓰며 estar와 함께 쓰지 않습니다 ✗","con: '~와 함께'라는 뜻이라 가격을 나타내지 못합니다 ✗"]},{"id":"G705","q":"Los señores Díaz ____ aquí la semana pasada.","o":["estuvieron","están","van a estar","han estado"],"a":0,"k":"단순과거 estar","t":"디아스 부부는 지난주에 여기 있었다.","e":"'la semana pasada(지난주)'는 끝난 과거 시점이므로 단순과거를 씁니다. estar의 3인칭 복수 단순과거는 불규칙형 estuvieron입니다. 'los señores Díaz'는 '디아스 씨 부부'를 뜻합니다.","x":["estuvieron: 지난주(끝난 과거)의 단순과거 3인칭 복수 → 정답 ✓","están: 현재형이라 지난주와 맞지 않습니다 ✗","van a estar: 미래 표현이라 맞지 않습니다 ✗","han estado: 현재완료는 la semana pasada 같은 끝난 시점과 쓰지 않습니다 ✗"]},{"id":"G706","q":"¿____ qué ciudad nació Picasso?","o":["Desde","A","De","En"],"a":3,"k":"장소의 en","t":"피카소는 어느 도시에서 태어났나요?","e":"태어난 장소는 'nacer en + 장소'로 나타냅니다. 의문문에서는 전치사가 의문사 앞으로 와서 '¿En qué ciudad...?'가 됩니다. 참고로 피카소는 말라가(Málaga)에서 태어났습니다.","x":["Desde: '~부터'라는 뜻이라 태어난 장소에 쓰지 않습니다 ✗","A: 방향·목적지를 나타내 출생지에 쓰지 않습니다 ✗","De: '¿De qué ciudad es?'(어느 도시 출신이야?)에는 쓰지만 nacer와는 en을 씁니다 ✗","En: nacer en '~에서 태어나다' → 정답 ✓"]},{"id":"G707","q":"Estoy muerto ____ miedo, acabo de ver una serpiente.","o":["a","de","con","por"],"a":1,"k":"estar muerto de","t":"무서워 죽겠어, 방금 뱀을 봤거든.","e":"'estar muerto de + 감정/상태'는 '~해서 죽겠다'라는 과장 표현입니다. 'muerto de miedo(무서워 죽겠다)', 'muerto de hambre(배고파 죽겠다)', 'muerto de sueño(졸려 죽겠다)'처럼 씁니다.","x":["a: 이 표현에 쓰는 전치사가 아닙니다 ✗","de: 'muerto de + 감정' 고정 표현 → 정답 ✓","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗","por: 'muerto por'는 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"G708","q":"Los sábados trabajo desde las 8 ____ las 13 horas.","o":["para","hasta","por","en"],"a":1,"k":"desde...hasta","t":"토요일마다 나는 8시부터 13시까지 일한다.","e":"시간의 범위 '~부터 ~까지'는 'desde ... hasta ...'로 씁니다. 앞에 desde가 있으므로 짝이 맞는 hasta가 옵니다. 'de las 8 a las 13'처럼 de...a로도 말할 수 있습니다.","x":["para: '~까지(기한)'라는 뜻도 있지만 범위의 끝을 나타낼 때는 hasta를 씁니다 ✗","hasta: desde와 짝을 이루는 '~까지' → 정답 ✓","por: 'por la mañana'처럼 대략적인 시간대에 쓰며 범위의 끝이 아닙니다 ✗","en: 시간 범위의 끝을 나타내지 못합니다 ✗"]},{"id":"G709","q":"Mi marido ____ antes que yo.","o":["acuesta","se acueste","se acuesta","acueste"],"a":2,"k":"재귀동사 acostarse","t":"남편은 나보다 일찍 잔다.","e":"acostarse는 '(자기 자신이) 잠자리에 들다, 눕다'라는 재귀동사입니다. 재귀대명사 se가 없으면 acostar는 '(다른 사람을) 재우다'라는 뜻이 됩니다. 일반적인 사실이므로 직설법 현재 'se acuesta'(o→ue 변화)를 씁니다.","x":["acuesta: se가 없으면 '남을 재우다'라는 뜻이 됩니다 ✗","se acueste: 접속법이라 사실을 말하는 문장에 맞지 않습니다 ✗","se acuesta: 재귀동사 직설법 현재 3인칭 단수 → 정답 ✓","acueste: 접속법이고 재귀대명사도 없습니다 ✗"]},{"id":"G710","q":"Estos regalos son ____ mis hijos.","o":["hacia","a","para","por"],"a":2,"k":"전치사 para(대상)","t":"이 선물들은 우리 아이들을 위한 것이다.","e":"선물·물건을 받을 사람, 즉 '~에게 줄, ~를 위한'은 전치사 para로 나타냅니다. 'Esto es para ti(이건 너를 위한 거야)'처럼 자주 씁니다. por는 이유나 대신함을 나타냅니다.","x":["hacia: '~쪽으로'라는 방향을 나타내 받는 사람에 쓰지 않습니다 ✗","a: 'regalar a'처럼 동사와 쓰지만 'ser a mis hijos'는 쓰지 않습니다 ✗","para: 받는 사람·대상 '~를 위한' → 정답 ✓","por: '~때문에, ~대신에'라는 뜻이라 의미가 달라집니다 ✗"]},{"id":"G711","q":"¡Qué diccionario tan bueno! ¿Me ____ dejas un momento?","o":["los","la","le","lo"],"a":3,"k":"직접목적격 lo","t":"정말 좋은 사전이다! 잠깐 빌려줄래?","e":"dejar(빌려주다)의 목적어는 앞에 나온 'diccionario(사전)'입니다. 남성 단수이므로 직접목적격 lo를 씁니다. 'me lo dejas'에서 me는 '나에게', lo는 '그것을'이며 순서는 간접 → 직접입니다.","x":["los: 복수형이라 단수 diccionario와 맞지 않습니다 ✗","la: 여성형이라 남성명사 diccionario와 맞지 않습니다 ✗","le: 간접목적격이라 이미 me가 있는 자리에 맞지 않습니다 ✗","lo: 남성 단수 diccionario를 받는 직접목적격 → 정답 ✓"]},{"id":"G712","q":"Si no puedes darle a Javi las llaves, ____ daré yo.","o":["las","se los","se las","le las"],"a":2,"k":"se las 변환","t":"하비에게 열쇠를 줄 수 없으면 내가 줄게.","e":"간접목적격 le(하비에게)와 직접목적격 las(열쇠들을)가 함께 오면, le가 se로 바뀝니다. 그래서 'le las'가 아니라 'se las daré'가 됩니다. llaves는 여성 복수이므로 las입니다.","x":["las: 간접목적어(하비에게)를 나타내는 대명사가 빠졌습니다 ✗","se los: los는 남성 복수라 여성명사 llaves와 맞지 않습니다 ✗","se las: le → se 변환 + 여성 복수 las → 정답 ✓","le las: le와 lo/la/los/las가 함께 오면 le는 반드시 se로 바뀝니다 ✗"]},{"id":"G713","q":"¿Qué hacéis en ____ tiempo libre?","o":["vuestro","vuestras","vuestra","vuestros"],"a":0,"k":"소유형용사 vuestro","t":"너희는 여가 시간에 뭐 하니?","e":"vosotros(너희)의 소유형용사는 vuestro로, 명사의 성·수에 맞춰 변합니다. tiempo(시간)는 남성 단수이므로 vuestro가 됩니다. 중남미에서는 ustedes를 쓰므로 'su tiempo libre'라고 합니다.","x":["vuestro: 남성 단수 tiempo 앞 소유형용사 → 정답 ✓","vuestras: 여성 복수형이라 맞지 않습니다 ✗","vuestra: 여성 단수형이라 남성명사 tiempo와 맞지 않습니다 ✗","vuestros: 남성 복수형이라 단수 tiempo와 맞지 않습니다 ✗"]},{"id":"G714","q":"No creo que a Jaime ____ interese ver esa obra de teatro.","o":["ø","le","lo","se"],"a":1,"k":"interesar 구문","t":"하이메가 그 연극을 보는 데 관심이 있을 것 같지 않아.","e":"interesar(관심을 끌다)는 gustar처럼 '관심 있는 사람'을 간접목적격 대명사로 씁니다. 'a Jaime'는 3인칭 단수이므로 le를 함께 씁니다. 'No creo que' 뒤라서 동사가 접속법 interese로 쓰였습니다.","x":["ø: 'a + 사람'이 있으면 간접목적격 대명사가 꼭 필요합니다 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓","lo: 직접목적격이라 interesar 구문에 쓰지 않습니다 ✗","se: 재귀대명사라 이 구조와 맞지 않습니다 ✗"]},{"id":"G715","q":"Ya ____ mis tareas domésticas. Ahora me voy a dar un paseo.","o":["he hecho","estaba haciendo","hacía","haría"],"a":0,"k":"ya + 현재완료","t":"집안일은 이미 다 했어. 이제 산책하러 나갈 거야.","e":"'Ya(이미)'와 함께 방금 끝나서 현재와 연결된 일을 말할 때는 현재완료를 씁니다. 'he hecho(했다)'는 hacer의 불규칙 과거분사 hecho를 쓴 현재완료입니다. 뒤 문장의 'Ahora(이제)'도 현재와의 연결을 보여 줍니다.","x":["he hecho: ya + 현재와 연결된 완료 → 정답 ✓","estaba haciendo: '하고 있던 중이었다'는 뜻이라 완료와 맞지 않습니다 ✗","hacía: 과거의 습관·배경이라 '이미 끝냈다'를 나타내지 못합니다 ✗","haría: 가능법(~할 텐데)이라 맞지 않습니다 ✗"]},{"id":"G716","q":"¿____ te salió el examen de portugués?","o":["Qué","Dónde","Cómo","Por qué"],"a":2,"k":"salir + 결과 cómo","t":"포르투갈어 시험은 어떻게 됐어?","e":"'¿Cómo te salió...?'는 '(시험·일이) 어떻게 됐어?'라고 결과를 묻는 표현입니다. salir bien/mal(잘/못 되다)의 결과를 묻기 때문에 cómo(어떻게)를 씁니다. te는 '너에게(너의 경우)'를 나타냅니다.","x":["Qué: '무엇'이라는 뜻이라 결과의 상태를 묻지 못합니다 ✗","Dónde: '어디'를 묻는 의문사라 맞지 않습니다 ✗","Cómo: 결과가 '어떻게' 되었는지 묻는 의문사 → 정답 ✓","Por qué: '왜'를 묻는 말이라 의미가 달라집니다 ✗"]},{"id":"G717","q":"El gato está ____ la silla.","o":["de bajo","debajo de","bajo de","debajo"],"a":1,"k":"debajo de","t":"고양이가 의자 밑에 있다.","e":"'~아래에'는 'debajo de + 명사'로 씁니다. 뒤에 명사(la silla)가 오면 반드시 de를 넣어야 합니다. 명사 없이 쓸 때만 debajo 단독으로 씁니다. 예: El gato está debajo.(고양이는 밑에 있어.)","x":["de bajo: 띄어 쓰면 '낮은 것의'라는 엉뚱한 뜻이 됩니다 ✗","debajo de: 명사 앞 '~아래에' → 정답 ✓","bajo de: bajo는 전치사로 쓸 때 de 없이 'bajo la silla'로 씁니다 ✗","debajo: 뒤에 명사가 올 때는 de가 필요합니다 ✗"]},{"id":"G718","q":"Ojalá nos ____ el dinero que nos deben.","o":["devolvieron","devuelven","devuelvan","devolverán"],"a":2,"k":"ojalá + 접속법","t":"그들이 우리에게 빚진 돈을 돌려주면 좋겠다.","e":"ojalá(~하면 좋겠다)는 바람을 나타내므로 뒤에 접속법을 씁니다. devolver(돌려주다)는 o→ue로 바뀌며 3인칭 복수 접속법 현재는 devuelvan입니다. 예: Ojalá haga buen tiempo.(날씨가 좋으면 좋겠다.)","x":["devolvieron: 직설법 단순과거라 바람을 나타내지 못합니다 ✗","devuelven: 직설법 현재라 ojalá 뒤에 쓰지 않습니다 ✗","devuelvan: ojalá 뒤 접속법 현재 → 정답 ✓","devolverán: 미래형이라 ojalá 뒤에 쓰지 않습니다 ✗"]},{"id":"G719","q":"Alfredo es un ____ amigo mío.","o":["bueno","buen","buena","bien"],"a":1,"k":"bueno → buen","t":"알프레도는 내 좋은 친구다.","e":"bueno(좋은)가 남성 단수 명사 앞에 오면 buen으로 줄어듭니다. 'un buen amigo(좋은 친구)'처럼요. 'un amigo mío'는 '내 친구 중 한 명'이라는 뜻입니다.","x":["bueno: 남성 단수 명사 앞에서는 buen으로 줄여야 합니다 ✗","buen: 남성 단수 명사 앞 줄임형 → 정답 ✓","buena: 여성형이라 amigo와 맞지 않습니다 ✗","bien: 부사(잘)라 명사를 꾸밀 수 없습니다 ✗"]},{"id":"G720","q":"Aquí hay ____ gente, ¿por qué no vamos a un sitio más tranquilo?","o":["mucho","poca","poquísima","demasiada"],"a":3,"k":"demasiado 일치","t":"여기 사람이 너무 많아, 좀 더 조용한 곳으로 가지 않을래?","e":"뒤의 '좀 더 조용한 곳으로 가자'는 말에서 사람이 너무 많다는 뜻임을 알 수 있습니다. demasiado(너무 많은)는 명사에 성·수를 맞추는데, gente(사람들)는 문법적으로 여성 단수라 demasiada가 됩니다.","x":["mucho: gente는 여성명사라 mucha가 되어야 합니다 ✗","poca: '적은'이라는 뜻이라 조용한 곳으로 가자는 말과 맞지 않습니다 ✗","poquísima: '아주 적은'이라는 뜻이라 문맥과 반대입니다 ✗","demasiada: 여성 단수 gente에 맞춘 '너무 많은' → 정답 ✓"]},{"id":"G721","q":"¿____ están los platos y los vasos?","o":["A dónde","Donde","Dónde","Adónde"],"a":2,"k":"의문사 dónde","t":"접시랑 컵은 어디에 있어?","e":"사물이 '어디에 있는지' 위치를 물을 때는 '¿Dónde está(n)...?'를 씁니다. 의문사이므로 악센트(ó)가 필요합니다. adónde/a dónde는 '어디로(가다)'처럼 이동 방향을 물을 때 씁니다.","x":["A dónde: '어디로'라는 방향을 묻는 말이라 estar와 맞지 않습니다 ✗","Donde: 악센트가 없으면 의문사가 아니라 관계부사(~하는 곳)가 됩니다 ✗","Dónde: 위치 '어디에'를 묻는 의문사 → 정답 ✓","Adónde: '어디로'라는 이동 방향을 물을 때 씁니다 ✗"]},{"id":"G722","q":"¿Dónde ____ la boda de tu prima?","o":["fue","ha estado","estuvo","hubo"],"a":0,"k":"ser(행사 장소)","t":"네 사촌 결혼식은 어디서 했어?","e":"결혼식·파티·회의 같은 '행사'가 열리는 장소를 말할 때는 estar가 아니라 ser를 씁니다. 'La boda fue en Sevilla(결혼식은 세비야에서 열렸다)'처럼요. 끝난 과거 행사이므로 ser의 단순과거 fue입니다.","x":["fue: 행사의 장소를 나타내는 ser의 단순과거 → 정답 ✓","ha estado: estar는 사물·사람의 위치에 쓰며 행사에는 쓰지 않습니다 ✗","estuvo: 행사 개최 장소에는 estar를 쓰지 않습니다 ✗","hubo: 'hubo una boda(결혼식이 있었다)'처럼 존재를 나타내며 dónde + 정관사 명사와는 어색합니다 ✗"]},{"id":"G723","q":"El examen fue facilísimo, no ____ ninguna dificultad para aprobarlo.","o":["tuve","estuve teniendo","voy a tener","estaba teniendo"],"a":0,"k":"단순과거 tener","t":"시험은 아주 쉬웠어, 합격하는 데 전혀 어려움이 없었어.","e":"앞 문장 'El examen fue facilísimo(시험은 아주 쉬웠다)'처럼 끝난 사건을 말하므로 단순과거를 씁니다. tener의 1인칭 단수 단순과거는 불규칙형 tuve입니다. 'no ... ninguna dificultad'는 '전혀 어려움이 없다'는 이중부정입니다.","x":["tuve: 끝난 일(시험)의 단순과거 → 정답 ✓","estuve teniendo: tener는 진행형으로 잘 쓰지 않으며 어색합니다 ✗","voy a tener: 미래 표현이라 이미 끝난 시험과 맞지 않습니다 ✗","estaba teniendo: 과거진행이라 결과를 말하는 문장에 맞지 않습니다 ✗"]},{"id":"G724","q":"Ayer ____ un cuadro desde la mañana hasta la medianoche.","o":["estuve pintando","estaba pintando","pintaba","he pintado"],"a":0,"k":"단순과거 진행형","t":"어제 나는 아침부터 자정까지 그림을 그리고 있었다.","e":"과거의 정해진 기간(desde ... hasta ...) 동안 계속된 행동을 하나의 끝난 덩어리로 말할 때는 'estuve + 현재분사'(단순과거 진행형)를 씁니다. 'estaba pintando'는 다른 사건의 배경일 때 주로 씁니다.","x":["estuve pintando: 끝난 기간 동안 계속된 행동 → 정답 ✓","estaba pintando: 배경 묘사용이라 시작과 끝이 정해진 기간과 어색합니다 ✗","pintaba: 과거의 습관을 나타내 어제의 특정 기간과 맞지 않습니다 ✗","he pintado: 현재완료는 ayer와 함께 쓰지 않습니다 ✗"]},{"id":"G725","q":"No trabajamos ____ domingos.","o":["el","a los","en los","los"],"a":3,"k":"요일 + 정관사","t":"우리는 일요일에는 일하지 않는다.","e":"요일 앞에는 전치사 없이 정관사를 씁니다. 매주 반복되는 '~요일마다'는 복수 정관사 los를 써서 'los domingos'가 됩니다. 'el domingo'는 '(이번) 일요일에'라는 한 번의 날을 뜻합니다.","x":["el: 단수라 '이번 일요일'이 되어 습관적 의미와 맞지 않습니다 ✗","a los: 요일 앞에는 전치사 a를 쓰지 않습니다 ✗","en los: 요일 앞에는 전치사 en을 쓰지 않습니다 ✗","los: 반복되는 요일 '일요일마다' → 정답 ✓"]},{"id":"G726","q":"Usted ____ muy sincero.","o":["son","eres","sois","es"],"a":3,"k":"usted + 3인칭 단수","t":"당신은 매우 솔직하시군요.","e":"usted(당신)는 의미상 2인칭이지만 동사는 3인칭 단수로 활용합니다. 그래서 ser의 3인칭 단수 es를 씁니다. 복수 ustedes는 3인칭 복수(son)를 씁니다.","x":["son: 3인칭 복수라 ustedes에 씁니다 ✗","eres: tú(너)에 쓰는 형태라 usted와 맞지 않습니다 ✗","sois: vosotros(너희)에 쓰는 형태입니다 ✗","es: usted에 맞는 3인칭 단수 → 정답 ✓"]},{"id":"G727","q":"Cuando ____ 18 años, voy a sacarme el carné de conducir.","o":["tengo","tenga","tiene","tendré"],"a":1,"k":"cuando + 접속법","t":"18살이 되면 운전면허를 딸 거야.","e":"cuando가 미래의 일(아직 일어나지 않은 때)을 말할 때는 뒤에 접속법 현재를 씁니다. 그래서 'Cuando tenga 18 años(내가 18살이 되면)'가 됩니다. 반면 습관을 말할 때는 직설법을 씁니다(Cuando tengo tiempo, leo).","x":["tengo: 직설법이라 현재 습관을 나타내며 미래의 때에는 맞지 않습니다 ✗","tenga: 미래의 때를 나타내는 cuando + 접속법 → 정답 ✓","tiene: 3인칭이라 주어(yo)와 맞지 않습니다 ✗","tendré: cuando 뒤에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G728","q":"____ padres viven en Toledo.","o":["Mi","Mis","Míos","Los míos"],"a":1,"k":"소유형용사 mis","t":"우리 부모님은 톨레도에 사신다.","e":"padres(부모님)는 복수이므로 소유형용사도 복수형 mis를 씁니다. 명사 앞에 오는 소유형용사 mi/mis는 명사의 수에만 맞춥니다. 'Los míos'는 '내 것들'이라는 뜻으로 명사 없이 씁니다.","x":["Mi: 단수형이라 복수 padres와 맞지 않습니다 ✗","Mis: 복수 명사 앞 소유형용사 → 정답 ✓","Míos: 명사 뒤에 쓰는 형태라 명사 앞에 올 수 없습니다 ✗","Los míos: '내 것들'이라는 대명사라 뒤에 명사가 올 수 없습니다 ✗"]},{"id":"G729","q":"Aquel día no ____ a clase porque me sentía enfermo.","o":["he ido","iría","fui","iba"],"a":2,"k":"단순과거 vs 불완료","t":"그날 나는 몸이 아파서 수업에 가지 않았다.","e":"'Aquel día(그날)'의 한 번 일어난 사건(수업에 안 감)은 단순과거 'no fui'로 씁니다. 그 이유가 되는 배경 상태(아팠다)는 불완료과거 'me sentía'로 표현합니다. ir의 단순과거 1인칭은 fui입니다.","x":["he ido: 현재완료라 과거 특정한 날(aquel día)과 맞지 않습니다 ✗","iría: 가능법(~갈 텐데)이라 실제 사건과 맞지 않습니다 ✗","fui: 특정한 날 일어난 사건의 단순과거 → 정답 ✓","iba: 불완료과거로 습관(가곤 했다)의 느낌이 되어 어색합니다 ✗"]},{"id":"G730","q":"¿Qué quieres ____ decirnos?","o":["de","por","a","ø"],"a":3,"k":"querer + 동사원형","t":"우리에게 무슨 말을 하고 싶은 거야?","e":"querer(원하다)는 전치사 없이 바로 동사원형을 받습니다. 'querer decir'는 '말하고 싶다' 또는 '의미하다'라는 뜻입니다. 대명사 nos(우리에게)는 동사원형 뒤에 붙였습니다.","x":["de: querer 뒤에 de를 쓰지 않습니다 ✗","por: querer 뒤에 por를 쓰지 않습니다 ✗","a: querer 뒤에 a를 쓰지 않습니다(사람 목적어 제외) ✗","ø: querer + 동사원형 바로 연결 → 정답 ✓"]},{"id":"G731","q":"Que yo sepa, los Rodríguez siguen ____ en Madrid.","o":["a vivir","vivir","vivido","viviendo"],"a":3,"k":"seguir + 현재분사","t":"내가 알기로는 로드리게스 가족은 아직 마드리드에 살고 있다.","e":"'seguir + 현재분사(-ando/-iendo)'는 '계속 ~하고 있다, 여전히 ~하다'라는 뜻입니다. 그래서 'siguen viviendo(여전히 살고 있다)'가 됩니다. 'Que yo sepa'는 '내가 알기로는'이라는 관용 표현입니다.","x":["a vivir: seguir 뒤에 'a + 동사원형'은 쓰지 않습니다 ✗","vivir: seguir 뒤에 동사원형은 쓰지 않습니다 ✗","vivido: 과거분사라 seguir와 함께 '계속 ~하다'를 만들지 못합니다 ✗","viviendo: seguir + 현재분사 '계속 ~하다' → 정답 ✓"]},{"id":"G732","q":"Los estudiantes ____ el autobús escolar.","o":["esperado","están esperando","esperando","esperar"],"a":1,"k":"현재진행형","t":"학생들은 통학 버스를 기다리고 있다.","e":"문장에 활용된 동사가 없으므로 동사 전체가 필요합니다. 'estar + 현재분사'인 'están esperando(기다리고 있다)'가 완전한 동사 형태입니다. 주어 los estudiantes가 복수이므로 están입니다.","x":["esperado: 과거분사만으로는 문장의 동사가 될 수 없습니다 ✗","están esperando: estar + 현재분사, 현재진행형 → 정답 ✓","esperando: estar 없이 현재분사만으로는 동사가 되지 않습니다 ✗","esperar: 동사원형이라 활용된 동사가 필요합니다 ✗"]},{"id":"G733","q":"¿Me encantan tus zapatillas? ¿Dónde ____ venden?","o":["lo","la","las","les"],"a":2,"k":"직접목적격 las","t":"네 운동화 정말 마음에 든다! 그거 어디서 팔아?","e":"앞에 나온 'tus zapatillas(네 운동화)'를 받는 직접목적격 대명사가 필요합니다. zapatillas는 여성 복수이므로 las를 씁니다. '¿Dónde las venden?'은 '그것들을 어디서 팔아?'라는 뜻이며, 여기서 venden은 불특정 주어(사람들이 판다)입니다.","x":["lo: 남성 단수형이라 맞지 않습니다 ✗","la: 단수형이라 복수 zapatillas와 맞지 않습니다 ✗","las: 여성 복수 zapatillas를 받는 직접목적격 → 정답 ✓","les: 간접목적격(그들에게)이라 '팔다'의 대상에 맞지 않습니다 ✗"]},{"id":"G734","q":"Ayer Ángela no ____ cenar, no tenía hambre.","o":["quise","querría","quiere","quiso"],"a":3,"k":"단순과거 querer","t":"어제 앙헬라는 저녁을 먹으려 하지 않았다, 배가 고프지 않았거든.","e":"'Ayer(어제)'의 한 번의 결정(먹지 않겠다고 함)은 단순과거로 나타냅니다. 주어가 Ángela(3인칭 단수)이므로 quiso입니다. 'no quiso'는 '거절했다, 하려 하지 않았다'는 뉘앙스가 있습니다.","x":["quise: 1인칭 단수(나는)라 주어 Ángela와 맞지 않습니다 ✗","querría: 가능법(~하고 싶을 텐데)이라 과거 사실과 맞지 않습니다 ✗","quiere: 현재형이라 ayer와 맞지 않습니다 ✗","quiso: 단순과거 3인칭 단수 → 정답 ✓"]},{"id":"G735","q":"Nada me ____ tanto asco como la carne cruda.","o":["da","dé","doy","di"],"a":0,"k":"dar asco","t":"생고기만큼 역겨운 건 없어.","e":"'dar asco a alguien'은 '~에게 역겨움을 주다', 즉 '~가 역겹다'라는 표현입니다. 주어는 nada(아무것도)이고 3인칭 단수이므로 da를 씁니다. 'Nada ... tanto ... como ...'는 '~만큼 …한 것은 없다'라는 뜻입니다.","x":["da: 3인칭 단수 직설법 현재 → 정답 ✓","dé: 접속법이라 사실을 말하는 문장에 맞지 않습니다 ✗","doy: 1인칭 단수(나는 준다)라 주어 nada와 맞지 않습니다 ✗","di: 1인칭 단수 단순과거라 주어도 시제도 맞지 않습니다 ✗"]},{"id":"G736","q":"____ un corte en el dedo cuando estaba cocinando.","o":["Hice","Me hice","Yo hice","Me lo hice"],"a":1,"k":"재귀 hacerse","t":"요리하다가 손가락을 베였다.","e":"'hacerse un corte'는 '(자기 몸에) 상처를 내다, 베이다'라는 표현입니다. 자기 자신에게 일어난 일이므로 재귀대명사 me가 필요합니다. 'Me hice daño(다쳤다)'도 같은 구조입니다.","x":["Hice: 재귀대명사가 없어 '(무언가를) 잘랐다'는 뜻이 되어 어색합니다 ✗","Me hice: 자기 몸에 상처를 낸 재귀 표현 → 정답 ✓","Yo hice: 주어만 있고 재귀대명사 me가 빠졌습니다 ✗","Me lo hice: lo가 un corte와 겹쳐 중복됩니다 ✗"]},{"id":"G737","q":"Si no te gusta este postre, puedo traerte ____.","o":["un otro","otro","uno otro","otra"],"a":1,"k":"otro(관사 없이)","t":"이 디저트가 마음에 안 들면 다른 걸 가져다줄 수 있어.","e":"otro(다른)는 앞에 부정관사 un/uno를 붙이지 않습니다. 'un otro'는 흔한 실수입니다. postre(디저트)는 남성명사이므로 남성형 otro를 씁니다.","x":["un otro: otro 앞에는 부정관사를 쓰지 않습니다 ✗","otro: 남성명사 postre를 받는 '다른 것' → 정답 ✓","uno otro: 이런 형태는 쓰지 않습니다 ✗","otra: 여성형이라 남성명사 postre와 맞지 않습니다 ✗"]},{"id":"G738","q":"Cuando ____ mayor, voy a dar la vuelta al mundo.","o":["seré","soy","sea","voy a ser"],"a":2,"k":"cuando + 접속법","t":"나는 어른이 되면 세계 일주를 할 거야.","e":"미래의 시점을 말하는 cuando 뒤에는 접속법 현재를 씁니다. ser의 접속법 현재 1인칭은 sea이므로 'Cuando sea mayor(내가 커서/어른이 되면)'가 됩니다. 'dar la vuelta al mundo'는 '세계 일주를 하다'라는 표현입니다.","x":["seré: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","soy: 직설법 현재라 미래의 때와 맞지 않습니다 ✗","sea: 미래 시점 cuando + 접속법 현재 → 정답 ✓","voy a ser: 미래 표현이라 cuando 뒤에 쓰지 않습니다 ✗"]},{"id":"G739","q":"____ tenés menos plata que yo.","o":["Usted","Vos","Tú","Vosotros"],"a":1,"k":"voseo","t":"너는 나보다 돈이 적어.","e":"'tenés'는 아르헨티나·우루과이 등에서 쓰는 voseo(tú 대신 vos를 쓰는 방식)의 동사 형태입니다. 그래서 주어는 vos입니다. 스페인식으로는 'Tú tienes'가 됩니다. 'plata'도 중남미에서 '돈(dinero)'이라는 뜻으로 많이 씁니다.","x":["Usted: usted는 3인칭 형태 tiene를 씁니다 ✗","Vos: tenés와 짝을 이루는 voseo 주어 → 정답 ✓","Tú: tú는 tienes를 씁니다 ✗","Vosotros: vosotros는 tenéis를 씁니다 ✗"]},{"id":"G740","q":"Mis abuelos ven ____ la televisión cada noche.","o":["a","ø","por","para"],"a":1,"k":"ver + 사물 목적어","t":"우리 할아버지 할머니는 매일 밤 TV를 보신다.","e":"ver(보다)의 목적어가 사물(la televisión)이면 전치사 없이 바로 씁니다. 사람이 목적어일 때만 '인칭의 a'를 붙입니다(Veo a mi madre). 'cada noche'는 '매일 밤'입니다.","x":["a: 사람 목적어 앞에만 쓰며 사물인 TV 앞에는 쓰지 않습니다 ✗","ø: 사물 목적어는 전치사 없이 바로 → 정답 ✓","por: 'por la televisión'은 'TV를 통해'라는 뜻이라 의미가 달라집니다 ✗","para: '~를 위해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G741","q":"Señores, ____ atentamente, por favor.","o":["escuchen","escuchad","escuchas","escuchan"],"a":0,"k":"ustedes 명령형","t":"여러분, 주의 깊게 들어 주세요.","e":"'Señores(여러분)'처럼 여러 사람에게 정중하게 명령할 때는 ustedes 명령형을 씁니다. -ar 동사 escuchar는 접속법 형태 escuchen이 됩니다. vosotros형 escuchad는 친한 사이에 씁니다.","x":["escuchen: ustedes 정중한 명령형 → 정답 ✓","escuchad: vosotros(친한 사이)에 쓰는 명령형이라 Señores에게는 어색합니다 ✗","escuchas: 직설법 tú형이라 명령이 아닙니다 ✗","escuchan: 직설법 3인칭 복수(그들은 듣는다)라 명령이 아닙니다 ✗"]},{"id":"G742","q":"Mi tío tiene 65 años, ____ parece que tiene 45.","o":["pero","porque","que","o"],"a":0,"k":"접속사 pero","t":"우리 삼촌은 65살이지만, 45살처럼 보인다.","e":"앞 내용(65살)과 반대되거나 예상 밖의 내용(45살처럼 보임)을 이어 줄 때는 pero(하지만)를 씁니다. 'parece que ...'는 '~인 것 같다'라는 뜻입니다.","x":["pero: 대조를 나타내는 '하지만' → 정답 ✓","porque: '왜냐하면'이라는 이유라 의미가 맞지 않습니다 ✗","que: 두 문장을 대조로 연결하지 못합니다 ✗","o: '또는'이라는 선택을 나타내 맞지 않습니다 ✗"]},{"id":"G743","q":"Shakira nació ____ 2 de febrero de 1977.","o":["a","lo","a la","el"],"a":3,"k":"날짜 + 정관사 el","t":"샤키라는 1977년 2월 2일에 태어났다.","e":"날짜 앞에는 전치사 없이 정관사 el을 씁니다. 'el 2 de febrero de 1977(1977년 2월 2일에)'처럼요. 스페인어 날짜는 '일 - de - 월 - de - 년' 순서이며, 월 이름은 소문자로 씁니다.","x":["a: 날짜 앞에 a를 쓰지 않습니다 ✗","lo: 중성 관사라 날짜 앞에 쓰지 않습니다 ✗","a la: 날짜는 남성(el día)으로 보아 la를 쓰지 않습니다 ✗","el: 날짜 앞의 정관사 → 정답 ✓"]},{"id":"G744","q":"¿Qué ____ gustaría beber?","o":["las","se","les","los"],"a":2,"k":"gustar 구문 les","t":"여러분은 무엇을 마시고 싶으세요?","e":"gustar 구문에서 '좋아하는 사람'은 간접목적격 대명사로 씁니다. 여러 손님(ustedes)에게 묻는 상황이므로 3인칭 복수 간접목적격 les를 씁니다. 손님 한 명(usted)에게 묻는다면 le가 됩니다.","x":["las: 직접목적격(그녀들을)이라 gustar 구문에 쓰지 않습니다 ✗","se: 재귀대명사라 gustar 구문의 간접목적어가 될 수 없습니다 ✗","les: ustedes에 해당하는 간접목적격 → 정답 ✓","los: 직접목적격(그들을)이라 gustar 구문에 쓰지 않습니다 ✗"]},{"id":"G745","q":"Mi papá tiene dos hermanos, uno mayor y otro menor ____ él.","o":["que","para","a","de"],"a":0,"k":"비교급 menor que","t":"우리 아빠에게는 형제가 둘 있는데, 한 명은 아빠보다 형이고 다른 한 명은 동생이다.","e":"mayor(나이가 많은)와 menor(나이가 어린)는 그 자체로 비교급이라 비교 대상 앞에 que를 씁니다. 'mayor que él(그보다 나이가 많은)', 'menor que él(그보다 어린)'처럼요. 여기서는 'mayor y otro menor que él'로 que él이 둘 다에 걸립니다.","x":["que: 비교급(menor) 뒤 비교 대상 '~보다' → 정답 ✓","para: '~치고는'이라는 다른 의미라 맞지 않습니다 ✗","a: 비교 대상을 나타내지 못합니다 ✗","de: 숫자 앞(más de diez)이나 최상급에 쓰며 사람 비교에는 que를 씁니다 ✗"]},{"id":"G746","q":"____ no está bien y lo sabes.","o":["Mintiendo","Mientes","Mentido","Mentir"],"a":3,"k":"동사원형 주어","t":"거짓말하는 건 좋지 않아, 너도 알잖아.","e":"스페인어에서 '~하는 것'이라는 행동 자체를 주어로 쓸 때는 동사원형을 씁니다. 'Mentir no está bien(거짓말하는 것은 옳지 않다)'처럼요. 영어는 -ing를 쓰지만 스페인어는 현재분사(-ando/-iendo)를 주어로 쓰지 않습니다.","x":["Mintiendo: 현재분사는 주어로 쓸 수 없습니다 ✗","Mientes: '너는 거짓말한다'라는 활용형이라 뒤의 no está와 문장이 이어지지 않습니다 ✗","Mentido: 과거분사라 주어가 될 수 없습니다 ✗","Mentir: 행동 자체를 주어로 쓰는 동사원형 → 정답 ✓"]},{"id":"G747","q":"¿____ de las dos camisas prefieres?","o":["Qué","Cómo","Cuál","Cuándo"],"a":2,"k":"cuál de + 복수","t":"두 셔츠 중에 어느 걸 더 좋아해?","e":"'정해진 것들 중 어느 것'을 고를 때는 'cuál de + 정관사 + 복수명사'를 씁니다. 'Cuál de las dos camisas(두 셔츠 중 어느 것)'처럼요. qué 바로 뒤에는 de를 쓰지 않습니다.","x":["Qué: 'qué de'라는 구조는 쓰지 않습니다 ✗","Cómo: '어떻게'라는 뜻이라 선택을 묻지 못합니다 ✗","Cuál: 여러 중 하나를 고르는 '어느 것' → 정답 ✓","Cuándo: '언제'라는 시간을 묻는 의문사입니다 ✗"]},{"id":"G748","q":"Nunca he usado ____ detergente.","o":["ese","esos","esa","esas"],"a":0,"k":"지시형용사 ese","t":"나는 그 세제를 한 번도 써 본 적이 없다.","e":"detergente(세제)는 남성 단수 명사이므로 지시형용사도 남성 단수 ese를 씁니다. -e로 끝나는 명사는 성이 다양하므로 단어와 함께 외워 두는 것이 좋습니다(el detergente, la leche).","x":["ese: 남성 단수 지시형용사 → 정답 ✓","esos: 복수형이라 단수 detergente와 맞지 않습니다 ✗","esa: 여성형이라 남성명사 detergente와 맞지 않습니다 ✗","esas: 여성 복수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G749","q":"Te lo digo ____ serio, no puedo comer más.","o":["de","a","en","por"],"a":2,"k":"en serio","t":"진심으로 말하는 건데, 더는 못 먹겠어.","e":"'en serio'는 '진지하게, 진심으로'라는 고정 표현입니다. '¿En serio?(정말?)'처럼 놀라움을 나타낼 때도 많이 씁니다. 'hablar en serio(진지하게 말하다)', 'tomar en serio(진지하게 받아들이다)'로도 씁니다.","x":["de: 'de serio'라는 표현은 쓰지 않습니다 ✗","a: 'a serio'라는 표현은 쓰지 않습니다 ✗","en: 'en serio(진심으로)' 고정 표현 → 정답 ✓","por: 'por serio'라는 표현은 쓰지 않습니다 ✗"]},{"id":"G750","q":"____ valijas están en esa habitación.","o":["Las suyas","Su","Suyas","Sus"],"a":3,"k":"소유형용사 sus","t":"그분의 여행 가방들은 저 방에 있어요.","e":"명사 앞의 소유형용사는 명사의 수에 맞춥니다. valijas(여행 가방들)가 복수이므로 sus를 씁니다. su/sus는 '그의, 그녀의, 당신의, 그들의' 모두를 뜻할 수 있습니다. 'valija'는 아르헨티나·우루과이 등에서 maleta 대신 쓰는 말입니다.","x":["Las suyas: '그분의 것들'이라는 대명사라 뒤에 명사가 올 수 없습니다 ✗","Su: 단수형이라 복수 valijas와 맞지 않습니다 ✗","Suyas: 명사 뒤에 쓰는 형태라 명사 앞에 올 수 없습니다 ✗","Sus: 복수 명사 앞 소유형용사 → 정답 ✓"]}];